INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-8b874d97e90e00f0', 'ga-chien-sa-thai', 330, 'Gà chiên sả kiểu Thái', 'Đùi gà lọc xương ướp sả giã tơi sợi, rễ ngò, tỏi tiêu rồi chiên ngập dầu vàng giòn rụm, xóc cùng lá chanh Kaffir thơm nức', 'Gà chiên sả kiểu Thái hấp dẫn với từng miếng thịt đùi gà mềm mọng bên trong, lớp vỏ ngoài giòn rụm áo phủ những sợi sả giã tơi chiên vàng ruộm, dậy hương nồng nàn của rễ ngò rí, tiêu đen và lá chanh Kaffir.', 'Bày gà chiên sả cùng sợi sả chiên giòn ra đĩa lớn, dùng nóng với cơm trắng hoặc xôi nếp dẻo kèm tương ớt chua ngọt Thái và dưa leo.', 'Gà chiên ngon nhất ngay sau khi vớt ráo dầu; phần dư bọc kín bảo quản ngăn mát tối đa 48 giờ, làm nóng lại bằng nồi chiên không dầu ở 180°C trong 6–8 phút để lấy lại độ giòn.', 'thai', 'mon_chien', NULL, 'medium', 40, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Đùi gà","Sả ớt","Ẩm thực Thái","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 427, 426.5, 1785, 30.4, 26.4, 5.9, 16.1, 0.8, 4.3, 1092, 2.73, '["Citrus Leaf Culinary Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'a575cd3644687bf4ffe4ce7ee40ae71e30a24d529ca0335291ccb0aff6b74836', '087e9c86937ff6f8b04afee1f88ce65277f460e939a40079c82d5c3a33d1d9e4', 4),
('imp-b95544e75512c4e8', 'mi-y-toi-dau-ot', 331, 'Mì Ý tỏi dầu ớt kiểu truyền thống', 'Sợi Spaghetti al dente xóc cùng tỏi lát phi vàng trong dầu ô liu nguyên chất, ớt sừng đỏ cay nồng và nước luộc mì sánh mịn', 'Mì Ý tỏi dầu ớt truyền thống chinh phục vị giác bằng sự thuần khiết: dầu ô liu nguyên chất thơm nức mùi tỏi lát phi dịu và vị cay ấm của ớt sừng đỏ, hoàn thiện bằng kỹ thuật xóc chảo với nước luộc mì tạo lớp sốt bóng mượt tự nhiên.', 'Chia mì ra 3 đĩa sâu lòng khi còn nóng hổi, rưới đều phần dầu tỏi ớt còn lại trong chảo và rắc thêm ngò tây tươi thái nhỏ nếu thích.', 'Mì tỏi dầu ớt ngon nhất khi dùng nóng ngay sau khi nấu; nếu cần hâm lại, đảo nhanh trên chảo cùng 1–2 muỗng canh nước ấm để tránh mì bị khô.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Aglio e Olio","Cay nhẹ","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry","toss_mix"]', '["wheat"]', 423, 422.9, 1769, 10.7, 14.9, 2.1, 60.9, 2.7, 2.3, 395, 0.99, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'f410cc3375ee28ff769eb5e0956acf4482cc88a3b7cb2dcd641406f30d1333c8', '943ba15ee0d5e8fad6847477e21d1a9ce45e4feb1e358ba07a2cfdd2236a1f54', 4),
('imp-5ae4665cc17ff036', 'mi-y-sot-cay-ca-chua', 332, 'Mì Ý Penne sốt cà chua cay Arrabbiata', 'Mì ống Penne có rãnh thấm đẫm sốt cà chua lột vỏ ninh sánh quyện vị cay nồng của ớt tươi, hương tỏi phi dầu ô liu và ngò tây thơm mát', 'Penne all''Arrabbiata là món mì cay nổi tiếng vùng Lazio với cái tên mang nghĩa ''giận dữ'' bởi sắc đỏ rực của cà chua và vị cay bùng nổ từ ớt tươi. Mì ống Penne có rãnh nhỏ giúp ôm trọn phần sốt cà chua sánh đặc cùng hương ngò tây tươi mát.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng hổi, rắc thêm ngò tây tươi băm và phô mai Pecorino Romano bào mịn nếu thích.', 'Sốt Arrabbiata ngon nhất khi dùng ngay; phần dư bảo quản hộp kín trong ngăn mát tối đa 1–2 ngày và hâm nóng trên chảo cùng chút nước lọc.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Arrabbiata","Sốt cay","Cà chua"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["milk","wheat"]', 449, 448.7, 1877, 15.1, 13.3, 3.3, 68, 4.6, 6.9, 716, 1.79, '["USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC Pecorino Ref"]', '16a242100a73ec1803f750fdb13a912fc9570cd02561a535783ba386d04f3846', 'c00408e31d736fedc58545898f2f8991529d0ff39bbea9e7083c6dcc06965cf0', 4),
('imp-9c48616208fff232', 'mi-y-bong-cai-xanh', 333, 'Mì Ý sốt kem bông cải xanh hạnh nhân', 'Sợi mì Spaghetti quyện sốt bông cải xanh xay mịn cùng phô mai Parmesan, bông cải om mềm và hạnh nhân rang giòn bùi thơm', 'Mì Ý bông cải xanh hạnh nhân là món pasta rau củ thanh mát, giàu dinh dưỡng với phần sốt xanh mướt được tạo nên từ một nửa bông cải xanh xay nhuyễn cùng hạnh nhân rang và phô mai Parmesan, kết hợp phần bông cải om mềm giữ nguyên nhánh tạo kết cấu thú vị.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng, rắc phần hạnh nhân rang giòn còn lại, ít phô mai Parmesan bào và ớt tươi thái lát lên trên.', 'Món mì sốt rau củ ngon nhất khi ăn nóng ngay; nếu còn dư bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo cùng vài muỗng nước lọc cho sốt mượt lại.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Bông cải xanh","Hạnh nhân","Thanh đạm"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["almond","milk","tree_nuts","wheat"]', 584, 583.7, 2442, 21.3, 24.8, 6.6, 71.6, 7.5, 5, 677, 1.69, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170379","USDA FDC 170567","USDA FDC 170848","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', 'd6ddf99b03905d628dd03b18374d5a68aecae9a75fb0206b1429e01b83140a16', '5d96d7d2893eb93e5cc9d4a8b40f10c07614c6210048e1cc7b41bb238cf7f2d9', 4),
('imp-b5571547ad5d2cec', 'mi-y-ca-hoi-bo-chanh', 334, 'Mì Ý cá hồi sốt bơ chanh', 'Mì ống hoặc Spaghetti trộn cá hồi áp săn thấm rượu vang trắng, nước cốt chanh vàng thanh mát và sốt bơ lạt đánh bóng thơm ngò tây', 'Mì Ý cá hồi sốt bơ chanh là lựa chọn hoàn hảo cho bữa tối nhanh gọn mà vẫn tinh tế. Cá hồi áp chảo vừa chín mềm được hòa quyện cùng hành tím phi thơm, rượu vang trắng, nước cốt chanh vàng và bơ lạt đánh bóng ngoài bếp lửa.', 'Chia mì và cá hồi ra 3 đĩa sâu lòng khi còn nóng, rắc vỏ chanh vàng bào sợi mảnh, phần ngò tây tươi còn lại và tiêu đen xay lên trên.', 'Món mì cá hồi sốt bơ chanh nên thưởng thức ngay lúc nóng để sốt bơ giữ độ bóng mượt; phần dư bảo quản ngăn mát tối đa 24 giờ và hâm nhẹ trên chảo lửa nhỏ.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Cá hồi","Bơ chanh","Nấu nhanh"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["fish","milk","salmon","sulphites","wheat"]', 655, 654.9, 2740, 27.8, 29.7, 9.2, 64.3, 3.6, 3.8, 448, 1.12, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 170416","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167"]', 'd3f1f616f764d857d3e4aa6df85c730517100f64ce47d3d5dcbf397c272ba719', '67e8950d77f39848430cfbeb7921b41aa1372a72d2b5fb74844ad67f3d51ec6a', 4),
('imp-7b5f0d33681ea7d2', 'ga-parmigiana-nuong', 335, 'Gà Parmigiana nướng phô mai', 'Ức gà tẩm bột chiên xù giòn rụm phủ sốt cà chua húng quế và phô mai Mozzarella nướng tan béo ngậy chuẩn vị Ý', 'Món gà Parmigiana kinh điển với từng lát ức gà dần mỏng tẩm bột chiên xù trộn phô mai Pecorino vàng giòn, phủ sốt cà chua húng quế nấu sánh và phô mai Mozzarella nướng chảy thơm lừng.', 'Dọn nóng trực tiếp từ khay nướng, rắc ngò tây băm; dùng kèm mì Ý luộc hoặc salad rau xanh trộn dầu giấm để cân bằng vị béo.', 'Nên thưởng thức ngay khi lớp vỏ còn giòn; nếu còn dư, đậy kín trong ngăn mát tối đa 2 ngày và hâm nóng lại bằng lò nướng 180°C trong 10 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Gà Parmigiana","Ẩm thực Ý","Nướng lò","Phô mai","Món chính"]', '["lunch","dinner"]', '["pan_fry","simmer","grill_roast"]', '["chicken","egg","milk","wheat"]', 692, 691.9, 2895, 62.1, 32.4, 11.9, 37.7, 4.1, 8, 1501, 3.75, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169072","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170845","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 171477","USDA FDC 172232","USDA FDC 173468","USDA FDC Pecorino Ref"]', 'efc4d47f0499fad55f611e3d4170ae58885fd1ff5116b3a07931e190e81dd2f0', '98ffaa2517b022e2f5a83077bcdcaa1982ad4cec3a3dc9910bcf1dabe001034f', 4),
('imp-e3df53f1154592bc', 'ca-nuong-ca-chua-y', 336, 'Cá nướng cà chua chanh vàng kiểu Ý', 'Phi lê cá biển thịt trắng ướp chanh tỏi nướng lò cùng cà chua chín mọng và lớp vụn bánh mì giòn thơm thảo mộc', 'Phi lê cá thịt trắng chắc ngọt được ướp thấm vị nước cốt chanh vàng, tỏi và dầu ô liu, phủ lớp vụn bánh mì ngò tây giòn rụm rồi nướng lò cùng cà chua chín mọng tiết sốt chua ngọt tự nhiên.', 'Dọn cá nóng ra đĩa, rưới phần nước sốt cà chua đọng dưới khay lên trên và ăn kèm bánh mì giòn hoặc khoai tây nướng.', 'Món ngon nhất khi ăn nóng ngay sau khi nướng; nếu còn thừa có thể bảo quản ngăn mát tối đa 24 giờ và hâm lại ở 170°C trong 6–8 phút.', 'italian', 'mon_lau_tiec', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Cá nướng","Ẩm thực Ý","Cà chua","Chanh vàng","Ít béo"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","wheat"]', 332, 332.2, 1390, 33, 16.6, 2.8, 13.1, 2.3, 3.7, 724, 1.81, '["Panko / Batter Mix Ref","USDA FDC 167746","USDA FDC 169230","USDA FDC 170416","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175148"]', '8d5061d70b4d0b4ab7f459fbb2aac2cb66f8e6741401406a8e8126f73123848d', '261071898f9ef91fe2dc1a424494bb530b0deb9df1ab49b3a1e5ea3a058e5fc3', 4),
('imp-a0ed6c762f7dceba', 'bo-pizzaiola', 337, 'Bò om sốt cà chua lá Oregano (Pizzaiola)', 'Lát thịt bò dần mỏng nấu nhanh trong sốt cà chua sánh quyện mùi tỏi thơm và lá Oregano chuẩn phong vị Napoli', 'Món bò Pizzaiola dân dã vùng Napoli với từng lát thịt bò dần mỏng mềm ngọt, thấm đẫm sốt cà chua nấu sánh thơm lừng mùi tỏi và thảo mộc Oregano đặc trưng.', 'Dọn nóng ngay ra đĩa, múc nhiều sốt cà chua rưới lên mặt thịt và rắc vài lá húng quế tươi; ăn kèm bánh mì giòn chấm sốt hoặc mì Ý luộc.', 'Nếu nấu trước, nên nấu riêng phần sốt cà chua và bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại sốt rồi mới cho thịt bò vào nấu chín để thịt không bị dai.', 'italian', 'mon_kho', NULL, 'easy', 10, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Bò Pizzaiola","Ẩm thực Ý","Thịt bò","Cà chua","Món mặn"]', '["lunch","dinner"]', '["simmer","braise"]', '["beef"]', 319, 318.8, 1335, 27.4, 20, 6.1, 7.5, 2, 3.9, 667, 1.67, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170187","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '59bba854661b3adbc13fcad87cb54d65bc60564bc22fba2d2622e72fc6ebc23f', '48e4ab40adcd4ebb53f819d712534a998f0a94559e184915327a9eccd1919f68', 4),
('imp-2865ee57783628d7', 'salad-mi-y-nguoi', 338, 'Salad mì Ý trộn nguội phô mai Feta', 'Mì xoắn Fusilli dai nhẹ hòa quyện cà chua bi, dưa leo giòn mát, phô mai Feta mặn béo và sốt chanh dầu ô liu', 'Đĩa salad mì Ý thanh mát mang phong vị Địa Trung Hải với những xoắn mì Fusilli chín vừa al dente quyện sốt dầu ô liu chanh vàng, cà chua mọng nước, dưa leo giòn ngọt và phô mai Feta béo mặn.', 'Dọn lạnh trực tiếp sau khi ủ mát 30 phút, rắc thêm lá húng quế tươi; rất hợp làm món chính nhẹ nhàng cho bữa trưa hoặc món khai vị cho tiệc nướng.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; trước khi ăn đảo nhẹ lại một lượt cho sốt hòa đều mà không cần hâm nóng.', 'italian', 'mon_cuon_nom', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Salad mì Ý","Ẩm thực Ý","Món mát","Bữa trưa","Feta"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["milk","wheat"]', 420, 420.3, 1758, 14.9, 15.3, 5.4, 56.3, 3.5, 4.2, 534, 1.34, '["USDA FDC 167746","USDA FDC 168409","USDA FDC 168927","USDA FDC 170000","USDA FDC 170457","USDA FDC 170853","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '4e6b611f9dcacb098e16d2f5ee35f835f2d6ea8b5610a77b9e3063647c4ac217', '18f78b8144f2cb92bddda87b7bb5a09e6ce254cf4de5557b5584a959d5d7221e', 4),
('imp-f9481ae10c0cc62a', 'sup-ca-chua-kem-y', 339, 'Súp cà chua kem tươi kiểu Ý', 'Súp cà chua chín xay mịn lọc rây mượt mà kết hợp sữa tươi, kem béo và bánh mì áp chảo giòn rụm ấm áp', 'Bát súp cà chua kem kiểu Ý mịn mượt như nhung với vị chua thanh tự nhiên từ cà chua chín hòa quyện độ béo dịu của sữa tươi, kem tươi và hương húng quế Tây thanh tao.', 'Múc súp nóng ra tô sâu lòng, rưới thêm vòng kem tươi, rắc phô mai Parmesan bào và dùng kèm các viên bánh mì áp chảo giòn rụm để giữ độ giòn.', 'Bảo quản phần súp trong hộp kín ở ngăn mát tối đa 2 ngày, tách riêng bánh mì giòn; khi ăn hâm nóng lại trên lửa thật nhỏ và khuấy đều, không đun sôi bùng.', 'italian', 'mon_canh', NULL, 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Súp kem cà chua","Ẩm thực Ý","Khai vị","Món nóng","Crouton"]', '["lunch","dinner"]', '["simmer","pan_fry"]', '["milk","wheat"]', 409, 409.3, 1712, 10.6, 28, 14.2, 30.9, 3.5, 15.5, 1062, 2.66, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170000","USDA FDC 170457","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171595","USDA FDC 172232","USDA FDC 172687","USDA FDC 173430","USDA FDC 173468"]', '777a673e4e0c2d07a03b31964642c6669c8d2d661f565f124da91bfc42d31bdb', '549799400d5b6266539a3bd44ffd6523b4b2533c7748068f4ce85672b6316596', 4),
('imp-e39ba043b6d1f19d', 'rau-cu-nuong-y', 340, 'Rau củ nướng dầu ô liu kiểu Ý', 'Bông cải xanh, cà rốt và hành tây nướng chín tới xém cạnh caramel ngọt bùi quyện sốt dầu ô liu tỏi thơm', 'Khay rau củ nướng vàng xém cạnh với bông cải xanh giòn ngọt, cà rốt bùi bở và hành tây thơm lừng mùi tỏi nướng caramel hóa, quyện dầu ô liu nguyên chất, giấm Balsamic Ý chua ngọt dịu và thảo mộc Oregano Địa Trung Hải.', 'Dọn nóng hoặc ở nhiệt độ phòng như món ăn kèm lý tưởng cho gà nướng, bít tết bò hay cá áp chảo, hoặc dùng kèm cơm trắng đều ngon.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại bằng nồi chiên không dầu hoặc lò nướng 180°C khoảng 5–6 phút để rau giòn cạnh trở lại.', 'italian', 'mon_chay', NULL, 'easy', 12, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Rau củ nướng","Món chay","Ẩm thực Ý","Món phụ","Thanh nhẹ"]', '["lunch","dinner"]', '["grill_roast"]', '["sulphites"]', 166, 166.2, 695, 3.8, 10.3, 1.4, 17.4, 5.1, 6.6, 512, 1.28, '["USDA FDC 169230","USDA FDC 170000","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173470","USDA FDC 173475"]', '33be6358a761e86705eed5ac4e47452fe48e0161ef4392c680b766665e402862', '9b6625345de0bb5b2ab0801f3a2431177ff79a7c1ab1c80d5bf95e54f216d753', 4),
('imp-f50c115d909f97f2', 'canh-nam-ca-chua-chua-nhe', 341, 'Canh nấm cà chua chua nhẹ', 'Món canh thanh đạm kết hợp nấm đùi gà giòn ngọt và cà chua chín đỏ au, nấu nhanh gọn chỉ trong 20 phút', 'Canh nấm cà chua chua nhẹ không dùng thịt nhưng vẫn ngọt thanh nhờ sự kết hợp giữa nấm đùi gà, nấm rơm hoặc nấm hương tươi cùng vị chua dịu từ cà chua chín và hương thơm ấm nhẹ của gừng, hành tỏi.', 'Múc canh ra tô lớn khi còn nóng, rắc hành lá và chút tiêu đen xay; dùng kèm cơm trắng và đậu phụ chiên sả ớt hoặc cá kho.', 'Canh nấm ngon nhất khi dùng hết trong bữa; nếu bảo quản ngăn mát tủ lạnh tối đa 24 giờ, chỉ đun sôi lại 2 phút trên lửa vừa để nấm giữ độ giòn ngọt.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 10, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nấm đùi gà","Cà chua","Thanh đạm","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 111, 111.2, 465, 4.1, 6, 0.9, 12.7, 3.2, 6.3, 898, 2.24, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169251","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', 'b818d9b40063743456f446c8fd1625c5bdfa0c0cd991ffa750e434b229ebf551', 'ec3c7de7874a6f46f8328839e88092ea9c733ff5c1298d77262cbaa98534695e', 4),
('imp-ae5b053b8361f807', 'canh-tom-nau-sa-chua', 342, 'Canh tôm nấu sả chua', 'Nước canh miền Trung thơm lừng sả tươi và ớt hiểm, vị chua thanh của chanh hòa quyện cùng tôm tươi ngọt giòn kích thích vị giác', 'Canh tôm nấu sả chua mang đậm phong vị miền Trung với nước dùng trong vắt, thơm nồng hương sả đập dập và cay nhẹ từ ớt hiểm, kết hợp thịt tôm tươi săn ngọt cùng vị chua thanh mát của cà chua và nước cốt chanh.', 'Dọn canh nóng vào tô lớn, rắc hành lá và thêm vài lát ớt tươi; ăn nóng cùng cơm trắng và các món cá kho hoặc thịt ram mặn.', 'Canh ngon nhất khi dùng nóng ngay sau khi vắt chanh; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại phần nước canh và tôm 1–2 phút rồi mới nêm lại chút nước cốt chanh nếu cần.', 'vietnamese', 'mon_canh', 'trung', 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Miền Trung","Chua cay","Sả chanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 133, 133.1, 557, 15.5, 3.9, 0.6, 10.7, 1.5, 5.6, 1397, 3.49, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '60c43859f8dae007e40cd5367b7dec9604b2f2c3f6da0935de68059ea1afc715', 'e16d3c98654f3d3780e790bd6a44a26417c31ae780bf5c00472b7007bcf12d3d', 4),
('imp-ac77ed3af015efd7', 'canh-bo-bap-cai', 343, 'Canh thịt bò nấu bắp cải', 'Thịt bò thăn thái mỏng mềm ngọt quyện cùng lá bắp cải giòn ngọt và nước canh trong veo, món canh ấm áp cho bữa tối gia đình', 'Canh thịt bò nấu bắp cải kết hợp vị ngọt đậm của thịt bò thăn thái lát với độ ngọt mát tự nhiên của bắp cải và cà chua. Nước canh trong trẻo, thơm dịu mùi tỏi phi và ngò rí, cực kỳ dễ ăn.', 'Dọn canh nóng vào tô lớn, rắc hành lá, ngò rí và tiêu đen xay; thưởng thức cùng cơm trắng nóng dẻo và chén nước mắm ớt cắt lát.', 'Canh ngon nhất khi ăn nóng ngay lúc mới nấu để bắp cải giòn và thịt bò mềm ngọt; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhanh 1–2 phút trước khi dùng.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Bắp cải","Thanh ngọt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["beef","fish"]', 205, 205.4, 860, 17.6, 11.5, 3.6, 8.6, 2.9, 4.1, 1274, 3.18, '["USDA FDC 169230","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '1b30dea248be1d603857e8f36a7423549ab7af876f1f6ca762e2221df60173c8', '5b0f16ff1bea49b7e36b6649b17029e7c940a3eca6bcb3d9865d9b08d95ac04b', 4),
('imp-4ec35a6c12daa33d', 'muc-kho-tieu', 344, 'Mực kho tiêu', 'Mực tươi cắt khoanh khứa vảy rồng giòn ngọt kho tiêu đen cay nồng, nước sốt nâu cánh gián sánh đậm cực bắt cơm', 'Những khoanh mực tươi trụng sơ giữ nguyên độ giòn sần sật, thấm đẫm nước kho mặn ngọt màu cánh gián quyện mùi hành tỏi phi thơm và tiêu đen xay cay nồng.', 'Múc mực kho tiêu ra đĩa sâu lòng, rắc thêm tiêu đen xay và hành lá cắt khúc; ăn nóng với cơm trắng và dưa leo thái lát.', 'Ngon nhất khi dùng hết trong ngày để giữ độ giòn của mực; nếu bảo quản ngăn mát tối đa 24 giờ, làm nóng nhanh trên chảo lửa nhỏ khoảng 2 phút.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Mực tươi","Tiêu đen","Nam Bộ","Đưa cơm"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["fish","molluscs","squid"]', 226, 225.9, 945, 21, 10.2, 1.7, 11.9, 0.7, 5.2, 1064, 2.66, '["MEXT Sake 16021","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '000d2fdcd3a68e9d187c99b3c3027b2f5993f9ded508ceb88f47557d6272b6c7', 'ef4f133991164537581e78d5684e547d87bbaa727a2865ec4d7403401d638d9f', 4),
('imp-01121ea953ffed76', 'suon-kho-trung', 345, 'Sườn non kho trứng cút', 'Sườn non heo kho mềm róc xương cùng trứng cút luộc và nước dừa tươi thanh ngọt, thấm đẫm màu cánh gián đậm đà chuẩn cơm nhà', 'Những miếng sườn non kho liu riu trong nước dừa tươi đến khi mềm rệu, kết hợp cùng trứng cút bùi béo thấm màu nâu hổ phách sóng sánh và hương thơm cay ấm của tiêu ớt.', 'Múc sườn và trứng cút ra đĩa sâu lòng, chan nước kho sánh bóng và rắc hành lá cùng tiêu xay; ăn nóng với cơm trắng dẻo.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi dùng hâm lại trên lửa nhỏ cho nước sốt nóng sánh đều.', 'vietnamese', 'mon_kho', 'bac', 'medium', 20, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Trứng cút","Bắc Bộ","Cơm nhà"]', '["lunch","dinner"]', '["braise","boil","stir_fry"]', '["egg","fish","pork"]', 353, 352.7, 1475, 17.1, 26.2, 8.5, 11.7, 1.6, 8.7, 1098, 2.75, '["USDA FDC 167861","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172191","USDA FDC 173468","USDA FDC 173647"]', '5abf4b4fe39ba32c692c79c18bfeb4ba341d0125e9ca9e18098fb28076bed604', 'c8f74ef980631bbc4c17599e4ca6903fdc3ffac36ecb49cac6fbb7320459b619', 4),
('imp-296b724137581830', 'dau-phu-kho-tieu', 346, 'Đậu phụ kho tiêu', 'Đậu phụ trắng chiên vàng giòn hai mặt kho liu riu trong sốt nước tương sánh keo thơm nồng tiêu đen, món chay mặn đều dùng được cực đưa cơm', 'Những miếng đậu phụ vàng ruộm bên ngoài, mềm béo bên trong thấm đẫm sốt nước tương ngọt mặn hài hòa quyện vị cay ấm của tiêu đen xay và hương tỏi phi.', 'Xếp đậu phụ kho tiêu ra đĩa sâu lòng, rưới sốt sánh bóng và rắc hành lá, ớt lát cùng tiêu xay; ăn nóng với cơm trắng và rau luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ với 1 muỗng canh nước lọc.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Đậu phụ","Món chay","Nhanh gọn","Đưa cơm"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["soybean","wheat"]', 241, 241.2, 1009, 17.6, 16.9, 2.5, 9.2, 2, 5.1, 973, 2.43, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '4a5d3eb680c7cae2a8092da8be8828d5949b1de5113b795c165642c141221231', 'fa7e8cb7fea67d891c6c15749cc75cdf9a018e82818e6f087ca831258c3d3552', 4),
('imp-54c8037962551d6b', 'gia-do-xao-toi', 347, 'Giá đỗ xào tỏi', 'Giá đỗ trắng mập giòn ngọt xào chớp nhoáng trên lửa lớn cùng tỏi phi vàng thơm và hành lá xanh tươi', 'Giá đỗ xào tỏi là món rau cấp tốc giữ nguyên độ giòn mọng ngọt thanh tự nhiên của giá đỗ tươi, quyện mùi tỏi phi vàng thơm lừng và vị mặn dịu vừa vặn, cực kỳ hợp để giải ngấy trong bữa cơm gia đình.', 'Gắp giá đỗ xào tỏi ra đĩa phẳng ngay sau khi tắt bếp, dùng nóng với cơm trắng cùng các món thịt kho hoặc cá chiên.', 'Giá đỗ xào rất nhanh ra nước khi nguội nên cần ăn hết ngay trong bữa; không khuyến khích bảo quản qua đêm.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["fish"]', 116, 115.6, 484, 4.5, 7.2, 1.1, 11.1, 2.6, 5.4, 924, 2.31, '["USDA FDC 169230","USDA FDC 169963","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'b3981b1e4dbccfd3c2f031d3bc5e66983b93422ac7f68ec890e53284b4429d8a', '165a01ade8a0619fcfb9dff6ab23ad7299ae0886c184aaaeb26bb0ca0a16edb2', 4),
('imp-e75e90d847daa628', 'mi-xao-hai-san', 348, 'Mì xào hải sản', 'Sợi mì trứng dai ngon xào lửa lớn cùng tôm mực giòn ngọt, cải thìa, cà rốt và ớt chuông quyện sốt dầu hào đậm đà', 'Mì xào hải sản là món ăn đủ chất và rực rỡ sắc màu với những vắt mì trứng dai mềm không bết dính, ôm trọn tôm sú, mực ống tươi giòn cùng cải thìa, cà rốt, ớt chuông thấm đẫm sốt dầu hào và nước tương thơm lừng.', 'Bày mì xào hải sản ra đĩa lớn, rắc thêm ngò rí và tiêu đen xay; dùng nóng kèm chén nước tương dầm ớt xắt lát.', 'Món mì xào ngon nhất khi ăn nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với 1 muỗng canh nước lọc ở lửa vừa.', 'vietnamese', 'mon_xao', 'nam', 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Mì xào","Nam Bộ","Đủ chất"]', '["breakfast","lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","egg","molluscs","shrimp","soybean","squid","wheat"]', 492, 492, 2059, 31.9, 14.5, 2.4, 59.5, 5, 9, 1483, 3.71, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170390","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'c824e433bee5ac6dd2f5abc3bacebd44d36cba133a321218f8f65e4f549c02e7', '054a40628e78675329a0a573139ab1fc62f24a07929d56602dedca6b8b15a0a2', 4),
('imp-1e6d5d1750d3aa51', 'ga-xao-ca-chua', 349, 'Gà xào cà chua', 'Thịt đùi gà áp chảo vàng mềm om thấm sốt cà chua đỏ sánh đậm vị xì dầu, ăn kèm hành tây giòn ngọt cực hao cơm', 'Gà xào cà chua mang hương vị cơm nhà ấm cúng với từng miếng thịt đùi gà săn mềm mọng nước, thấm đẫm phần sốt cà chua chín nhừ đỏ au quyện xì dầu mặn ngọt dịu nhẹ và hành tây giòn thơm.', 'Trút gà xào cà chua ra đĩa sâu lòng, rưới đều nước sốt sánh lên trên cùng hành lá và tiêu đen xay; dùng nóng với cơm trắng hoặc bún tươi.', 'Bảo quản trong hộp kín ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa vừa khoảng 3–4 phút cho sốt sôi đều trở lại.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Cà chua","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","soybean","wheat"]', 408, 407.5, 1705, 33.7, 24.1, 5.7, 13.8, 2.7, 7.3, 1118, 2.8, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'aaa534a0854a57f9b3e281f066dfbb5a1ab909ccf8c045fe3bd9e7e1ad8448ee', '6ebf6906a5c23a7c5d4b27bba43a68fdc70d645e17c7648a8d763a1f3ed833ce', 4),
('imp-ce3c9df133ba1cd4', 'banh-trang-chien-trung', 350, 'Bánh tráng chiên trứng', 'Bánh tráng nướng chiên phồng giòn rụm phủ trứng gà béo mềm, hành lá, ruốc sấy và rau răm thơm nức', 'Bánh tráng chiên trứng là món ăn vặt đường phố Sài Gòn nổi tiếng nhờ sự kết hợp giữa miếng bánh tráng mỏng chiên phồng giòn rụm bên dưới và lớp trứng gà béo mềm bên trên, điểm thêm vị mặn thơm của ruốc sấy, hành phi, ớt hiểm và rau răm tươi.', 'Cắt bánh thành từng miếng tam giác vừa ăn khi còn nóng giòn, chấm kèm tương ớt cay ngọt và thưởng thức ngay lúc mới ra chảo.', 'Món ăn ngon nhất ngay khi vừa chiên xong để giữ độ giòn của bánh tráng; không nên cất tủ lạnh qua ngày vì hơi ẩm từ trứng sẽ làm bánh tráng bị dai cứng.', 'vietnamese', 'mon_chien', 'nam', 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Ăn vặt","Bánh tráng","Sài Gòn","Dưới 30 phút"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["crustaceans","egg","shrimp"]', 367, 367.3, 1537, 11.1, 16.4, 3.2, 44, 1.4, 2.6, 1002, 2.51, '["USDA / Asian Dried Shrimp Ref","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC Rice Paper Ref","USDA FDC Sriracha Ref","VN Rau Ram Ref"]', 'f8fa03bb80198ad18167b83ce5ce1fc270e8d63d5c1cf0a9c826696324c8b0c2', '8888d4ade4d1f7585109efdc6b6c62de6600e2295b7dd602b10a3f8652677ce0', 4),
('imp-1d4d9422e7f81e97', 'cua-hap-chanh-ot', 351, 'Cua thịt hấp chanh sả ớt', 'Cua biển thịt chắc hấp chín đỏ au cùng sả, gừng, hành tây thơm nồng, gỡ thịt ngọt mọng chấm muối tiêu chanh ớt', 'Cua thịt tươi sống được chà rửa sạch và hấp cách thủy cùng sả cây đập dập, hành tây, gừng và ớt hiểm giúp khử mùi bùn biển, giữ nguyên từng thớ thịt trắng muốt ngọt đậm quyện chén muối tiêu chanh ớt.', 'Bày cua hấp đỏ au ra mâm lớn cùng vài lát chanh tươi và rau răm thơm nồng; bóc mai gỡ thịt chấm muối tiêu chanh ớt ngay khi còn nóng.', 'Chỉ hấp và dùng cua tươi sống trong ngày. Nếu còn dư, gỡ sẵn thịt cua bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hấp nóng lại trước khi ăn.', 'vietnamese', 'mon_hap_luoc', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Hải sản","Cua biển","Món Nam","Đãi tiệc"]', '["lunch","dinner"]', '["steam"]', '["crab","crustaceans"]', 202, 202.2, 846, 37.3, 2.3, 0.5, 6.7, 1.1, 2.5, 1411, 3.53, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN Rau Ram Ref"]', 'a070f49b50e179907a2466fd4e11284e009b5762ef46bdcdaa70bce0302cd71d', 'c2e739d6cd0a7fd914d1c709221e640c4ce105bb8226b048f6deeffbcf8a1aa0', 4),
('imp-d3972d88e860aba9', 'goi-muc-chanh', 352, 'Gỏi mực chanh ớt giòn ngọt', 'Mực ống tươi luộc gừng chín tới cắt khoanh giòn ngọt trộn cùng hành lá chần, rau răm và nước mắm chanh tỏi ớt chua cay mát lành', 'Gỏi mực chanh ớt là món khai vị hải sản thanh mát, nhanh gọn với từng khoanh mực ống trắng giòn ngọt tự nhiên không tanh, quyện hành lá chần dịu hăng, rau răm thơm nồng và nước trộn chanh tỏi ớt đậm vị chua cay hài hòa.', 'Bày gỏi mực ra đĩa, rắc vài lát ớt hiểm và rau răm lên trên; dọn ăn ngay kèm bánh phồng tôm hoặc bánh đa nướng giòn rụm.', 'Gỏi mực ngon nhất khi dùng ngay trong vòng 30 phút sau khi trộn để khoanh mực giữ độ giòn và không tiết nước; nếu chưa trộn, bọc kín mực luộc ráo và nước chấm riêng trong ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi mực","Hải sản","Chanh ớt","Khai vị","Miền Trung"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","molluscs","squid"]', 287, 287.4, 1203, 24.8, 2.4, 0.6, 41, 1.3, 10.2, 1645, 4.11, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","VN Banh Da Ref","VN Rau Ram Ref"]', '0b3db5508772ed50415456859cc22de71e35c13bb120724d112a498dc78be134', '44992233b8bf22c46a46c34e0ae2a6b0b29d161cdfa3963a2e337fa29ffd8eae', 4),
('imp-68184b07a3c61cff', 'cuon-nem-nuong-banh-trang', 353, 'Cuốn nem nướng bánh tráng chấm sốt nếp gan tôm', 'Nem thịt heo giò sống mỡ hạt lựu nướng thơm xiên sả, cuốn bánh tráng cùng rau sống, giá đỗ, dưa leo, đồ chua và chấm sốt nếp tôm thịt gan sánh bùi', 'Cuốn nem nướng bánh tráng đậm chất miền Trung với những xiên nem thịt heo giò sống lẫn mỡ hạt lựu nướng vàng ruộm thơm sả, cuốn gọn trong bánh tráng cùng rau sống, giá đỗ, dưa leo, đồ chua và chén sốt gạo nếp tôm thịt gan heo béo bùi khó cưỡng.', 'Bày nem nướng nóng ra đĩa cùng bánh tráng, rau sống, dưa leo, giá đỗ và đồ chua; múc sốt chấm ra chén rắc đậu phộng rang giã dập lên trên để cuốn và chấm nóng.', 'Nem đã nướng chín và sốt chấm bảo quản riêng trong hộp kín ngăn mát tối đa 2 ngày; khi ăn làm nóng nem trong nồi chiên không dầu 160°C trong 4 phút và hâm nóng lại chén sốt với chút nước lọc.', 'vietnamese', 'mon_cuon_nom', 'trung', 'medium', 45, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Nem nướng","Bánh tráng cuốn","Miền Trung","Nước chấm đặc biệt","Đãi tiệc"]', '["lunch","dinner"]', '["grill_roast","simmer","assemble"]', '["crustaceans","fish","molluscs","peanut","pork","shrimp","soybean","wheat"]', 653, 652.7, 2731, 30.6, 35.9, 11.3, 52.9, 3.3, 9.8, 1319, 3.3, '["Annatto Infused Oil Ref","NIN VN Gio Lua Ref","USDA FDC 167820","USDA FDC 167871","USDA FDC 167902","USDA FDC 168409","USDA FDC 168573","USDA FDC 168881","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169717","USDA FDC 169963","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 174277","USDA FDC 175179","USDA FDC Rice Paper Ref"]', '4e6c30b65cad8e34ef8d2dd92b15bbb1a3f70d2898b00c007683aaf170f18395', '7bc7dbebc5b029bb3ec79300ce16a0d70d933fbeb99a22cbaed7c485a4e635d3', 4),
('imp-ed9f34ecd475d031', 'bun-dau-mam-tom', 354, 'Bún đậu mắm tôm', 'Mẹt bún lá ép cắt miếng, đậu phụ chiên giòn nóng hổi, thịt ba chỉ luộc mềm, chả cốm thơm bùi chấm cùng bát mắm tôm đánh sủi bọt béo ngậy', 'Mẹt bún đậu mắm tôm đậm chất Hà thành quy tụ đủ hương vị từ đậu phụ mơ chiên vỏ giòn ruột béo, thịt ba chỉ luộc thái mỏng, chả cốm chiên thơm dẻo cùng bát mắm tôm pha quất, đường và dầu nóng đánh bông hấp dẫn.', 'Xếp bún lá cắt miếng, đậu phụ chiên vàng, chả cốm, thịt ba chỉ thái lát, dưa leo và rau tía tô, kinh giới, xà lách lên mẹt tre lót lá chuối, đặt bát mắm tôm đánh sủi bọt ở giữa để chấm ngập.', 'Món ngon nhất khi dùng ngay lúc đậu phụ và chả cốm còn nóng giòn; nếu dư thịt luộc hoặc đậu chiên, bảo quản ngăn mát tối đa 24 giờ và làm nóng đậu bằng nồi chiên không dầu ở 180°C trong 4 phút.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bún đậu mắm tôm","Hà Nội","Món mẹt","Ăn trưa"]', '["lunch","dinner"]', '["boil","deep_fry","assemble"]', '["crustaceans","pork","shrimp","soybean","sulphites"]', 938, 937.7, 3923, 36, 63.9, 19.9, 58.4, 5.4, 5.2, 1293, 3.23, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","NIN VN Gio Lua Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169231","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 171413","USDA FDC 172475","USDA FDC 173190","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647"]', '96be49bface0667d9580104d2d302cadd9e14c2c52ef03cfb4bbe49700750dea', '5cd9cba5d22ff33b4270ba59bb43856ec249157e79c7e689b27179be2effecbb', 4),
('imp-a744a977e7e4b165', 'hu-tieu-muc', 355, 'Hủ tiếu mực', 'Nước dùng ninh xương heo cùng tôm khô, khô mực nướng và củ cải trắng ngọt thanh trong veo, ăn kèm mực ống chần giòn sần sật và thịt heo băm xào thơm', 'Tô hủ tiếu mực Nam Bộ thanh nhẹ đầy đủ dinh dưỡng với nồi nước lèo trong vắt ngọt tự nhiên từ xương ống heo, củ cải trắng, tôm khô và khô mực nướng, kết hợp mực ống tươi giòn ngọt cùng thịt heo băm xào đậm đà.', 'Trụng hủ tiếu và giá đỗ cho vào tô, xếp mực ống khoanh, thịt băm xào, hẹ lá và cần tây lên trên, chan nước lèo sôi nóng và rắc hành tỏi phi vàng cùng tiêu xay và ớt thái lát.', 'Nước lèo và thịt băm bảo quản ngăn mát tối đa 2 ngày; mực ống tươi nên chần ngay trước khi ăn trong nước sôi để giữ độ giòn ngọt, không bị dai.', 'vietnamese', 'mon_bun_pho', 'nam', 'easy', 25, 60, 4, '/frigo/illustrations/delicious-meal.png', '["Hủ tiếu mực","Hải sản","Nước dùng trong","Nam Bộ"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["celery","crustaceans","fish","molluscs","pork","shrimp","squid"]', 617, 616.6, 2581, 39, 21.7, 6.4, 65.4, 3.9, 8.1, 2081, 5.2, '["MEXT Surume Ref","NIN VN Fresh Pho Noodle Ref","Pork Bone Stock Extraction Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167902","USDA FDC 168452","USDA FDC 169230","USDA FDC 169963","USDA FDC 169988","USDA FDC 169994","USDA FDC 170000","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC Sucrose Ref"]', '10a365540f3d8c375d969159ed8b615b5084bf8186395b7ff8d3a614184e4830', '4999282a1292828f4a1b2931488b137646088fae26e90e9f0ddb3cf57fcac9f1', 4),
('imp-c67f536bef1c38d6', 'bap-cai-kho-nam-chay', 356, 'Bắp cải kho nấm đùi gà chay', 'Bắp cải kho mềm ngọt cùng nấm đùi gà, cà rốt và đậu phụ chiên thấm đượm nước tương sánh đậm bữa cơm ngày rằm', 'Món kho chay ấm áp đưa cơm với từng miếng bắp cải mềm ngọt mà vẫn giữ được thớ lá, hòa quyện nấm đùi gà giòn sần sật, cà rốt và đậu phụ chiên ngấm đẫm nước sốt tương sánh nhẹ thơm mùi hành boa-rô và tiêu xay.', 'Múc bắp cải kho nấm ra đĩa sâu lòng khi còn nóng, rưới phần nước kho sánh lên mặt rồi rắc hành lá và tiêu đen xay; dùng kèm cơm trắng nóng.', 'Để nguội rồi bảo quản hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ 4–5 phút và thêm chút nước nếu cạn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món kho","Bắp cải","Nấm đùi gà","Ngày rằm"]', '["lunch","dinner"]', '["braise"]', '["soybean","wheat"]', 239, 239.4, 1002, 12, 13, 2, 24, 6.4, 10.6, 1494, 3.73, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172472","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '43fab93218dc01021504e654d0141e3abeaebb34a7a6274fc61507f140afc2f1', '52a4bc8a9060a3b75028490dd3b3feb0c263c179611919f7a5ba0a29c6936ae6', 4),
('imp-35deaaa123c7470d', 'nom-gia-chua-cay', 357, 'Nộm giá đỗ chua cay chay', 'Giá đỗ chần sơ giòn sần sật trộn cùng cà rốt bào sợi, nước mắm chay chanh tỏi ớt chua cay và đậu phộng rang bùi béo', 'Đĩa nộm giá đỗ chua cay chay thanh mát chống ngán với từng cọng giá đỗ trắng mập giòn sần sật, cà rốt cam tươi bào sợi, quyện đều nước trộn nước mắm chay chanh tỏi ớt hài hòa, thơm dịu rau húng quế và bùi béo đậu phộng rang.', 'Bày nộm giá ra đĩa, rắc thêm đậu phộng rang giã dập và húng quế thái nhỏ lên trên; dùng ngay như món khai vị hoặc ăn kèm các món kho chay.', 'Món nộm ngon nhất ngay sau khi trộn để giữ độ giòn ráo; nếu chuẩn bị trước, nên tách riêng phần rau củ ráo nước và phần nước trộn, chỉ trộn đều ngay trước khi dọn bữa.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Món nộm","Giá đỗ","Khai vị","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["peanut","soybean"]', 147, 147, 616, 6.9, 5.3, 0.7, 21.9, 4.2, 14.9, 816, 2.04, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 172232","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","Vegetarian Fish Sauce Ref"]', 'd1291fff8d6d03ec4023a82dea5f818a81a7af5be73cbefbdc457eb16bf5a7c2', 'ea10fad4f536d7827f22c2241b6eb39a061021f7980197c8f5408f05016df7c8', 4),
('imp-94b6bce7403fedc6', 'chao-nam-dau-phu', 358, 'Cháo nấm đậu phụ', 'Cháo gạo rang nấu mềm mịn quyện nấm đùi gà giòn ngọt, đậu phụ non béo thanh cùng gừng sợi và xì dầu dịu nhẹ', 'Tô cháo nấm đậu phụ thanh đạm dễ tiêu với hạt gạo tẻ kết hợp gạo nếp rang thơm sánh mịn, nấm đùi gà xào thơm giòn ngọt cùng đậu phụ trắng mềm béo, gừng tươi ấm bụng và hương xì dầu dịu nhẹ.', 'Múc cháo nóng ra tô, rắc hành lá, ngò rí, gừng thái sợi và tiêu đen xay; có thể chấm đậu phụ hoặc nêm thêm vài giọt xì dầu tùy khẩu vị.', 'Ngon nhất khi ăn nóng trong ngày. Nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, khi hâm nóng lại cần thêm chút nước sôi khuấy đều trên lửa nhỏ để cháo sánh mượt như mới.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 12, 28, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo chay","Nấm đùi gà","Đậu phụ","Thanh đạm","Dễ tiêu"]', '["breakfast","dinner"]', '["boil","simmer","stir_fry"]', '["soybean","wheat"]', 299, 299, 1251, 13.1, 7.6, 1.1, 46, 2.9, 2, 1035, 2.59, '["USDA FDC 168881","USDA FDC 169231","USDA FDC 169251","USDA FDC 169756","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'b4b4b61d4c4efe3c0476fde2667271a4b90586128bd78db878e5fbd8bebdadc1', 'e100e250074ded180108a3d871b7c1f7fb7dc44f62fd9dfda5f8d72df237e7ab', 4),
('imp-4f7a2cd919912ac9', 'mi-tron-trung-hanh', 359, 'Mì trộn trứng hành', 'Sợi mì dai săn trộn sốt xì dầu, dầu mè hành phi thơm nức, ăn kèm trứng chiên béo mềm và nhiều hành lá', 'Món mì trộn trứng hành siêu tốc chỉ trong 10 phút nhưng đậm đà khó cưỡng với từng sợi mì dai bóng không nát áo đều sốt xì dầu nước mắm, hương dầu hành phi thơm lừng, dầu mè béo nhẹ và trứng gà chiên vàng mềm.', 'Trộn đều mì nóng với nước sốt và dầu hành, xếp trứng chiên lên trên, rắc mè rang và tiêu xay rồi ăn nóng kèm tương ớt hoặc dưa leo thái lát.', 'Ngon nhất khi trộn và ăn ngay lúc mì còn nóng để sợi mì giữ độ dai săn, không bị trương nở.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Mì trộn","Ăn nhanh","Dưới 20 phút","Sinh viên","Tiết kiệm"]', '["breakfast","lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","fish","sesame","soybean","wheat"]', 485, 485.1, 2030, 17.2, 20.3, 3.9, 58.4, 3.2, 4.5, 1663, 4.16, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173647","USDA FDC 174277"]', '99c4f5d161f42b2fb0ff593a9672d6c7e423e2a01b226f0bf311476120c8fb53', 'c09e4b82495a82fb98f42e26a6a98a11c88784216cf3ed1cb281e0f93e2a1c7d', 4),
('imp-edac077a60dfa8b5', 'trung-kho-tra-trung-hoa', 360, 'Trứng gà kho trà vân đá ngũ vị', 'Trứng gà luộc lòng đào rạn vỏ ngâm ủ trong nước kho hoa hồi, quế thanh, nguyệt quế, tiêu Tứ Xuyên và xì dầu tạo hoa văn vân đá đẹp mắt', 'Món trứng kho vân đá truyền thống của ẩm thực đường phố Trung Hoa: những quả trứng gà luộc vừa chín tới được gõ rạn nhẹ lớp vỏ ngoài, rồi ngâm ủ trong nồi nước gia vị đậm hương hoa hồi, quế thanh, lá nguyệt quế, tiêu Tứ Xuyên và xì dầu cho ra đường vân đá nâu sẫm thơm bùi.', 'Bóc vỏ trứng kho vân đá, cắt đôi bày ăn kèm tô mì nước, cháo trắng hoặc dùng như món ăn vặt mặn thơm giàu đạm.', 'Giữ nguyên trứng chưa bóc vỏ ngâm trong nước kho ở ngăn mát tủ lạnh tối đa 4 ngày; dùng lạnh, ở nhiệt độ phòng hoặc hâm ấm nhẹ đều ngon.', 'chinese', 'mon_kho', NULL, 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Trứng kho trà","Vân đá","Ngũ vị","Ăn vặt","Trung Hoa"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["egg","soybean","wheat"]', 137, 136.7, 572, 11.6, 8.4, 2.8, 2.3, 0.2, 1.2, 878, 2.19, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 169231","USDA FDC 169655","USDA FDC 170917","USDA FDC 171287","USDA FDC 171316","USDA FDC 171320","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '12ba84fc176a5f79a5839ba435e28c719a0dbb9885f577397e749c9d7621a8bd', 'cd8ba3722cad50501036615d9a6cee44c3920c64e11a5923e092a413faab52b0', 4),
('imp-0efe9204d9dbdb3e', 'ga-chien-ot-kho', 361, 'Gà chiên giòn xóc ớt khô hoa tiêu Tứ Xuyên', 'Thịt đùi gà cắt miếng vừa ăn chiên giòn vàng rụm, đảo lửa nhỏ cùng ớt khô, hoa tiêu Tứ Xuyên, gừng tỏi và mè rang cay tê bùng nổ', 'Món Lạp Tử Kê trứ danh vùng Trùng Khánh – Tứ Xuyên: những miếng thịt đùi gà rút xương ướp gia vị chiên giòn rụm bên ngoài, mềm mọng bên trong, xóc thơm cùng ớt khô ngâm mềm, hoa tiêu Tứ Xuyên tê đầu lưỡi, gừng tỏi và mè trắng rang.', 'Trút gà chiên ớt khô ra đĩa rộng cùng toàn bộ gia vị thơm và dùng nóng ngay; thực khách gắp từng miếng gà giòn thơm trong đĩa ớt hấp dẫn.', 'Món ngon nhất khi dùng ngay lúc nóng giòn; nếu còn dư, bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 4 phút ở 180°C.', 'chinese', 'mon_chien', NULL, 'medium', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Gà chiên","Tứ Xuyên","Cay tê","Món nhậu","Giòn rụm"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["chicken","sesame","soybean","wheat"]', 316, 316.3, 1324, 23.2, 21.4, 4.7, 6.8, 1.7, 1.5, 573, 1.43, '["Shaoxing Wine Ref","Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170150","USDA FDC 170933","USDA FDC 171319","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', '384d037ed1e66bae64db993d43f041234bbbaca8bd2e44be9e130e4c46414816', 'd477e3e4e5c8170dd82aa574cfb1ca72fb18becf0a46d600e1167d9eef128ef7', 4),
('imp-0a1f8e0bd042cbfd', 'ba-chi-xao-bap-cai', 362, 'Thịt ba chỉ xào bắp cải giòn kiểu Trung', 'Những lát ba chỉ mỏng áp chảo xém cạnh tươm mỡ, xào lửa lớn cùng bắp cải ngọt giòn, tỏi gừng, rượu Thiệu Hưng và dầu mè thơm lừng', 'Món xào dân dã cực kỳ đưa cơm của ẩm thực Trung Hoa: thịt ba chỉ thái lát mỏng áp chảo xém cạnh cho tiết bớt mỡ béo ngậy, dùng chính phần mỡ thơm đó xào lửa lớn với bắp cải trắng xé miếng giòn ngọt, rưới xì dầu nhạt quanh thành chảo dậy hương chảo nóng.', 'Trút thịt ba chỉ xào bắp cải ra đĩa lớn, dùng nóng ngay với cơm trắng dẻo khi bắp cải còn giữ độ giòn ngọt mọng nước.', 'Món ngon nhất khi ăn nóng ngay lúc vừa xào để bắp cải không bị mềm nhũn; bảo quản ngăn mát tối đa 24 giờ và đảo nóng nhanh 2 phút trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Bắp cải","Món xào","Đưa cơm","Trung Hoa"]', '["lunch","dinner"]', '["stir_fry"]', '["pork","sesame","soybean","wheat"]', 662, 661.8, 2769, 12.9, 62, 20.6, 13.2, 3.4, 6.3, 1582, 3.95, '["Shaoxing Wine Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170106","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', 'edc888af37391d3a606f5bb96fb5f3f3c8b89fba7ec3d834351541aaa0850145', '2a3433af64513a48c4873dbaa5e85dc3b7adf9d204576aea214cc26933004ccc', 4),
('imp-ae6d3af49ade8384', 'cua-xao-gung-hanh', 363, 'Cua biển xào gừng hành kiểu Quảng Đông', 'Cua biển tươi chặt miếng chiên sơ khóa vị ngọt, xào nhanh cùng gừng lát, hành lá và sốt dầu hào sánh đậm chuẩn vị Quảng Đông', 'Món cua xào gừng hành kiểu Quảng Đông nổi bật với thịt cua săn ngọt, lớp vỏ thấm đẫm nước sốt dầu hào sánh nhẹ thơm nức mùi gừng phi, tỏi và hành lá tươi.', 'Dọn cua nóng ra đĩa sâu lòng, rưới hết phần sốt gừng hành lên mặt; thưởng thức ngay cùng cơm trắng nóng, chuẩn bị kẹp càng cua và khăn ướt.', 'Món hải sản ngon nhất khi dùng ngay trong bữa; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo lửa vừa với chút nước lọc.', 'chinese', 'mon_xao', NULL, 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món xào","Cua biển","Quảng Đông","Hải sản","Tiệc gia đình"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crab","crustaceans","molluscs","sesame","soybean","wheat"]', 257, 256.6, 1074, 24.4, 11.9, 1.8, 11.3, 0.7, 1.9, 679, 1.7, '["Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', '787b213b0bba2c4d41efb57a99d25f04049a966577f0911857d7c1fbe56358f7', '6e067df5cb5b30d7794d05ac0d87b94ff6635c26e94fb84cc91475da858b5d2e', 4),
('imp-122b920eba3f2e50', 'mi-xao-dau-phu', 364, 'Mì xào đậu phụ cải thảo kiểu Hoa', 'Sợi mì Udon dai mềm xào cùng đậu phụ áp chảo vàng giòn, cải thảo, cà rốt và sốt tương đen Hoisin đậm đà kiểu Trung Hoa', 'Đĩa mì xào đậu phụ kiểu Hoa hài hòa giữa sợi mì Udon mềm dai thấm đẫm sốt tương Hoisin sánh bóng, đậu phụ vàng ruộm bên ngoài béo mềm bên trong cùng cải thảo và cà rốt giòn ngọt.', 'Chia mì nóng ra đĩa, rắc thêm chút tiêu xay hoặc hành lá, có thể dọn kèm ít tương ớt nếu thích vị cay nhẹ.', 'Mì xào ngon nhất khi ăn nóng ngay sau khi nấu; nếu dư có thể bảo quản hộp kín trong ngăn mát 1 ngày và xào lại nhanh với 1 muỗng canh nước lọc.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Đậu phụ","Món chay","Nhanh gọn","Cải thảo"]', '["lunch","dinner"]', '["boil","pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 411, 410.6, 1717, 18.1, 17.8, 2.6, 46.3, 5, 8.3, 877, 2.19, '["MEXT Boiled/Fresh Udon","Shaoxing Wine Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 169977","USDA FDC 170005","USDA FDC 170393","USDA FDC 171028","USDA FDC 171370","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '970936443e0d5419c3c731500b93aec739e6a176a3e1552121e75fc4590046d4', '25add1b9996b287d2a6e851fc2b491fa24b450cabf170e21428d33c72e062663', 4),
('imp-01ae566db4a7feab', 'sup-bo-nam-trung', 365, 'Súp thịt bò nấm đùi gà kiểu Hoa', 'Súp bò nấm thanh ngọt từ nước hầm bò cùng thịt thăn bò mềm mọng, nấm đùi gà giòn sần sật, gừng ấm và tiêu trắng dậy hương', 'Tô súp thịt bò nấm đùi gà kiểu Hoa ấm nóng với nước dùng trong ngọt thanh vị nấm và gừng, những lát thịt bò chín tới mềm ngọt quyện chút sánh mịn nhẹ dịu và hương dầu mè tiêu trắng.', 'Múc súp nóng ra tô sâu lòng, rắc hành lá tươi và thêm chút tiêu trắng xay; dùng làm món khai vị hoặc ăn kèm cơm trắng nóng.', 'Ngon nhất khi thưởng thức ngay lúc nóng để thịt bò không bị dai; phần súp dư bảo quản ngăn mát tối đa 24 giờ và đun sôi lăn tăn lại trên lửa nhỏ.', 'chinese', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món súp","Thịt bò","Nấm đùi gà","Thanh ngọt","Ấm bụng"]', '["lunch","dinner"]', '["simmer"]', '["beef","sesame","soybean","wheat"]', 281, 281.2, 1176, 28, 13.5, 4.9, 11.9, 2.2, 1.8, 1539, 3.85, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170187","USDA FDC 170933","USDA FDC 171028","USDA FDC 171593","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'd73e1f4d5f99fb0007ce1d7705ed4224e17d386fd09cbc7807df50f79604dc1e', '6ccfad13d727887f71c5089388a6ce13c710f6d182ef9b787fe571e89a04523c', 4),
('imp-296dbce4d9098a2e', 'ca-nuong-tuong', 366, 'Cá chẽm nướng xì dầu hành gừng', 'Phi lê cá thịt trắng nướng giấy bạc mềm mọng thấm sốt xì dầu ngọt dịu, rưới dầu mè phi hành gừng tỏi thơm nức kiểu Trung Hoa', 'Những miếng phi lê cá chẽm trắng muốt, mềm mọng tự nhiên sau khi nướng kín giấy bạc cùng gừng hành và xì dầu nhạt, nổi bật với lớp dầu mè phi tỏi hành nóng hổi rưới lên mặt khi dọn.', 'Gắp cá nướng ra đĩa sâu lòng, chan phần nước sốt xì dầu trong khay cùng hành gừng phi dầu mè lên trên; ăn nóng kèm cơm trắng và rau cải luộc.', 'Bảo quản cá nướng trong hộp kín ở ngăn mát tủ lạnh tối đa 24 giờ; khi dùng hâm lại ở lò 160°C trong 6–8 phút hoặc hấp cách thủy 5 phút để thịt cá không bị khô.', 'chinese', 'mon_lau_tiec', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Phi lê cá","Xì dầu","Hành gừng","Bữa tối"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","sesame","soybean","wheat"]', 275, 274.7, 1150, 37.6, 10.8, 2.1, 5.5, 0.7, 2, 1236, 3.09, '["USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175148"]', '73173933b7130ec909e6655046baa65d903b7d0cb0ecfd8703816f3ec0c8130a', 'd5fe46e9381fd47055e8af79b5feb3c996717910f04bbe528962909461c85ccf', 4),
('imp-0a43bfa1d02fa497', 'rau-bina-tron-toi', 367, 'Cải bó xôi trộn tỏi dầu mè', 'Cải bó xôi chần nhanh ngâm nước đá giữ màu xanh mướt, trộn tỏi băm, xì dầu nhạt, giấm đen Trấn Giang và mè trắng rang thanh mát', 'Món khai vị lạnh kiểu Trung Hoa thanh mát với từng cọng cải bó xôi xanh mướt giòn ngọt, quyện đều nước sốt chua mặn dịu từ giấm đen Trấn Giang, xì dầu, tỏi băm và dầu mè thơm lừng.', 'Bày rau trộn ra đĩa nông lòng, rắc hạt mè trắng rang lên trên; dùng mát như món khai vị hoặc ăn kèm các món kho, món chiên để giải ngấy.', 'Món trộn lạnh dùng ngon nhất trong ngày; nếu chưa ăn ngay, đậy kín bảo quản ngăn mát tối đa 12 giờ và trộn đều lại trước khi dọn.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 10, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cải bó xôi","Khai vị","Thanh mát","Món chay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 97, 97.2, 406, 4.7, 5.8, 0.8, 8.9, 3.2, 2.4, 793, 1.98, '["Chinkiang Black Vinegar Ref","USDA FDC 168462","USDA FDC 169230","USDA FDC 169655","USDA FDC 170150","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref"]', '0bc7e3cd6443b1da341a25e97d7699e93824fe163e0c2f1104cd6d2be9588a5b', '7e98c61d165844b4b863e5d900939aa37ad637c5b7771867e0d6bc35fe857839', 4),
('imp-329f0579ddc26919', 'ca-chua-tron-toi', 368, 'Cà chua trộn tỏi dầu mè kiểu Hoa', 'Cà chua chín đỏ chần lột vỏ thái múi cau, ướp lạnh thấm đẫm sốt tỏi băm, xì dầu nhạt, giấm gạo và dầu mè thanh mát giải ngấy', 'Món cà chua trộn lạnh thanh ngọt giải ngấy với từng múi cà chua bóc vỏ mềm mọng, thấm đượm vị chua ngọt dịu của giấm gạo đường cát, hòa quyện hương tỏi phi nhẹ, xì dầu và dầu mè thơm nồng.', 'Xếp cà chua ướp lạnh ra đĩa sâu lòng, rưới phần nước sốt dưới đáy tô lên mặt, rắc hành lá xanh và ngò rí; ăn lạnh làm món khai vị hoặc kèm các món chiên nướng.', 'Món ăn lạnh không cần hâm nóng; nên thưởng thức trong vòng 4–6 giờ sau khi ướp để cà chua giữ được độ tươi giòn, tránh để quá lâu ở nhiệt độ phòng.', 'chinese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Món trộn","Cà chua","Khai vị","Thanh mát","Món chay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["sesame","soybean","wheat"]', 123, 123.1, 515, 2.6, 7.9, 1.1, 12, 2.2, 7.5, 830, 2.08, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 171028","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'fdd73a1346c6970cc303a87d476fefc238bf4666324ef92c534b7dd1be21e22c', 'a0df65f866d26ff18f44aca79ae35869be8e4b8420d723107ad150539182f39e', 4),
('imp-59f5760d6349d284', 'nam-nhoi-thit-hap', 369, 'Nấm đùi gà nhồi thịt hấp xì dầu', 'Nấm đùi gà thớ chắc nhồi nhân thịt heo xay quết dẻo cùng trứng gà, hấp chín mọng ngọt rồi rưới sốt dầu hào xì dầu sánh bóng', 'Những miếng nấm đùi gà giòn ngọt tự nhiên ôm lấy phần nhân thịt heo xay mềm dẻo đậm hương gừng hành và dầu hào, hấp chín tới giữ trọn nước ngọt rồi phủ lớp sốt sánh bóng thơm mùi dầu mè.', 'Xếp nấm nhồi thịt ra đĩa nóng, rưới sốt dầu hào sánh mịn và rắc hành lá xanh thái nhỏ; dùng ngay cùng cơm trắng nóng.', 'Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn hấp cách thủy 5–7 phút cho nóng đều và giữ nguyên độ ẩm của nhân thịt.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Nấm đùi gà","Thịt băm","Khéo tay","Cơm nhà"]', '["lunch","dinner"]', '["steam","simmer"]', '["egg","molluscs","pork","sesame","soybean","wheat"]', 362, 361.9, 1514, 22.8, 23.9, 8.5, 14.2, 2.9, 4.3, 1054, 2.64, '["Shaoxing Wine Ref","USDA FDC 167902","USDA FDC 168580","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171369","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'a894daa684785b91de51c6a01b4de176a4c4dadd24c12ea80e110825f03edbb1', '2a6ced45abecb9459f3d941c6f8809601f34f96a9daa8ad54faa914ee5fbd4b1', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-d8001a64eeaa9150', 'com-tron-trung-tan-nhat', 370, 'Cơm trộn trứng Nhật (Tamago Kake Gohan)', 'Cơm trắng hạt ngắn nóng bốc hơi trộn trứng gà tươi đánh quyện cùng xì dầu Nhật, cá bào Katsuobushi và rong biển Nori béo mịn chuẩn bữa sáng Nhật', 'Món cơm trộn trứng Tamago Kake Gohan trứ danh của Nhật Bản: hơi nóng từ cơm mới nấu làm trứng gà tươi tiệt trùng chín nhẹ thành lớp sốt kem vàng óng mịn màng, hòa quyện vị umami của xì dầu Nhật, cá bào Katsuobushi và rong biển Nori.', 'Trộn đều mạnh tay ngay khi cơm còn thật nóng cho đến khi trứng nổi bọt mịn bao quanh từng hạt cơm, rắc thêm hành lá và mè rang rồi ăn kèm dưa muối Nhật hoặc súp Miso.', 'Món ăn sử dụng trứng tươi đánh với cơm nóng nên phải thưởng thức ngay lập tức sau khi trộn; tuyệt đối không bảo quản lại hay để qua bữa.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 5, 5, 2, '/frigo/illustrations/delicious-meal.png', '["Tamago Kake Gohan","Cơm trộn trứng","Bữa sáng nhanh","Nhật Bản","Tối giản"]', '["breakfast","lunch"]', '["assemble","toss_mix"]', '["egg","fish","sesame","soybean","wheat"]', 342, 342, 1431, 15.1, 6.1, 1.7, 54.2, 1.4, 1.6, 721, 1.8, '["MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 171287","USDA FDC 174277"]', '19afc6f619d217d355aeaf9aba798610f71ddc08ac43465453dbb12babde01e3', '2c9333f162aedf66e0cc8fbce6dc9c30375a9077ba1c4093fc0e3b6de110d151', 4),
('imp-e420d7a0eed8a0d6', 'tom-sot-cay-nhat', 371, 'Tôm sốt cay Nhật Bản (Ebi Chili)', 'Tôm tươi áp chảo giòn ngọt quyện sốt cà cay thơm nồng ấm từ tương ớt đậu bản Doubanjiang, tương cà, gừng tỏi và rượu Sake kiểu Yoshoku Nhật Bản', 'Món Ebi Chili trứ danh trong ẩm thực Nhật Bản: tôm tươi sơ chế sạch giòn sần sật được áp chảo nhanh tay giữ trọn độ ngọt, sau đó áo đều lớp sốt đỏ óng sánh mịn hòa quyện vị cay thơm lên men của Doubanjiang và vị chua ngọt dịu từ tương cà.', 'Múc tôm sốt cay ra đĩa nóng, rắc thêm phần lá xanh hành lá thái nhỏ; dùng kèm cơm trắng nóng hoặc mì xào rau củ đều rất bắt vị.', 'Món tôm ngon nhất khi ăn nóng ngay vừa nấu xong; nếu còn thừa, đậy kín bảo quản ngăn mát tối đa 2 ngày và hâm nhanh trên chảo lửa vừa với 1 muỗng canh nước lọc để tôm không bị dai.', 'japanese', 'mon_xao', NULL, 'medium', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Ebi Chili","Tôm sốt cay","Yoshoku","Nhật Bản","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 273, 273.1, 1143, 25.8, 10.3, 1.6, 18.4, 0.9, 7.4, 1343, 3.36, '["MEXT Sake 16021","Pixian Doubanjiang Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '8febca6b675e777d608a428b9181c75823b72952ffec8ffd3c7f1f56c70bf979', '55a79d3eb495badd92a4859e611604ab1e2d7abee9587df42e95766cd5d8109a', 4),
('imp-2138056075abd874', 'salad-dau-phu-dua-leo', 372, 'Salad đậu phụ dưa leo kiểu Nhật', 'Đậu phụ trắng ép ráo cắt khối mềm mịn trộn cùng dưa leo giòn mát, hành lá và sốt tương Miso trắng giấm gạo dầu ô liu mè rang thanh nhẹ', 'Món salad lạnh kiểu Nhật hài hòa kết cấu giữa đậu phụ trắng mềm béo đã ép ráo nước, dưa leo tươi giòn mát và lớp sốt trộn sánh thơm từ tương Miso trắng, giấm gạo, xì dầu Nhật, dầu ô liu và mè trắng rang.', 'Dọn salad đậu phụ dưa leo lạnh mát ra tô hoặc đĩa sâu lòng, rắc thêm hạt mè rang lên mặt; rất thích hợp dùng làm món khai vị hoặc món ăn kèm chống ngán cho các món chiên nướng.', 'Salad đậu phụ ngon nhất khi ăn trong ngày ngay sau khi làm lạnh 10 phút; nếu bảo quản qua đêm trong tủ lạnh, dưa leo có thể tiết nước làm loãng sốt.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 3, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Đậu phụ","Dưa leo","Thanh mát","Món chay nhẹ"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["sesame","soybean","wheat"]', 253, 252.6, 1057, 14.1, 18.5, 2.6, 11.5, 3, 4.2, 1034, 2.58, '["USDA FDC 168409","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 171413","USDA FDC 172238","USDA FDC 172446","USDA FDC 172475","USDA FDC 174277"]', '5d84a2afde3240c01848d79165385e4be1c53d792ac17a3a4d8b9752c69e47be', '6653ebb1cd0a86b1bb8865456cf75160a3835eb9daaa6e781241d95fa7170142', 4),
('imp-ff9fd0fdcdd85b79', 'bap-cai-nuong-bo', 373, 'Bắp cải áp chảo bơ xì dầu kiểu Nhật', 'Bắp cải tươi cắt miếng dày áp chảo xém cạnh ngọt thơm quyện bơ lạt tan chảy, tỏi lát, xì dầu Nhật và cá bào Katsuobushi chuẩn món nhắm Izakaya', 'Món bắp cải áp chảo bơ xì dầu đơn giản mà cuốn hút theo phong cách quán Izakaya Nhật Bản: từng miếng bắp cải được nướng xém vàng tự nhiên giữ trọn vị ngọt giòn, thấm đẫm hương béo thơm của bơ lạt quyện xì dầu Nhật và tỏi phi.', 'Dọn bắp cải áp chảo nóng hổi ra đĩa, rắc thêm hành lá xanh và ít cá bào khô Katsuobushi lên mặt; ăn kèm cơm nóng hoặc dùng làm món rau phụ cân bằng bữa tiệc nướng.', 'Món ăn ngon nhất khi thưởng thức nóng ngay sau khi chế biến lúc bơ còn thơm béo; nếu còn dư, bảo quản ngăn mát tối đa 1 ngày và áp chảo lại nhanh trên lửa vừa 2 phút trước khi ăn.', 'japanese', 'mon_xao', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Izakaya","Bắp cải áp chảo","Bơ xì dầu","Món phụ Nhật","Nhanh gọn"]', '["lunch","dinner"]', '["pan_fry"]', '["fish","milk","soybean","wheat"]', 128, 127.6, 534, 3.6, 9.7, 4.7, 8.3, 3.2, 3.8, 607, 1.52, '["MEXT Katsuobushi 10099","USDA FDC 169230","USDA FDC 169975","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277"]', '1ac81c8acee98823cc4ade2e7c9ef1361ece2d78a71a0041b494ce841442cfdf', '3c539a042caf9e7d85217bf31a2ef8a0677d150f04031e1d6d7e8837a94ab30c', 4),
('imp-d6e35b3fa19080de', 'trung-om-nam-nhat', 374, 'Trứng om nấm đùi gà kiểu Nhật', 'Nấm đùi gà om mềm trong nước dùng Dashi xì dầu Mirin thanh ngọt rồi phủ trứng gà đánh tan om chín mượt mà, ấm bụng cho bữa cơm nhẹ', 'Món trứng om nấm Tamago-toji kiểu gia đình Nhật với nấm đùi gà thái lát sần sật thấm đẫm nước dùng Dashi pha xì dầu nhạt, rượu Mirin và Sake, ôm trọn bởi lớp trứng gà đánh mịn chín mềm vừa tới.', 'Múc trứng om nấm ra tô cùng ít nước dùng thanh ngọt, rắc hành lá xanh và tiêu đen xay nếu thích; dùng nóng trực tiếp chan lên cơm trắng hoặc ăn kèm mì Udon.', 'Món trứng om ngon nhất khi thưởng thức nóng ngay sau khi nấu để giữ độ mềm mượt của trứng; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 1 ngày và hâm ấm nhẹ trên lửa nhỏ, tránh đun sôi làm trứng bị khô xác.', 'japanese', 'mon_kho', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Trứng gà","Nấm đùi gà","Nhanh gọn","Ấm bụng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","soybean","wheat"]', 165, 165.2, 691, 12.9, 7.3, 2.3, 11.3, 1.8, 6.1, 1019, 2.55, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 174277"]', 'f14fae2f30afb6f5d41d546b6f26e25e48134445d4de727d13e337a0a8c12ea3', '568f6e647ed88e6e92ae8dbf2d4b7816900e5cdea02859b4f9a2bd82692230b6', 4),
('imp-cc88c6bd94df496e', 'canh-cua-nam-nhat', 375, 'Canh trong cua thịt nấm đùi gà kiểu Nhật', 'Nước dùng Dashi thanh trong nấu cùng thịt cua hấp gỡ sợi ngọt biển, nấm đùi gà lát mỏng, rượu Sake và hành lá kiểu Osuimono trang nhã', 'Món canh trong Osuimono trang nhã của Nhật Bản: nền nước dùng Dashi kết hợp vị ngọt thanh của nấm đùi gà và từng thớ thịt cua biển tươi ngọt, nêm nhẹ với xì dầu nhạt để giữ nước canh trong vắt mà đậm đà hương vị umami.', 'Múc canh nóng ra 3 bát có nắp hoặc tô sứ nhỏ, chia đều thịt cua và nấm đùi gà, rắc hành lá thái khoanh lên mặt; dùng làm món canh khai vị hoặc dùng kèm bữa cơm gia đình thanh nhẹ.', 'Canh ngon nhất khi thưởng thức nóng ngay sau khi nấu để giữ trọn mùi thơm và độ ngọt của thịt cua; nếu còn dư, đậy kín để ngăn mát tối đa 1 ngày và hâm nóng nhẹ lửa vừa đến khi vừa sôi lăn tăn.', 'japanese', 'mon_canh', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Canh trong Nhật","Thịt cua","Nấm đùi gà","Umami","Thanh đạm"]', '["lunch","dinner"]', '["simmer"]', '["crab","crustaceans","fish","soybean","wheat"]', 84, 84.4, 353, 14.4, 0.9, 0.2, 4, 1.3, 0.7, 904, 2.26, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 170005","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","USDA FDC 174277"]', '75edfbb84128d835a1b87c525b1809e692445d8fb38890973bc502a69acafab1', '37d1e49dbeadf2dc35e07bd90b3ec945cfb7c70534e1e96b62e740bdb96870c9', 4),
('imp-df7a6429150724b1', 'tom-om-ca-chua-nhat', 376, 'Tôm om cà chua kiểu Nhật (Yoshoku)', 'Tôm tươi áp chảo săn ngọt om cùng cà chua chín nhừ, hành tây, tỏi thơm trong nước sốt xì dầu tương cà Sake đậm đà phong cách Yoshoku chan cơm', 'Món tôm om cà chua phong cách Yoshoku hiện đại của Nhật Bản: tôm tươi áp chảo nhanh tay giữ độ giòn ngọt, hòa quyện trong nước sốt cà chua tươi nấu nhừ cùng hành tây, tương cà, xì dầu Nhật và rượu Sake thơm lừng.', 'Múc tôm om cà chua ra đĩa sâu lòng khi còn nóng hổi, rắc hành lá xanh thái khoanh lên mặt; dùng chan trực tiếp lên cơm trắng nóng hổi.', 'Nên dùng hết trong ngày để tôm giữ được độ giòn ngọt; nếu bảo quản ngăn mát tối đa 2 ngày, tách riêng phần tôm hoặc hâm nhanh lửa vừa trong 2 phút cho vừa nóng tới.', 'japanese', 'mon_kho', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Yoshoku","Tôm tươi","Cà chua","Chan cơm"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 182, 181.7, 760, 22.2, 5.1, 0.8, 11.8, 2, 7, 825, 2.06, '["MEXT Sake 16021","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '0c92ea97488a5fe7a33d6652b34846c3c5f1af0057dbba40cfff235b9d027342', 'de17a798b71ef30441393d7f5f7dba4c48a1462a4a4a33ef703e520bf1203147', 4),
('imp-9157234945e6ff01', 'ga-ham-dak-jjim', 377, 'Gà hầm tương kiểu Andong (Andong Jjimdak)', 'Đùi gà hầm mềm quyện sốt tương đen Chunjang, dầu hào và siro ngô cùng miến khoai lang dai trong, khoai tây, cà rốt', 'Andong Jjimdak là món gà hầm nổi tiếng xuất xứ từ vùng Andong, Hàn Quốc. Thịt đùi gà được áp chảo săn rồi hầm cùng khoai tây, cà rốt, nấm đùi gà và miến khoai lang trong hỗn hợp sốt tương, dầu hào, siro ngô và chút tương đen Chunjang tạo màu nâu óng đậm vị mặn ngọt hài hòa.', 'Bày nguyên chảo hoặc múc gà, miến và rau củ ra đĩa sâu lòng, đặt dưa leo thái lát và hành lá thái sợi lên trên, rắc mè rang rồi ăn nóng kèm cơm trắng.', 'Gà và rau củ có thể bảo quản ngăn mát tủ lạnh tới 2 ngày (lưu ý miến để lâu sẽ hút hết sốt và nở mềm, nên thêm chút nước khi hâm trên lửa nhỏ).', 'korean', 'mon_kho', NULL, 'medium', 35, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Andong jjimdak","Gà hầm","Hàn Quốc","Miến Hàn","Đậm đà"]', '["lunch","dinner"]', '["braise"]', '["chicken","molluscs","sesame","soybean","wheat"]', 628, 628.3, 2630, 37.5, 27.1, 6.2, 59.9, 4.7, 19.1, 1721, 4.3, '["Korean Chunjang Ref","USDA FDC 168409","USDA FDC 168580","USDA FDC 168836","USDA FDC 168952","USDA FDC 169230","USDA FDC 169231","USDA FDC 170000","USDA FDC 170005","USDA FDC 170026","USDA FDC 170106","USDA FDC 170150","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '1582f187a40f70bebd7650e6bbe0622be01dcdb04d856937df72a18e0ca76a4f', '22e60653d287953d49c3bd3dd2a6d240a3ff6cc62fd9598eddba2075cbd66fd7', 4),
('imp-aedcf1c5c1d05d04', 'tom-xao-tuong-han', 378, 'Tôm xào sốt tương bơ tỏi kiểu Hàn', 'Tôm tươi săn giòn xào lửa lớn với bơ tỏi thơm ngậy, nước tương, rượu ngọt Mirin và hành lá xanh mướt', 'Tôm xào sốt tương bơ tỏi kiểu Hàn là món ăn đưa cơm nhanh gọn chỉ mất 20 phút. Tôm tươi bóc vỏ ướp nhẹ muối tiêu được xào nhanh trên chảo bơ tỏi thơm lừng rồi áo đều lớp sốt nước tương, rượu mirin và chút đường tạo độ bóng mặn ngọt hài hòa.', 'Trút tôm nóng ra đĩa, rắc thêm hạt mè trắng rang và hành lá; dùng ngay với cơm trắng nóng dẻo.', 'Tôm xào ngon nhất khi ăn ngay lúc vừa chế biến; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ nên đảo ấm lại trên chảo trong 1 phút để tôm không bị khô dai.', 'korean', 'mon_xao', NULL, 'easy', 12, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm xào","Bơ tỏi","Hàn Quốc","Banchan","Món nhanh"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","milk","sesame","shrimp","soybean","wheat"]', 212, 212, 887, 20.2, 10.2, 3.1, 10.2, 1.1, 5.5, 783, 1.96, '["MEXT Hon-Mirin 16031","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5fca005daf1c2f00542c62bb1e170aecb0c2013885b97cc1dba0d9e977e6dfa6', '76e11cec84031e27fbd2b8caf15b59d1b324d14ae34af731005a7957821a1bae', 4),
('imp-e39a1be406f9e1ea', 'trung-hap-han', 379, 'Trứng hấp xốp kiểu Hàn (Gyeran Jjim)', 'Trứng hấp bông xốp phồng cao mềm tan trong miệng, đậm vị nước mắm, nước tương và thơm lừng dầu mè hành lá', 'Gyeran Jjim là món trứng hấp nổi tiếng thường được phục vụ nóng hổi trong thố đất tại các quán thịt nướng Hàn Quốc. Bằng kỹ thuật khuấy nhẹ giữa chừng khi nấu trong nồi đáy dày hoặc nồi đất đậy nắp kín, trứng nở phồng bông xốp như bánh souffle nhưng vẫn giữ độ ẩm mềm mịn tan ngay đầu lưỡi.', 'Dọn nguyên thố hoặc nồi đất còn đang bốc hơi nghi ngút, rắc thêm hành lá, ớt bột Hàn và hạt mè rang; ăn nóng ngay kèm cơm trắng và thịt nướng.', 'Trứng hấp Gyeran Jjim ngon nhất khi thưởng thức ngay lúc vừa tắt bếp vì sẽ xẹp nhẹ khi nguội; nếu còn dư bảo quản ngăn mát tối đa 24 giờ.', 'korean', 'mon_hap_luoc', NULL, 'easy', 5, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Gyeran jjim","Trứng hấp","Hàn Quốc","Bông xốp","Món nhanh"]', '["breakfast","lunch","dinner"]', '["steam"]', '["egg","fish","sesame","soybean","wheat"]', 146, 145.6, 609, 10.1, 10.1, 2.7, 3.5, 0.7, 1.8, 529, 1.32, '["Korean Chili Flake Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '62f750f3590596be60da0d6a48da6ca9d233379acf240b0e0c65a77f8e393bef', 'c7b1bff8333d19ec81340ebaff34a379fb43bba4dcee12ac14decccdfc7e5c6a', 4),
('imp-da5a134e2654eeb5', 'dau-phu-tron-kimchi', 380, 'Đậu phụ luộc trộn kim chi xào kiểu Hàn (Dubu Kimchi)', 'Đậu phụ luộc mềm ấm xếp cạnh kim chi cải thảo xào sốt Gochujang cay đậm thơm mùi gừng tỏi và dầu mè', 'Đậu phụ trộn kim chi xào (Dubu Kimchi) là sự đối lập đầy tinh tế giữa những lát đậu phụ trắng luộc mềm mát, thanh vị với phần kim chi cải thảo xào nóng hổi đậm đà vị chua cay của tương ớt Gochujang, tỏi gừng và dầu mè rang. Đây vừa là món khai vị thanh nhẹ vừa là món nhậu truyền thống rất được yêu thích ở Hàn Quốc.', 'Xếp các lát đậu phụ quanh viền đĩa lớn, múc phần kim chi xào nóng vào giữa, rắc hành lá và mè rang lên trên; gắp một lát đậu phụ kẹp cùng kim chi thưởng thức.', 'Nên dùng ngay khi đậu phụ còn ấm mềm và kim chi còn nóng; nếu còn dư, tách riêng đậu phụ và kim chi xào bảo quản ngăn mát tối đa 24 giờ.', 'korean', 'mon_chay', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi","Hàn Quốc","Khai vị"]', '["lunch","dinner"]', '["boil","stir_fry","assemble"]', '["sesame","soybean","wheat"]', 281, 281.1, 1176, 19, 17.3, 2.5, 17.9, 4.4, 9.1, 1046, 2.61, '["USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'b744f56a9f63bebf9ff60675a249fe5d01a3911b77666e1b93bd92d8ec67974b', '8e1d9227130e1e6e63932153b3fbd444d83c23915015c032f1f7e721ef320f75', 4),
('imp-8cd9bb1abdd63a9e', 'mi-lanh-naengmyeon', 381, 'Mì lạnh nước kiểu Hàn (Mul Naengmyeon)', 'Sợi mì kiều mạch dai giòn ngập trong nước dùng bò dăm đá chua ngọt thanh mát, ăn kèm thịt bò luộc, củ cải muối và trứng luộc', 'Mì lạnh Mul Naengmyeon là đặc sản giải nhiệt mùa hè trứ danh của ẩm thực Hàn Quốc. Sợi mì kiều mạch được luộc chín vừa rồi xả kỹ qua nước đá lạnh để đạt độ dai giòn sần sật, chan nước hầm thịt bò lọc sạch mỡ pha giấm đường và mù tạt vàng cay dịu lạnh buốt.', 'Xếp mì cuộn gọn vào tô lạnh, chan nước dùng dăm đá men theo thành tô, bày thịt bò thái lát, củ cải trộn, dưa leo và trứng luộc bổ đôi lên trên; ăn ngay khi còn lạnh.', 'Nước dùng bò đã nêm có thể giữ lạnh trong ngăn mát 2–3 ngày hoặc cấp đông trước để tạo lớp dăm đá; chỉ luộc mì ngay trước khi ăn để sợi mì không bị bở.', 'korean', 'mon_bun_pho', NULL, 'medium', 30, 60, 3, '/frigo/illustrations/delicious-meal.png', '["Naengmyeon","Mì lạnh","Hàn Quốc","Mùa hè","Thịt bò"]', '["lunch","dinner"]', '["boil","simmer","assemble"]', '["beef","buckwheat","egg","mustard","sesame","soybean","wheat"]', 617, 617.3, 2583, 33, 17.3, 6.1, 83.4, 5.3, 12.8, 1993, 4.98, '["Korean Chili Flake Ref","MEXT Dry Soba 01097","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170198","USDA FDC 171287","USDA FDC 172234","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'bc12a59c8c9e58159c685edb54512e3ef946b3fa492a8c5f438b1833ccffcf5f', 'e106f4760c65ae8d6a0ae7432790880dbec594cfb5e2d896f8fe47e2f09b8e53', 4),
('imp-a631650d667191b4', 'muc-nuong-cay-han', 382, 'Mực nướng sốt cay kiểu Hàn (Ojingeo Gui)', 'Mực tươi khứa caro ướp sốt Gochujang siro ngô cay ngọt, nướng xém cạnh thơm lừng cuốn lá tía tô và chanh tươi', 'Mực nướng cay Ojingeo Gui là món nhậu (anju) khoái khẩu tại các quán nướng Hàn Quốc. Thân mực tươi được chà muối sạch nhớt, khứa caro nông và ướp thấm sốt tương ớt Gochujang, ớt bột Hàn, siro ngô và chút mù tạt vàng, khi nướng trên lửa lớn chỉ 4–5 phút là mực săn giòn, áo lớp sốt đỏ bóng thơm nức.', 'Bày mực nướng lên đĩa lót lá tía tô thái sợi, rắc hành lá, mè trắng rang, rưới dầu mè và vắt chút nước cốt chanh vàng; cắt khoanh bằng kéo ngay trước khi ăn nóng.', 'Nên thưởng thức ngay lúc vừa nướng xong để giữ độ giòn ngọt của mực; mực đã ướp sốt có thể giữ lạnh tối đa 12 giờ trước khi nướng.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Ojingeo gui","Mực nướng","Hàn Quốc","Món nhậu","Cay ngọt"]', '["lunch","dinner"]', '["grill_roast"]', '["molluscs","mustard","sesame","soybean","squid","wheat"]', 300, 300.3, 1257, 24.6, 7.7, 1.4, 32.8, 2.6, 19.7, 879, 2.2, '["Korean Chili Flake Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA FDC 167746","USDA FDC 168836","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172234","USDA FDC 173468","USDA FDC 174223","USDA FDC 174277"]', 'bb16ee2f752c5a172fd3fb3ff5ec3e04e8327951152c347dd298c4c960606b62', '88cf0c248858ad1e1053f5e74cd5b89b4ced97f4e43fc3aaaa7586395665e9b4', 4),
('imp-2a958e709ba9cb7c', 'dau-phu-xao-kimchi', 383, 'Đậu phụ áp chảo kim chi xào cay (Dubu Kimchi)', 'Đậu phụ áp chảo vàng ruộm hai mặt ăn kèm kim chi xào cay đậm Gochujang thơm mùi tỏi phi và hành tây ngọt', 'Phiên bản đậu phụ áp chảo kim chi xào cay (Dubu Kimchi) mang đến kết cấu giòn nhẹ bên ngoài của từng miếng đậu phụ vàng ruộm, hòa quyện cùng đĩa kim chi cải thảo xào sốt Gochujang đỏ óng cay nồng, rất thích hợp ăn cùng cơm trắng nóng hoặc làm món nhắm cuối tuần.', 'Xếp đậu phụ áp chảo nóng cạnh phần kim chi xào, rắc hành lá và hạt mè trắng rang lên trên; dùng nóng cùng cơm trắng hoặc đồ uống lạnh.', 'Ngon nhất khi ăn nóng ngay để cảm nhận vỏ đậu phụ còn giòn; nếu còn dư bảo quản hộp kín ngăn mát tối đa 24 giờ và áp chảo ấm lại trước khi dùng.', 'korean', 'mon_xao', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu kimchi","Đậu phụ","Kim chi xào","Hàn Quốc","Món nhậu"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 251, 251, 1050, 15.1, 15.6, 2.3, 17.6, 4.5, 8.8, 1004, 2.51, '["Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'b4f5cf3281dd4724f8f8c334581ba727d8944427ac4e5060f06e712fb7c51818', '43259ad3705221db35076429a6d5790f7f8394722ef53e20852e16b717eb565a', 4),
('imp-1f3a7df71f4cbc77', 'suon-nuong-galbi', 384, 'Sườn bò nướng LA Galbi kiểu Hàn', 'Sườn bò cắt ngang ướp sốt tương hành tây, tỏi gừng, mật ong và dầu mè nướng than xém cạnh thơm lừng, ăn kèm ssamjang và rau cuốn', 'LA Galbi là món sườn bò cắt ngang xương nổi tiếng của Hàn Quốc, được ướp ngập trong hỗn hợp nước tương, mật ong, đường, rượu mirin, dầu mè và hành tây gừng tỏi xay mịn giúp từng thớ thịt mềm mọng và thấm vị đậm đà. Khi nướng trên vỉ than hoặc chảo gang nóng, dẻ sườn chín nhanh, viền thịt xém cạnh caramel thơm nức.', 'Dùng kéo cắt phần thịt sườn thành miếng vừa ăn ngay trên đĩa, cuốn cùng lá xà lách, lá tía tô, chấm sốt ssamjang pha sẵn hoặc ăn kèm cơm trắng và kim chi.', 'Sườn sống đã ướp có thể bảo quản ngăn mát tới 24 giờ hoặc cấp đông tới 1 tháng; sườn đã nướng bảo quản ngăn mát tối đa 2 ngày và hâm nhanh trên chảo nóng 2 phút.', 'korean', 'mon_lau_tiec', NULL, 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["LA Galbi","Sườn bò nướng","Hàn Quốc","Tiệc nướng","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast"]', '["beef","sesame","soybean","wheat"]', 465, 464.9, 1945, 27.4, 29.7, 11.2, 21.5, 2.3, 13.6, 1183, 2.96, '["Korean Doenjang Ref","MEXT Hon-Mirin 16031","MEXT Shiso Ref","USDA / Korean Gochujang Ref","USDA Beef Rib / Bone Ref","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 173647","USDA FDC 174277"]', 'b3b86178009a0357f734f5d234c7ece272a7907836bf9e13c4d7aeb9cd6e3670', 'a5473f81b8e5a4ea7ee4e3e8c4dd1c82506e901e7b5e27ad0710f9aac0e796d5', 4),
('imp-328b6c9769e256eb', 'tom-nuong-muoi-ot-han', 385, 'Tôm nướng muối hạt kiểu Hàn (Saeu Sogeum Gui)', 'Tôm tươi nguyên vỏ nướng chín trên lớp muối biển hạt to thơm lừng, bóc vỏ chấm sốt Gochujang chanh mật ong cay chua hài hòa', 'Tôm nướng muối hạt (Saeu Sogeum Gui) là món ăn mùa thu rất được yêu thích tại Hàn Quốc nhờ cách chế biến mộc mạc giúp giữ trọn độ ngọt tự nhiên của tôm tươi. Tôm nguyên vỏ được nướng áp nhiệt gián tiếp trên lớp muối biển hạt to nóng già nên chín đều, vỏ giòn thơm mà thịt bên trong vẫn mọng nước, chấm kèm sốt tương ớt Gochujang pha chanh mật ong.', 'Gắp tôm nóng ra đĩa, gạt nhẹ hạt muối bám ngoài vỏ, rắc hành lá thái nhỏ và hạt mè trắng rang; bóc vỏ tại bàn và chấm ngập bát sốt Gochujang tỏi ớt chanh.', 'Món tôm nướng muối ngon nhất khi ăn nóng ngay tại bàn vì tôm để nguội sẽ bớt độ ngọt và dai; không khuyến khích bảo quản qua ngày.', 'korean', 'mon_lau_tiec', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng muối","Hàn Quốc","Món nhậu","Hải sản","Chấm Gochujang"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 207, 206.9, 866, 27.6, 4.6, 0.7, 14.9, 1.3, 8.3, 1073, 2.68, '["USDA / Korean Gochujang Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169640","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171028","USDA FDC 173468","USDA FDC 175179"]', '99d26f6363d9e612d6b2c157a4e52ae399972c62106d9c9320fcc3b91b8472b2', '5df66d2a83118752d3aaf7c6e92c9e53c239509c848fa3a94c33daf503818d0b', 4),
('imp-5dbb6aa38dae701d', 'mi-xao-kimchi-han', 386, 'Mì xào kim chi Hàn Quốc', 'Sợi mì ramen dai mềm xào cùng kim chi cải thảo chua cay đậm vị, quyện bơ tỏi thơm béo và trứng ốp la lòng đào hấp dẫn', 'Đĩa mì xào kim chi Hàn Quốc nóng hổi với sợi mì ramen săn bóng áo đều sốt tương ớt Gochujang cay nhẹ, vị chua thanh của kim chi lên men, chút béo ngậy từ bơ lạt và trứng ốp la đặt trên mặt.', 'Chia mì ra đĩa sâu lòng, đặt trứng ốp la lòng đào lên trên, rắc thêm hành lá và rong biển lá khô cắt sợi; dùng nóng ngay để sợi mì giữ độ dai ngon.', 'Món mì xào ngon nhất khi ăn ngay lúc vừa ra chảo; nếu còn dư có thể cất hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với 1 muỗng canh nước lọc.', 'korean', 'mon_xao', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Kim chi","Hàn Quốc","Bữa tối nhanh","Trứng ốp la"]', '["lunch","dinner"]', '["boil","stir_fry","pan_fry"]', '["egg","milk","sesame","soybean","wheat"]', 514, 513.7, 2149, 18.3, 19.1, 5.8, 67.9, 4.8, 7.3, 1479, 3.7, '["USDA / Korean Gochujang Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 168456","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173430","USDA FDC 173647","USDA FDC 174277"]', '61f3ae98eed7914e232eac99aa2453a93368b3cd0eb7ca2d1fdd0486a1897419', '4fdc9845fdab8adeff8116f6150a1aec1195d9707e2e8136441cd37657a72db5', 4),
('imp-b7f8a716b25a7072', 'canh-bo-bap-cai-han', 387, 'Canh bò cải thảo Hàn Quốc', 'Nước canh thịt bò xào tỏi dầu mè trong veo ngọt thanh, nấu mềm cùng cải thảo tươi mát kiểu cơm nhà Hàn Quốc', 'Tô canh bò cải thảo Hàn Quốc ấm áp với nước dùng trong thanh ngọt tự nhiên từ thịt bò xào săn và rau cải thảo hầm mềm, điểm xuyết hương dầu mè và tỏi thơm dịu rất dễ ăn.', 'Múc canh nóng vào tô lớn, rắc chút hạt mè trắng rang lên trên; dọn ăn kèm cơm trắng nóng dẻo và một đĩa kim chi cải thảo.', 'Canh ngon nhất khi ăn nóng trong ngày; phần dư bảo quản ngăn mát tủ lạnh tối đa 2 ngày trong hộp kín và đun sôi lại trên lửa vừa trước khi dùng.', 'korean', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Thịt bò","Cải thảo","Hàn Quốc","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["beef","sesame","soybean","wheat"]', 166, 165.5, 693, 15.3, 9.7, 3, 4.8, 1.8, 1.7, 940, 2.35, '["USDA FDC 169230","USDA FDC 169977","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '684a1086ebcd521160c088c83a5ea97deb01ee3b2cd6d5dfa78ff2221af859e8', 'b60c1fb5e2f4003183ecdd70106e4716ca92bd28430506dd6972711b7b362598', 4),
('imp-7d38862afc164a8d', 'muc-hap-tuong-han', 388, 'Mực xào xì dầu Hàn Quốc', 'Khoanh mực tươi giòn ngọt xào lửa lớn cùng hành tây, ớt chuông và sốt xì dầu dầu hào mặn ngọt không cay', 'Món mực xào xì dầu Hàn Quốc (Ojingeo Ganjang-bokkeum) nổi bật với từng khoanh mực trắng giòn sần sật, thấm đẫm sốt xì dầu đặc và dầu hào ngọt mặn hài hòa cùng hành tây, ớt chuông giòn tươi.', 'Trút mực xào ra đĩa rộng, rắc thêm hạt mè trắng rang lên trên; dọn nóng ngay ăn kèm cơm trắng rất bắt vị, phù hợp cho cả trẻ nhỏ vì không cay.', 'Mực xào ngon nhất khi thưởng thức ngay sau khi nấu để giữ độ giòn ngọt; nếu bảo quản ngăn mát tối đa 24 giờ, chỉ đảo nóng nhanh trên chảo 1–2 phút tránh làm mực dai.', 'korean', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Mực tươi","Xì dầu","Hàn Quốc","Không cay"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","squid","wheat"]', 348, 347.7, 1455, 29.2, 16.5, 2.7, 20.5, 2.1, 8.9, 1005, 2.51, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170108","USDA FDC 170150","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174223"]', 'a9337c6bcc5cff3c7620e0f9a526eaae65b2fb04d245e6804e1203bc53cbfec5', 'e15a457bb5d30de285cb541a5f5505b3ff37efaeefffa06dbf08f3886cb3aacb', 4),
('imp-c78c4d4ca35484d3', 'com-nam-han', 389, 'Cơm nấu nấm Hàn Quốc', 'Gạo tẻ hạt ngắn dẻo thơm nấu cùng nấm đùi gà, bào ngư và kim châm trong nước dùng tảo bẹ, chan sốt xì dầu hành lá', 'Nồi cơm nấm Hàn Quốc (Beoseot-bap) tỏa hương thơm dịu tự nhiên nhờ gạo được rang sơ rồi nấu trực tiếp với nước dùng tảo bẹ Kombu cùng ba loại nấm ngọt giòn, ăn kèm chén sốt xì dầu hành lá thanh tao.', 'Xới nhẹ cho cơm tơi đều cùng các loại nấm, múc ra chén rồi rưới từng muỗng sốt xì dầu hành lá theo khẩu vị; ăn kèm kim chi hoặc rong biển cuộn.', 'Cơm nấm bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi hâm nóng hãy vẩy thêm 1 muỗng canh nước lọc rồi đậy nắp hấp hoặc quay lò vi sóng để hạt cơm mềm dẻo lại.', 'korean', 'mon_chay', NULL, 'easy', 20, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Cơm nấm","Món chay","Hàn Quốc","Nấm tươi","Thanh đạm"]', '["lunch","dinner"]', '["boil","simmer"]', '["sesame","soybean","wheat"]', 458, 458.1, 1917, 10.9, 7.3, 1.1, 87.3, 4.3, 1.3, 505, 1.26, '["USDA FDC 168457","USDA FDC 168580","USDA FDC 169253","USDA FDC 169756","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', 'd80452e133c80da2d221a0a05e8933952f4faa10769fbbfdb587eb6dac07b852', '9ddb98ee95bf89970ec85c85da5a2cd682cb99074f3dfb226a78c37c40aca126', 4),
('imp-97c4b38c79bf9f39', 'canh-kimchi-tom', 390, 'Canh kim chi tôm đậu phụ Hàn Quốc', 'Nước canh kim chi chua cay nồng nàn hòa quyện vị ngọt tươi của tôm sú và đậu phụ non mềm mịn chuẩn vị Jjigae', 'Nồi canh kim chi tôm (Haemul Kimchi Jjigae) bốc khói nghi ngút với nước dùng cá cơm tảo bẹ đậm đà, vị chua dịu từ kim chi chín kỹ kết hợp cùng thịt tôm giòn ngọt và từng miếng đậu phụ non tan mềm.', 'Dọn nguyên nồi canh đang sôi lăn tăn hoặc múc ra tô đất giữ nhiệt, rắc hành lá xanh lên trên; thưởng thức nóng cùng cơm trắng dẻo.', 'Nếu còn dư, nên vớt riêng phần tôm để không bị dai, bảo quản phần nước canh và kim chi trong ngăn mát tối đa 2 ngày rồi đun sôi lại và thả tôm vào làm nóng nhanh.', 'korean', 'mon_canh', NULL, 'easy', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hải sản","Tôm tươi","Hàn Quốc","Cay ấm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["crustaceans","fish","sesame","shrimp","soybean","wheat"]', 223, 223.3, 935, 21.3, 8.3, 1.2, 17.4, 4, 6.5, 1723, 4.31, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 171028","USDA FDC 171413","USDA FDC 172476","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '8d6c0f32e46d0e9b040b90668d561535e94a237cb46a654ab2618e122e30bf47', 'ec7e4c25ed7c21185e182fd8572de393629385999776cac1ae10e08e40e6f812', 4),
('imp-b855b6ba4a9a3be8', 'tom-yum-tom-nam', 391, 'Canh Tom Yum tôm nấm kiểu Thái', 'Nước dùng đầu tôm ninh ngọt tự nhiên dậy hương sả, riềng, lá chanh Kaffir hòa quyện vị chua cay đậm đà cùng tôm tươi và nấm', 'Canh Tom Yum tôm nấm kiểu Thái trứ danh với nước dùng nấu trực tiếp từ gạch đầu tôm và vỏ tôm xào thơm, kết hợp bộ ba thảo mộc sả, riềng, lá chanh Kaffir cùng nấm đùi gà giòn ngọt và tôm tươi chín tới mọng thịt.', 'Múc canh Tom Yum nóng hổi ra tô sâu lòng, rắc hành lá và ngò gai; dùng nóng ăn kèm cơm trắng gạo thơm hoặc chan bún tươi.', 'Canh ngon nhất khi thưởng thức ngay lúc nóng để giữ hương thơm của chanh tươi; nếu dư, vớt bớt sả riềng rồi bảo quản ngăn mát tối đa 24 giờ, hâm nóng lại không đun sôi bùng quá lâu.', 'thai', 'mon_canh', NULL, 'medium', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Tom Yum","Canh chua cay","Tôm tươi","Ẩm thực Thái","Hải sản"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 167, 166.7, 698, 20.6, 5.6, 0.9, 10.4, 2.1, 4.5, 1508, 3.77, '["Citrus Leaf Culinary Ref","Thai Tom Yum Paste Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN Culinary Herb Ref"]', '36626d90fdd3ee673a304dc4a8f36d59755a54c4e18fab175d6e5017b1d9ee93', 'b20c9f10defb46a67f1dd02c0e8528905f90ffed1754c03476f2b7b88988e4b2', 4),
('imp-2b514b564c702ff1', 'tom-nuong-chanh-ot', 392, 'Tôm nướng chanh ớt kiểu Thái', 'Xiên tôm sú tươi nướng lửa lớn chín mọng xém cạnh, áo sốt chanh tươi, nước mắm và ớt tỏi chua cay mặn ngọt đậm đà', 'Tôm nướng chanh ớt kiểu Thái mang hương vị biển tươi mát với từng con tôm sú chắc thịt nướng cháy cạnh thơm lừng, được phết đẫm lớp sốt chanh tươi, nước mắm, đường và ớt tỏi băm đậm vị ngay khi còn nóng.', 'Dọn xiên tôm nướng nóng hổi ra đĩa, rắc thêm hành lá; dùng làm món khai vị tiệc gia đình hoặc ăn kèm rau sống, dưa leo và cơm trắng.', 'Tôm nướng ngon nhất ngay khi vừa nhấc khỏi vỉ; nếu còn dư, gỡ xiên bảo quản hộp kín ngăn mát tối đa 24 giờ và làm nóng nhanh 2 phút bằng nồi chiên không dầu ở 170°C.', 'thai', 'mon_lau_tiec', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Chanh ớt","Ẩm thực Thái","Hải sản","Món tiệc"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","fish","shrimp"]', 207, 207.1, 867, 29.7, 6.3, 1, 9.1, 0.7, 6.2, 1528, 3.82, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 175179"]', '830ba8f43b79773724e783fdf219432c6834b434d61c84adc62894ac0ba7b7f1', '59d167a189cd8962b2c2157b4dd5c86b5d41381aea57c0b1cfc04a0b6b419fb8', 4),
('imp-119da2ec6738c17e', 'ga-hap-chanh-sa', 393, 'Gà hấp chanh sả kiểu Thái', 'Đùi gà ta ướp sả, riềng, lá chanh Kaffir và húng quế hấp mềm mọng nước, chấm nước mắm chanh tỏi ớt pha nước ngọt tiết từ đĩa hấp', 'Gà hấp chanh sả kiểu Thái thơm dịu và mọng ngọt với từng miếng thịt đùi gà ướp kỹ cùng sả, riềng, lá chanh Kaffir và rễ ngò xay nhuyễn, hấp chín mềm cùng lá húng quế Thái, chấm kèm nước mắm chanh tỏi ớt hòa chút nước ngọt gà hấp đậm đà.', 'Bày gà hấp nóng ra đĩa, rưới nhẹ ít nước hấp và rắc hành lá thái nhỏ lên mặt; chấm kèm chén nước chấm chanh tỏi ớt và dùng với cơm trắng nóng.', 'Gà hấp ngon nhất khi ăn nóng; nếu còn dư, bảo quản kín cùng phần nước hấp trong ngăn mát tối đa 48 giờ, hấp lại 6–8 phút cho nóng mềm.', 'thai', 'mon_hap_luoc', NULL, 'easy', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Gà hấp","Sả chanh","Ẩm thực Thái","Thanh đạm","Cơm gia đình"]', '["lunch","dinner"]', '["steam"]', '["chicken","fish","molluscs","soybean","wheat"]', 358, 357.7, 1497, 32.1, 16.5, 4.5, 20.5, 1.4, 9.3, 1263, 3.16, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 172185","USDA FDC 172232","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '98d09035df2de0005658be94bceeeae55a27b6794baaf18369857914b267ac7d', 'f9b77a983ab0069c8e1820a36f47d29884fbcebee432a045577ae71154a313bf', 4),
('imp-2fb85e79ab43b8bc', 'goi-bo-nuong-thai', 394, 'Gỏi bò nướng Nam Tok kiểu Thái', 'Thịt bò nướng chín tới thái lát mỏng trộn thính gạo rang thơm lừng, sả, hành tím, bạc hà và sốt mắm chanh ớt cay nồng', 'Gỏi bò nướng Nam Tok kiểu Thái đặc trưng với thịt thăn bò ướp vừa vị nướng xém cạnh, giữ trọn nước thịt ngọt mềm, trộn ngay cùng thính gạo rang (Khao Khua), sả thái mỏng, hành tím, lá bạc hà và nước trộn chanh ớt mắm đậm đà.', 'Trình bày gỏi bò Nam Tok ra đĩa, ăn ngay khi thịt còn ấm nhẹ kèm rau xà lách, dưa leo thái lát, xôi nếp hoặc cơm trắng.', 'Món gỏi thính gạo ngon nhất ngay sau khi trộn để thính thơm và rau không bị ỉu; phần thịt bò nướng có thể bọc kín giữ mát 24 giờ và chỉ trộn sốt trước khi ăn.', 'thai', 'mon_cuon_nom', NULL, 'medium', 35, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Nam Tok","Gỏi bò","Thính gạo","Ẩm thực Thái","Khai vị"]', '["lunch","dinner"]', '["grill_roast","toss_mix"]', '["beef","fish","molluscs","soybean","wheat"]', 338, 337.6, 1413, 26.8, 17, 5.5, 19.6, 2.1, 4.9, 1051, 2.63, '["Toasted Rice Powder Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170499","USDA FDC 170931","USDA FDC 171319","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172883","USDA FDC 173474","USDA FDC 174277"]', 'dd34f1439f6adefe716cf5480bf3ce6474d5d002b9f3b558753bbe2212530e1d', '5058b8764ac170e4fce7934ae90e7bb8826fd09ded3c0d3f06591b1f11db681e', 4),
('imp-3f14cf8e63967712', 'muc-xao-toi-ot-thai', 395, 'Mực xào tỏi ớt kiểu Thái', 'Khoanh mực tươi khía vảy rồng xào lửa lớn giòn sần sật, thấm đẫm sốt dầu hào tỏi ớt giã cối thơm nồng đậm vị biển', 'Mực xào tỏi ớt kiểu Thái ghi điểm với từng miếng mực tươi khía vảy rồng giòn sần sật, không ra nước, thấm đẫm hương thơm nồng nàn của tỏi ớt giã cối phi vàng và sốt dầu hào, nước mắm, xì dầu đặc đậm đà đưa cơm.', 'Trút mực xào nóng hổi ra đĩa, dùng ngay với cơm trắng nóng kèm vài lát dưa leo tươi và chanh cắt múi nếu thích.', 'Hải sản xào ngon nhất khi ăn ngay lúc vừa tắt bếp; phần dư bảo quản ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng 1 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Mực xào","Tỏi ớt","Hải sản","Ẩm thực Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["fish","molluscs","soybean","squid","wheat"]', 237, 236.6, 990, 21.8, 10.2, 1.7, 13.9, 0.7, 3.9, 1129, 2.82, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '25808177a85ff1b1f60db3c4e88fce852126c5e87513a5fdf2c65ca1aa16cbf7', 'ca2754ec720062086b8cebdd94858bebea81868ea9e8a117e95f32e4ab0edafc', 4),
('imp-244640181aff1fb6', 'nam-nuong-sa', 396, 'Nấm đùi gà nướng sả kiểu Thái', 'Khoanh nấm đùi gà khứa vằn ướp sả băm nhuyễn, hành tím, tương ớt và dầu hào chay nướng xém vàng đậm hương', 'Nấm đùi gà nướng sả kiểu Thái là món chay thơm nức với từng khoanh nấm giòn ngọt tự nhiên được luộc sơ khử hăng, khứa vảy rồng thấm đẫm sốt xì dầu, dầu hào chay, dầu mè và sả băm nhuyễn, nướng xém cạnh hấp dẫn.', 'Xếp nấm nướng sả nóng hổi ra đĩa, rắc mè rang và hành lá thái nhỏ lên mặt; ăn kèm cơm trắng nóng và rưới thêm nước sốt nướng trong khay.', 'Nên ăn ngay sau khi nướng để nấm giòn ngọt; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 3–4 phút.', 'thai', 'mon_chay', NULL, 'easy', 25, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nấm đùi gà","Nấm nướng","Sả ớt","Ẩm thực Thái"]', '["lunch","dinner"]', '["grill_roast"]', '["sesame","soybean","wheat"]', 192, 191.6, 801, 6.2, 10.9, 1.6, 21.4, 4, 7.1, 825, 2.06, '["USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","USDA FDC Sriracha Ref","Vegan Mushroom Sauce Ref"]', '3ae24e8a87463313884e882dc6a4f8bbd276f2f776ee4c5f8669c68c85e12ea3', '2db91a6246cbb59298bc37a6942f11248a8518ed154f61b7bce859320d89f5f7', 4),
('imp-f494a9f384ce66a4', 'cua-xao-cay-thai', 397, 'Cua xào cay kiểu Thái', 'Thịt cua biển ngọt mềm xào nhanh cùng ớt hiểm, tỏi phi thơm, ớt chuông xanh và sốt dầu hào đậm đà vị biển', 'Cua xào cay kiểu Thái (Poo Pad Prik) nổi bật với thớ thịt cua tươi trắng ngọt tự nhiên quyện trong nước sốt dầu hào, xì dầu nhạt sánh nhẹ, dậy mùi tỏi phi, ớt hiểm cay nồng cùng vị giòn mát của ớt chuông xanh và hành lá.', 'Dọn nóng thịt cua xào cay ra đĩa, dùng ngay với cơm trắng nóng hổi hoặc bánh mì giòn chấm nước sốt đậm đà.', 'Thịt cua ngon nhất khi ăn ngay lúc vừa xào xong; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng nhẹ trên chảo trong 1–2 phút.', 'thai', 'mon_xao', NULL, 'medium', 15, 12, 4, '/frigo/illustrations/delicious-meal.png', '["Cua xào","Poo Pad Prik","Hải sản","Ẩm thực Thái","Cay nồng"]', '["lunch","dinner"]', '["stir_fry"]', '["crab","crustaceans","molluscs","soybean","wheat"]', 209, 209, 875, 19.8, 10.8, 1.7, 8.3, 1.2, 4.4, 901, 2.25, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172883","USDA FDC 174208","USDA FDC 174277"]', 'd734e0f4c6a668bd462eada9da044ca6ac32f655039d7a66aa89d0f96b1d90f7', '388e1a390f90f04b9e42fbaf6e0359b82b90a94f83124da3274c1dbf44db5fc5', 4),
('imp-0ec0d1db60dbdc1e', 'com-ga-khao-man-gai', 398, 'Cơm gà Khao Man Gai kiểu Thái', 'Gà ta luộc liu riu thịt ngọt mọng, cơm Jasmine xào mỡ gà nấu nước luộc thơm tỏi gừng ăn kèm sốt tương đậu lên men Taojiew', 'Cơm gà Khao Man Gai kiểu Thái chinh phục thực khách với từng hạt cơm gạo thơm dẻo bóng nhẹ mùi tỏi gừng và mỡ gà, thịt gà ta luộc chín tới da giòn thịt mọng ngọt, ăn kèm chén sốt tương đậu nành lên men gừng ớt đậm vị và bát nước dùng thanh ngọt.', 'Xới cơm nóng ra đĩa, xếp thịt gà chặt miếng vừa ăn và dưa leo thái lát bên cạnh; dọn kèm chén nước chấm tương đậu gừng ớt và bát nước dùng gà rắc ngò rí.', 'Nên bảo quản riêng cơm, thịt gà và nước chấm trong ngăn mát tối đa 48 giờ; hấp nóng lại cơm gà 5 phút trước khi ăn.', 'thai', 'mon_hap_luoc', NULL, 'medium', 25, 60, 4, '/frigo/illustrations/delicious-meal.png', '["Khao Man Gai","Cơm gà","Ẩm thực Thái","Nước chấm gừng","Bữa trưa"]', '["lunch","dinner"]', '["boil","simmer"]', '["chicken","soybean","wheat"]', 836, 836.2, 3499, 44.1, 32.7, 8.8, 88.5, 3.5, 8.8, 1348, 3.37, '["Dark Soy Sauce Label Ref","Korean Doenjang Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169756","USDA FDC 169997","USDA FDC 170000","USDA FDC 170106","USDA FDC 170933","USDA FDC 171077","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'b0d5e99604694433b4de3a5b6daf6c3964a8dfe85f172691b88c85d92b4c667c', 'ff913a34184d4bfd9172a977d6f9473e4a6ffbcc024cc2977b782280f701a59d', 4),
('imp-4316659025be0f91', 'mi-xao-bo-cay-thai', 399, 'Mì xào bò cay kiểu Thái', 'Sợi hủ tiếu bản rộng áp chảo xém cạnh kiểu Pad Kee Mao cùng thịt bò mềm, cải rổ, cà rốt, ớt tỏi và lá húng quế Thái dậy mùi', 'Mì xào bò cay kiểu Thái (Pad Kee Mao) nổi bật với sợi hủ tiếu bản rộng dai mềm xém cạnh thơm mùi chảo lửa, thịt bò thăn mềm mọng đậm vị, hòa quyện vị cay nồng của tỏi ớt giã cùng mùi thơm đặc trưng không thể thiếu của lá húng quế Thái.', 'Gắp mì xào bò cay nóng hổi ra đĩa lớn, rắc thêm hành lá và thưởng thức ngay khi lá húng quế còn thơm nồng.', 'Mì xào lửa lớn ngon nhất khi dùng ngay; phần dư bảo quản ngăn mát tối đa 24 giờ và áp chảo nhanh lại trên lửa vừa với 1 muỗng canh nước.', 'thai', 'mon_xao', NULL, 'easy', 25, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Kee Mao","Mì xào","Thịt bò","Ẩm thực Thái","Cay nồng"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 671, 671.3, 2809, 31.4, 24, 6.4, 80.3, 3.7, 10.3, 1328, 3.32, '["Dark Soy Sauce Label Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170187","USDA FDC 170390","USDA FDC 170393","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', 'b198a296dc013f32bf176af46cec1d81ebc4dcbc0aaeab28d808a12c7c0bb2d6', '87cdbf68b7a9073d868c0a0f1397505b764a555a709cf98cf0aa93bec659c852', 4),
('imp-0e30c82a4c77802e', 'goi-dau-phu-cay-thai', 400, 'Gỏi đậu phụ cay kiểu Thái', 'Đậu phụ non ướp lạnh mát mịn kết hợp sả, hành tím, dưa leo, rau thơm và nước sốt chanh đường thốt nốt cay nồng thanh mát', 'Gỏi đậu phụ cay kiểu Thái mang đến sự tương phản thú vị giữa từng khối đậu phụ non mềm mịn mát lạnh và lớp rau thơm băm nhuyễn giòn tươi gồm sả non, hành tím, dưa leo, bạc hà, ngò rí thấm đẫm nước sốt chanh ớt đường thốt nốt chua cay hài hòa.', 'Rắc mè đen rang thơm lên trên mặt đĩa gỏi đậu phụ, dọn dùng ngay khi đậu còn mát lạnh như món khai vị thanh nhẹ hoặc ăn kèm cơm trắng nóng.', 'Món gỏi đậu phụ non nên dùng hết ngay sau khi rưới sốt; nếu chuẩn bị trước, ướp lạnh riêng đậu phụ và chén rau củ trộn trong ngăn mát tối đa 6 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi đậu phụ","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["toss_mix","assemble"]', '["sesame","soybean","wheat"]', 162, 162, 678, 10, 6, 0.9, 19, 2.2, 9.3, 849, 2.12, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170150","USDA FDC 170499","USDA FDC 172476","USDA FDC 173474","USDA FDC 174277","USDA FDC Palm Sugar Ref"]', '60e3247733175ec419adfcd2fc2d0b16836e00b9c99a14b44971cc835e604d72', 'cde071cc679e1033b1844bd5982b7681d96abb0271b4d2d22d34a56de24d53e0', 4),
('imp-d005aca18d138bfe', 'tom-xao-hung-que-thai', 401, 'Tôm xào húng quế kiểu Thái', 'Tôm tươi xào nhanh lửa lớn cùng tỏi ớt giã thơm nồng, sốt dầu hào đậm đà và lá húng quế Thái dậy vị Pad Krapao trứ danh', 'Tôm xào húng quế kiểu Thái (Pad Krapao Tôm) là món ăn đường phố cực kỳ bắt cơm với từng con tôm tươi săn giòn áo lớp sốt dầu hào, nước mắm sánh đậm, hòa cùng vị cay thơm nồng nàn của tỏi ớt giã và lá húng quế Thái đảo nhanh khi tắt bếp.', 'Trút tôm xào húng quế ra đĩa, rắc thêm hành lá và thưởng thức ngay với cơm trắng nóng hổi cùng một quả trứng ốp la lòng đào kiểu Thái.', 'Món xào tôm ngon nhất khi ăn nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh 1 phút trên chảo nóng.', 'thai', 'mon_xao', NULL, 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Pad Krapao","Tôm xào","Húng quế","Ẩm thực Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 209, 208.7, 873, 20.4, 10.3, 1.5, 9.7, 1, 5.5, 1253, 3.13, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'ff28164d20178425241cf86b8e879a0fd6802c3694faa1104c29ac619e999b51', '93b0fa97f3ef47cccc2d4228f39d30378db9d4ef04bc84cbe6274e4e058a0066', 4),
('imp-a9710414682c8521', 'mi-xao-xi-dau-bo-thai', 402, 'Mì xào xì dầu bò kiểu Thái', 'Sợi mì trứng dai ngon xào xém cạnh kiểu Pad See Ew cùng thịt bò ướp mềm, trứng gà tơi, bắp cải giòn ngọt và sốt xì dầu đậm đà', 'Mì xào xì dầu bò kiểu Thái (Pad See Ew biến tấu với mì sợi trứng) hấp dẫn với từng sợi mì vàng nâu bóng mượt, hơi xém cạnh thơm mùi khói chảo, hòa quyện thịt bò thăn mềm ngọt, trứng gà tơi béo và bắp cải giòn giòn đậm vị xì dầu.', 'Gắp mì xào xì dầu bò nóng hổi ra đĩa, rắc thêm chút tiêu xay và hành lá; có thể ăn kèm vài lát ớt tươi hoặc giấm ớt ngâm kiểu Thái.', 'Món mì ngon nhất khi ăn nóng ngay sau khi xào; phần dư bảo quản ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo chống dính khoảng 2 phút.', 'thai', 'mon_xao', NULL, 'easy', 25, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Pad See Ew","Mì xào","Thịt bò","Xì dầu","Ẩm thực Thái"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","egg","molluscs","soybean","wheat"]', 692, 692, 2896, 38, 25.8, 7.1, 76.4, 4.9, 10.2, 1455, 3.64, '["Dark Soy Sauce Label Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '0e3052bb90f0b98e1fc693da7bd39bb5e9be6dd885a0d6ca5cb0605afdf0d472', '68e69f4714727d3f6cb8c8d6e348ace939981a534be2eda050545a3813e731c5', 4),
('imp-c64c83ef34771b5a', 'canh-nam-sa-thai', 403, 'Canh nấm sả Thái chay thanh vị', 'Canh nấm đùi gà và đậu phụ non nấu sả riềng lá chanh kiểu Thái, nước dùng trong thanh ngọt dịu và dậy mùi thảo mộc', 'Bát canh nấm sả Thái chay thanh mát lấy cảm hứng từ món Tom Yum nước trong, kết hợp nấm đùi gà giòn ngọt, đậu phụ non mềm mịn cùng hương thơm nồng nàn của sả, riềng tươi, lá chanh Thái và vị chua dịu tự nhiên từ cà chua, nước cốt chanh.', 'Múc canh nóng ra tô lớn, vớt bỏ phần sả riềng già cho dễ ăn, rắc thêm hành lá và ngò rí; dùng ngay làm món khai vị hoặc ăn kèm cơm trắng nóng.', 'Nên thưởng thức ngay khi vừa nấu xong để giữ trọn hương chanh tươi; nếu bảo quản tủ mát trong 24 giờ, đun sôi nhẹ lại phần nước canh và nấm rồi mới vắt thêm chanh.', 'thai', 'mon_canh', NULL, 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Canh chay","Nấm đùi gà","Thảo mộc Thái","Thanh nhẹ","Khai vị"]', '["lunch","dinner"]', '["simmer"]', '["soybean"]', 128, 127.6, 533, 7.3, 4.9, 0.7, 17.1, 3.8, 6.9, 1116, 2.79, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 171413","USDA FDC 172476","USDA FDC 173647","Vegetarian Fish Sauce Ref","Vegetarian Seasoning Powder Ref"]', '66dfc88efc1d155757ef0fc3f2835cc070ef33373f7408bdac02f6edbad0c6dd', '5e89a0bc0e81e5495427b7aa13dd966e58c49bdcfea3c1cbfb64cded5d811ae9', 4),
('imp-a71f6ef791b463ea', 'goi-tom-sa-chanh', 404, 'Gỏi tôm sả chanh kiểu Thái', 'Tôm sú chần chín giòn ngọt trộn cùng sả non, hành tím, bạc hà và nước mắm chanh ớt cay nồng đặc trưng món gỏi Plaa Goong', 'Đĩa gỏi tôm sả chanh kiểu Thái mang hương vị tươi mát bùng nổ với thịt tôm sú chần vừa chín tới giòn sần sật, quyện cùng sả thái khoanh mỏng, ngò gai, lá bạc hà và sốt trộn chua cay mặn ngọt hài hòa.', 'Bày gỏi tôm ra đĩa sâu lòng, rắc thêm ngò gai và lá bạc hà tươi lên mặt; dùng ngay làm món khai vị hoặc ăn kèm xà lách và bánh phồng tôm giòn.', 'Gỏi tôm ngon nhất khi trộn và dùng hết trong vòng 30 phút để tôm giữ độ giòn và rau không ra nước; nếu chuẩn bị trước, nên bảo quản riêng tôm chần và nước sốt trong tủ mát tối đa 12 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi Thái","Tôm sú","Sả chanh","Khai vị","Chua cay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","shrimp"]', 191, 191.4, 801, 28.4, 1, 0.2, 19.3, 1.7, 9.7, 1263, 3.16, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 172185","USDA FDC 173474","USDA FDC 175179","USDA FDC Sriracha Ref","VN Culinary Herb Ref"]', '696a79bd6f35ce2fee46fc0f307b86b6714fc0b676fcc3eaee6a5b3b76971e04', '6da0457ffafe2201986fe697431d5586d126a62910db5ecf50151926224b2a61', 4),
('imp-9236740e2b55e8a1', 'com-chien-ga-thai', 405, 'Cơm chiên gà kiểu Thái (Khao Pad Gai)', 'Cơm rang tơi hạt cùng thịt đùi gà mềm ngọt, trứng gà, xì dầu Thái và nước mắm ớt Prik Nam Pla đậm vị đường phố Bangkok', 'Cơm chiên gà Thái (Khao Pad Gai) chinh phục vị giác nhờ từng hạt cơm dẻo tơi săn cạnh, thịt đùi gà áp chảo mềm ngọt quyện trứng gà béo bùi, dậy mùi thơm đặc trưng của xì dầu nhạt, tiêu trắng và chén nước mắm ớt chanh ăn kèm.', 'Ép cơm chiên vào chén rồi úp ra đĩa, rắc thêm ngò rí và tiêu trắng xay; dọn nóng kèm dưa leo thái lát, múi chanh tươi và chén nước mắm ớt Prik Nam Pla.', 'Ngon nhất khi ăn nóng ngay lúc vừa rang xong; nếu còn dư, đậy kín bảo quản tủ mát tối đa 24 giờ và đảo nhanh trên chảo nóng với 1 muỗng cà phê nước lọc cho hạt cơm mềm tơi trở lại.', 'thai', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Khao Pad","Cơm chiên","Thịt gà","Đường phố Thái","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","egg","fish","soybean","wheat"]', 506, 506.3, 2119, 26.6, 19.5, 4.6, 55, 2.5, 6, 1677, 4.19, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 174277"]', '0d937e3c06be24885a8d4ad425fffafdd9db337e31bb915a035c32462b80b102', 'bd0c13c0212369d00b87afd2d74c788772867d5fa27934cc58db91e015e2c524', 4),
('imp-a1904f60d9f4f10e', 'mi-y-bo-toi', 406, 'Mì Ý sốt bơ tỏi (Burro e Aglio)', 'Sợi mì Spaghetti dai vừa quyện sốt nhũ hóa từ bơ lạt béo thơm, tỏi phi lát mỏng và phô mai Parmesan bào mịn', 'Món mì Ý bơ tỏi tối giản mà tinh tế với từng sợi Spaghetti dai mượt bao phủ bởi lớp sốt nhũ hóa óng ả từ bơ lạt, nước luộc mì giàu tinh bột, tỏi phi lát vàng dịu và phô mai Parmesan.', 'Chia mì ra đĩa sâu lòng ngay khi vừa tắt bếp, rắc thêm phô mai Parmesan bào và ngò tây tươi thái nhỏ; ăn nóng để cảm nhận trọn vị béo mịn.', 'Món này ngon nhất khi thưởng thức ngay lúc còn nóng; nếu còn dư có thể cất ngăn mát tối đa 24 giờ và áp chảo lại cùng chút nước ấm hoặc bơ lạt.', 'italian', 'mon_bun_pho', NULL, 'easy', 8, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý bơ tỏi","Ẩm thực Ý","Nhanh gọn","Spaghetti","Món chính"]', '["lunch","dinner"]', '["boil","pan_fry"]', '["milk","wheat"]', 603, 602.5, 2520, 18.4, 23.9, 14.3, 78.2, 3.7, 2.9, 777, 1.94, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171319","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', '9a44f796e208519a3d8b62f70881c7ee366e8e7681f29a65f8a83e9f75871dd8', '645c84f12179a5302b97c69dc602cbb972c31991b36bf905e692fa3d05d5e70a', 4),
('imp-cc5f58548e934d9e', 'mi-y-tom-toi-ot', 407, 'Mì Ý tôm tỏi ớt (Aglio Olio)', 'Sợi mì Ý thấm đẫm sốt dầu ô liu bơ tỏi ớt cay nhẹ quyện thịt tôm tươi ngọt giòn và hương vỏ chanh vàng thanh mát', 'Món mì Ý hải sản tinh tế với tôm tươi xào săn ngọt thịt, sợi mì dai mềm quyện sốt dầu ô liu bơ thơm nức mùi tỏi phi, chút cay nồng của ớt tươi và vị tươi mát từ vỏ chanh vàng bào.', 'Dọn nóng ngay ra đĩa sâu lòng, rắc thêm ngò tây băm nhỏ và chút phô mai Parmesan bào nếu thích.', 'Món mì sốt dầu hải sản ngon nhất khi ăn nóng ngay; nếu cần bảo quản, cất hộp kín ngăn mát tối đa 24 giờ và đảo nóng lại trên chảo với chút nước ấm.', 'italian', 'mon_bun_pho', NULL, 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý tôm","Aglio Olio","Ẩm thực Ý","Hải sản","Cay nhẹ"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","milk","shrimp","wheat"]', 633, 633.2, 2650, 34.3, 26.4, 9.1, 64.7, 3.1, 2.5, 624, 1.56, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '3f2f377cd7fea7646eae08c84647dcd7c7c7a08b554d463408ea4b311d73ced4', '4893eaeeecfa2dbbc68228ff9ca9bb810f97241ff8b9a1b3c5c32fc0230e2392', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-8fdcddab058d5f65', 'mi-y-sot-ca-chua-tuoi', 408, 'Mì Ý sốt cà chua tươi (Pomodoro)', 'Sợi mì Spaghetti al dente quyện sốt cà chua tươi nấu nhanh giữ trọn vị ngọt thanh cùng húng quế Tây thơm mát', 'Đĩa mì Ý sốt cà chua tươi Pomodoro thanh vị với cà chua chín mọng nấu nhanh cùng tỏi phi dầu ô liu, thêm chút cà chua cô đặc tạo màu đỏ au đẹp mắt và hương thơm dịu của lá húng quế Tây.', 'Dọn mì nóng ra đĩa sâu lòng, rắc lá húng quế Tây xé nhỏ và thêm ít phô mai Parmesan bào mịn tùy khẩu vị.', 'Món mì sốt cà chua tươi ngon nhất khi dùng ngay lúc nóng; phần sốt nấu dư có thể bảo quản ngăn mát 2 ngày và hâm nóng lại với ít nước trước khi trộn mì.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Ý Pomodoro","Cà chua tươi","Ẩm thực Ý","Nhanh gọn","Món chính"]', '["lunch","dinner"]', '["boil","simmer"]', '["milk","wheat"]', 486, 486.2, 2034, 16.2, 14.7, 3.2, 72.6, 4.8, 6.5, 956, 2.39, '["USDA FDC 168927","USDA FDC 169230","USDA FDC 170457","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647"]', 'bce6a9b293974e2c8a080c44320e973a2adbc952970502ef95fc89cfb058aca3', '31e287d274df6ccc5f3558a3ead27a7b702c23078f04f03dcbce3c9e7f017ec6', 4),
('imp-d4d1de72f13e8f30', 'lasagna-bo-bam', 409, 'Lasagna bò bằm nướng sốt Béchamel', 'Từng lớp lá mì Lasagna xen kẽ sốt bò bằm Ragù ninh chậm đậm đà, sốt sữa trắng Béchamel béo mịn và phô mai Parmesan nướng vàng', 'Món Lasagna truyền thống vùng Bologna với 5 tầng lá mì mềm dẻo ôm trọn phần sốt thịt bò bằm và thịt xông khói ninh chậm cùng cà chua, cân bằng bởi sốt sữa trắng Béchamel thơm mùi nhục đậu khấu và lớp phô mai Parmesan nướng vàng giòn.', 'Để khay Lasagna nghỉ 10 phút sau khi ra lò rồi cắt thành từng phần vuông vức; dùng nóng kèm salad rau xanh trộn giấm thanh mát.', 'Có thể bảo quản ngăn mát tối đa 3 ngày hoặc cấp đông từng phần tối đa 1 tháng; khi ăn phủ giấy bạc hâm nóng ở 180°C khoảng 15–20 phút.', 'italian', 'mon_lau_tiec', NULL, 'hard', 30, 120, 6, '/frigo/illustrations/delicious-meal.png', '["Lasagna","Bò bằm","Ẩm thực Ý","Nướng lò","Tiệc cuối tuần"]', '["lunch","dinner"]', '["simmer","assemble","grill_roast"]', '["beef","celery","milk","pork","sulphites","wheat"]', 713, 712.9, 2983, 35.8, 42.6, 17.8, 45.1, 3.5, 11.3, 1442, 3.61, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171326","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', '7890e4ac36ba2c6fcfe12f9d67f9c2b44cd69f5a813517dcb64a279f24655341', '6191d81864915d41da97b8b632b91b96fd14f14a40bb0d598055ff302259acbb', 4),
('imp-3fd9eb5a7c40c3c0', 'risotto-ga-hanh', 410, 'Risotto gà hành kiểu Ý', 'Hạt gạo Arborio dẻo béo nấu chậm cùng nước dùng gà nóng, ức gà áp chảo vàng mềm, bơ lạt và phô mai Parmesan sánh mượt', 'Đĩa cơm Ý Risotto béo mịn chuẩn vị với từng hạt gạo Arborio mềm dẻo bên ngoài nhưng vẫn giữ lõi sần nhẹ bên trong, quyện thịt ức gà ngọt mềm, hành tây thơm dịu, bơ lạt và phô mai Parmesan.', 'Múc cơm Risotto nóng ra đĩa sâu lòng, rắc ngò tây băm nhỏ và thêm ít phô mai Parmesan bào lên trên; thưởng thức ngay khi cơm còn sánh chảy nhẹ.', 'Món Risotto ngon nhất khi ăn nóng ngay sau khi hoàn thiện; nếu còn dư có thể bảo quản ngăn mát tối đa 2 ngày và hâm nóng trên chảo với chút nước dùng gà hoặc nước ấm.', 'italian', 'mon_lau_tiec', NULL, 'medium', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Risotto","Ẩm thực Ý","Ức gà","Gạo Ý","Món chính"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["chicken","milk","sulphites"]', 638, 637.5, 2667, 31.5, 23.6, 10.4, 70.2, 1.7, 2.9, 1400, 3.5, '["USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 172883","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '02ec2d8872cdad073a144ed0313ef0c85bd3638246be0818538a1241f12ea6d8', '200c94fce3a5995aa69f8a44440463b20249aca1aea073f3551633b0111cc9e4', 4),
('imp-4c5955ef4919d61a', 'mi-y-cua-ot', 411, 'Mì Ý thịt cua tỏi ớt chanh vàng', 'Sợi mì Spaghetti quyện thịt cua biển ngọt thanh, dầu ô liu phi tỏi ớt thơm nồng và hương vỏ chanh vàng tươi mát', 'Món mì Ý hải sản tinh tế với từng thớ thịt cua biển ngọt tự nhiên hòa quyện sốt nhũ hóa trắng sánh từ dầu ô liu phi thơm tỏi ớt và nước luộc mì, điểm nhấn bởi hương thơm tươi mát của vỏ chanh vàng và ngò tây.', 'Chia mì ra 4 đĩa sâu lòng khi còn nóng hổi, rắc thêm ngò tây băm và một vòng nhỏ dầu ô liu nguyên chất; tránh dùng phô mai để giữ trọn vị ngọt thanh của thịt cua.', 'Mì hải sản ngon nhất khi ăn ngay lúc nóng; nếu còn thừa bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo với ít nước ấm.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Mì Ý cua","Hải sản","Ẩm thực Ý","Cay nhẹ","Bữa tối"]', '["lunch","dinner"]', '["boil","stir_fry"]', '["crab","crustaceans","wheat"]', 486, 485.6, 2032, 23.3, 12.3, 1.8, 68.9, 3.3, 2.8, 627, 1.57, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208"]', '9931a9d5aede0d95dd9a459bdf38c48ea289e099129c04014a41215856a9df15', 'a5cfa01b1d72407c37dade79ab327252725d6d62f29c5bd49aa42c239516770b', 4),
('imp-c398c169dc196c4e', 'tom-nuong-toi-chanh-y', 412, 'Tôm nướng tỏi chanh vàng kiểu Ý', 'Tôm tươi nguyên vỏ ướp dầu ô liu, tỏi băm, chanh vàng và ngò tây nướng chín tới giữ trọn độ giòn ngọt mọng nước', 'Món khai vị hải sản kiểu Ý đầy cuốn hút với những con tôm tươi nguyên vỏ nướng nhanh trên lửa lớn, thịt tôm chắc ngọt thơm lừng hương dầu ô liu, tỏi băm, vỏ chanh vàng và ngò tây tươi.', 'Dọn nóng ngay ra đĩa, rưới thêm phần nước sốt dầu tỏi chanh sạch lên trên, rắc ngò tây băm và bày kèm vài múi chanh vàng để vắt thêm.', 'Món tôm nướng ngon nhất khi thưởng thức nóng ngay sau khi nướng; nếu còn dư bảo quản ngăn mát tối đa 24 giờ và làm ấm lại nhanh trong lò 170°C khoảng 3–4 phút.', 'italian', 'mon_lau_tiec', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Ẩm thực Ý","Chanh vàng","Khai vị","Hải sản"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","shrimp"]', 278, 277.8, 1163, 32.1, 15.5, 2.2, 4.4, 1.1, 0.8, 771, 1.93, '["USDA FDC 167746","USDA FDC 169230","USDA FDC 170106","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', '8cbc45ccac28adaf3dee1907555bd81e9da69d1c10f41ceca52b8c1d3abbfcd5', '4b08b02f32633da516f00f24591e5c1d7782d8ecaf69245fe0548456e33fef30', 4),
('imp-8fcc592ab7250a38', 'bap-cai-om-ca-chua-y', 413, 'Bắp cải om cà chua kiểu Ý', 'Bắp cải thái sợi om chậm trong sốt cà chua sánh dịu quyện vị ngọt của hành tây, tỏi thơm và dầu ô liu béo nhẹ', 'Món rau om dân dã vùng Bắc Ý với từng sợi bắp cải chín mềm ngọt lịm, thấm đều nước sốt cà chua đỏ au quyện hương dầu ô liu, hành tây và tỏi phi dịu nhẹ.', 'Múc nóng ra đĩa sâu lòng để dùng làm món ăn kèm cho các món thịt nướng, xúc xích hoặc chấm trực tiếp với bánh mì giòn.', 'Món bắp cải om để qua đêm trong ngăn mát tối đa 2 ngày càng thấm đẫm gia vị; khi ăn hâm nóng lại trên chảo với lửa vừa khoảng 5 phút.', 'italian', 'mon_chay', NULL, 'easy', 12, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bắp cải om","Món chay","Ẩm thực Ý","Món phụ","Thanh đạm"]', '["lunch","dinner"]', '["braise","simmer"]', '[]', 170, 169.9, 712, 4, 10.2, 1.4, 19.1, 6.3, 10.2, 770, 1.92, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 169975","USDA FDC 170000","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173468"]', '9179b1db2d1a94f1aee49d808e6df9afe9748352498601cbe8961ec22db0cea9', '71df3d86ef60f3f59aa0a2139c1e24a0fca3756c880f643b4f8d6940d9da5e19', 4),
('imp-da0c2dea539000e5', 'frittata-nam-pho-mai', 414, 'Frittata nấm phô mai kiểu Ý', 'Trứng chiên dày kiểu Ý vàng ươm thơm lừng nhân nấm đùi gà xào cháy cạnh, hành tỏi và phô mai Parmesan béo mặn', 'Ổ trứng chiên dày Frittata kiểu Ý mềm ẩm bên trong, xém vàng bên ngoài với nấm đùi gà xào thơm ngọt, ngò tây tươi, tỏi phi và phô mai Parmesan tan quyện đậm đà.', 'Cắt ổ Frittata thành từng miếng tam giác đều nhau, rắc thêm ngò tây tươi và dùng nóng hoặc ở nhiệt độ phòng cùng bánh mì nướng và salad trộn.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn làm nóng lại nhẹ bằng chảo khô lửa nhỏ hoặc thưởng thức nguội đều rất ngon.', 'italian', 'mon_nhanh_sang', NULL, 'easy', 12, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Frittata","Bữa sáng","Ẩm thực Ý","Trứng nấm","Phô mai"]', '["breakfast","lunch"]', '["pan_fry"]', '["egg","milk"]', 299, 299.4, 1252, 19.7, 21.3, 6.3, 8.7, 2.6, 1.6, 740, 1.85, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 173468"]', '8777c4420e2b58c01c3fa22917f94bb0a7613f3beb2c6690ff3d0920d49397ae', 'da84d2b469a79b598b3478d4e3325c34c231875bb012086cf607b4369e731573', 4);

