INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-8b874d97e90e00f0_v4_step_1', 'imp-8b874d97e90e00f0', 1, 'prep', 'Sơ chế đùi gà và giã tơi sả thành sợi bông', 'Rửa sạch 600 g thịt đùi gà lọc xương (xát nhẹ với 1 g muối rồi rửa lại), dùng khăn giấy thấm thật khô và cắt miếng vuông 4–5 cm. Cắt khúc phần gốc trắng của 4 cây sả tươi, đập dập rồi dùng chày giã liên tục trong cối đến khi sả tơi nhẹ thành từng sợi mảnh như bông.', 'Giã sả cho tơi sợi giúp khi chiên sả chín giòn như ruốc và bám đều quanh miếng gà thay vì bị cứng sượng.', NULL),
('imp-8b874d97e90e00f0_v4_step_2', 'imp-8b874d97e90e00f0', 2, 'marinate', 'Giã cốt gia vị ướp gà thấm đều', 'Giã nhuyễn tỏi, rễ ngò rí và 5 g tiêu đen xay thành hỗn hợp sệt thơm. Cho thịt gà vào tô lớn cùng phần sả đã giã tơi, hỗn hợp tỏi tiêu rễ ngò, 30 ml dầu hào, 15 ml nước mắm, 5 g đường cát trắng và 1 g muối còn lại; dùng tay bóp trộn đều và ướp trong ngăn mát ít nhất 30 phút.', NULL, 30),
('imp-8b874d97e90e00f0_v4_step_3', 'imp-8b874d97e90e00f0', 3, 'prep', 'Áo bột bắp và chuẩn bị lá chanh Kaffir thái chỉ', 'Rửa sạch 5 g lá chanh Kaffir, bỏ gân giữa và thái chỉ thật mảnh. Trước khi chiên, rắc đều 20 g bột bắp vào tô gà đã ướp, trộn nhẹ để lớp bột mỏng áo đều các miếng gà và sợi sả.', NULL, NULL),
('imp-8b874d97e90e00f0_v4_step_4', 'imp-8b874d97e90e00f0', 4, 'cook', 'Làm nóng dầu chiên ở nhiệt độ vừa 165°C', 'Đổ 450 ml dầu ăn vào nồi hoặc chảo sâu lòng, đun trên lửa vừa đến khi đạt khoảng 165°C (nhúng đầu đũa gỗ thấy sủi bọt lăn tăn nhẹ xung quanh). Không để dầu quá nóng bốc khói vì sả và đường trong gia vị ướp sẽ nhanh cháy sậm màu.', NULL, NULL),
('imp-8b874d97e90e00f0_v4_step_5', 'imp-8b874d97e90e00f0', 5, 'cook', 'Chiên gà cùng sợi sả vàng giòn chín đều', 'Thả gà vào chiên thành 2 mẻ vừa phải trên lửa vừa trong khoảng 5–6 phút, thỉnh thoảng đảo nhẹ để từng miếng gà chín tận lõi (không còn nước hồng khi xăm thử) và áo màu vàng nâu giòn rụm. Vớt gà và các sợi sả vàng giòn ra giá lưới cho ráo dầu.', 'Các sợi sả tơi thường chín vàng nhanh hơn thịt gà, hãy dùng vợt lưới vớt riêng những sợi sả vàng ruộm trước để tránh bị cháy đắng.', 6),
('imp-8b874d97e90e00f0_v4_step_6', 'imp-8b874d97e90e00f0', 6, 'finish', 'Xóc gà với lá chanh Kaffir và dọn kèm tương ớt', 'Cho toàn bộ gà chiên và sả chiên giòn vào tô khô, rắc lá chanh Kaffir thái chỉ vào xóc đều vài lượt để hơi nóng làm lá dậy hương thơm dịu. Bày ra đĩa, dọn nóng cùng chén tương ớt chua ngọt Thái và cơm hoặc xôi nếp.', 'Chỉ xóc lá chanh Kaffir thái chỉ sau khi vớt gà ra khỏi chảo dầu nóng để giữ được màu xanh tươi và hương thơm thanh mát.', NULL),
('imp-b95544e75512c4e8_v4_step_1', 'imp-b95544e75512c4e8', 1, 'prep', 'Chuẩn bị tỏi lát, ớt sừng và ngò tây', 'Bóc vỏ 2–3 tép tỏi tươi, bổ đôi lấy bỏ lõi xanh ở giữa cho dịu vị hăng rồi thái lát mỏng đều nhau. Rửa sạch 2 quả ớt sừng đỏ tươi, bỏ hạt nếu muốn giảm cay rồi thái lát mỏng; nhặt lá ngò tây tươi rửa sạch, thấm khô và thái nhỏ.', NULL, NULL),
('imp-b95544e75512c4e8_v4_step_2', 'imp-b95544e75512c4e8', 2, 'cook', 'Đun nước muối và luộc mì Ý non độ al dente', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 13 g muối hạt. Thả 240 g mì Ý Spaghetti khô vào luộc khoảng 7–8 phút (ít hơn 2 phút so với thời gian trên bao bì) để sợi mì còn chín tiếp khi xóc chảo. Múc giữ lại khoảng 150 ml nước luộc mì.', NULL, 8),
('imp-b95544e75512c4e8_v4_step_3', 'imp-b95544e75512c4e8', 3, 'sauce', 'Phi tỏi ớt trên lửa nhỏ với dầu ô liu', 'Đổ 45 ml dầu ô liu nguyên chất vào chảo rộng trên lửa thật nhỏ. Thả tỏi thái lát và ớt sừng vào phi từ từ khoảng 2 phút đến khi tỏi dậy mùi thơm và vừa ngả màu vàng nhạt thì nhấc chảo khỏi bếp ngay để tỏi không bị cháy đắng.', 'Có thể nghiêng nhẹ chảo cho dầu dồn về một góc để tỏi và ớt ngập đều dầu và chín vàng đồng loạt.', 2),
('imp-b95544e75512c4e8_v4_step_4', 'imp-b95544e75512c4e8', 4, 'sauce', 'Tạo nền nhũ tương dầu với nước luộc mì', 'Đặt chảo dầu tỏi ớt lên lại bếp ở lửa vừa, múc khoảng 60 ml nước luộc mì đang sôi vào chảo, đảo nhẹ để dầu và nước tinh bột sủi bọt hòa quyện bước đầu.', NULL, NULL),
('imp-b95544e75512c4e8_v4_step_5', 'imp-b95544e75512c4e8', 5, 'cook', 'Xóc mì Ý quyện sốt sánh bóng', 'Dùng kẹp gắp thẳng mì Ý Spaghetti từ nồi cho vào chảo, thêm từng ít nước luộc mì còn lại và xóc đảo liên tục trong 2 phút trên lửa vừa đến khi sợi mì chín tới hoàn toàn và được phủ lớp sốt óng mượt.', 'Gắp mì trực tiếp từ nồi sang chảo giúp tận dụng lượng nước tinh bột bám sẵn trên sợi mì để sốt sánh nhanh hơn.', 2),
('imp-b95544e75512c4e8_v4_step_6', 'imp-b95544e75512c4e8', 6, 'finish', 'Nêm lại muối, rắc ngò tây và dùng nóng', 'Nếm thử và rắc thêm phần muối hạt còn lại (khoảng 2 g) nếu cần, tắt bếp. Rắc ngò tây tươi thái nhỏ (nếu dùng) vào đảo đều lần cuối, chia mì ra 3 đĩa sâu lòng và thưởng thức ngay khi còn nóng hổi.', 'Rắc ngò tây tươi sau khi đã tắt bếp giúp giữ trọn sắc xanh tươi và hương thơm thanh mát cho đĩa mì.', NULL),
('imp-5ae4665cc17ff036_v4_step_1', 'imp-5ae4665cc17ff036', 1, 'prep', 'Sơ chế ngò tây, ớt tươi và dằm cà chua', 'Rửa sạch 12 g ngò tây tươi, thấm khô và thái nhỏ để riêng. Bỏ cuống 2 quả ớt tươi rồi thái khoanh mỏng (bỏ bớt hạt nếu ăn cay vừa); bóc vỏ 2 tép tỏi tươi, đập dập nhẹ. Trút 320 g cà chua lột vỏ đóng hộp ra tô và dùng nĩa dằm nát.', NULL, NULL),
('imp-5ae4665cc17ff036_v4_step_2', 'imp-5ae4665cc17ff036', 2, 'sauce', 'Phi thơm tỏi và ớt với dầu ô liu lửa nhỏ', 'Đặt chảo lớn lên bếp ở lửa nhỏ với 30 ml dầu ô liu nguyên chất, cho tỏi tươi và ớt tươi cắt khoanh vào đảo nhẹ khoảng 3 phút cho dầu dậy mùi cay thơm nồng mà không để tỏi cháy nâu.', 'Giữ lửa nhỏ khi phi tỏi ớt giúp tinh dầu ớt hòa tan sâu vào dầu ô liu mà không bị khét đắng.', 3),
('imp-5ae4665cc17ff036_v4_step_3', 'imp-5ae4665cc17ff036', 3, 'sauce', 'Ninh sánh sốt cà chua cay Arrabbiata', 'Trút toàn bộ cà chua dằm vào chảo, nêm 2 g muối ăn và đảo đều. Đun trên lửa vừa khoảng 15–18 phút, thỉnh thoảng khuấy đều cho sốt sánh đặc, không còn loãng nước; sau đó gắp bỏ tép tỏi ra ngoài.', 'Vớt bỏ tép tỏi sau khi sốt đã dậy hương giúp sốt Arrabbiata thanh vị và mịn đẹp.', 16),
('imp-5ae4665cc17ff036_v4_step_4', 'imp-5ae4665cc17ff036', 4, 'cook', 'Luộc mì Ý Penne đạt độ dai al dente', 'Khi sốt ninh được khoảng 10 phút, đun sôi mạnh nồi với 2,5 lít nước lọc cùng 12 g muối ăn. Thả 240 g mì Ý Penne rigate vào luộc khoảng 9–10 phút đến độ al dente, giữ lại 80 ml nước luộc mì trước khi vớt.', NULL, 10),
('imp-5ae4665cc17ff036_v4_step_5', 'imp-5ae4665cc17ff036', 5, 'cook', 'Xóc mì Penne quyện đều sốt cay', 'Cho mì Penne đã vớt thẳng vào chảo sốt cà chua cay, thêm 1–2 muỗng canh nước luộc mì nếu sốt đặc rồi xóc đảo đều tay khoảng 1–2 phút trên lửa vừa để từng ống mì bám đều sốt đỏ bóng.', 'Thêm một ít nước luộc mì giàu tinh bột giúp sốt cà chua cay bám mượt bên trong lẫn bên ngoài ống mì Penne.', 2),
('imp-5ae4665cc17ff036_v4_step_6', 'imp-5ae4665cc17ff036', 6, 'finish', 'Rắc ngò tây, phô mai Pecorino và dọn nóng', 'Tắt bếp, rắc phần lớn ngò tây tươi thái nhỏ vào đảo đều. Múc mì ra 3 đĩa sâu lòng, rắc phần ngò tây còn lại và 30 g phô mai Pecorino Romano bào lên trên nếu thích rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-9c48616208fff232_v4_step_1', 'imp-9c48616208fff232', 1, 'prep', 'Tách bông cải xanh và rang thơm hạnh nhân', 'Rửa sạch 450 g bông cải xanh tươi, chỉ tách lấy phần bông nhỏ vừa ăn (bông lớn chẻ đôi cho đều), bỏ phần cuống già. Rang 40 g hạnh nhân bóc vỏ trên chảo khô lửa vừa khoảng 1–2 phút đến khi dậy mùi thơm nhẹ rồi trút ra để riêng.', 'Rang hạnh nhân rất nhanh trên lửa vừa để giữ vị bùi ngọt mà không bị cháy đắng.', 2),
('imp-9c48616208fff232_v4_step_2', 'imp-9c48616208fff232', 2, 'cook', 'Phi tỏi và om mềm bông cải xanh', 'Cho 30 ml dầu ô liu nguyên chất vào chảo lớn, phi thơm tỏi tươi đập dập khoảng 1 phút rồi cho toàn bộ bông cải xanh vào đảo lửa lớn 2 phút cho xém cạnh nhẹ. Rót 150 ml nước lọc vào chảo, nêm 3 g muối ăn, đậy nắp om lửa nhỏ khoảng 12–15 phút đến khi bông cải chín mềm.', NULL, 14),
('imp-9c48616208fff232_v4_step_3', 'imp-9c48616208fff232', 3, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Trong lúc om bông cải, đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 11 g muối ăn. Cho 240 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút đạt độ al dente; múc giữ lại 100 ml nước luộc mì trước khi vớt.', NULL, 9),
('imp-9c48616208fff232_v4_step_4', 'imp-9c48616208fff232', 4, 'sauce', 'Xay mịn sốt kem bông cải xanh hạnh nhân', 'Gắp bỏ tép tỏi ra khỏi chảo bông cải, dùng nĩa dằm nhẹ vài bông trong chảo. Múc một nửa lượng bông cải đã om cùng một nửa lượng hạnh nhân rang cho vào máy xay với 25 g phô mai Parmesan bào và 2–3 muỗng canh nước luộc mì, xay thành sốt kem xanh mịn.', 'Chia đôi bông cải giúp món mì vừa có lớp sốt kem xanh mịn bám sợi vừa còn nguyên các bông giòn mềm.', NULL),
('imp-9c48616208fff232_v4_step_5', 'imp-9c48616208fff232', 5, 'cook', 'Trộn mì Ý với sốt bông cải và bơ lạt', 'Trút mì Ý Spaghetti vào chảo bông cải, đổ toàn bộ phần sốt kem bông cải xanh vừa xay vào rồi đảo đều tay 2 phút trên lửa vừa, thêm chút nước luộc mì nếu cần cho sốt bám mượt. Tắt bếp và đảo tan 15 g bơ lạt (nếu dùng).', 'Đảo tan bơ lạt sau khi tắt bếp giúp lớp sốt rau củ thêm bóng mượt và dậy mùi thơm béo dịu.', 2),
('imp-9c48616208fff232_v4_step_6', 'imp-9c48616208fff232', 6, 'finish', 'Rắc hạnh nhân rang, ớt tươi và dọn nóng', 'Chia mì ra 3 đĩa sâu lòng, rắc phần hạnh nhân rang còn lại (đập dập nhẹ), 10 g phô mai Parmesan bào và 1 quả ớt tươi thái lát (nếu dùng) lên trên, thưởng thức nóng ngay.', NULL, NULL),
('imp-b5571547ad5d2cec_v4_step_1', 'imp-b5571547ad5d2cec', 1, 'prep', 'Sơ chế cá hồi, hành tím và chanh vàng', 'Thấm thật khô 250 g phi lê cá hồi tươi rồi cắt khối vừa ăn cỡ 2 cm. Bóc vỏ và băm nhỏ 45 g hành tím; rửa sạch và băm nhỏ 10 g ngò tây tươi; bào lấy 1 muỗng cà phê vỏ vàng chanh vàng tươi và vắt lấy khoảng 25 ml nước cốt.', NULL, NULL),
('imp-b5571547ad5d2cec_v4_step_2', 'imp-b5571547ad5d2cec', 2, 'cook', 'Luộc mì Ý và giữ nước luộc giàu tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 10 g muối ăn. Thả 240 g mì Ý Penne vào luộc khoảng 8–9 phút (bớt 1–2 phút so với hướng dẫn bao bì) để đạt độ al dente; múc giữ lại 120 ml nước luộc mì trước khi vớt.', NULL, 9),
('imp-b5571547ad5d2cec_v4_step_3', 'imp-b5571547ad5d2cec', 3, 'sauce', 'Phi thơm hành tím và áp săn cá hồi', 'Đặt chảo lớn lên bếp ở lửa nhỏ với 30 ml dầu ô liu nguyên chất, cho hành tím băm và một nửa lượng ngò tây tươi vào đảo 3 phút đến khi hành mềm trong mà không cháy. Tăng lên lửa vừa, thả cá hồi vào đảo nhẹ tay khoảng 3 phút cho các mặt săn lại và chín đều.', 'Không đảo mạnh tay hay nấu cá hồi quá lâu để từng miếng cá giữ nguyên khối mềm ngọt.', 6),
('imp-b5571547ad5d2cec_v4_step_4', 'imp-b5571547ad5d2cec', 4, 'sauce', 'Khử rượu vang trắng và thêm nước cốt chanh', 'Rót 75 ml rượu vang trắng khô vào chảo cá hồi, đun liu riu 2 phút cho bay hơi hết mùi cồn. Tiếp theo rưới nước cốt chanh vàng cùng 2 g muối ăn và 1 g tiêu đen xay vào đảo nhẹ cho sốt hòa quyện.', 'Đun cho cồn rượu vang bay hơi hoàn toàn trước khi vắt chanh để sốt giữ được vị chua thanh dịu nhẹ.', 2),
('imp-b5571547ad5d2cec_v4_step_5', 'imp-b5571547ad5d2cec', 5, 'cook', 'Xóc mì Ý trong sốt cá hồi và đánh bóng bơ', 'Cho mì Ý đã vớt vào chảo cá hồi, rưới dần từng ít nước luộc mì và xóc đảo nhẹ tay 2 phút trên lửa vừa cho mì ngấm sốt. Tắt bếp hoàn toàn, thả 30 g bơ lạt cắt nhỏ vào đảo nhanh đến khi bơ tan chảy tạo lớp sốt sánh bóng.', 'Cho bơ lạt lạnh vào sau khi đã tắt bếp giúp sốt bơ chanh bám mượt quanh sợi mì mà không tách dầu.', 2),
('imp-b5571547ad5d2cec_v4_step_6', 'imp-b5571547ad5d2cec', 6, 'finish', 'Rắc vỏ chanh bào, ngò tây và thưởng thức nóng', 'Nếm lại gia vị cho vừa miệng, chia mì cá hồi ra 3 đĩa sâu lòng rồi rắc vỏ chanh vàng bào, phần ngò tây tươi còn lại và 0,5 g tiêu đen xay lên trên, dùng nóng ngay.', NULL, NULL),
('imp-7b5f0d33681ea7d2_v4_step_1', 'imp-7b5f0d33681ea7d2', 1, 'sauce', 'Nấu sốt cà chua húng quế sánh mịn', 'Đun nóng 30 ml dầu ô liu trong nồi nhỏ trên lửa vừa-nhỏ, cho 1 củ tỏi đập dập vào phi thơm trong 30 giây, đảo liên tục để tỏi không bị cháy đắng. Đổ 600 g cà chua nghiền đóng hộp Ý vào nồi, xé tay 10 g lá húng quế Tây thả vào, nêm 3 g muối ăn và 1 g tiêu đen xay. Đậy nắp hờ, hạ lửa nhỏ và om liu riu khoảng 20 phút cho sốt sánh dịu lại.', 'Xé lá húng quế bằng tay thay vì cắt dao giúp tinh dầu thơm giữ nguyên trong lá, đồng thời không để tỏi chuyển nâu vì sẽ làm đắng cả nồi sốt.', 20),
('imp-7b5f0d33681ea7d2_v4_step_2', 'imp-7b5f0d33681ea7d2', 2, 'prep', 'Dần mỏng và ướp ức gà', 'Rửa sạch 600 g ức gà phi lê, thấm thật khô bằng khăn giấy. Xẻ ngang mỗi miếng ức gà thành 2–3 lát dày đều nhau, đặt giữa hai lớp màng bọc thực phẩm hoặc giấy nến rồi dùng búa dần thịt đập nhẹ đến độ dày khoảng 0,5 cm. Rắc đều 3 g muối ăn và 1 g tiêu đen xay lên cả hai mặt lát gà.', 'Dần đều độ dày giúp các miếng gà chín đồng thời khi chiên, giữ được độ mọng nước bên trong mà lớp vỏ không bị cháy.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_3', 'imp-7b5f0d33681ea7d2', 3, 'prep', 'Chuẩn bị ba đĩa áo bột tẩm gà', 'Bày sẵn 3 đĩa sâu lòng: đĩa thứ nhất đựng 100 g bột mì đa dụng; đĩa thứ hai đập 2 quả trứng gà đánh tan đều cùng nước cốt 1/2 quả chanh vàng; đĩa thứ ba trộn đều 120 g bột chiên xù với 40 g phô mai Pecorino Romano bào mịn và một nửa lượng ngò tây băm (5 g). Lần lượt áo từng lát gà qua bột mì rồi giũ sạch bột thừa, nhúng qua trứng rồi lăn đều vào đĩa bột chiên xù, ấn nhẹ tay cho bột bám chặt hai mặt.', 'Để phần trứng thừa rỏ bớt trước khi đặt vào đĩa bột chiên xù giúp lớp áo bám khít, không bị vón cục và bong tróc khi chiên.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_4', 'imp-7b5f0d33681ea7d2', 4, 'cook', 'Chiên vàng giòn từng lát gà', 'Đổ 100 ml dầu ăn vào chảo rộng đáy dày, đun nóng trên lửa vừa đến khi thả thử vài vụn bột chiên xù thấy sủi bọt xèo mạnh. Đặt các lát gà đã tẩm bột vào chiên mỗi mặt khoảng 2 phút đến khi lớp vỏ chuyển màu vàng ruộm giòn tan và thịt gà bên trong chín trắng hoàn toàn (nhiệt tâm đạt 74°C). Gắp gà ra đĩa có lót giấy thấm dầu và đặt thêm tờ giấy lên mặt để hút bớt dầu thừa.', 'Chỉ lật gà đúng một lần trong quá trình chiên và để gà nghỉ trên giấy thấm dầu 2 phút để lớp vỏ giữ được độ giòn rụm tối đa.', 4),
('imp-7b5f0d33681ea7d2_v4_step_5', 'imp-7b5f0d33681ea7d2', 5, 'cook', 'Xếp gà cùng sốt cà chua và phô mai Mozzarella', 'Làm nóng lò nướng trước ở chế độ lửa trên 220°C. Múc 2 muôi sốt cà chua đã nấu trải đều xuống đáy khay nướng chịu nhiệt, xếp các lát gà chiên giòn lên trên, tiếp tục múc thêm sốt cà chua phủ đều mặt từng miếng gà. Xé 250 g phô mai Mozzarella tươi đã thấm ráo nước phủ kín lên trên và rắc phần ngò tây băm còn lại (5 g).', 'Nhớ thấm ráo nước của phô mai Mozzarella tươi trước khi xếp lên khay để nước phô mai không chảy ra làm ướt lớp vỏ giòn hay cháy khét thành khay.', NULL),
('imp-7b5f0d33681ea7d2_v4_step_6', 'imp-7b5f0d33681ea7d2', 6, 'finish', 'Nướng chảy phô mai và dọn nóng', 'Đặt khay gà vào rãnh trên của lò nướng trong khoảng 3–4 phút ở 220°C đến khi phô mai Mozzarella tan chảy hoàn toàn, sủi bọt nhẹ và hơi xém vàng ở mép. Lấy khay ra, nghỉ 2 phút rồi dọn nóng ngay ra đĩa ấm.', NULL, 4),
('imp-e3df53f1154592bc_v4_step_1', 'imp-e3df53f1154592bc', 1, 'prep', 'Làm nóng lò và sơ chế phi lê cá', 'Bật lò nướng làm nóng trước ở 200°C chế độ hai lửa trên-dưới trong 10 phút. Rửa nhanh 600 g phi lê cá thịt trắng dưới vòi nước lạnh, dùng nhíp kiểm tra gắp hết xương dăm dọc thớ thịt rồi thấm thật khô bề mặt cá bằng khăn giấy.', 'Thấm thật khô miếng cá giúp nước ướp và lớp vụn bánh mì bám chắc, đồng thời mặt cá khi nướng lên màu vàng đẹp mà không bị ra nước đục.', 10),
('imp-e3df53f1154592bc_v4_step_2', 'imp-e3df53f1154592bc', 2, 'marinate', 'Pha nước sốt chanh tỏi và ướp cá', 'Trong chén nhỏ, khuấy đều 30 ml dầu ô liu, nước cốt 1/2 quả chanh vàng, 1/2 lượng tỏi băm nhuyễn, 6 g ngò tây băm, 3 g muối ăn và 1 g tiêu đen xay. Xếp 4 miếng cá vào đĩa sâu, phết đều hỗn hợp lên hai mặt và để ướp khoảng 15 phút ở nhiệt độ phòng cho thấm vị.', 'Không ướp cá với nước cốt chanh quá 20 phút vì lượng axit tự nhiên có thể làm bề mặt thịt cá bị tái bở trước khi nướng.', 15),
('imp-e3df53f1154592bc_v4_step_3', 'imp-e3df53f1154592bc', 3, 'prep', 'Chuẩn bị cà chua và hỗn hợp vụn bánh mì thảo mộc', 'Cà chua chín rửa sạch, bổ đôi hoặc bổ múi cau vừa ăn; nửa quả chanh vàng còn lại thái lát mỏng. Trong bát riêng, trộn tơi 30 g bột chiên xù cùng phần tỏi băm còn lại, 6 g ngò tây băm và 15 ml dầu ô liu.', NULL, NULL),
('imp-e3df53f1154592bc_v4_step_4', 'imp-e3df53f1154592bc', 4, 'cook', 'Xếp cá cùng cà chua lên khay nướng', 'Phết đều 10 ml dầu ô liu còn lại lên đáy khay nướng chống dính (hoặc lót giấy nến). Đặt 4 khúc cá đã ướp vào giữa khay, xếp cà chua xen kẽ xung quanh, rắc 3 g muối ăn và 1 g tiêu đen xay còn lại lên cá và cà chua. Phủ đều hỗn hợp bột chiên xù thảo mộc lên kín mặt trên từng miếng cá.', NULL, NULL),
('imp-e3df53f1154592bc_v4_step_5', 'imp-e3df53f1154592bc', 5, 'cook', 'Nướng lò đến khi cá chín mọng, mặt vàng giòn', 'Đặt khay vào ngăn giữa lò nướng ở 200°C, nướng khoảng 15–18 phút. Khoảng 5 phút cuối, đặt thêm các lát chanh vàng mỏng lên mặt cá và nướng tiếp đến khi lớp vụn bánh mì chuyển vàng giòn, cà chua mềm nhừ tiết nước ngọt và thớ cá chuyển trắng đục hoàn toàn, dễ tách nhẹ bằng nĩa.', 'Canh chừng trong 5 phút cuối để cá vừa chín tới giữ độ mọng nước ngọt thịt, tránh nướng quá lâu làm phi lê cá bị khô xác.', 18),
('imp-e3df53f1154592bc_v4_step_6', 'imp-e3df53f1154592bc', 6, 'finish', 'Nghỉ cá và rưới nước sốt cà chua', 'Lấy khay cá ra khỏi lò, để cá nghỉ 3 phút cho phần nước ngọt ổn định bên trong thớ thịt. Chuyển cá và cà chua ra đĩa ấm, rưới phần nước sốt cà chua đọng dưới khay lên trên và rắc nốt 4 g ngò tây tươi băm nhỏ để hoàn thiện.', NULL, NULL),
('imp-a0ed6c762f7dceba_v4_step_1', 'imp-a0ed6c762f7dceba', 1, 'prep', 'Dần mỏng và thấm khô thịt thăn bò', 'Dùng mũi dao khía vài đường ngắn dọc viền gân mỡ để các lát thịt thăn bò không bị cong rút khi nấu. Đặt 500 g thịt bò thái lát lên một tờ giấy nến, phủ thêm tờ giấy nữa lên trên rồi dần nhẹ tay đến khi thịt đạt độ dày đều khoảng 3–4 mm mà không bị rách nát; thấm khô bề mặt thịt.', 'Không ướp muối trực tiếp lên thịt bò sống trước khi cho vào sốt vì muối sẽ kéo nước ra làm thịt dễ bị dai và sậm màu.', NULL),
('imp-a0ed6c762f7dceba_v4_step_2', 'imp-a0ed6c762f7dceba', 2, 'sauce', 'Phi thơm tỏi với dầu ô liu', 'Bóc vỏ, đập dập 3 tép tỏi. Đun nóng 30 ml dầu ô liu trong chảo rộng trên lửa vừa, thả tỏi đập dập vào phi khoảng 2 phút đến khi dậy mùi thơm dịu và tỏi vừa chuyển vàng nhẹ.', 'Giữ nhiệt vừa và đảo liên tục để tỏi không bị cháy khét vì tỏi cháy sẽ làm đắng toàn bộ phần sốt cà chua.', 2),
('imp-a0ed6c762f7dceba_v4_step_3', 'imp-a0ed6c762f7dceba', 3, 'sauce', 'Ninh sốt cà chua sánh vị', 'Đổ 350 g cà chua nghiền đóng hộp Ý vào chảo, dùng 50 ml nước lọc tráng sạch phần cà chua còn sót rồi rót vào cùng. Đun sôi nhẹ rồi hạ lửa nhỏ, om liu riu khoảng 15 phút và thỉnh thoảng khuấy đều cho sốt bay bớt hơi nước, sánh mịn và dịu vị chua.', NULL, 15),
('imp-a0ed6c762f7dceba_v4_step_4', 'imp-a0ed6c762f7dceba', 4, 'sauce', 'Nêm gia vị và lá Oregano', 'Khi sốt đã cạn sánh vừa ý, rắc 2 g lá Oregano khô, 5 g muối ăn và 2 g tiêu đen xay vào chảo, khuấy đều cho gia vị tan hoàn toàn rồi gắp bỏ các tép tỏi đã phi thơm.', 'Nêm lá Oregano vào bước sốt đã sánh giúp tinh dầu thảo mộc không bị bay hơi mất mùi và giữ được hương vị hài hòa, không át mất vị ngọt của thịt bò.', NULL),
('imp-a0ed6c762f7dceba_v4_step_5', 'imp-a0ed6c762f7dceba', 5, 'cook', 'Om nhanh các lát thịt bò trong sốt nóng', 'Xếp từng lát thịt bò đã dần mỏng vào chảo sao cho mặt thịt ngập đều trong lớp sốt (nếu lát quá lớn có thể cắt đôi). Giữ sốt sôi liu riu ở lửa vừa, nấu mỗi mặt khoảng 2 phút rồi lật mặt còn lại nấu thêm 2 phút đến khi thịt bò chín mềm vừa đủ và thấm đẫm sốt.', 'Do lát thịt đã được dần mỏng 3–4 mm nên thịt chín rất nhanh; tránh đun quá lâu hoặc để lửa quá lớn khiến thớ thịt bò bị co rút và dai.', 4),
('imp-a0ed6c762f7dceba_v4_step_6', 'imp-a0ed6c762f7dceba', 6, 'finish', 'Hoàn thiện và thưởng thức nóng', 'Kiểm tra thịt bò đã chín đều, nêm nếm lại sốt một lần cuối cho vừa miệng rồi tắt bếp. Xếp thịt ra đĩa sâu lòng, rưới đẫm phần sốt cà chua sánh đỏ lên trên và trang trí bằng vài lá húng quế Tây tươi trước khi dọn nóng.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_1', 'imp-2865ee57783628d7', 1, 'cook', 'Luộc mì xoắn Fusilli chín tới và làm nguội', 'Đun sôi mạnh 2000 ml nước lọc cùng 12 g muối ăn, thả 200 g mì Ý xoắn vào luộc khoảng 8–9 phút theo hướng dẫn bao bì để sợi mì đạt độ chín vừa tới (al dente). Vớt mì ra rổ, xả ngay dưới vòi nước lạnh cho nguội hoàn toàn và để ráo nước trong 5 phút.', 'Không luộc mì quá mềm vì sau khi trộn nước sốt mì sẽ tiếp tục hút ẩm; phải để mì thật ráo nước để nước sốt không bị loãng nhạt.', 9),
('imp-2865ee57783628d7_v4_step_2', 'imp-2865ee57783628d7', 2, 'prep', 'Sơ chế rau củ và phô mai Feta', 'Cà chua rửa sạch, bổ đôi hoặc cắt miếng hạt lựu; dưa leo tươi bổ dọc, dùng thìa nạo bỏ phần ruột mềm để salad không bị chảy nước rồi cắt hạt lựu 1 cm. Hành tây tím thái lát thật mỏng, lá húng quế Tây xé nhỏ và phô mai Feta cắt khối vuông 1,5 cm.', 'Nạo bỏ ruột dưa leo và thái hành tây tím thật mỏng giúp món salad giữ được độ giòn tươi lâu và không bị hăng gắt.', NULL),
('imp-2865ee57783628d7_v4_step_3', 'imp-2865ee57783628d7', 3, 'sauce', 'Pha nước sốt dầu ô liu chanh vàng', 'Cho 25 ml dầu ô liu, nước cốt 1/2 quả chanh vàng, 2 g lá Oregano khô, 3 g muối ăn còn lại và 1 g tiêu đen xay vào chén nhỏ. Dùng nĩa hoặc phới lồng nhỏ đánh đều tay khoảng 30 giây đến khi hỗn hợp hơi sánh quyện.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_4', 'imp-2865ee57783628d7', 4, 'finish', 'Trộn mì với nước sốt và rau củ', 'Cho toàn bộ mì Ý xoắn đã ráo hẳn nước vào tô trộn lớn, rưới đều nước sốt dầu ô liu chanh vàng lên trên và trộn kỹ để từng vòng xoắn mì áo đều gia vị. Tiếp tục cho cà chua, dưa leo tươi và hành tây tím vào đảo nhẹ nhàng.', NULL, NULL),
('imp-2865ee57783628d7_v4_step_5', 'imp-2865ee57783628d7', 5, 'finish', 'Thêm phô mai Feta và ủ mát', 'Nhẹ tay cho 150 g phô mai Feta cắt khối cùng một nửa lượng lá húng quế Tây (5 g) vào tô, đảo thật nhẹ để khối phô mai giữ nguyên hình dáng. Đậy kín tô và đặt vào ngăn mát tủ lạnh khoảng 30 phút cho salad thấm vị mát lạnh.', 'Phô mai Feta vốn có vị mặn sẵn nên hãy nếm thử sau khi trộn rồi mới điều chỉnh thêm muối hoặc nước cốt chanh nếu cần.', 30),
('imp-2865ee57783628d7_v4_step_6', 'imp-2865ee57783628d7', 6, 'finish', 'Trình bày và thưởng thức lạnh', 'Lấy tô salad ra khỏi tủ lạnh, đảo nhẹ lại một lượt, chia ra đĩa và rắc nốt 5 g lá húng quế Tây còn lại lên trên mặt trước khi dọn lạnh.', NULL, NULL),
('imp-f9481ae10c0cc62a_v4_step_1', 'imp-f9481ae10c0cc62a', 1, 'cook', 'Nấu mềm cà chua cùng bơ và húng quế', 'Rửa sạch 6 quả cà chua chín đỏ, bổ múi cau. Đun chảy 15 g bơ lạt trong nồi ở lửa vừa, cho cà chua cùng 6 g lá húng quế Tây vào đảo đều, hạ lửa nhỏ và nấu khoảng 10 phút đến khi cà chua mềm rục, tiết hết nước ngọt.', NULL, 10),
('imp-f9481ae10c0cc62a_v4_step_2', 'imp-f9481ae10c0cc62a', 2, 'cook', 'Xào hành tây và làm nền bột sánh', 'Trong nồi súp chính, đun chảy 20 g bơ lạt còn lại cùng 15 ml dầu ô liu ở lửa nhỏ. Cho 1 củ hành tây băm nhỏ vào xào 8 phút đến khi hành mềm trong, thêm 2 tép tỏi băm đảo thêm 1 phút cho thơm. Rắc 16 g bột mì đa dụng vào đảo đều liên tục 2 phút cho bột chín thơm mà không bị sậm màu.', 'Cho tỏi băm vào sau cùng khi hành tây gần chín mềm giúp tỏi giữ mùi thơm ngọt mà không bị cháy đắng.', 11),
('imp-f9481ae10c0cc62a_v4_step_3', 'imp-f9481ae10c0cc62a', 3, 'cook', 'Nấu sốt sữa và ninh cùng cà chua', 'Rót từ từ 450 ml sữa tươi không đường thành từng đợt nhỏ vào nồi hành tây bột mì, vừa rót vừa khuấy đều tay bằng phới lồng để hỗn hợp sánh mịn không vón cục, đun lửa vừa 5 phút. Tiếp theo đổ 500 ml nước dùng rau củ, 4 g đường cát trắng, 6 g muối ăn, 1,5 g tiêu đen xay và toàn bộ nồi cà chua đã nấu mềm vào, hạ lửa nhỏ đun liu riu thêm 12 phút.', 'Rót sữa từ từ từng chút một và khuấy đều ngay từ đầu là bí quyết để hỗn hợp bột mì tan mượt hoàn toàn.', 17),
('imp-f9481ae10c0cc62a_v4_step_4', 'imp-f9481ae10c0cc62a', 4, 'cook', 'Xay nhuyễn, lọc rây và hòa kem tươi', 'Tắt bếp, để súp nguội bớt 3 phút rồi dùng máy xay cầm tay xay thật nhuyễn, sau đó lọc hỗn hợp qua rây mịn để loại bỏ hoàn toàn vỏ và hạt cà chua. Đổ súp trở lại nồi, thêm 100 ml kem tươi nấu ăn vào khuấy đều rồi hâm ấm lại ở lửa thật nhỏ trong 2 phút, tuyệt đối không để sôi bùng.', 'Lọc súp qua rây giúp kết cấu súp sánh mịn mượt mà chuẩn nhà hàng, còn việc không đun sôi sau khi cho kem tươi giúp súp không bị tách béo lợn cợn.', NULL),
('imp-f9481ae10c0cc62a_v4_step_5', 'imp-f9481ae10c0cc62a', 5, 'cook', 'Áp chảo bánh mì hạt lựu giòn rụm', 'Cắt 2 lát bánh mì thành khối vuông nhỏ khoảng 1 cm. Làm nóng 10 ml dầu ô liu còn lại trên chảo chống dính ở lửa vừa, cho bánh mì vào đảo đều tay 4–5 phút đến khi các cạnh vàng giòn đều thì trút ra đĩa lót giấy thấm.', NULL, 5),
('imp-f9481ae10c0cc62a_v4_step_6', 'imp-f9481ae10c0cc62a', 6, 'finish', 'Múc súp nóng và trang trí', 'Nêm nếm lại súp lần cuối cho vừa miệng, múc nóng ra 4 bát sâu lòng, rắc 20 g phô mai Parmesan bào mịn lên trên và đặt các viên bánh mì áp chảo giòn cạnh bên để dùng kèm ngay khi súp còn nóng.', NULL, NULL),
('imp-e39ba043b6d1f19d_v4_step_1', 'imp-e39ba043b6d1f19d', 1, 'prep', 'Làm nóng lò và sơ chế bông cải xanh', 'Làm nóng lò nướng trước ở 200°C chế độ hai lửa trên-dưới trong 10 phút và lót giấy nến lên khay nướng rộng. Bông cải xanh tách thành từng bông vừa ăn cỡ 3–4 cm, giữ phần cuống non gọt sơ vỏ xơ rồi thái lát vừa; rửa sạch và vẩy thật ráo nước trên rổ.', 'Bông cải xanh cần thật ráo nước trước khi trộn dầu; rau còn ướt sẽ bị hấp mềm trong lò thay vì nướng xém cạnh caramel.', 10),
('imp-e39ba043b6d1f19d_v4_step_2', 'imp-e39ba043b6d1f19d', 2, 'prep', 'Thái cà rốt, hành tây và chuẩn bị tỏi', 'Cà rốt tươi gọt vỏ, thái khoanh chéo dày đều khoảng 1 cm để chín đồng bộ cùng bông cải. Hành tây bóc vỏ, bổ múi cau dày giữ nguyên chút gốc cho đỡ rời cánh; bóc vỏ 3–4 tép tỏi khô và đập dập nhẹ.', 'Để nguyên tép tỏi đập dập thay vì băm nhuyễn giúp tỏi nướng chín mềm ngọt dịu mà không bị cháy khét ở nhiệt độ cao.', NULL),
('imp-e39ba043b6d1f19d_v4_step_3', 'imp-e39ba043b6d1f19d', 3, 'marinate', 'Pha sốt dầu ô liu giấm Balsamic thảo mộc và trộn rau', 'Trong chén nhỏ, khuấy đều 45 ml dầu ô liu, 15 ml giấm Balsamic Ý, 3 g lá Oregano và hương thảo khô, 4,5 g muối ăn và 1 g tiêu đen xay. Cho toàn bộ bông cải xanh, cà rốt, hành tây và tỏi vào âu lớn, rưới sốt lên rồi dùng tay trộn đều để gia vị bám đều khắp các mặt rau củ.', NULL, NULL),
('imp-e39ba043b6d1f19d_v4_step_4', 'imp-e39ba043b6d1f19d', 4, 'cook', 'Xếp rau một lớp đều trên khay nướng', 'Trút toàn bộ rau củ đã trộn sốt ra khay có lót giấy nến, dàn đều thành một lớp duy nhất với khoảng cách thoáng giữa các miếng rau để hơi nóng lưu thông dễ dàng.', 'Không xếp rau chồng chéo lên nhau vì hơi nước tích tụ sẽ làm rau bị sũng nước thay vì chín xém giòn cạnh.', NULL),
('imp-e39ba043b6d1f19d_v4_step_5', 'imp-e39ba043b6d1f19d', 5, 'cook', 'Nướng rau ở 200°C và đảo mặt giữa chừng', 'Đặt khay vào ngăn giữa lò nướng ở 200°C trong khoảng 25–30 phút. Sau 15 phút đầu, kéo khay ra đảo nhẹ một lượt để các mặt rau vàng đều rồi nướng tiếp đến khi cà rốt mềm bùi, hành tây ngọt trong và viền bông cải xém caramel.', NULL, 28),
('imp-e39ba043b6d1f19d_v4_step_6', 'imp-e39ba043b6d1f19d', 6, 'finish', 'Rưới giấm Balsamic cuối và dọn nóng', 'Lấy khay rau nướng ra, rưới nốt 5 ml giấm Balsamic Ý còn lại lên rau khi còn nóng hổi để dậy hương chua ngọt dịu thanh, gắp rau củ ra đĩa và dọn dùng nóng hoặc ấm.', NULL, NULL),
('imp-f50c115d909f97f2_v4_step_1', 'imp-f50c115d909f97f2', 1, 'prep', 'Làm sạch và cắt thái hai loại nấm tươi', 'Cắt bỏ phần gốc bám đất của 200 g nấm đùi gà tươi và 150 g nấm rơm, ngâm nhanh trong thau nước pha 2 g muối ăn khoảng 3 phút rồi rửa lại nước sạch và vắt nhẹ cho ráo. Thái lát xéo nấm đùi gà dày 0,5 cm, bổ đôi nấm rơm để khi nấu giữ độ giòn sần sật.', 'Không ngâm nấm quá lâu trong nước vì nấm sẽ hút nhiều nước, bị nhũn và mất đi vị ngọt tự nhiên.', 3),
('imp-f50c115d909f97f2_v4_step_2', 'imp-f50c115d909f97f2', 2, 'prep', 'Sơ chế cà chua và các gia vị thơm', 'Rửa sạch 3 quả cà chua chín đỏ, bỏ cuống; thái hạt lựu 1 quả để xào lấy màu đỏ cam, 2 quả còn lại bổ múi cau. Bóc vỏ và băm nhỏ 15 g hành tím, 1/2 củ tỏi khô; thái sợi mỏng 10 g gừng tươi và cắt khúc 1,5 cm 1/2 bó hành lá (riêng đầu hành băm nhỏ).', NULL, NULL),
('imp-f50c115d909f97f2_v4_step_3', 'imp-f50c115d909f97f2', 3, 'cook', 'Phi thơm hành tỏi và xào cà chua tạo màu', 'Làm nóng nồi trên lửa vừa với 25 ml dầu ăn, cho hành tím, tỏi khô, đầu hành băm và gừng thái sợi vào phi thơm khoảng 1 phút. Trút phần cà chua thái hạt lựu cùng 1 g muối ăn vào xào đều 3 phút đến khi cà chua mềm nhuyễn, tiết nước sốt màu đỏ cam sánh nhẹ.', 'Xào kỹ phần cà chua băm trước giúp nước canh có màu đỏ tự nhiên bắt mắt mà vẫn giữ được những múi cà chua nguyên đẹp thả vào sau.', 3),
('imp-f50c115d909f97f2_v4_step_4', 'imp-f50c115d909f97f2', 4, 'cook', 'Xào săn nấm tươi dậy hương ngọt', 'Tăng nhẹ lên lửa vừa lớn, cho toàn bộ nấm đùi gà và nấm rơm vào nồi đảo đều tay khoảng 2 phút cùng cà chua xào để nấm săn bề mặt và dậy mùi thơm đặc trưng.', NULL, 2),
('imp-f50c115d909f97f2_v4_step_5', 'imp-f50c115d909f97f2', 5, 'cook', 'Đổ nước nấu sôi và nêm vị chua thanh', 'Đổ 1300 ml nước lọc vào nồi, đun lửa lớn đến khi sôi bùng rồi hạ lửa vừa, hớt sạch bọt nổi. Thả 2 quả cà chua bổ múi cau vào nấu thêm 3 phút cho nấm chín ngọt hoàn toàn. Nêm 25 ml nước mắm ngon, 2 g muối ăn còn lại, 8 g đường cát trắng và 5 ml giấm gạo cho đạt vị chua thanh ngọt dịu.', 'Nếu muốn dùng làm món canh chay thuần, bạn có thể thay nước mắm bằng nước tương ngon hoặc nước mắm chay với lượng tương đương.', 3),
('imp-f50c115d909f97f2_v4_step_6', 'imp-f50c115d909f97f2', 6, 'finish', 'Rắc hành lá, tiêu xay và dùng nóng', 'Khi cà chua múi cau vừa chín mềm không bị nát, tắt bếp ngay và thả hành lá cắt khúc vào nồi đảo nhẹ. Múc canh ra tô lớn, rắc 1 g tiêu đen xay lên mặt rồi dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-ae5b053b8361f807_v4_step_1', 'imp-ae5b053b8361f807', 1, 'prep', 'Làm sạch tôm tươi và ướp nhẹ gia vị', 'Bóc vỏ, bỏ đầu và rút sạch chỉ đen dọc lưng 350 g tôm tươi, rửa sạch rồi để ráo. Ướp tôm với 10 ml nước mắm, 2 g muối ăn, 1 g tiêu đen xay và phần đầu hành lá băm nhỏ trong 10 phút để thịt tôm săn đậm vị.', NULL, 10),
('imp-ae5b053b8361f807_v4_step_2', 'imp-ae5b053b8361f807', 2, 'prep', 'Sơ chế sả tươi, cà chua, chanh và ớt hiểm', 'Rửa sạch 3 cây sả tươi; lấy 1 cây băm thật nhuyễn, 2 cây còn lại đập dập rồi cắt khúc 5 cm. Rửa sạch 3 quả cà chua chín đỏ, bổ múi cau. Đập dập 1 quả ớt hiểm, thái lát 1 quả còn lại; vắt lấy nước cốt 1 quả chanh tươi và bỏ hết hạt; hành lá thái khúc 1,5 cm.', NULL, NULL),
('imp-ae5b053b8361f807_v4_step_3', 'imp-ae5b053b8361f807', 3, 'cook', 'Phi thơm sả băm và xào sơ cà chua', 'Đặt nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho sả băm và sả cây đập dập vào phi khoảng 1 phút đến khi dậy hương thơm nồng đặc trưng. Thêm một nửa số cà chua bổ múi cau vào đảo 2 phút cho cà hơi mềm và tiết sắc đỏ cam nhẹ.', 'Xào nhanh sả đập dập trong dầu nóng trước khi đổ nước sẽ giúp tinh dầu sả tiết ra tối đa, làm nước canh thơm lừng.', 2),
('imp-ae5b053b8361f807_v4_step_4', 'imp-ae5b053b8361f807', 4, 'cook', 'Nấu sôi nước dùng sả thơm lừng', 'Đổ 1250 ml nước lọc vào nồi, thêm 1 quả ớt hiểm đập dập rồi đun lửa lớn đến khi sôi bùng. Hạ lửa vừa nấu thêm 4 phút cho sả và ớt tiết hết hương thơm vào nước dùng, hớt sạch bọt nổi để nước canh trong veo.', 'Không đun sả quá lâu ở lửa lớn vì nước dễ bị đục; giữ sôi vừa khoảng 4 phút là đủ để nước ngấm vị sả thơm.', 4),
('imp-ae5b053b8361f807_v4_step_5', 'imp-ae5b053b8361f807', 5, 'cook', 'Thả cà chua còn lại và nấu chín tôm tươi', 'Cho nốt phần cà chua múi cau còn lại vào nồi, nêm 25 ml nước mắm ngon, 3 g muối ăn và 10 g đường cát trắng. Khi nước sôi trở lại, thả toàn bộ tôm tươi đã ướp vào nấu trên lửa vừa khoảng 3 phút đến khi tôm cong tròn, chuyển màu đỏ cam đều và thịt chín chắc hoàn toàn.', NULL, 3),
('imp-ae5b053b8361f807_v4_step_6', 'imp-ae5b053b8361f807', 6, 'finish', 'Vắt chanh tươi sau khi tắt bếp và dọn canh', 'Tắt bếp để nồi canh ngừng sôi hẳn rồi từ từ rưới nước cốt chanh tươi vào khuấy nhẹ, nếm lại vị chua cay mặn ngọt hài hòa. Thả hành lá cắt khúc và ớt hiểm thái lát lên mặt, múc canh nóng ra tô thưởng thức cùng cơm trắng.', 'Chỉ rưới nước cốt chanh khi đã tắt bếp để tránh nhiệt độ cao làm tinh dầu vỏ chanh tiết vị đắng và mất mùi thơm thanh mát.', NULL),
('imp-ac77ed3af015efd7_v4_step_1', 'imp-ac77ed3af015efd7', 1, 'prep', 'Thái lát mỏng và ướp thịt bò thăn', 'Thấm thật khô 300 g thịt bò thăn bằng khăn giấy rồi thái lát mỏng ngang thớ. Cho thịt bò vào tô, ướp với 1/2 lượng tỏi băm, đầu hành lá băm, 2 g hạt nêm, 2 g muối ăn, 1 g tiêu đen xay và 5 ml dầu ăn trong 15 phút cho thịt ngấm vị và mềm ẩm.', 'Trộn thêm chút dầu ăn vào bước ướp giúp bề mặt lát bò mềm mượt, không bị khô xơ khi gặp nước sôi.', 15),
('imp-ac77ed3af015efd7_v4_step_2', 'imp-ac77ed3af015efd7', 2, 'prep', 'Sơ chế bắp cải, cà chua và rau thơm', 'Tách rời từng lá 1/2 bắp cải trắng, rửa sạch dưới vòi nước rồi cắt miếng vuông cạnh 4 cm vừa ăn. Rửa sạch 1 quả cà chua chín, bổ múi cau; nhặt rửa sạch ngò rí và phần lá xanh hành lá rồi cắt khúc 2 cm.', NULL, NULL),
('imp-ac77ed3af015efd7_v4_step_3', 'imp-ac77ed3af015efd7', 3, 'cook', 'Phi thơm tỏi và xào tái nhanh thịt bò', 'Làm nóng nồi trên lửa lớn vừa với 10 ml dầu ăn còn lại, phi thơm phần tỏi băm còn lại khoảng 30 giây. Cho thịt bò đã ướp vào đảo nhanh tay 1 phút đến khi thịt vừa chín tái khoảng 70% thì trút ngay ra đĩa riêng.', 'Xào tái nhanh trên lửa lớn rồi vớt ra đĩa riêng giúp thịt bò thơm mùi tỏi phi mà không bị nấu quá lửa gây dai.', 1),
('imp-ac77ed3af015efd7_v4_step_4', 'imp-ac77ed3af015efd7', 4, 'cook', 'Nấu nước dùng bắp cải ngọt thanh', 'Dùng luôn nồi vừa xào thịt, cho cà chua bổ múi cau vào đảo sơ 1 phút rồi đổ 1400 ml nước lọc vào đun lửa lớn đến khi sôi bùng. Hớt sạch bọt nổi, thả toàn bộ bắp cải vào nấu trên lửa vừa khoảng 6 phút đến khi cọng bắp cải chuyển màu trong và chín mềm ngọt.', NULL, 6),
('imp-ac77ed3af015efd7_v4_step_5', 'imp-ac77ed3af015efd7', 5, 'cook', 'Nêm gia vị và thả thịt bò chín tới', 'Nêm 18 ml nước mắm ngon, 3 g hạt nêm và 4 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều. Trút đĩa thịt bò xào tái cùng phần nước tiết ra vào nồi, đun sôi trở lại khoảng 30–40 giây cho thịt bò chín hoàn toàn rồi tắt bếp ngay.', 'Đổ cả phần nước ngọt tiết ra trên đĩa thịt bò vào nồi canh sẽ giúp nước dùng tăng thêm độ ngọt tự nhiên.', NULL),
('imp-ac77ed3af015efd7_v4_step_6', 'imp-ac77ed3af015efd7', 6, 'finish', 'Thêm hành ngò, tiêu xay và dùng nóng', 'Thả hành lá và ngò rí cắt khúc vào nồi đảo nhẹ một lượt, múc canh nóng ra tô lớn và rắc 0,5 g tiêu đen xay lên mặt trước khi dọn cơm.', NULL, NULL),
('imp-4ec35a6c12daa33d_v4_step_1', 'imp-4ec35a6c12daa33d', 1, 'prep', 'Làm sạch khử tanh và trụng sơ mực tươi', 'Rút bỏ túi mực, nội tạng, mắt và răng ở đầu 450 g mực tươi, lột bỏ lớp da ngoài nếu thích rồi ngâm mực với nước pha 15 ml rượu trắng trong 8 phút để khử mùi tanh, rửa sạch và khứa vảy rồng, cắt miếng vừa ăn. Trụng nhanh mực qua nồi nước sôi 1 phút rồi vớt ra để thật ráo.', 'Trụng nhanh qua nước sôi giúp mực săn giòn và hạn chế tiết quá nhiều nước loãng khi kho.', 8),
('imp-4ec35a6c12daa33d_v4_step_2', 'imp-4ec35a6c12daa33d', 2, 'marinate', 'Ướp mực cùng nước mắm và tiêu đen xay', 'Cho mực đã ráo vào tô, ướp với 25 ml nước mắm ngon, 4 g đường cát trắng, 4 g hạt nêm, 1,5 g tiêu đen xay và 1 quả ớt hiểm thái lát. Trộn đều và để 15 phút cho mực thấm gia vị.', NULL, 15),
('imp-4ec35a6c12daa33d_v4_step_3', 'imp-4ec35a6c12daa33d', 3, 'sauce', 'Thắng nước màu và phi thơm hành tỏi', 'Làm nóng nồi đất hoặc chảo với 30 ml dầu ăn và 8 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan và chuyển màu nâu cánh gián. Rót nhanh 20 ml nước lọc khuấy đều rồi cho hành tím và tỏi băm vào phi thơm 1 phút.', 'Phi hành tỏi trên lửa nhỏ sau khi hãm nước màu để hành tỏi thơm vàng mà không bị cháy đắng.', NULL),
('imp-4ec35a6c12daa33d_v4_step_4', 'imp-4ec35a6c12daa33d', 4, 'cook', 'Đảo săn mực trên lửa lớn', 'Vặn lửa lớn, trút toàn bộ mực đã ướp vào nồi đảo nhanh tay trong 3 phút cho bề mặt mực săn lại và áo đều nước màu cánh gián.', NULL, 3),
('imp-4ec35a6c12daa33d_v4_step_5', 'imp-4ec35a6c12daa33d', 5, 'cook', 'Kho liu riu đến khi nước sốt sánh sệt', 'Thêm 30 ml nước lọc còn lại vào nồi, hạ lửa nhỏ kho liu riu không đậy nắp trong 7 phút cho đến khi mực chín trắng đục hoàn toàn và nước kho rút cạn sánh bóng bám quanh từng miếng mực.', 'Không kho mực quá 10 phút vì thịt mực sẽ bị teo nhỏ, dai cứng và mất đi độ giòn ngọt tự nhiên.', 7),
('imp-4ec35a6c12daa33d_v4_step_6', 'imp-4ec35a6c12daa33d', 6, 'finish', 'Rắc hành lá, tiêu đen và dọn dùng nóng', 'Nêm lại vừa miệng, thả hành lá cắt khúc, quả ớt hiểm thái lát còn lại và 1,5 g tiêu đen xay vào đảo nhẹ rồi tắt bếp. Múc mực kho tiêu ra đĩa và dùng nóng với cơm trắng.', NULL, NULL),
('imp-01121ea953ffed76_v4_step_1', 'imp-01121ea953ffed76', 1, 'prep', 'Chần sơ sườn non và luộc bóc vỏ trứng cút', 'Rửa sạch 600 g sườn non với 2 g muối, chặt miếng vừa ăn rồi chần qua nồi nước sôi pha 3 g muối trong 3 phút để sạch bọt bẩn, vớt ra rửa lại nước lạnh và để ráo. Luộc 15 quả trứng cút trong nước sôi 7 phút rồi ngâm ngay vào thau nước lạnh 5 phút trước khi bóc sạch vỏ.', 'Ngâm trứng cút vào nước lạnh ngay sau khi luộc giúp vỏ tách dễ dàng và lòng đỏ không bị thâm xanh.', 7),
('imp-01121ea953ffed76_v4_step_2', 'imp-01121ea953ffed76', 2, 'marinate', 'Ướp sườn non với gia vị và hành tỏi băm', 'Băm nhuyễn hành tím, tỏi khô và 1 quả ớt hiểm. Cho sườn vào tô lớn, ướp cùng một nửa lượng hành tỏi băm, ớt băm, 25 ml nước mắm ngon, 10 g đường cát trắng, 3 g muối và 1 g tiêu đen xay. Trộn đều và ướp 30 phút cho sườn thấm sâu.', NULL, 30),
('imp-01121ea953ffed76_v4_step_3', 'imp-01121ea953ffed76', 3, 'sauce', 'Thắng nước màu cánh gián và xào săn sườn', 'Đun nóng 10 ml dầu ăn với 15 g đường cát trắng còn lại trong nồi đáy dày trên lửa nhỏ đến khi đường tan chuyển màu nâu cánh gián, rót nhanh 30 ml nước lọc ấm vào khuấy đều. Thêm 20 ml dầu ăn và phi thơm phần hành tím tỏi băm còn lại, rồi trút sườn vào xào săn trên lửa vừa 4 phút.', NULL, 4),
('imp-01121ea953ffed76_v4_step_4', 'imp-01121ea953ffed76', 4, 'cook', 'Đảo nhẹ trứng cút và đổ nước dừa tươi', 'Thả 15 quả trứng cút đã bóc vỏ và 2 quả ớt hiểm nguyên trái vào nồi sườn, đảo nhẹ tay 2 phút cho trứng áo đều lớp nước màu đẹp. Rót 500 ml nước dừa tươi vào ngập mặt sườn, đun sôi bùng và hớt sạch bọt nổi.', 'Đảo nhẹ tay bằng muỗng gỗ hoặc lắc nồi khi có trứng cút để giữ trứng tròn nguyên không bị sứt mẻ.', NULL),
('imp-01121ea953ffed76_v4_step_5', 'imp-01121ea953ffed76', 5, 'cook', 'Kho liu riu cho sườn mềm và nước sánh lại', 'Hạ lửa nhỏ, đậy hé vung kho liu riu trong 30 phút cho thịt sườn mềm rệu (thêm 70 ml nước lọc ấm nếu nước dừa cạn nhanh). Mở nắp tăng lên lửa vừa kho tiếp 5 phút cùng 10 ml nước mắm còn lại đến khi nước kho rút còn khoảng một phần ba và sánh bóng.', 'Chừa lại phần nước kho sánh vừa phải ở đáy nồi để chan cơm nóng hoặc chấm rau luộc sẽ đậm vị hơn.', 30),
('imp-01121ea953ffed76_v4_step_6', 'imp-01121ea953ffed76', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện món ăn', 'Nêm lại gia vị vừa khẩu vị rồi tắt bếp. Múc sườn non và trứng cút ra đĩa sâu lòng, rưới nước kho óng ả và rắc hành lá cắt nhỏ cùng 1 g tiêu đen xay còn lại lên trên để dùng nóng với cơm trắng.', NULL, NULL),
('imp-296b724137581830_v4_step_1', 'imp-296b724137581830', 1, 'prep', 'Thấm khô, cắt miếng đậu phụ và băm tỏi', 'Rửa nhẹ 4 bìa đậu phụ trắng qua nước sạch, thấm thật ráo rồi cắt thành các miếng vuông vừa ăn cỡ 3x3 cm. Bóc vỏ tỏi khô băm nhuyễn; hành lá rửa sạch thái nhỏ; ớt tươi thái lát mỏng.', 'Thấm thật khô đậu phụ trước khi cho vào chảo dầu nóng giúp đậu nhanh vàng giòn, không bị bắn dầu và không dính chảo.', NULL),
('imp-296b724137581830_v4_step_2', 'imp-296b724137581830', 2, 'cook', 'Chiên vàng đều hai mặt đậu phụ', 'Làm nóng chảo chống dính với 25 ml dầu ăn trên lửa vừa, xếp từng miếng đậu phụ vào chiên khoảng 4 phút mỗi mặt đến khi lớp vỏ ngoài phồng nhẹ và vàng đều các mặt thì gắp ra đĩa có lót giấy thấm dầu.', NULL, 8),
('imp-296b724137581830_v4_step_3', 'imp-296b724137581830', 3, 'sauce', 'Pha chén sốt nước tương tiêu đen', 'Trong chén riêng, khuấy tan 35 ml nước tương, 12 g đường cát trắng, 4 g hạt nêm chay nấm hương, 1 g tiêu đen xay và 80 ml nước lọc cho đến khi đường và hạt nêm tan hoàn toàn.', 'Pha tan trước hỗn hợp gia vị trong chén giúp khi đổ vào chảo nóng không bị vón cục và thấm đều từng miếng đậu.', NULL),
('imp-296b724137581830_v4_step_4', 'imp-296b724137581830', 4, 'cook', 'Phi thơm tỏi băm và đun sôi sốt kho', 'Chắt bớt dầu thừa trong chảo, giữ lại khoảng 10 ml dầu ăn phi thơm tỏi băm trên lửa vừa khoảng 1 phút đến khi vừa ngả vàng thơm. Đổ chén nước sốt nước tương vào chảo đun sôi nhẹ 1 phút cho gia vị hòa quyện.', NULL, NULL),
('imp-296b724137581830_v4_step_5', 'imp-296b724137581830', 5, 'cook', 'Kho nhỏ lửa cho đậu phụ ngấm sốt sánh keo', 'Xếp nhẹ nhàng đậu phụ đã chiên vàng vào chảo sốt, hạ lửa nhỏ kho liu riu trong 8 phút. Thỉnh thoảng lắc nhẹ chảo hoặc lật mặt từng miếng đậu thật nhẹ tay để đậu thấm đều gia vị và nước kho rút sánh keo lại.', 'Hạn chế dùng đũa khuấy mạnh để giữ nguyên vẹn các miếng đậu vàng giòn ngấm sốt.', 8),
('imp-296b724137581830_v4_step_6', 'imp-296b724137581830', 6, 'finish', 'Rắc tiêu đen, hành lá và dọn nóng', 'Khi nước kho đã sệt sánh bóng quanh miếng đậu, rắc 1,5 g tiêu đen xay còn lại, hành lá thái nhỏ và ớt tươi cắt lát vào đảo nhẹ rồi tắt bếp. Bày đậu phụ kho tiêu ra đĩa và ăn nóng với cơm trắng.', NULL, NULL),
('imp-54c8037962551d6b_v4_step_1', 'imp-54c8037962551d6b', 1, 'prep', 'Nhặt rửa và làm ráo hoàn toàn giá đỗ', 'Nhặt bỏ phần rễ dài và vỏ đậu đen còn sót trên giá đỗ, rửa nhẹ tay 2 lần nước sạch rồi vớt ra rổ thưa, vẩy thật ráo nước để khi xào giá không bị ra nước và nát dập.', 'Để giá đỗ thật khô ráo trước khi xào giúp món ăn giòn sần sật và không bị sũng nước dưới đáy đĩa.', NULL),
('imp-54c8037962551d6b_v4_step_2', 'imp-54c8037962551d6b', 2, 'prep', 'Chuẩn bị tỏi băm và hành lá', 'Tỏi khô bóc vỏ, đập dập rồi băm nhỏ. Hành lá rửa sạch, bỏ gốc già và cắt khúc dài khoảng 4 cm để chung một chén.', NULL, NULL),
('imp-54c8037962551d6b_v4_step_3', 'imp-54c8037962551d6b', 3, 'cook', 'Phi thơm vàng tỏi băm', 'Đặt chảo rộng lên bếp lửa vừa-lớn, đun nóng 25 ml dầu ăn rồi cho tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi vừa ngả vàng nhẹ và tỏa mùi thơm lừng.', 'Không phi tỏi quá cháy sẫm vì tỏi khét sẽ làm mất vị ngọt thanh của giá đỗ.', NULL),
('imp-54c8037962551d6b_v4_step_4', 'imp-54c8037962551d6b', 4, 'cook', 'Xào giá đỗ chớp nhoáng trên lửa lớn', 'Vặn bếp lên lửa lớn nhất, trút toàn bộ giá đỗ vào chảo dầu tỏi và đảo nhanh tay liên tục khoảng 1 phút. Rắc 5 g hạt nêm, 3 g muối ăn và rưới 8 ml nước mắm ngon, tiếp tục đảo đều thêm 1 phút cho cọng giá vừa chín tới vẫn còn căng giòn.', 'Tổng thời gian xào giá trên chảo chỉ nên từ 1,5 đến 2 phút để giữ trọn độ giòn mọng.', 2),
('imp-54c8037962551d6b_v4_step_5', 'imp-54c8037962551d6b', 5, 'cook', 'Thêm hành lá và tiêu đen xay', 'Thả hành lá cắt khúc và 1,5 g tiêu đen xay vào chảo giá đỗ, đảo nhanh tay thêm 15–20 giây cho hành vừa chín xanh rồi tắt bếp ngay.', NULL, 1),
('imp-54c8037962551d6b_v4_step_6', 'imp-54c8037962551d6b', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp ngay giá đỗ xào tỏi ra đĩa phẳng để tránh hơi nóng trong chảo làm giá tiếp tục chín mềm, rưới chút nước xào thơm mùi tỏi lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-e75e90d847daa628_v4_step_1', 'imp-e75e90d847daa628', 1, 'marinate', 'Làm sạch và ướp tôm, mực tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch lưng rút chỉ đen rồi rửa sạch. Mực ống rút bỏ túi mực và nội tạng, rửa sạch và thái khoanh dày 1 cm. Cho tôm và mực vào tô ướp cùng 3 g hạt nêm, 3 g đường cát trắng và 1 g tiêu đen xay trong 15 phút.', NULL, 15),
('imp-e75e90d847daa628_v4_step_2', 'imp-e75e90d847daa628', 2, 'prep', 'Sơ chế rau củ và trụng mì trứng dai tơi', 'Cải thìa tách lá rửa sạch, cắt khúc 5 cm; cà rốt thái lát mỏng; ớt chuông bỏ hạt thái sợi; hành tây bổ múi cau; hành tím và tỏi khô băm nhỏ; hành lá và ngò rí cắt khúc. Ngâm mì trứng khô trong nước lạnh 5 phút cho mềm rồi trụng qua nước sôi 45 giây, vớt ngay ra xả nước lạnh, để thật ráo rồi trộn với 5 ml dầu ăn để sợi mì tơi bóng.', 'Xả nước lạnh ngay sau khi trụng mì và xóc với chút dầu ăn giúp sợi mì giữ độ dai và không bị bết dính khi xào.', 5),
('imp-e75e90d847daa628_v4_step_3', 'imp-e75e90d847daa628', 3, 'cook', 'Xào chín tôm và mực trên lửa lớn', 'Làm nóng 15 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một nửa lượng tỏi và hành tím băm. Trút tôm mực đã ướp vào đảo nhanh tay 2–3 phút đến khi tôm chuyển màu đỏ cam và mực săn cuộn chín hoàn toàn thì trút riêng ra đĩa.', 'Xào riêng hải sản trên lửa lớn giúp tôm mực chín giòn ngọt mà không tiết nước làm nhão mì.', 3),
('imp-e75e90d847daa628_v4_step_4', 'imp-e75e90d847daa628', 4, 'cook', 'Xào chín tới cà rốt, ớt chuông và cải thìa', 'Dùng lại chảo, đun nóng 20 ml dầu ăn còn lại rồi phi thơm nốt hành tím và tỏi băm. Cho cà rốt và ớt chuông vào xào trước với 40 ml nước lọc, nêm 3 g hạt nêm, 3 g đường cát trắng và 2 g muối ăn khoảng 2 phút trên lửa vừa-lớn; sau đó thêm cải thìa và hành tây đảo thêm 1,5 phút cho rau vừa chín tới.', NULL, 3),
('imp-e75e90d847daa628_v4_step_5', 'imp-e75e90d847daa628', 5, 'cook', 'Đảo mì trứng quyện sốt dầu hào và hải sản', 'Cho toàn bộ mì trứng đã ráo vào chảo rau củ, rưới 15 ml dầu hào và 15 ml nước tương (xì dầu), đảo đều tay trên lửa lớn khoảng 1,5 phút cho sợi mì thấm sốt nâu bóng. Tiếp theo trút đĩa tôm mực trở lại chảo, đảo đều thêm 1 phút cho quyện đều.', 'Dùng hai chiếc đũa đảo tơi mì cùng rau và hải sản giúp sợi mì không bị đứt gãy.', NULL),
('imp-e75e90d847daa628_v4_step_6', 'imp-e75e90d847daa628', 6, 'finish', 'Thêm hành lá, ngò rí và dùng nóng', 'Thả hành lá và ngò rí cắt khúc vào đảo nhanh 15 giây rồi tắt bếp. Bày mì xào hải sản ra đĩa rộng, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng ngay.', NULL, NULL),
('imp-1e6d5d1750d3aa51_v4_step_1', 'imp-1e6d5d1750d3aa51', 1, 'marinate', 'Sơ chế và ướp thịt đùi gà với xì dầu', 'Thịt đùi gà lọc xương rửa sạch, thấm khô rồi cắt miếng vuông dày khoảng 2 cm. Cho thịt gà vào tô ướp cùng một nửa lượng tỏi băm, 15 ml nước tương (xì dầu), 3 g muối ăn, 3 g đường cát trắng và một nửa lượng tiêu đen xay, trộn đều và để thấm 15 phút.', NULL, 15),
('imp-1e6d5d1750d3aa51_v4_step_2', 'imp-1e6d5d1750d3aa51', 2, 'prep', 'Bổ múi cà chua, hành tây và cắt hành lá', 'Cà chua chín rửa sạch, bỏ cuống rồi bổ mỗi quả thành 6–8 múi cau. Hành tây bóc vỏ cắt múi cau vừa ăn. Hành lá rửa sạch, tách đầu hành trắng băm nhỏ, phần lá xanh cắt khúc 3 cm; phần tỏi còn lại băm nhỏ.', NULL, NULL),
('imp-1e6d5d1750d3aa51_v4_step_3', 'imp-1e6d5d1750d3aa51', 3, 'cook', 'Áp chảo săn vàng thịt đùi gà', 'Đun nóng 25 ml dầu ăn trong chảo rộng trên lửa vừa, phi thơm đầu hành trắng và phần tỏi băm còn lại. Trút thịt gà đã ướp vào dàn đều một lớp, tăng lên lửa lớn và xào khoảng 4–5 phút đến khi các miếng gà săn chắc và xém vàng hai mặt.', 'Dàn đều thịt gà thành một lớp để miếng gà xém vàng thơm mà không bị tiết nước hấp luộc.', 5),
('imp-1e6d5d1750d3aa51_v4_step_4', 'imp-1e6d5d1750d3aa51', 4, 'cook', 'Om thịt gà chín kỹ cùng sốt cà chua', 'Hạ xuống lửa vừa, cho toàn bộ cà chua bổ múi vào chảo đảo nhẹ 1 phút. Rót 100 ml nước lọc và 5 ml nước mắm ngon vào, đậy vung om khoảng 9–10 phút cho đến khi cà chua mềm nhừ tạo thành sốt đỏ sánh và thịt gà chín hoàn toàn tận lõi (không còn màu hồng).', 'Không om quá 12 phút để thịt đùi gà giữ độ mọng mềm và múi cà chua vẫn còn giữ dáng đẹp mắt.', 10),
('imp-1e6d5d1750d3aa51_v4_step_5', 'imp-1e6d5d1750d3aa51', 5, 'cook', 'Thêm hành tây giòn ngọt và cân chỉnh sốt', 'Mở vung, thả hành tây cắt múi cau vào đảo đều trên lửa vừa-lớn khoảng 2 phút cho hành vừa chín tái giòn ngọt. Nêm thêm 5 ml nước tương (xì dầu) và 3 g đường cát trắng còn lại sao cho sốt đạt vị chua dịu, mặn ngọt hài hòa.', 'Cho hành tây vào bước cuối giúp hành giữ được độ giòn ngọt và màu sắc tươi sáng.', NULL),
('imp-1e6d5d1750d3aa51_v4_step_6', 'imp-1e6d5d1750d3aa51', 6, 'finish', 'Hoàn thiện với hành lá và dọn nóng', 'Thả hành lá cắt khúc và phần tiêu đen xay còn lại vào chảo, đảo nhanh tay 15 giây rồi tắt bếp. Bày gà xào cà chua ra đĩa sâu lòng, rưới sốt lên trên và ăn nóng cùng cơm trắng.', NULL, NULL),
('imp-ce3c9df133ba1cd4_v4_step_1', 'imp-ce3c9df133ba1cd4', 1, 'prep', 'Sơ chế hành lá, rau răm, ớt và đánh trứng', 'Hành lá rửa sạch để ráo rồi thái nhỏ; rau răm thái rối; ớt hiểm băm nhỏ. Nếu tự làm hành phi, phi vàng giòn 20 g hành tím thái lát với 10 ml dầu ăn rồi vớt ra để riêng. Đập 3 quả trứng gà vào tô, thêm 1,5 g muối ăn và 1 g tiêu đen xay rồi đánh tan nhẹ tay cho hòa quyện.', 'Đánh trứng vừa tay, không đánh nổi bọt quá nhiều để giữ độ mềm béo tự nhiên khi áp nhiệt.', NULL),
('imp-ce3c9df133ba1cd4_v4_step_2', 'imp-ce3c9df133ba1cd4', 2, 'cook', 'Làm nóng chảo và áp giòn mặt bánh tráng', 'Đặt chảo chống dính rộng lên bếp ở lửa vừa, cho khoảng 8–10 ml dầu ăn vào tráng đều đáy chảo. Đặt 1 lá bánh tráng mỏng vào chảo, dùng xẻng ép nhẹ cho mặt bánh tiếp xúc đều với dầu nóng trong khoảng 20 giây đến khi bánh bắt đầu phồng giòn nhẹ.', NULL, NULL),
('imp-ce3c9df133ba1cd4_v4_step_3', 'imp-ce3c9df133ba1cd4', 3, 'cook', 'Trải đều trứng gà lên mặt bánh tráng nóng', 'Nhanh tay múc khoảng 1/4 phần trứng gà đã đánh đổ lên giữa bánh tráng rồi nghiêng hoặc dùng lưng muỗng dàn đều khắp bề mặt trước khi trứng kịp đông hẳn.', 'Thao tác dàn trứng cần nhanh và dứt khoát ngay khi bánh vừa ấm phồng để trứng bám chặt vào bề mặt bánh tráng.', NULL),
('imp-ce3c9df133ba1cd4_v4_step_4', 'imp-ce3c9df133ba1cd4', 4, 'cook', 'Rắc ruốc sấy, hành lá, rau răm và chiên chín trứng', 'Hạ xuống lửa nhỏ, rắc đều lên mặt trứng một phần muối ăn (hoặc muối tôm) còn lại, hành lá thái nhỏ, ruốc sấy, hành phi (nếu dùng), ớt hiểm băm và rau răm. Chiên khoảng 2–3 phút cho trứng chín đông hoàn toàn và mặt bánh dưới vàng giòn đều.', NULL, 3),
('imp-ce3c9df133ba1cd4_v4_step_5', 'imp-ce3c9df133ba1cd4', 5, 'cook', 'Gập đôi bánh và lặp lại với các lá còn lại', 'Gập đôi chiếc bánh tráng lại (hoặc giữ nguyên hình tròn tùy thích), áp thêm 30 giây cho giòn đều hai mép rồi gắp ra đặt trên giá thoáng hơi. Lặp lại thao tác với phần bánh tráng, dầu ăn và nguyên liệu còn lại.', 'Không xếp chồng các miếng bánh nóng lên nhau vì hơi nước bốc lên sẽ làm vỏ bánh tráng nhanh bị ỉu mềm.', 3),
('imp-ce3c9df133ba1cd4_v4_step_6', 'imp-ce3c9df133ba1cd4', 6, 'finish', 'Cắt miếng và thưởng thức nóng với tương ớt', 'Dùng kéo cắt bánh tráng chiên trứng thành từng miếng tam giác vừa ăn, rưới thêm tương ớt lên trên hoặc bày chén tương ớt bên cạnh và ăn ngay khi còn giòn rụm.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-1d4d9422e7f81e97_v4_step_1', 'imp-1d4d9422e7f81e97', 1, 'prep', 'Làm ngất và chà rửa sạch cua thịt nguyên con', 'Giữ nguyên dây buộc, ngâm 4 con cua thịt tươi sống vào thau nước đá lạnh khoảng 15 phút cho cua ngất hoàn toàn để không bị rụng càng khi hấp. Tháo dây buộc, dùng bàn chải chà sạch kỹ toàn bộ mai, càng, các kẽ chân và phần yếm cua dưới vòi nước chảy rồi để ráo.', 'Ngâm nước đá lạnh làm cua ngủ yên giúp tháo dây dễ dàng, giữ trọn vẹn càng chân đẹp mắt và không làm mất nước ngọt bên trong cua.', 15),
('imp-1d4d9422e7f81e97_v4_step_2', 'imp-1d4d9422e7f81e97', 2, 'prep', 'Sơ chế sả, gừng, hành tây, hành lá, ớt và rau răm', 'Bóc bẹ già 4 cây sả, đập dập cắt khúc 5 cm. Cạo vỏ 30 g gừng thái lát mỏng; hành tây bóc vỏ bổ múi cau; hành lá cắt khúc 5 cm. Thái lát xéo 2 quả ớt hiểm và băm nhỏ 1 quả còn lại; nhặt rửa sạch rau răm để ráo; cắt vài lát chanh trang trí và chuẩn bị phần chanh vắt nước cốt.', NULL, NULL),
('imp-1d4d9422e7f81e97_v4_step_3', 'imp-1d4d9422e7f81e97', 3, 'cook', 'Xếp cua ngửa bụng và hấp chín đỏ au', 'Đổ 500 ml nước lọc vào đáy nồi hấp sao cho mặt nước thấp hơn vỉ. Xếp hành tây bổ múi, sả đập dập và gừng thái lát lên mặt vỉ, đặt 4 con cua ngửa phần yếm lên trên để giữ trọn gạch và nước ngọt. Rải hành lá, 2 quả ớt hiểm thái lát cùng 6 g muối hạt lên mình cua, đậy kín nắp đun sôi rồi hạ lửa vừa hấp 18 phút.', 'Luôn đặt cua nằm ngửa bụng lên trên khi hấp để phần gạch cua và nước ngọt tự nhiên đọng lại trong mai không bị chảy xuống nồi.', 18),
('imp-1d4d9422e7f81e97_v4_step_4', 'imp-1d4d9422e7f81e97', 4, 'sauce', 'Pha muối tiêu chanh ớt chấm thịt cua', 'Trong lúc chờ cua chín, trộn đều 6 g muối hạt còn lại, 2 g tiêu đen xay, 5 g đường cát trắng và 1 quả ớt hiểm băm nhỏ trong chén, vắt nước cốt 1,5 quả chanh tươi vào khuấy tan tạo thành chén muối chấm sánh thơm.', NULL, NULL),
('imp-1d4d9422e7f81e97_v4_step_5', 'imp-1d4d9422e7f81e97', 5, 'cook', 'Kiểm tra độ chín an toàn của cua hấp', 'Mở nắp kiểm tra thấy toàn bộ vỏ mai, càng và chân cua đã chuyển màu đỏ cam tươi đều, tách thử phần yếm thấy gạch đặc sánh và thịt trắng đục chắc nịch không còn trong sống là đạt; nếu cua lớn dày mình có thể hấp thêm 3 phút cho chín hẳn.', 'Tuyệt đối không dùng cua đã chết trước khi hấp vì thịt dễ bị bở, mất vị ngọt và tiềm ẩn nguy cơ mất an toàn thực phẩm.', NULL),
('imp-1d4d9422e7f81e97_v4_step_6', 'imp-1d4d9422e7f81e97', 6, 'finish', 'Bày mâm cua hấp nóng kèm rau răm và muối chấm', 'Gắp cua ra mâm lớn, để ráo hơi nóng khoảng 2 phút cho mặt vỏ khô se, xếp kèm rau răm tươi và vài lát chanh tươi xung quanh; thưởng thức nóng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_1', 'imp-d3972d88e860aba9', 1, 'prep', 'Làm sạch khử tanh mực ống tươi', 'Rút bỏ nang mực, túi mực và mắt, bóc sạch lớp da ngoài rồi chà rửa mực với 3 g muối ăn, xả sạch lại bằng nước lạnh và để thật ráo.', 'Chọn mực ống thân trắng bóng, thịt săn đàn hồi và không có mùi lạ để món gỏi giòn ngọt tự nhiên.', NULL),
('imp-d3972d88e860aba9_v4_step_2', 'imp-d3972d88e860aba9', 2, 'cook', 'Luộc mực vừa chín tới với gừng và thái khoanh', 'Đun sôi 800 ml nước lọc trên lửa lớn cùng 15 g gừng tươi đập dập và 2 g muối ăn. Thả mực vào luộc khoảng 3 phút đến khi thân mực săn lại, chuyển màu trắng đục chín hoàn toàn thì vớt ra ngâm nhanh vào nước nguội sạch rồi vớt ráo, thái khoanh tròn dày khoảng 1 cm.', 'Không luộc mực quá lâu vì thịt mực sẽ bị teo và dai; vớt ra ngay khi mực vừa chuyển trắng đục và săn đều.', 3),
('imp-d3972d88e860aba9_v4_step_3', 'imp-d3972d88e860aba9', 3, 'cook', 'Chần sơ hành lá và chuẩn bị rau thơm', 'Tận dụng nồi nước sôi vừa luộc mực, nhúng nhanh hành lá vào chần 15 giây rồi vớt ra ngâm nước lạnh cho giữ màu xanh và giảm vị hăng, để ráo và cắt khúc 3 cm. Nhặt rửa sạch rau răm rồi thái nhỏ, băm nhuyễn tỏi khô và 1 quả ớt hiểm, quả ớt còn lại thái lát.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_4', 'imp-d3972d88e860aba9', 4, 'sauce', 'Pha nước trộn gỏi mắm chanh tỏi ớt', 'Cho 40 ml nước mắm ngon, 25 g đường cát trắng và nước cốt 2 quả chanh tươi vào bát, khuấy tan hoàn toàn đường rồi thêm tỏi băm và ớt hiểm băm nhuyễn vào đảo đều.', NULL, NULL),
('imp-d3972d88e860aba9_v4_step_5', 'imp-d3972d88e860aba9', 5, 'prep', 'Trộn thấm khoanh mực lần đầu', 'Cho toàn bộ mực thái khoanh vào tô lớn, rưới một nửa bát nước trộn mắm chanh vào đảo đều và để yên 5 phút cho từng khoanh mực ngấm vị chua ngọt.', NULL, 5),
('imp-d3972d88e860aba9_v4_step_6', 'imp-d3972d88e860aba9', 6, 'finish', 'Trộn hành lá, rau răm và dọn ăn kèm bánh phồng', 'Cho hành lá chần cắt khúc và rau răm thái nhỏ vào tô mực, rưới nốt phần nước trộn còn lại rồi trộn nhẹ tay cho đều vị. Bày gỏi ra đĩa, trang trí vài lát ớt hiểm lên trên và dọn ăn ngay kèm bánh phồng tôm giòn rụm.', 'Chanh tươi có độ chua khác nhau tùy quả nên hãy nếm thử sau khi trộn để gia giảm nhẹ đường hoặc nước cốt chanh cho vừa miệng.', NULL),
('imp-68184b07a3c61cff_v4_step_1', 'imp-68184b07a3c61cff', 1, 'prep', 'Ngâm nấu cháo gạo nếp và sơ chế đồ chua', 'Vo sạch 50 g gạo nếp, ngâm nước 2 giờ (hoặc qua đêm) cho nở mềm rồi cho vào nồi nấu với nước khoảng 15 phút trên lửa nhỏ đến khi hạt nếp nở bung thành cháo, để nguội bớt và xay thật nhuyễn mịn. Cà rốt bào sợi, trộn với 60 ml giấm gạo và 10 g đường cát trắng, cất ngăn mát 30 phút làm đồ chua.', NULL, 15),
('imp-68184b07a3c61cff_v4_step_2', 'imp-68184b07a3c61cff', 2, 'marinate', 'Quết dẻo nhân nem nướng và ướp thấm', 'Thái hạt lựu 80 g thịt mỡ ba chỉ đã rửa sạch nước ấm. Trộn đều thịt mỡ, 150 g giò sống và 300 g thịt heo xay với 16 g bột năng, 12 ml dầu hào, 4 g đường cát trắng, 6 ml nước mắm, 1/2 lượng tỏi băm, 1/2 lượng hành tím băm, 2 g tiêu đen xay và 10 ml dầu màu điều. Quết mạnh tay 5 phút cho khối thịt dẻo dính, bọc kín ướp ngăn mát 45 phút.', 'Quết thịt thật kỹ và ướp lạnh trước khi nặn giúp nem nướng săn chắc, có độ giòn dai tự nhiên mà không bị bở.', 45),
('imp-68184b07a3c61cff_v4_step_3', 'imp-68184b07a3c61cff', 3, 'cook', 'Bọc thịt quanh sả và nướng chín vàng thơm', 'Cắt sả cây dài 15 cm, đập dập phần đầu. Chia thịt thành từng nắm vừa tay, nặn bọc chặt quanh đầu cây sả. Xếp các que nem vào nồi chiên không dầu hoặc lò nướng ở 180°C nướng 12 phút, trở mặt nướng thêm 5 phút đến khi nem chín kỹ hoàn toàn bên trong và vàng xém cạnh thơm lừng.', 'Làm nóng nồi chiên không dầu trước 5 phút giúp nem lên màu vàng đều và giữ độ mọng nước bên trong.', 17),
('imp-68184b07a3c61cff_v4_step_4', 'imp-68184b07a3c61cff', 4, 'sauce', 'Xào tôm thịt gan nấu sốt chấm sánh bùi', 'Băm thật nhuyễn 80 g tôm tươi lột vỏ, 50 g thịt heo xay còn lại và 50 g gan heo đã rửa sạch. Bắc chảo với 15 ml dầu ăn ở lửa vừa, phi thơm phần hành tím và tỏi băm còn lại cùng 5 ml dầu màu điều rồi cho hỗn hợp tôm thịt gan vào xào chín 3 phút, sau đó xay nhuyễn. Đổ phần thịt xay và cháo nếp xay vào nồi, nêm 36 ml nước mắm, 6 ml nước tương và 6 g đường cát trắng, khuấy đều trên lửa nhỏ đến khi sốt sôi sánh sệt.', 'Khuấy liên tục khi đun sôi lại phần sốt gạo nếp để tránh bén đáy nồi.', NULL),
('imp-68184b07a3c61cff_v4_step_5', 'imp-68184b07a3c61cff', 5, 'prep', 'Chuẩn bị rau sống, dưa leo và đậu phộng rang', 'Rửa sạch xà lách rau sống và giá đỗ, để thật ráo nước. Thái thanh dài dưa leo bỏ ruột. Rang chín vàng đậu phộng trên lửa nhỏ, xát sạch vỏ lụa rồi giã dập vừa.', NULL, NULL),
('imp-68184b07a3c61cff_v4_step_6', 'imp-68184b07a3c61cff', 6, 'finish', 'Trình bày nem nướng cuốn bánh tráng và thưởng thức', 'Xếp nem nướng nóng ra đĩa cùng bánh tráng cuốn, đĩa rau sống, giá đỗ, dưa leo và đồ chua cà rốt. Múc sốt chấm nóng ra chén và rắc đậu phộng rang giã dập lên trên. Khi ăn, cuốn nem cùng rau củ trong bánh tráng và chấm đẫm sốt.', NULL, NULL),
('imp-ed9f34ecd475d031_v4_step_1', 'imp-ed9f34ecd475d031', 1, 'prep', 'Sơ chế rau sống, dưa leo và cắt bún lá', 'Nhặt rửa sạch lá tía tô, rau kinh giới và xà lách, ngâm nước muối loãng 15 phút (dùng 3 g muối ăn) rồi vớt ra vẩy thật ráo nước. Dưa leo rửa sạch thái lát xéo vừa ăn. Bún lá cắt thành từng miếng vuông đều cỡ 3–4 cm.', NULL, 15),
('imp-ed9f34ecd475d031_v4_step_2', 'imp-ed9f34ecd475d031', 2, 'cook', 'Luộc chín mềm và thái lát thịt ba chỉ', 'Rửa sạch thịt ba chỉ heo rồi cho vào nồi cùng 1,5 lít nước lọc, 5 g muối ăn và 20 g gừng tươi đập dập. Luộc ở lửa vừa khoảng 25 phút đến khi xiên đũa qua thấy thịt chín mềm không còn nước hồng chảy ra, vớt ra ngâm nhanh vào nước nguội cho trắng giòn rồi để ráo, thái lát mỏng vừa ăn.', 'Luộc thịt cùng gừng đập dập và ngâm nước nguội ngay khi vớt ra giúp miếng thịt trắng đẹp và không bị thâm khô.', 25),
('imp-ed9f34ecd475d031_v4_step_3', 'imp-ed9f34ecd475d031', 3, 'cook', 'Chiên giòn đậu phụ mơ và chả cốm', 'Đun nóng 250 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thả từng miếng đậu phụ mơ trắng đã thấm khô vào chiên khoảng 6–8 phút cho vàng phồng giòn đều các mặt rồi vớt ra rổ thưa cho ráo dầu. Tiếp tục chiên chả cốm khoảng 3–4 phút cho vàng giòn hai mặt, vớt ra để ráo.', 'Chiên đậu ở lửa vừa cho dầu ngập mặt giúp lớp vỏ ngoài giòn rụm mà bên trong vẫn mềm béo.', 10),
('imp-ed9f34ecd475d031_v4_step_4', 'imp-ed9f34ecd475d031', 4, 'sauce', 'Pha mắm tôm đánh bông thơm béo', 'Cho 60 g mắm tôm ngon vào bát sạch cùng 15 g đường cát trắng và 5 ml rượu trắng. Múc 25 ml dầu ăn đang nóng già từ chảo vừa chiên đậu rưới trực tiếp vào bát mắm để khử mùi nồng và làm dậy hương béo thơm. Vắt nước cốt của 2 quả quất (hoặc chanh tươi) vào rồi dùng đũa đánh nhanh tay đến khi mắm tôm sủi bọt trắng mịn, thêm ớt hiểm tươi thái lát.', 'Rưới dầu nóng vào mắm tôm rồi mới vắt nước cốt quất đánh đều sẽ giúp mắm tôm dậy mùi thơm dịu và nổi bọt bông lâu tan.', NULL),
('imp-ed9f34ecd475d031_v4_step_5', 'imp-ed9f34ecd475d031', 5, 'prep', 'Cắt miếng chả cốm và sắp xếp rau', 'Cắt chả cốm chiên nóng thành từng lát xéo vừa gắp; xếp gọn rau tía tô, kinh giới, xà lách và dưa leo lên một góc mẹt.', NULL, NULL),
('imp-ed9f34ecd475d031_v4_step_6', 'imp-ed9f34ecd475d031', 6, 'finish', 'Bày mẹt bún đậu mắm tôm và thưởng thức', 'Xếp bún lá cắt miếng, đậu phụ chiên giòn nóng, thịt ba chỉ thái lát và chả cốm quanh mẹt, đặt bát mắm tôm đánh bông ở chính giữa và thưởng thức ngay khi đậu phụ còn nóng giòn.', NULL, NULL),
('imp-a744a977e7e4b165_v4_step_1', 'imp-a744a977e7e4b165', 1, 'prep', 'Chần xương heo và chuẩn bị nguyên liệu hầm', 'Chần xương ống heo trong 400 ml nước sôi với 3 g muối ăn khoảng 4 phút rồi rửa sạch dưới vòi nước lạnh. Ngâm tôm khô 15 phút cho mềm; nướng khô mực trên lửa nhỏ 2 phút cho thơm; nướng sém hành tây và 25 g hành tím khô rồi cạo sạch lớp cháy; cắt khúc củ cải trắng.', NULL, 15),
('imp-a744a977e7e4b165_v4_step_2', 'imp-a744a977e7e4b165', 2, 'cook', 'Hầm nước lèo xương heo và hải sản khô', 'Cho xương ống heo, tôm khô, khô mực nướng, củ cải trắng, hành tây nướng và 25 g hành tím nướng vào nồi với 1,6 lít nước lọc lạnh cùng 5 g muối ăn. Đun sôi nhẹ rồi hạ lửa nhỏ hầm khoảng 50 phút, hớt bọt thường xuyên cho nước lèo thật trong. Vớt bỏ xác xương và rau củ rồi nêm 5 g muối ăn còn lại, 15 g đường phèn và 30 ml nước mắm ngon cho vừa miệng.', 'Hầm xương ở lửa liu riu và hớt bọt kỹ ngay từ đầu giúp nước lèo hủ tiếu mực trong veo, ngọt thanh.', 50),
('imp-a744a977e7e4b165_v4_step_3', 'imp-a744a977e7e4b165', 3, 'cook', 'Phi hành tỏi giòn và xào thịt heo xay', 'Đun nóng 25 ml dầu ăn trên chảo lửa vừa, phi vàng giòn 15 g hành tím thái lát và tỏi khô băm rồi vớt phần xác phi ra giấy thấm dầu. Dùng phần dầu thơm trong chảo xào chín tơi thịt heo xay khoảng 4 phút cùng 2 g muối ăn và 1 g tiêu đen xay rồi trút ra chén riêng.', 'Vớt hành tỏi phi ra khi vừa chuyển màu vàng nhạt để phần phi giòn thơm mà không bị đắng khét.', 5),
('imp-a744a977e7e4b165_v4_step_4', 'imp-a744a977e7e4b165', 4, 'cook', 'Làm sạch và chần nhanh mực ống tươi', 'Làm sạch mực ống tươi, cắt khoanh dày 1,5 cm. Đun sôi một nồi nước khác rồi thả mực vào chần nhanh khoảng 45–60 giây đến khi khoanh mực vừa săn cong trắng đục chín đều thì vớt ngay ra đĩa.', 'Chần mực nhanh trong nước thật sôi không quá 1 phút để giữ độ giòn sần sật và vị ngọt tự nhiên.', 2),
('imp-a744a977e7e4b165_v4_step_5', 'imp-a744a977e7e4b165', 5, 'prep', 'Trụng hủ tiếu, giá đỗ và cắt rau thơm', 'Trụng nhanh sợi hủ tiếu tươi qua nước sôi khoảng 30 giây cho mềm nóng rồi chia vào 4 tô; trụng sơ giá đỗ qua nước sôi đặt vào tô cùng hẹ lá cắt khúc, cần tây và thái lát ớt tươi.', NULL, NULL),
('imp-a744a977e7e4b165_v4_step_6', 'imp-a744a977e7e4b165', 6, 'finish', 'Xếp mực, thịt băm và chan nước lèo nóng', 'Xếp mực ống chần và thịt heo xay xào lên trên mặt tô hủ tiếu, chan ngập nước lèo đang sôi nóng, rắc hành tỏi phi vàng, 1 g tiêu đen xay còn lại và dọn nóng cùng ớt tươi thái lát.', NULL, NULL),
('imp-c67f536bef1c38d6_v4_step_1', 'imp-c67f536bef1c38d6', 1, 'prep', 'Sơ chế bắp cải, nấm đùi gà, cà rốt và đậu phụ chiên', 'Bắp cải tách lá, bỏ phần gân quá cứng, rửa sạch rồi cắt miếng vuông khoảng 4 cm và để ráo. Nấm đùi gà cắt gốc, rửa nhanh trong nước sạch để ráo rồi thái lát dày 0,6 cm. Cà rốt gọt vỏ thái khoanh dày 0,5 cm; đậu phụ chiên sẵn cắt miếng vuông cạnh 2,5 cm; hành boa-rô băm nhuyễn; hành lá thái nhỏ.', 'Cắt bắp cải miếng hơi to vừa phải để sau khi kho chín mềm lá cải vẫn giữ hình dáng đẹp mà không bị nhũn nát.', NULL),
('imp-c67f536bef1c38d6_v4_step_2', 'imp-c67f536bef1c38d6', 2, 'cook', 'Phi thơm hành boa-rô và xào săn nấm đùi gà', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, thả hành boa-rô băm vào phi khoảng 40 giây cho dậy hương thơm. Trút nấm đùi gà vào xào nhanh tay 2 phút đến khi lát nấm săn lại.', 'Xào săn nấm trước khi cho rau củ và nước giúp nấm đậm đà và không tiết nhiều nước làm loãng vị kho.', 2),
('imp-c67f536bef1c38d6_v4_step_3', 'imp-c67f536bef1c38d6', 3, 'sauce', 'Trộn bắp cải, cà rốt, đậu phụ với sốt nước tương', 'Cho bắp cải, cà rốt và đậu phụ chiên sẵn vào nồi nấm. Nêm 45 ml nước tương, 12 g đường cát trắng, 4 g hạt nêm chay, 2 g muối ăn và rót 200 ml nước lọc vào nồi, đảo nhẹ tay cho gia vị hòa tan đều.', NULL, NULL),
('imp-c67f536bef1c38d6_v4_step_4', 'imp-c67f536bef1c38d6', 4, 'cook', 'Kho nhỏ lửa cho bắp cải mềm và thấm đều gia vị', 'Đun sôi nồi kho trên lửa lớn rồi hạ xuống lửa vừa nhỏ, đậy nắp kho trong 15 phút cho bắp cải và cà rốt chín mềm, nước kho rút bớt thấm sâu vào đậu phụ chiên và nấm.', NULL, 15),
('imp-c67f536bef1c38d6_v4_step_5', 'imp-c67f536bef1c38d6', 5, 'cook', 'Mở nắp rim nhẹ cho nước kho sánh lại', 'Mở nắp nồi, tiếp tục kho thêm 4 phút trên lửa vừa để nước kho hơi sánh lại, thỉnh thoảng lắc nhẹ quai nồi cho gia vị phủ đều mà không dùng đũa khuấy mạnh làm nát đậu và cải.', 'Lắc nhẹ nồi thay vì dùng đũa đảo giúp giữ trọn miếng bắp cải mềm nguyên và đậu phụ không bị vỡ.', 4),
('imp-c67f536bef1c38d6_v4_step_6', 'imp-c67f536bef1c38d6', 6, 'finish', 'Hoàn thiện món bắp cải kho nấm nóng hổi', 'Nêm nếm lại nước kho cho vừa khẩu vị ăn cơm, tắt bếp rồi rắc hành lá thái nhỏ và 1,5 g tiêu đen xay lên mặt nồi. Múc ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('imp-35deaaa123c7470d_v4_step_1', 'imp-35deaaa123c7470d', 1, 'prep', 'Chần nhanh giá đỗ và hành lá giữ độ giòn', 'Nhặt sạch giá đỗ và rửa kỹ rồi để ráo. Đun sôi nồi nước nhỏ, thả giá đỗ cùng hành lá cắt khúc 3–4 cm vào chần thật nhanh trong 10 giây, vớt ngay ra ngâm vào tô nước lạnh 1 phút rồi đổ ra rổ để thật ráo nước.', 'Chần giá đỗ rất nhanh qua nước sôi rồi sốc lạnh giúp giá hết mùi hăng ngái mà vẫn giữ độ giòn trắng.', 2),
('imp-35deaaa123c7470d_v4_step_2', 'imp-35deaaa123c7470d', 2, 'prep', 'Bóp giòn cà rốt bào sợi', 'Cà rốt gọt vỏ, bào sợi mỏng đều rồi trộn nhẹ với 3 g muối ăn và 3 g đường cát trắng trong 3 phút để rút bớt nước hăng. Sau đó xả nhanh qua nước đun sôi để nguội, vắt nhẹ tay cho ráo nước.', 'Ướp muối đường nhẹ rồi vắt ráo trước khi trộn giúp sợi cà rốt giòn sần sật và không tiết nước làm loãng nộm.', 3),
('imp-35deaaa123c7470d_v4_step_3', 'imp-35deaaa123c7470d', 3, 'sauce', 'Pha nước trộn nộm chay chua cay mặn ngọt', 'Vắt chanh tươi lấy nước cốt bỏ hạt; băm thật nhuyễn tỏi khô và ớt hiểm. Khuấy đều trong chén 30 ml nước mắm chay, 22 g đường cát trắng còn lại, 15 ml giấm gạo và nước cốt chanh cho đường tan hoàn toàn rồi thả tỏi ớt băm vào trộn đều.', 'Nêm thử hỗn hợp nước trộn đạt vị chua cay mặn ngọt hơi đậm một chút để khi áo vào giá và cà rốt là vừa miệng.', NULL),
('imp-35deaaa123c7470d_v4_step_4', 'imp-35deaaa123c7470d', 4, 'cook', 'Trộn đều giá đỗ, cà rốt và hành lá thấm vị', 'Cho giá đỗ đã ráo, cà rốt bào sợi và hành lá vào âu lớn. Rưới từ từ phần nước trộn nộm vào âu, dùng tay đeo găng bóp trộn thật nhẹ nhàng cho gia vị phủ đều rồi để nghỉ 5 phút cho nguyên liệu ngấm vị.', NULL, 5),
('imp-35deaaa123c7470d_v4_step_5', 'imp-35deaaa123c7470d', 5, 'cook', 'Thêm rau húng quế và chắt nước thừa', 'Nghiêng nhẹ âu để chắt bỏ phần nước dư nếu rau có tiết thêm nước, sau đó thả rau húng quế thái rối vào đảo đều nhẹ tay thêm một lượt để nộm dậy mùi thơm mát.', NULL, NULL),
('imp-35deaaa123c7470d_v4_step_6', 'imp-35deaaa123c7470d', 6, 'finish', 'Rắc đậu phộng rang và thưởng thức ngay', 'Gắp nộm giá đỗ chua cay ra đĩa, rắc đều 30 g đậu phộng rang giã dập lên mặt đĩa và thưởng thức ngay khi rau củ còn giòn mát.', NULL, NULL),
('imp-94b6bce7403fedc6_v4_step_1', 'imp-94b6bce7403fedc6', 1, 'prep', 'Rang thơm hỗn hợp gạo tẻ và gạo nếp', 'Trộn 160 g gạo tẻ với 40 g gạo nếp, vo nhẹ 2 nước rồi chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu.', 'Rang gạo trước giúp hạt gạo săn đều, khi nấu thành cháo chay vẫn có độ sánh béo tự nhiên rất ngon miệng.', 6),
('imp-94b6bce7403fedc6_v4_step_2', 'imp-94b6bce7403fedc6', 2, 'cook', 'Ninh nhừ cháo trắng trên lửa nhỏ', 'Đổ 1,8 lít nước lọc sôi vào nồi gạo rang, khuấy đều đáy nồi một lượt rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy đều sát đáy nồi cho hạt gạo nở bung mềm mịn.', NULL, 22),
('imp-94b6bce7403fedc6_v4_step_3', 'imp-94b6bce7403fedc6', 3, 'prep', 'Sơ chế nấm đùi gà, đậu phụ và rau thơm', 'Nấm đùi gà làm sạch rồi thái hạt lựu vừa ăn. Cắt 300 g đậu phụ trắng thành các khối vuông nhỏ cạnh 1,5 cm. Gừng tươi cạo vỏ thái sợi chỉ mảnh; băm nhỏ 20 g hành tím khô; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-94b6bce7403fedc6_v4_step_4', 'imp-94b6bce7403fedc6', 4, 'cook', 'Phi thơm hành tím và xào đậm đà nấm đùi gà', 'Làm nóng 15 ml dầu ăn trong chảo trên lửa vừa, cho hành tím băm vào phi thơm vàng nhẹ. Trút nấm đùi gà vào đảo nhanh trên lửa lớn khoảng 3 phút, nêm 10 ml xì dầu và 2 g hạt nêm chay nấm hương cho nấm săn ngọt, dậy mùi thơm rồi tắt bếp.', 'Xào nấm đùi gà với xì dầu trên lửa lớn giúp nấm săn giòn, không ra nước và tạo vị ngọt umami đậm đà cho nồi cháo chay.', 3),
('imp-94b6bce7403fedc6_v4_step_5', 'imp-94b6bce7403fedc6', 5, 'cook', 'Cho nấm và đậu phụ vào nồi cháo nấu chín quyện', 'Nêm 15 ml xì dầu còn lại, 4 g hạt nêm chay và 4 g muối ăn vào nồi cháo đã nhừ, khuấy đều. Trút phần nấm đùi gà xào, một nửa lượng gừng thái chỉ và nhẹ tay thả các khối đậu phụ trắng vào nồi, nấu sôi lăn tăn nhẹ thêm 3 phút rồi tắt bếp.', 'Thả đậu phụ vào sau cùng và khuấy thật nhẹ tay quanh thành nồi để giữ từng miếng đậu vuông vắn không bị vỡ nát.', NULL),
('imp-94b6bce7403fedc6_v4_step_6', 'imp-94b6bce7403fedc6', 6, 'finish', 'Múc cháo nấm đậu phụ ra tô và thưởng thức nóng', 'Múc cháo nấm đậu phụ nóng hổi ra 4 tô sứ, rắc hành lá thái nhỏ, ngò rí, phần gừng tươi thái chỉ còn lại và 1,5 g tiêu đen xay lên trên rồi thưởng thức ngay.', NULL, NULL),
('imp-4f7a2cd919912ac9_v4_step_1', 'imp-4f7a2cd919912ac9', 1, 'prep', 'Sơ chế hành lá, hành tím và pha sốt trộn mì', 'Thái lát mỏng 20 g hành tím khô; rửa sạch hành lá, thái nhuyễn phần lá xanh và cắt khúc ngắn đầu hành trắng rồi cho chung vào tô chịu nhiệt. Trong một chén khác, khuấy tan 25 ml xì dầu, 10 ml nước mắm ngon, 4 g đường cát trắng, 10 ml giấm gạo và 5 ml dầu mè thơm.', NULL, NULL),
('imp-4f7a2cd919912ac9_v4_step_2', 'imp-4f7a2cd919912ac9', 2, 'cook', 'Phi vàng hành tím làm dầu hành thơm nức', 'Đun nóng 15 ml dầu ăn trong chảo nhỏ trên lửa vừa, cho hành tím thái lát vào phi vàng giòn khoảng 2 phút rồi trút cả phần dầu nóng lẫn hành phi thẳng vào tô hành lá, đảo nhẹ cho hành chín xanh thơm lừng và giữ lại phần hành phi giòn.', 'Dội dầu hành phi đang sôi trực tiếp lên hành lá thái nhỏ vừa làm hành chín tái giữ màu xanh, vừa tạo ra thứ dầu hành thơm nức cho món mì trộn.', 2),
('imp-4f7a2cd919912ac9_v4_step_3', 'imp-4f7a2cd919912ac9', 3, 'cook', 'Chiên 2 quả trứng gà ốp la lòng đào', 'Dùng lại chảo nhỏ với 10 ml dầu ăn còn lại trên lửa vừa, đập 2 quả trứng gà vào chiên ốp la khoảng 2 phút đến khi lòng trắng đông chắc viền hơi vàng giòn và lòng đỏ sánh dẻo (hoặc chiên chín hẳn tùy khẩu vị), gắp ra đĩa riêng.', NULL, 2),
('imp-4f7a2cd919912ac9_v4_step_4', 'imp-4f7a2cd919912ac9', 4, 'cook', 'Trụng chín tới và làm săn sợi mì', 'Đun sôi 800 ml nước lọc, thả 2 vắt mì vào trụng khoảng 90 giây đến khi sợi mì vừa chín mềm vẫn còn độ dai. Vớt mì ra xả nhanh dưới vòi nước lạnh hoặc xóc ráo thật kỹ để sợi mì tơi rời không bị nhũn.', 'Không trụng mì quá lâu và phải xóc thật ráo nước trước khi trộn để nước sốt bám đặc đều từng sợi mì.', NULL),
('imp-4f7a2cd919912ac9_v4_step_5', 'imp-4f7a2cd919912ac9', 5, 'cook', 'Trộn đều mì với sốt xì dầu và dầu hành', 'Cho mì đã ráo nước vào tô lớn, rưới toàn bộ dầu hành phi và nước sốt xì dầu, dầu mè đã pha lên trên. Dùng đũa trộn đều tay trong 1 phút cho từng sợi mì bóng mượt, lên màu nâu óng đẹp mắt và thấm đều gia vị.', 'Trộn mì ngay khi còn ấm để hương thơm của dầu mè, xì dầu và hành phi quyện chặt vào từng sợi mì.', NULL),
('imp-4f7a2cd919912ac9_v4_step_6', 'imp-4f7a2cd919912ac9', 6, 'finish', 'Bày đĩa mì trộn trứng hành và rắc mè rang', 'Chia mì trộn ra 2 tô hoặc đĩa sâu lòng, đặt trứng gà ốp la lên trên, rắc 5 g mè trắng rang chín và 1 g tiêu đen xay rồi thưởng thức nóng ngay.', NULL, NULL),
('imp-edac077a60dfa8b5_v4_step_1', 'imp-edac077a60dfa8b5', 1, 'sauce', 'Nấu và để nguội nước kho ngũ vị', 'Cho gừng tươi thái lát, 3 g hoa hồi khô, 3 g quế thanh, 1 g lá nguyệt quế khô, 2 g tiêu Tứ Xuyên, 30 ml xì dầu nhạt, 15 ml xì dầu đặc, 4 g đường cát trắng, 8 g muối ăn, 20 ml rượu Thiệu Hưng và 700 ml nước lọc vào nồi (nếu có sẵn 10 g lá trà đen khô, cho thêm vào túi lọc để tạo hương trà truyền thống). Đun sôi rồi hạ lửa nhỏ đậy nắp om 10 phút cho thảo mộc tiết hương, sau đó tắt bếp mở nắp để nguội hoàn toàn.', 'Để nước kho nguội hẳn trước khi thả trứng vào ngâm sẽ giữ lòng đỏ mềm dẻo mà không bị chín quá cứng.', 10),
('imp-edac077a60dfa8b5_v4_step_2', 'imp-edac077a60dfa8b5', 2, 'cook', 'Luộc trứng gà chín lòng đào hoặc chín kỹ', 'Đun một nồi nước khác cho sôi mạnh, dùng muôi lớn nhẹ nhàng thả 8 quả trứng gà ở nhiệt độ phòng vào nước sôi (tránh va đập vỡ vỏ). Luộc đúng 7 phút cho lòng đỏ dẻo mềm hoặc 9 phút nếu thích lòng đỏ chín bở.', NULL, 7),
('imp-edac077a60dfa8b5_v4_step_3', 'imp-edac077a60dfa8b5', 3, 'prep', 'Ngâm nước đá làm nguội trứng nhanh', 'Vớt trứng ra thả ngay vào thau nước lạnh có đá viên trong 5 phút để dừng quá trình chín và giúp màng trứng dễ bong hơn khi bóc.', NULL, 5),
('imp-edac077a60dfa8b5_v4_step_4', 'imp-edac077a60dfa8b5', 4, 'prep', 'Gõ tạo mạng vết nứt vân đá trên vỏ trứng', 'Dùng lưng muỗng nhỏ gõ nhẹ đều khắp vỏ từng quả trứng để tạo mạng lưới vết nứt mịn đan xen nhau nhưng tuyệt đối không bóc vỏ ra.', 'Gõ lực vừa phải để nước kho thấm qua tạo hoa văn vân đá đều đẹp mà không làm vỡ nát phần lòng trắng mềm bên trong.', NULL),
('imp-edac077a60dfa8b5_v4_step_5', 'imp-edac077a60dfa8b5', 5, 'marinate', 'Ngâm ủ trứng trong nước kho gia vị', 'Xếp toàn bộ trứng đã gõ rạn vỏ vào nồi nước kho ngũ vị đã nguội hoàn toàn, đảm bảo nước ngập hết trứng. Đậy kín nắp và đặt vào ngăn mát tủ lạnh ngâm ít nhất 8 giờ cho vân màu đậm nét và thấm sâu vào tận lòng đỏ.', 'Ngâm từ 8 đến 24 giờ trong ngăn mát giúp đường vân đá hiện rõ nét và hương ngũ vị ngấm sâu đều khắp quả trứng.', 480),
('imp-edac077a60dfa8b5_v4_step_6', 'imp-edac077a60dfa8b5', 6, 'finish', 'Bóc vỏ lộ vân đá và thưởng thức', 'Lấy trứng ra bóc nhẹ vỏ dưới vòi nước sạch để lộ hoa văn vân đá nâu óng tự nhiên. Có thể dùng mát trực tiếp, cắt đôi xếp lên bát mì nóng hoặc hâm ấm nhẹ trong nước kho trước khi ăn.', NULL, NULL),
('imp-0efe9204d9dbdb3e_v4_step_1', 'imp-0efe9204d9dbdb3e', 1, 'prep', 'Ngâm mềm ớt khô tránh cháy đắng', 'Cắt 40 g ớt khô thành từng đoạn ngắn 1,5 cm (có thể giảm lượng ớt nếu ăn cay nhẹ), giũ bỏ bớt hạt rồi ngâm vào nước sạch 15 phút, sau đó vớt ra vẩy thật ráo nước.', 'Ngâm nước trước giúp ớt khô không bị cháy đen khi phi trên chảo nóng mà vẫn tiết ra màu đỏ và hương thơm nồng.', 15),
('imp-0efe9204d9dbdb3e_v4_step_2', 'imp-0efe9204d9dbdb3e', 2, 'marinate', 'Cắt khối và ướp mềm thịt đùi gà', 'Thái 450 g thịt đùi gà rút xương thành khối vuông nhỏ 2 cm. Trộn đều gà trong tô với 15 ml xì dầu, 15 ml rượu Thiệu Hưng, 1 g tiêu trắng xay, 1 g muối ăn và 6 g bột bắp, ướp 10 phút cho thịt ngấm vị và săn mềm.', NULL, 10),
('imp-0efe9204d9dbdb3e_v4_step_3', 'imp-0efe9204d9dbdb3e', 3, 'cook', 'Chiên nông từng mẻ gà vàng giòn rụm', 'Đun nóng 235 ml dầu ăn trong chảo sâu lòng trên lửa lớn đến khi đầu đũa sủi tăm mạnh. Chia gà thành 2 mẻ chiên nông 4–5 phút (giữ yên 1 phút đầu cho se vỏ rồi mới đảo đều mặt) đến khi từng miếng gà chín hoàn toàn bên trong, vỏ ngoài vàng giòn thì vớt ra giấy thấm dầu.', 'Chiên từng mẻ không chen chúc giúp mặt gà tiếp xúc tốt với đáy chảo, giòn rụm nhanh mà không bị ra nước.', NULL),
('imp-0efe9204d9dbdb3e_v4_step_4', 'imp-0efe9204d9dbdb3e', 4, 'cook', 'Phi ớt khô và hoa tiêu trên lửa nhỏ nhất', 'Dùng chảo sạch làm nóng 15 ml dầu ăn còn lại trên lửa nhỏ nhất, thả ớt khô đã ráo nước vào đảo đều 2 phút đến khi ớt dậy mùi thơm và chuyển màu đỏ sẫm. Tiếp tục cho 8 g hoa tiêu Tứ Xuyên vào đảo thêm 1 phút trên lửa nhỏ để tạo vị tê thơm mà không làm cháy đắng.', 'Luôn giữ lửa nhỏ nhất khi phi ớt khô và hoa tiêu để gia vị tiết tinh dầu thơm nồng mà không bị đắng khét.', 3),
('imp-0efe9204d9dbdb3e_v4_step_5', 'imp-0efe9204d9dbdb3e', 5, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Gạt ớt khô và hoa tiêu sang một bên chảo, cho gừng tươi thái lát, tỏi thái lát và đầu hành trắng vào khoảng trống giữa chảo phi thơm 30 giây cho dậy mùi.', NULL, NULL),
('imp-0efe9204d9dbdb3e_v4_step_6', 'imp-0efe9204d9dbdb3e', 6, 'finish', 'Xóc đều gà giòn với mè rang và hành lá', 'Trút toàn bộ gà chiên giòn trở lại chảo, rắc 9 g hạt mè trắng rang, 4 g đường cát trắng, 1 g muối ăn còn lại và phần lá hành xanh cắt khúc. Đảo nhanh tay 30 giây trên lửa vừa cho gia vị bám đều rồi trút ra đĩa thưởng thức nóng ngay.', NULL, NULL),
('imp-0a1f8e0bd042cbfd_v4_step_1', 'imp-0a1f8e0bd042cbfd', 1, 'prep', 'Thái lát mỏng ba chỉ và xé ráo bắp cải', 'Thấm khô 300 g thịt ba chỉ rồi thái lát mỏng đều tay. Tách 1/2 bắp cải trắng rửa sạch, để thật ráo nước rồi xé miếng vừa ăn khoảng 4 cm; thái lát tỏi, thái sợi gừng, thái khoanh ớt hiểm và cắt khúc hành lá (tách riêng đầu trắng và lá xanh).', 'Bắp cải phải thật ráo nước trước khi vào chảo để khi xào không bị chảy nước và giữ được độ giòn ngọt.', NULL),
('imp-0a1f8e0bd042cbfd_v4_step_2', 'imp-0a1f8e0bd042cbfd', 2, 'cook', 'Áp chảo thịt ba chỉ xém cạnh tươm mỡ', 'Làm nóng chảo sâu lòng trên lửa vừa lớn với 15 ml dầu ăn tráng mặt chảo, xếp các lát thịt ba chỉ vào áp chảo 5 phút (trở đều mặt sau mỗi 1–2 phút) đến khi thịt ra bớt mỡ thơm và xém vàng các cạnh.', NULL, 5),
('imp-0a1f8e0bd042cbfd_v4_step_3', 'imp-0a1f8e0bd042cbfd', 3, 'cook', 'Rưới rượu Thiệu Hưng và phi thơm gia vị', 'Gạt nhẹ thịt ba chỉ sang một bên chảo, rưới 15 ml rượu Thiệu Hưng vào phần chảo nóng đảo 20 giây cho bay hơi thơm nồng. Tiếp tục thả đầu hành trắng, tỏi thái lát, gừng thái sợi và ớt hiểm vào phi thơm 30 giây trên lửa vừa.', NULL, NULL),
('imp-0a1f8e0bd042cbfd_v4_step_4', 'imp-0a1f8e0bd042cbfd', 4, 'cook', 'Xào nhanh bắp cải trên lửa lớn giữ độ giòn', 'Tăng lên lửa lớn nhất, trút toàn bộ bắp cải vào đảo nhanh tay liên tục trong 3 phút đến khi lá bắp cải vừa mềm trong nhẹ mà phần cuống vẫn giữ độ giòn sần sật.', 'Xào lửa thật lớn và đảo liên tục giúp bắp cải chín nhanh, bóng mỡ thơm mà không bị ra nước nhũn.', 3),
('imp-0a1f8e0bd042cbfd_v4_step_5', 'imp-0a1f8e0bd042cbfd', 5, 'sauce', 'Rưới xì dầu quanh thành chảo và nêm vị', 'Rưới đều 45 ml xì dầu nhạt dọc theo thành chảo nóng cho bốc mùi thơm, thêm 4 g muối ăn và 6 g đường cát trắng rồi đảo đều 30 giây cho thịt và bắp cải thấm gia vị đậm đà.', 'Rưới xì dầu dọc theo thành chảo nóng giúp nước tương xèo nhẹ, dậy mùi thơm đặc trưng hơn so với đổ thẳng lên rau.', NULL),
('imp-0a1f8e0bd042cbfd_v4_step_6', 'imp-0a1f8e0bd042cbfd', 6, 'finish', 'Rưới dầu mè, rắc hành lá và dọn nóng', 'Rưới 15 ml dầu mè thơm và thả phần lá hành xanh vào chảo, đảo thêm 15 giây rồi tắt bếp ngay. Múc ra đĩa và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-ae6d3af49ade8384_v4_step_1', 'imp-ae6d3af49ade8384', 1, 'prep', 'Làm lạnh và sơ chế sạch cua biển', 'Cho cua biển tươi vào ngăn mát tủ lạnh khoảng 10 phút cho cua chậm lại dễ cầm, tháo dây buộc rồi lật ngửa bóc bỏ yếm. Tách phần mai, bỏ sạch mang xám hai bên và túi dạ dày sau miệng, rửa kỹ dưới vòi nước lạnh cho hết cát rồi chặt thân cua thành 4 đến 6 miếng, bổ đôi mai và dùng sống dao đập nhẹ vỏ càng cho dễ ngấm vị.', 'Thấm thật khô từng miếng cua bằng khăn giấy trước khi áo bột để cua không bị bắn dầu khi chiên và giữ được độ ngọt tự nhiên bên trong.', 10),
('imp-ae6d3af49ade8384_v4_step_2', 'imp-ae6d3af49ade8384', 2, 'prep', 'Thái gừng hành và pha sẵn chén sốt', 'Thái lát mỏng 30 g gừng tươi, băm nhỏ 4 tép tỏi khô và cắt khúc 5 cm phần hành lá tươi, tách riêng đầu hành trắng với phần lá xanh. Trong một chén nhỏ, khuấy tan 15 ml dầu hào, 10 ml xì dầu nhạt, 4 g đường cát trắng, 1 g tiêu trắng xay, 5 ml dầu mè thơm, 5 g bột bắp và 90 ml nước lọc rồi đặt sẵn cạnh bếp.', 'Pha sẵn nước sốt trước khi bật bếp giúp thao tác ở giai đoạn xào lửa lớn diễn ra liên tục, tránh làm cua bị chín quá mất độ mọng.', NULL),
('imp-ae6d3af49ade8384_v4_step_3', 'imp-ae6d3af49ade8384', 3, 'cook', 'Áo bột bắp và chiên sơ cua khóa ngọt', 'Cho cua đã thấm khô vào tô lớn, rắc đều 25 g bột bắp còn lại vào xóc nhẹ tạo lớp áo mỏng quanh mặt thịt. Đun nóng khoảng 400 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm mạnh, thả từng mẻ cua vào chiên khoảng 3 phút đến khi vỏ cua vừa chuyển màu đỏ cam thì vớt ra rổ để ráo dầu.', 'Chỉ chiên cua vừa chuyển đỏ rồi vớt ra ngay, không chiên quá lâu vì thịt cua còn được đảo tiếp với sốt sẽ dễ bị khô bã.', 3),
('imp-ae6d3af49ade8384_v4_step_4', 'imp-ae6d3af49ade8384', 4, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Chắt bớt phần dầu chiên ra hũ riêng, chỉ giữ lại khoảng 15 ml dầu ăn trong chảo. Bật lửa vừa, cho gừng thái lát vào đảo khoảng 30 giây đến khi cạnh gừng hơi săn thơm, tiếp tục thêm tỏi băm và phần đầu hành lá trắng vào phi thêm 20 giây cho dậy mùi thơm nồng mà không cháy xém.', NULL, NULL),
('imp-ae6d3af49ade8384_v4_step_5', 'imp-ae6d3af49ade8384', 5, 'cook', 'Xào cua với rượu Thiệu Hưng và sốt dầu hào', 'Tăng lên lửa lớn, trút toàn bộ cua đã chiên vào chảo đảo nhanh vài lượt cho áo đều dầu gừng. Rưới 15 ml rượu Thiệu Hưng quanh thành chảo cho bốc hơi thơm lừng, khuấy lại chén sốt bột bắp cho không lắng đáy rồi rưới đều lên cua, đảo liên tục khoảng 2 phút đến khi thịt cua chín trắng hoàn toàn.', NULL, 2),
('imp-ae6d3af49ade8384_v4_step_6', 'imp-ae6d3af49ade8384', 6, 'finish', 'Thêm hành lá xanh và hoàn thiện đĩa cua', 'Khi nước sốt sôi nhẹ và bắt đầu sánh bóng bám đều quanh từng miếng cua, cho toàn bộ phần lá xanh của hành lá vào đảo đều thêm 30 giây cho hành vừa chín tái xanh mướt rồi tắt bếp. Xếp cua ra đĩa lớn, rưới phần sốt gừng hành còn lại trong chảo lên trên và dọn nóng.', NULL, NULL),
('imp-122b920eba3f2e50_v4_step_1', 'imp-122b920eba3f2e50', 1, 'prep', 'Ép ráo đậu phụ và sơ chế rau củ', 'Đặt 3 bìa đậu phụ trắng lên khăn giấy sạch, ép nhẹ khoảng 5 phút cho thoát bớt nước rồi cắt thành khối vuông cạnh 2,5 cm. Rửa sạch cải thảo và cà rốt; cải thảo thái miếng vừa ăn tách riêng phần cọng trắng với lá xanh, cà rốt bào sợi mỏng, hành lá cắt khúc 4 cm, còn gừng tươi và tỏi khô băm nhuyễn.', 'Ép ráo đậu phụ trước khi áp chảo giúp mặt đậu nhanh vàng giòn, không bị bắn dầu và không nát vỡ khi đảo cùng mì.', NULL),
('imp-122b920eba3f2e50_v4_step_2', 'imp-122b920eba3f2e50', 2, 'sauce', 'Pha hỗn hợp sốt tương đen Hoisin', 'Cho vào bát nhỏ 25 ml xì dầu, 20 ml tương đen Hoisin, 15 ml rượu Thiệu Hưng, 10 ml dầu mè thơm, 8 g bột bắp, 6 g đường cát trắng, gừng băm, tỏi băm và 50 ml nước lọc. Khuấy đều tay đến khi bột bắp và đường tan hoàn toàn rồi đặt sẵn bên cạnh bếp.', 'Pha sẵn chén sốt trước khi xào giúp bạn chủ động tốc độ trên lửa lớn, tránh tình trạng rau chín nhũn trong lúc nêm từng loại gia vị.', NULL),
('imp-122b920eba3f2e50_v4_step_3', 'imp-122b920eba3f2e50', 3, 'cook', 'Trụng tơi mì Udon lúa mì', 'Đun sôi khoảng 1150 ml nước lọc trong nồi vừa, thả 2 gói mì Udon lúa mì tươi vào trụng khoảng 1 đến 2 phút trên lửa lớn, dùng đũa khuấy nhẹ cho các sợi mì tách tơi hoàn toàn mà không bị nát. Vớt mì ra rổ cho ráo hết nước.', NULL, 2),
('imp-122b920eba3f2e50_v4_step_4', 'imp-122b920eba3f2e50', 4, 'cook', 'Áp chảo đậu phụ vàng giòn các mặt', 'Làm nóng chảo chống dính lớn trên lửa vừa với 15 ml dầu ăn thực vật, xếp đều các khối đậu phụ vào thành một lớp thưa. Áp chảo khoảng 8 phút, lật đều các mặt đến khi đậu phụ vàng nâu giòn cạnh thì gắp riêng ra đĩa.', 'Không lật đậu phụ quá sớm; hãy đợi mặt dưới se vàng hẳn mới trở mặt để đậu giữ nguyên khối vuông đẹp mắt.', 8),
('imp-122b920eba3f2e50_v4_step_5', 'imp-122b920eba3f2e50', 5, 'cook', 'Xào nhanh cà rốt và cải thảo lửa lớn', 'Cho 10 ml dầu ăn còn lại vào chảo, tăng lên lửa lớn. Thả cà rốt thái sợi và phần cọng trắng cải thảo vào đảo nhanh 1 phút cho dậy mùi thơm, sau đó thêm phần lá xanh cải thảo vào xào tiếp khoảng 45 giây đến khi rau vừa chín tới, vẫn giữ độ giòn.', NULL, 2),
('imp-122b920eba3f2e50_v4_step_6', 'imp-122b920eba3f2e50', 6, 'finish', 'Đảo mì quyện sốt đậu phụ và dọn nóng', 'Trút mì Udon đã ráo nước, đậu phụ áp chảo, hành lá cắt khúc và khuấy lại chén sốt tương đen Hoisin rưới đều vào chảo. Xóc và đảo nhẹ tay trên lửa lớn khoảng 1 phút cho nước sốt sánh bóng áo đều từng sợi mì và rau củ rồi tắt bếp, dọn ngay khi còn nóng.', NULL, NULL),
('imp-01ae566db4a7feab_v4_step_1', 'imp-01ae566db4a7feab', 1, 'prep', 'Thái ngang thớ và ướp mềm thịt bò', 'Thấm khô 400 g thịt thăn bò bằng khăn giấy, thái lát mỏng 2 đến 3 mm theo chiều ngang thớ để thịt không bị dai. Cho bò vào tô ướp cùng 15 ml xì dầu nhạt, 5 ml dầu mè thơm và 1 g tiêu trắng xay, trộn đều rồi để thấm trong 15 phút.', 'Không cho muối vào lúc ướp thịt bò sống vì muối làm thịt tiết nước và bị săn cứng khi nấu nhanh.', 15),
('imp-01ae566db4a7feab_v4_step_2', 'imp-01ae566db4a7feab', 2, 'prep', 'Sơ chế nấm đùi gà và các nguyên liệu thơm', 'Rửa sạch nấm đùi gà tươi, cắt bỏ gốc già rồi thái lát dọc dày khoảng 0,5 cm vừa ăn. Gừng tươi thái lát mỏng, tỏi khô đập dập; hành lá tách phần đầu trắng đập dập để nấu nước dùng, còn phần lá xanh thái nhỏ để riêng.', NULL, NULL),
('imp-01ae566db4a7feab_v4_step_3', 'imp-01ae566db4a7feab', 3, 'cook', 'Nấu nước dùng bò thơm gừng hành', 'Cho 1000 ml nước dùng bò cùng 260 ml nước lọc vào nồi sâu lòng, thả gừng thái lát, tỏi đập dập và đầu hành trắng vào đun sôi trên lửa lớn. Khi nước sôi bùng, hạ xuống lửa vừa đun thêm 5 phút cho nước dùng dậy hương thơm rồi vớt bỏ bã gừng tỏi và đầu hành để nước súp trong đẹp.', NULL, 5),
('imp-01ae566db4a7feab_v4_step_4', 'imp-01ae566db4a7feab', 4, 'cook', 'Nấu chín nấm đùi gà ngọt nước', 'Cho toàn bộ nấm đùi gà thái lát vào nồi nước dùng đang sôi nhẹ trên lửa vừa, nấu khoảng 8 phút đến khi nấm chín mềm, ngấm vị và tiết ra độ ngọt tự nhiên cho nước súp. Hớt sạch bọt nổi nếu có.', 'Nấu nấm trước giúp nước súp ngọt thanh mà không làm thịt bò bị chín quá kỹ.', 8),
('imp-01ae566db4a7feab_v4_step_5', 'imp-01ae566db4a7feab', 5, 'cook', 'Trụng nhanh thịt bò và nêm gia vị', 'Giữ nồi súp sôi lăn tăn ở lửa vừa, thả từng lượt thịt bò đã ướp vào khuấy nhẹ cho tơi miếng, nấu khoảng 2 đến 3 phút đến khi thịt bò vừa chín đều không còn sắc đỏ sống. Nêm thêm 10 ml xì dầu nhạt còn lại, 5 g muối ăn và 1 g tiêu trắng xay cho vừa miệng.', 'Không đun sôi sục quá lâu sau khi thả bò để lát thịt giữ được độ mềm mọng và ngọt tự nhiên.', 3),
('imp-01ae566db4a7feab_v4_step_6', 'imp-01ae566db4a7feab', 6, 'finish', 'Tạo độ sánh nhẹ và hoàn thiện tô súp', 'Hòa tan 12 g bột bắp với 40 ml nước lọc còn lại, vừa khuấy nhẹ nồi súp theo một chiều vừa rót từ từ nước bột bắp vào đến khi nước súp có độ sánh mượt nhẹ rồi đun thêm 30 giây cho chín bột. Tắt bếp, múc súp ra tô, rắc hành lá xanh thái nhỏ và dùng ngay khi còn nóng.', NULL, NULL),
('imp-296dbce4d9098a2e_v4_step_1', 'imp-296dbce4d9098a2e', 1, 'prep', 'Làm nóng lò và sơ chế phi lê cá', 'Làm nóng trước lò nướng ở 180°C trong khoảng 10 phút. Rửa nhanh 700 g phi lê cá chẽm dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô hai mặt. Xoa đều 10 ml dầu ăn thực vật, 3 g muối ăn và 2 g tiêu đen xay lên cả hai mặt từng miếng cá.', 'Thấm thật khô mặt cá trước khi thoa dầu và muối tiêu giúp gia vị bám đều và hạn chế mùi tanh khi nướng kín.', NULL),
('imp-296dbce4d9098a2e_v4_step_2', 'imp-296dbce4d9098a2e', 2, 'prep', 'Thái gừng hành và pha chén sốt xì dầu', 'Thái 25 g gừng tươi thành sợi chỉ, cắt khúc 5 cm phần hành lá tươi và băm nhỏ 4 tép tỏi khô. Trong chén nhỏ, khuấy tan hoàn toàn 6 g đường cát trắng với 50 ml xì dầu nhạt và 60 ml nước lọc.', NULL, NULL),
('imp-296dbce4d9098a2e_v4_step_3', 'imp-296dbce4d9098a2e', 3, 'cook', 'Xếp cá vào khay lót gừng hành và rưới sốt', 'Lót một nửa lượng gừng thái sợi và một nửa hành lá cắt khúc xuống đáy khay nướng vừa kích thước, xếp 4 miếng phi lê cá lên trên thành một lớp không chồng chéo. Rưới đều hỗn hợp xì dầu nhạt đã pha lên mặt cá rồi rắc nốt phần gừng và hành lá còn lại lên trên (chừa lại ít để phi dầu mè).', 'Lớp gừng hành lót bên dưới vừa giúp cá không dính đáy khay vừa truyền hương thơm đều từ mặt dưới lên.', NULL),
('imp-296dbce4d9098a2e_v4_step_4', 'imp-296dbce4d9098a2e', 4, 'cook', 'Bọc kín giấy bạc và nướng chín cá', 'Đậy kín miệng khay bằng giấy bạc sao cho hơi nước không thoát ra ngoài, cho vào rãnh giữa lò nướng ở 180°C trong 15 phút. Sau đó mở hé giấy bạc kiểm tra thấy thịt cá chuyển trắng đục hoàn toàn và dễ tách thớ khi khều nhẹ bằng nĩa là cá đã chín tới.', 'Nướng kín bằng giấy bạc giữ trọn nước ngọt của phi lê cá; tránh nướng quá lâu làm thớ cá bị khô bở.', 15),
('imp-296dbce4d9098a2e_v4_step_5', 'imp-296dbce4d9098a2e', 5, 'cook', 'Phi thơm tỏi, gừng và hành với dầu mè', 'Trong lúc chờ cá nướng gần xong, đun nóng 15 ml dầu mè thơm trong chảo nhỏ trên lửa vừa, cho tỏi băm vào phi thơm khoảng 30 giây đến khi vừa vàng nhạt rồi cho phần hành lá và gừng sợi còn lại vào đảo nhanh 1 phút cho dậy hương thơm thì tắt bếp.', NULL, 2),
('imp-296dbce4d9098a2e_v4_step_6', 'imp-296dbce4d9098a2e', 6, 'finish', 'Trình bày và rưới dầu mè hành gừng nóng', 'Cẩn thận mở giấy bạc tránh bỏng hơi nóng, nhẹ nhàng chuyển từng miếng phi lê cá ra đĩa sâu lòng. Chan phần nước sốt xì dầu ấm trong khay nướng lên cá, sau đó rưới hỗn hợp hành gừng tỏi phi dầu mè thơm phức lên mặt và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_1', 'imp-0a43bfa1d02fa497', 1, 'prep', 'Rửa sạch cải bó xôi và băm tỏi', 'Nhặt bỏ phần lá úa và rễ già của 350 g cải bó xôi, tách nhánh rửa kỹ nhiều lượt trong thau nước lạnh cho sạch hoàn toàn đất cát bám ở gốc, vẩy ráo rồi cắt khúc dài 8 đến 10 cm. Tỏi khô bóc vỏ, băm thật nhuyễn để riêng.', 'Giữ lại phần gốc hồng non của cải bó xôi sau khi rửa sạch vì phần này rất giòn và ngọt tự nhiên.', NULL),
('imp-0a43bfa1d02fa497_v4_step_2', 'imp-0a43bfa1d02fa497', 2, 'sauce', 'Pha sẵn nước sốt trộn tỏi giấm đen', 'Cho vào bát nhỏ tỏi băm nhuyễn, 15 ml xì dầu nhạt, 15 ml giấm đen Trấn Giang, 10 ml dầu hào chay nấm đông cô, 10 ml dầu mè thơm, 1 g tiêu trắng xay, 2 g muối ăn và 4 g đường cát trắng. Khuấy đều tay đến khi muối đường tan hoàn toàn.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_3', 'imp-0a43bfa1d02fa497', 3, 'cook', 'Chần nhanh cải bó xôi giữ màu xanh mướt', 'Đun sôi 1200 ml nước lọc trong nồi lớn trên lửa lớn, đồng thời chuẩn bị sẵn một thau nước lạnh có thả đá viên. Khi nước sôi bùng, cho 5 ml dầu ăn thực vật vào nồi và thả một nửa số cải bó xôi vào chần khoảng 40 giây đến khi lá vừa chín mềm vẫn còn xanh tươi.', 'Chia rau thành 2 mẻ chần giúp nhiệt độ nước không tụt đột ngột, nhờ đó rau chín đều và không bị sậm màu.', 1),
('imp-0a43bfa1d02fa497_v4_step_4', 'imp-0a43bfa1d02fa497', 4, 'cook', 'Ngâm sốc nhiệt nước lạnh và chần mẻ tiếp theo', 'Vớt ngay mẻ rau đầu tiên thả vào thau nước đá lạnh để hãm nhiệt. Cho nốt 5 ml dầu ăn thực vật vào nồi nước đang sôi và chần phần cải bó xôi còn lại thêm 40 giây rồi vớt ra ngâm chung vào nước đá đến khi rau nguội hẳn.', NULL, NULL),
('imp-0a43bfa1d02fa497_v4_step_5', 'imp-0a43bfa1d02fa497', 5, 'prep', 'Vắt ráo kiệt nước rau đã chần', 'Vớt cải bó xôi khỏi thau nước lạnh, chia từng nắm nhỏ rồi dùng hai tay bóp vắt nhẹ nhàng nhưng thật kiệt nước để rau không bị nát mà vẫn ráo hoàn toàn, sau đó tách tơi cho vào tô trộn lớn.', 'Rau vắt càng ráo nước thì nước sốt càng bám đều vào từng cọng rau mà không bị chảy loãng ra đáy đĩa.', NULL),
('imp-0a43bfa1d02fa497_v4_step_6', 'imp-0a43bfa1d02fa497', 6, 'finish', 'Trộn đều sốt, ướp mát và rắc mè rang', 'Khuấy đều lại bát sốt rồi rưới lên tô cải bó xôi, trộn nhẹ tay cho gia vị phủ đều khắp cọng rau, nếm thử và chỉnh lại độ chua mặn vừa miệng. Có thể đậy kín để tủ lạnh 10 phút cho mát rồi gắp ra đĩa, rắc hạt mè trắng rang lên trên và thưởng thức.', NULL, 10),
('imp-329f0579ddc26919_v4_step_1', 'imp-329f0579ddc26919', 1, 'prep', 'Khía vỏ và chần bóc vỏ cà chua', 'Chọn 4 quả cà chua chín đỏ nhưng còn cầm chắc tay, rửa sạch rồi dùng mũi dao khía nhẹ hình chữ thập ở phần đáy quả. Đun sôi 1000 ml nước lọc trên lửa lớn, thả cà chua vào chần đúng 30 giây rồi vớt ngay sang thau nước lạnh, lột sạch lớp vỏ mỏng bên ngoài.', 'Chọn cà chua vừa chín tới và chần nhanh không quá 30 giây giúp cà chua dễ bóc vỏ mà ruột vẫn săn, không bị nhũn nát khi trộn.', 1),
('imp-329f0579ddc26919_v4_step_2', 'imp-329f0579ddc26919', 2, 'prep', 'Cắt múi cau cà chua và băm tỏi hành', 'Cắt bỏ cuống cà chua đã bóc vỏ rồi bổ mỗi quả thành 6 đến 8 múi cau vừa ăn, xếp nhẹ vào tô lớn. Băm thật nhuyễn 6 tép tỏi khô, thái nhỏ 30 g hành lá tươi (tách riêng đầu trắng và lá xanh) cùng 10 g ngò rí cắt khúc ngắn.', NULL, NULL),
('imp-329f0579ddc26919_v4_step_3', 'imp-329f0579ddc26919', 3, 'cook', 'Phi thơm một nửa tỏi băm tạo dầu tỏi', 'Làm nóng chảo nhỏ với 10 ml dầu ăn thực vật trên lửa vừa, cho một nửa lượng tỏi băm vào đảo nhanh khoảng 30 giây đến khi tỏi vừa ngả vàng nhạt và dậy mùi thơm thì tắt bếp ngay, để nguội bớt.', 'Kết hợp nửa tỏi phi thơm và nửa tỏi tươi giúp món trộn vừa thơm dịu mùi dầu tỏi vừa giữ nét cay nồng đặc trưng.', NULL),
('imp-329f0579ddc26919_v4_step_4', 'imp-329f0579ddc26919', 4, 'sauce', 'Pha nước sốt chua ngọt xì dầu giấm gạo', 'Trong bát nhỏ, khuấy tan hoàn toàn 25 ml xì dầu nhạt, 15 ml giấm gạo, 10 g đường cát trắng và 2 g muối ăn. Sau đó trộn thêm phần tỏi tươi băm còn lại, đầu hành trắng thái nhỏ và phần dầu tỏi phi vừa nguội vào khuấy đều.', 'Khuấy tan hoàn toàn đường và muối trước khi rưới giúp nước sốt thấm đều vào từng múi cà chua mà không bị lắng cặn dưới đáy tô.', NULL),
('imp-329f0579ddc26919_v4_step_5', 'imp-329f0579ddc26919', 5, 'marinate', 'Trộn nhẹ cà chua và ướp lạnh cho thấm', 'Rưới đều bát nước sốt lên tô cà chua múi cau, dùng thìa lớn đảo thật nhẹ tay từ dưới lên để nước sốt áo đều từng miếng cà chua mà không làm dập nát. Bọc kín tô bằng màng bọc thực phẩm, đặt vào ngăn mát tủ lạnh khoảng 30 phút cho cà chua thấm vị và mát lạnh.', 'Ướp lạnh tối thiểu 30 phút giúp cà chua tiết ra nước ngọt tự nhiên hòa quyện với sốt xì dầu giấm gạo rất thanh mát.', 30),
('imp-329f0579ddc26919_v4_step_6', 'imp-329f0579ddc26919', 6, 'finish', 'Rưới dầu mè thơm và hoàn thiện món trộn', 'Lấy tô cà chua khỏi tủ lạnh, rưới 15 ml dầu mè thơm lên trên rồi trộn nhẹ thêm một lượt cho nước sốt hòa quyện. Gắp cà chua ra đĩa sâu lòng, chan hết phần nước sốt chua ngọt, rắc lá hành xanh và ngò rí lên mặt rồi dùng lạnh ngay.', NULL, NULL),
('imp-59f5760d6349d284_v4_step_1', 'imp-59f5760d6349d284', 1, 'prep', 'Sơ chế và khía mặt nấm đùi gà', 'Rửa sạch 450 g nấm đùi gà tươi, cắt bỏ phần gốc già rồi bổ đôi từng cây theo chiều dọc, dùng mũi dao khía nhẹ hình caro lên mặt cắt bên trong và thấm thật khô bằng khăn giấy. Hành lá tươi thái nhỏ (chừa lại ít lá xanh để rắc mặt), gừng tươi băm nhuyễn.', 'Khía nhẹ mặt cắt của nấm và thấm khô hoàn toàn giúp lớp bột bắp và nhân thịt bám chặt, không bị bung rời khi hấp.', NULL),
('imp-59f5760d6349d284_v4_step_2', 'imp-59f5760d6349d284', 2, 'marinate', 'Quết dẻo nhân thịt heo xay với gia vị', 'Cho 400 g thịt heo xay vào tô lớn cùng trứng gà đánh tan, gừng băm, hành lá thái nhỏ, 15 ml xì dầu nhạt, 15 ml dầu hào, 15 ml rượu Thiệu Hưng, 6 g bột bắp, 5 ml dầu mè thơm, 4 g đường cát trắng, 3 g muối ăn và 1,5 g tiêu trắng xay. Dùng thìa quết mạnh theo một chiều đến khi nhân thành khối dẻo mịn rồi để nghỉ 10 phút.', NULL, 10),
('imp-59f5760d6349d284_v4_step_3', 'imp-59f5760d6349d284', 3, 'prep', 'Áo bột bắp và nhồi nhân lên miếng nấm', 'Rắc mỏng khoảng 2 g bột bắp lên mặt khía của từng miếng nấm đùi gà, sau đó múc từng phần nhân thịt đặt lên trên, dùng thìa ấn và miết nhẹ quanh mép để nhân ôm sát vào thớ nấm. Xếp nấm nhồi vào đĩa sâu lòng chịu nhiệt, hướng mặt nhân lên trên.', 'Lớp bột bắp mỏng đóng vai trò như chất kết dính tự nhiên giữa bề mặt nấm trơn và khối nhân thịt.', NULL),
('imp-59f5760d6349d284_v4_step_4', 'imp-59f5760d6349d284', 4, 'cook', 'Hấp chín nấm nhồi thịt trên lửa lớn', 'Đun sôi mạnh nước trong nồi xửng, đặt đĩa nấm vào hấp ở lửa lớn trong 15 phút. Kiểm tra bằng cách xiên nhẹ tăm vào phần nhân dày nhất: thấy nước chảy ra trong suốt, thịt chín trắng chắc hoàn toàn không còn màu hồng sống và nấm mềm ngọt là đạt.', 'Xếp các miếng nấm hơi thưa nhau để hơi nước lưu thông đều, giúp nhân thịt chín đồng nhất mà nấm không bị nhũn nước.', 15),
('imp-59f5760d6349d284_v4_step_5', 'imp-59f5760d6349d284', 5, 'sauce', 'Tận dụng nước hấp nấu sốt dầu hào sánh mịn', 'Nhấc đĩa nấm ra khỏi xửng, chắt toàn bộ phần nước ngọt tiết ra trên đĩa vào chảo nhỏ và đậy nắp giữ ấm đĩa nấm. Thêm phần nước lọc còn lại (chừa 15 ml hòa tan 4 g bột bắp) sao cho đủ khoảng 100 ml lỏng, cho tiếp 10 ml xì dầu nhạt, 15 ml dầu hào, 4 g đường cát trắng và 5 ml giấm gạo vào đun sôi nhẹ trên lửa nhỏ rồi rót nước bột bắp vào khuấy khoảng 2 phút đến khi sốt sánh bóng.', NULL, 2),
('imp-59f5760d6349d284_v4_step_6', 'imp-59f5760d6349d284', 6, 'finish', 'Rưới sốt nóng và hoàn thiện đĩa nấm hấp', 'Rưới đều phần nước sốt dầu hào xì dầu còn nóng hổi lên từng miếng nấm nhồi thịt, rắc nốt phần hành lá xanh thái nhỏ lên trên và dọn ăn ngay khi còn nóng cùng cơm trắng.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_1', 'imp-d8001a64eeaa9150', 1, 'prep', 'Chuẩn bị cơm nóng và các topping khô', 'Chuẩn bị sẵn 360 g cơm trắng hạt ngắn Nhật thật nóng bốc hơi. Rửa sạch hành lá tươi, thấm khô rồi thái khoanh thật mỏng; bóp tơi cá bào khô Katsuobushi và cắt rong biển lá khô Nori thành sợi mảnh.', 'Chỉ sử dụng trứng gà tươi sạch từ nguồn uy tín hoặc trứng đã tiệt trùng để đảm bảo an toàn thực phẩm khi ăn kiểu Tamago Kake Gohan.', NULL),
('imp-d8001a64eeaa9150_v4_step_2', 'imp-d8001a64eeaa9150', 2, 'prep', 'Tách riêng lòng trắng và lòng đỏ trứng gà', 'Đập 2 quả trứng gà tươi, khéo léo tách riêng 2 lòng trắng và 2 lòng đỏ ra từng chén nhỏ để giúp kết cấu cơm trộn bông mịn như sốt kem.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_3', 'imp-d8001a64eeaa9150', 3, 'sauce', 'Đánh lòng trắng trứng với xì dầu Nhật', 'Cho 20 ml xì dầu Nhật Bản (và 5 ml rượu ngọt Mirin nếu dùng) vào chén lòng trắng trứng, dùng đũa đánh nhanh tay khoảng 30 giây cho đến khi lòng trắng hơi nổi bọt mịn và hòa đều gia vị.', 'Đánh lòng trắng với xì dầu trước giúp gia vị phân bổ đều khắp hạt cơm và tránh làm lòng trắng còn lợn cợn khi trộn.', NULL),
('imp-d8001a64eeaa9150_v4_step_4', 'imp-d8001a64eeaa9150', 4, 'cook', 'Trộn lòng trắng trứng vào cơm nóng bốc hơi', 'Xới cơm trắng nóng ra 2 tô (180 g/tô), tạo một hõm nhỏ ở giữa rồi chia đều hỗn hợp lòng trắng trứng xì dầu đổ vào từng tô. Dùng đũa trộn thật nhanh và đều tay khoảng 1 phút cho hơi nóng làm lòng trắng sánh lại thành lớp kem mịn phủ quanh từng hạt cơm.', NULL, 1),
('imp-d8001a64eeaa9150_v4_step_5', 'imp-d8001a64eeaa9150', 5, 'finish', 'Phủ cá bào, rong biển và đặt lòng đỏ lên trên', 'Rắc đều cá bào khô Katsuobushi, rong biển lá khô Nori cắt sợi, hạt mè trắng rang và hành lá thái mỏng lên mặt hai tô cơm, sau đó nhẹ nhàng đặt 1 lòng đỏ trứng vào chính giữa mỗi tô.', NULL, NULL),
('imp-d8001a64eeaa9150_v4_step_6', 'imp-d8001a64eeaa9150', 6, 'finish', 'Trộn đều lần cuối và thưởng thức nóng', 'Khi ăn, chọc vỡ lòng đỏ và dùng đũa đảo đều mạnh tay khoảng 1 phút đến khi toàn bộ tô cơm chuyển màu vàng óng mượt mà và bùi béo thì dùng nóng ngay.', 'Không cho quá nhiều xì dầu cùng lúc vì vị mặn gắt sẽ át mất hương béo ngọt tự nhiên của lòng đỏ trứng gà.', 1),
('imp-e420d7a0eed8a0d6_v4_step_1', 'imp-e420d7a0eed8a0d6', 1, 'prep', 'Làm sạch tôm bằng bột năng và sơ chế gia vị', 'Cho 350 g tôm tươi đã bóc vỏ, rút chỉ lưng vào tô, rắc 10 g bột năng vào bóp nhẹ 30 giây để hút sạch nhớt và mùi tanh, sau đó rửa kỹ lại dưới vòi nước lạnh và thấm thật khô bằng khăn giấy. Băm thật nhuyễn gừng tươi và tỏi tươi; hành lá tách riêng phần đầu trắng băm nhỏ và phần lá xanh thái khoanh.', 'Chà tôm với một chút bột năng rồi xả sạch là mẹo giúp thịt tôm giòn săn tự nhiên và hoàn toàn hết mùi tanh.', NULL),
('imp-e420d7a0eed8a0d6_v4_step_2', 'imp-e420d7a0eed8a0d6', 2, 'marinate', 'Ướp tôm với Sake, gia vị và lớp áo bột mỏng', 'Ướp tôm đã thấm khô với 2 g muối ăn, 1 g tiêu trắng xay và 15 ml rượu Sake Nhật Bản, trộn đều rồi tiếp tục rắc thêm 10 g bột năng áo đều quanh từng con tôm; để nghỉ 10 phút cho thấm vị.', NULL, 10),
('imp-e420d7a0eed8a0d6_v4_step_3', 'imp-e420d7a0eed8a0d6', 3, 'cook', 'Áp chảo sơ tôm trên lửa vừa lớn', 'Đun nóng 12 ml dầu ăn thực vật trong chảo rộng trên lửa vừa lớn, xếp tôm thành một lớp thoáng và áp chảo mỗi mặt khoảng 1 phút đến khi mặt ngoài tôm vừa chuyển màu hồng cam và lớp bột se nhẹ thì gắp ngay ra đĩa riêng. Lau sạch cặn cháy nhẹ trong chảo bằng khăn giấy.', 'Không xào tôm chín kỹ ở bước này vì tôm sẽ tiếp tục được đảo cùng sốt nóng; áp chảo vừa chuyển màu giúp tôm giữ được độ giòn mọng.', 2),
('imp-e420d7a0eed8a0d6_v4_step_4', 'imp-e420d7a0eed8a0d6', 4, 'sauce', 'Phi thơm gừng tỏi và xào tương Doubanjiang', 'Cho 13 ml dầu ăn thực vật còn lại vào chảo trên lửa vừa, thả gừng tươi và tỏi băm vào phi khoảng 30 giây đến khi thơm dịu thì hạ lửa nhỏ, thêm 18 g tương ớt đậu bản Doubanjiang vào đảo đều 30 giây cho dậy màu dầu đỏ và hương thơm nồng.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-e420d7a0eed8a0d6_v4_step_5', 'imp-e420d7a0eed8a0d6', 5, 'sauce', 'Đun hòa quyện nền sốt cà cay ngọt', 'Đổ vào chảo 45 ml tương cà Ketchup, 150 ml nước dùng gà, 20 ml rượu Sake còn lại, 15 ml xì dầu Nhật Bản và 8 g đường cát trắng. Khuấy đều và đun sôi liu riu trên lửa vừa khoảng 3 phút cho các gia vị hòa quyện.', NULL, 3),
('imp-e420d7a0eed8a0d6_v4_step_6', 'imp-e420d7a0eed8a0d6', 6, 'cook', 'Nấu chín tôm trong sốt và tạo độ sánh bóng', 'Trút toàn bộ tôm đã áp chảo cùng phần đầu trắng hành lá vào chảo sốt, đảo nhẹ tay khoảng 2 phút đến khi tôm cong tròn, thịt chín đục hoàn toàn. Hòa tan 10 g bột năng còn lại với 45 ml nước lọc rồi rót từ từ vào chảo vừa khuấy đều đến khi sốt sánh bóng bám đều từng con tôm.', 'Rót nước bột năng từ từ từng chút một và khuấy liên tục trên lửa vừa để sốt sánh mượt đều, không bị vón cục.', 2),
('imp-e420d7a0eed8a0d6_v4_step_7', 'imp-e420d7a0eed8a0d6', 7, 'finish', 'Rưới dầu mè thơm và hoàn thiện đĩa tôm', 'Tắt bếp ngay khi sốt sánh đạt độ bóng đẹp, rưới 7 ml dầu mè thơm vào đảo nhanh một vòng để giữ trọn hương thơm. Múc tôm sốt cay ra đĩa nóng, rắc phần lá xanh hành lá thái nhỏ lên trên và dùng kèm cơm trắng.', NULL, NULL),
('imp-2138056075abd874_v4_step_1', 'imp-2138056075abd874', 1, 'prep', 'Ép ráo nước đậu phụ trắng', 'Lấy 300 g đậu phụ trắng loại chắc ra khỏi hộp, bọc kín bằng 2–3 lớp khăn giấy thấm nước rồi đặt lên đĩa phẳng và chèn một vật nặng vừa phải (như thớt nhỏ) lên trên. Để ép khoảng 15 phút cho đậu ráo bớt nước thừa.', 'Ép ráo đậu phụ trước khi trộn giúp miếng đậu săn chắc giữ nguyên khối vuông đẹp mắt và không làm loãng nước sốt salad.', 15),
('imp-2138056075abd874_v4_step_2', 'imp-2138056075abd874', 2, 'prep', 'Cắt khối dưa leo, đậu phụ và thái hành lá', 'Rửa sạch dưa leo tươi, lau thật khô, bổ dọc làm đôi và dùng thìa nạo nhẹ bỏ phần ruột hạt nhiều nước rồi cắt khối vuông cạnh 1,5 cm. Gỡ bỏ khăn giấy quanh đậu phụ và cắt khối vuông 1,5 cm đồng kích thước với dưa leo; hành lá thái khoanh thật mỏng.', NULL, NULL),
('imp-2138056075abd874_v4_step_3', 'imp-2138056075abd874', 3, 'sauce', 'Đánh sốt Miso giấm gạo dầu ô liu', 'Cho 30 g tương Miso trắng Nhật Bản, 40 ml giấm gạo Nhật, 30 ml xì dầu Nhật Bản và 4 g đường cát trắng vào tô nhỏ, dùng phới lồng khuấy tan mịn hoàn toàn. Vừa khuấy đều vừa rót từ từ 30 ml dầu ô liu nguyên chất vào cho sốt quyện sánh, sau đó trộn thêm 15 g hạt mè trắng rang.', 'Phải đánh tan hoàn toàn tương Miso với giấm và xì dầu trước khi rót dầu ô liu để sốt nhũ hóa mịn mượt, không bị vón cục.', NULL),
('imp-2138056075abd874_v4_step_4', 'imp-2138056075abd874', 4, 'prep', 'Trộn nhẹ nhàng đậu phụ và dưa leo với sốt', 'Cho đậu phụ cắt khối, dưa leo và hành lá thái mỏng vào tô trộn rộng, rưới đều toàn bộ phần sốt Miso mè rang lên trên. Dùng thìa dẹt hất nhẹ từ đáy tô lên để sốt phủ đều khắp mặt mà không làm vỡ nát miếng đậu phụ.', 'Dùng tô rộng và hất nhẹ từ đáy lên giúp các khối đậu phụ giữ nguyên hình dạng vuông vức, không bị nát vụn.', NULL),
('imp-2138056075abd874_v4_step_5', 'imp-2138056075abd874', 5, 'prep', 'Làm lạnh salad cho thấm vị', 'Bọc kín miệng tô bằng màng bọc thực phẩm và đặt vào ngăn mát tủ lạnh khoảng 10 phút cho các nguyên liệu mát giòn và ngấm đều hương vị sốt.', NULL, 10),
('imp-2138056075abd874_v4_step_6', 'imp-2138056075abd874', 6, 'finish', 'Bày đĩa, rắc mè rang và thưởng thức', 'Lấy salad đậu phụ dưa leo ra khỏi tủ lạnh, múc nhẹ nhàng vào đĩa sâu lòng, rắc 5 g hạt mè trắng rang còn lại lên mặt và dùng lạnh ngay.', NULL, NULL),
('imp-ff9fd0fdcdd85b79_v4_step_1', 'imp-ff9fd0fdcdd85b79', 1, 'prep', 'Cắt miếng bắp cải và sơ chế tỏi, hành lá', 'Bóc bỏ lá già ngoài cùng của 400 g bắp cải tươi, rửa sạch và để thật ráo nước. Bổ bắp cải thành miếng to cỡ 4–5 cm sao cho các lớp lá vẫn bám với nhau (phần lõi cứng thái lát mỏng hơn cho nhanh chín). Thái lát mỏng tỏi tươi và thái khoanh nhỏ hành lá.', 'Để bắp cải thật ráo nước trước khi áp chảo giúp lá rau nhanh xém vàng thơm mà không bị tiết nước hấp nhũn.', NULL),
('imp-ff9fd0fdcdd85b79_v4_step_2', 'imp-ff9fd0fdcdd85b79', 2, 'cook', 'Áp chảo mặt đầu bắp cải không đảo', 'Làm nóng chảo rộng trên lửa vừa với 10 ml dầu ăn thực vật. Xếp các miếng bắp cải thành một lớp phẳng xuống đáy chảo và giữ yên không đảo trong 3 phút cho mặt dưới xém vàng nâu nhẹ và dậy mùi ngọt tự nhiên.', 'Không đảo liên tục trong 3 phút đầu là bí quyết giúp bắp cải cháy cạnh thơm lừng như nướng vỉ thay vì ra nước như món xào.', 3),
('imp-ff9fd0fdcdd85b79_v4_step_3', 'imp-ff9fd0fdcdd85b79', 3, 'cook', 'Lật mặt áp tiếp cho bắp cải chín mềm', 'Dùng kẹp hoặc xẻng lật nhẹ nhàng từng miếng bắp cải sang mặt còn lại, áp tiếp trên lửa vừa khoảng 3 phút đến khi mặt thứ hai cũng hơi xém cạnh và phần lá bắt đầu mềm dịu.', NULL, 3),
('imp-ff9fd0fdcdd85b79_v4_step_4', 'imp-ff9fd0fdcdd85b79', 4, 'cook', 'Đậy nắp hấp nhanh làm mềm phần lõi', 'Đậy nắp chảo và hạ lửa vừa nhỏ thêm khoảng 2 phút để hơi ẩm tự nhiên trong bắp cải làm chín mềm phần cuống dày bên trong.', NULL, 2),
('imp-ff9fd0fdcdd85b79_v4_step_5', 'imp-ff9fd0fdcdd85b79', 5, 'sauce', 'Làm tan chảy bơ lạt với tỏi và xì dầu Nhật', 'Mở nắp, hạ lửa nhỏ rồi thả 25 g bơ lạt cùng tỏi thái lát vào chảo, nghiêng nhẹ cho bơ tan chảy quyện mùi tỏi thơm trong 1 phút. Rưới 15 ml xì dầu Nhật Bản dọc theo mép chảo nóng, rắc 2 g muối ăn và 1 g tiêu đen xay rồi đảo nhanh tay cho bơ xì dầu áo bóng từng miếng bắp cải.', 'Rưới xì dầu vào thành chảo nóng giúp tạo hương thơm xì dầu cháy đặc trưng mà không làm bắp cải bị mặn cục bộ.', 1),
('imp-ff9fd0fdcdd85b79_v4_step_6', 'imp-ff9fd0fdcdd85b79', 6, 'finish', 'Rắc hành lá, cá bào và thưởng thức nóng', 'Tắt bếp, gắp bắp cải áp chảo ra đĩa nóng và rưới phần bơ xì dầu còn lại trong chảo lên trên, rắc hành lá thái nhỏ cùng cá bào khô Katsuobushi (nếu dùng) và ăn ngay khi còn nóng.', NULL, NULL),
('imp-d6e35b3fa19080de_v4_step_1', 'imp-d6e35b3fa19080de', 1, 'prep', 'Sơ chế nấm đùi gà, hành lá và đánh trứng', 'Lau sạch 200 g nấm đùi gà tươi, cắt bỏ phần gốc cứng rồi thái lát mỏng dày khoảng 0,5 cm. Rửa sạch hành lá tươi và thái khoanh mỏng. Đập 5 quả trứng gà tươi ra tô, dùng đũa đánh tan đều lòng đỏ và lòng trắng nhưng không đánh nổi bọt.', 'Chỉ đánh nhẹ cho lòng trắng và lòng đỏ hòa đều thành dòng mịn; đánh quá mạnh tạo nhiều bọt khí sẽ khiến trứng om bị rỗ mặt.', NULL),
('imp-d6e35b3fa19080de_v4_step_2', 'imp-d6e35b3fa19080de', 2, 'sauce', 'Pha và đun sôi nước dùng om kiểu Nhật', 'Cho 300 ml nước dùng Dashi vào nồi nông hoặc chảo sâu lòng, thêm 18 ml xì dầu nhạt Nhật Bản, 15 ml rượu ngọt Mirin, 10 ml rượu Sake, 8 g đường cát trắng và 1,5 g muối ăn. Khuấy tan gia vị rồi đun trên lửa vừa khoảng 3 phút cho đến khi nước om sôi lăn tăn.', NULL, 3),
('imp-d6e35b3fa19080de_v4_step_3', 'imp-d6e35b3fa19080de', 3, 'cook', 'Om chín mềm nấm đùi gà trong nước dùng', 'Thả toàn bộ nấm đùi gà thái lát vào nồi nước om đang sôi, dàn đều và nấu trên lửa vừa khoảng 3 phút cho nấm chín mềm, giữ độ giòn nhẹ và tiết vị ngọt vào nước dùng.', NULL, 3),
('imp-d6e35b3fa19080de_v4_step_4', 'imp-d6e35b3fa19080de', 4, 'cook', 'Rưới trứng gà đánh tan và rắc hành lá', 'Hạ nhỏ lửa xuống mức thấp để nước chỉ lăn tăn nhẹ. Rưới từ từ tô trứng gà đánh tan theo vòng xoắn ốc phủ đều lên khắp mặt nấm, sau đó rắc đều phần hành lá thái khoanh lên trên.', 'Rưới trứng thành dòng mảnh theo vòng tròn từ ngoài vào trong giúp trứng chín đều thành mảng mềm mịn ôm lấy từng lát nấm.', NULL),
('imp-d6e35b3fa19080de_v4_step_5', 'imp-d6e35b3fa19080de', 5, 'cook', 'Đậy nắp om chín tới cho trứng mềm mượt', 'Đậy nắp nồi và om trên lửa nhỏ khoảng 2 phút cho đến khi phần lòng trắng chín đông hoàn toàn và trứng đạt độ mềm ẩm mượt mà thì tắt bếp ngay, tránh nấu quá lâu làm trứng khô cứng.', 'Tắt bếp ngay khi trứng vừa se mặt vì lượng nhiệt dư trong nồi sẽ tiếp tục làm trứng chín mịn hoàn hảo.', 2),
('imp-d6e35b3fa19080de_v4_step_6', 'imp-d6e35b3fa19080de', 6, 'finish', 'Múc ra tô và rắc tiêu thưởng thức nóng', 'Nhẹ nhàng xắn chia trứng om nấm ra 3 tô cùng nước dùng trong nồi, rắc thêm chút tiêu đen xay nếu thích và dùng nóng ngay với cơm trắng hoặc mì.', NULL, NULL),
('imp-cc88c6bd94df496e_v4_step_1', 'imp-cc88c6bd94df496e', 1, 'prep', 'Sơ chế thịt cua, nấm đùi gà và hành lá', 'Kiểm tra và nhặt sạch vụn vỏ nếu có trong 200 g thịt cua hấp chín gỡ sẵn, tách nhẹ thành thớ vừa ăn. Lau sạch 150 g nấm đùi gà tươi, bỏ gốc rồi thái lát mỏng dài 3 cm; rửa sạch hành lá tươi và thái khoanh mỏng.', NULL, NULL),
('imp-cc88c6bd94df496e_v4_step_2', 'imp-cc88c6bd94df496e', 2, 'cook', 'Đun sôi nhẹ nước dùng Dashi', 'Đổ 450 ml nước lọc và 150 ml nước dùng Dashi vào nồi, đun trên lửa vừa đến khi nước dùng sôi lăn tăn nhẹ nhàng.', 'Không đun sôi bùng quá mạnh để giữ hương thơm tinh tế của Dashi và giúp nước canh trong vắt.', NULL),
('imp-cc88c6bd94df496e_v4_step_3', 'imp-cc88c6bd94df496e', 3, 'cook', 'Nấu chín mềm nấm đùi gà', 'Thả toàn bộ nấm đùi gà thái lát vào nồi nước dùng, hạ lửa vừa nhỏ và nấu khoảng 3 phút cho đến khi nấm chín mềm và tiết vị ngọt tự nhiên.', NULL, 3),
('imp-cc88c6bd94df496e_v4_step_4', 'imp-cc88c6bd94df496e', 4, 'sauce', 'Nêm Sake, xì dầu nhạt và muối thanh nhẹ', 'Thêm 15 ml rượu Sake Nhật Bản, 10 ml xì dầu nhạt Nhật Bản và 2,5 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều rồi nếm thử để điều chỉnh độ mặn thanh hài hòa.', 'Canh trong kiểu Nhật đề cao vị thanh dịu tự nhiên nên chỉ nêm xì dầu nhạt vừa đủ dậy hương, tránh làm sẫm màu nước canh.', NULL),
('imp-cc88c6bd94df496e_v4_step_5', 'imp-cc88c6bd94df496e', 5, 'cook', 'Thả thịt cua làm nóng nhanh và hớt bọt', 'Nhẹ nhàng cho 200 g thịt cua vào nồi canh, đun lửa nhỏ khoảng 2 phút cho nước vừa sôi lăn tăn trở lại và thịt cua nóng đều tận lõi; dùng muôi hớt sạch bọt mỏng nổi trên mặt nếu có.', 'Thịt cua đã hấp chín sẵn nên chỉ nấu nhanh 2 phút để làm nóng và quyện vị, tránh đun lâu làm thịt cua bị bở xác.', 2),
('imp-cc88c6bd94df496e_v4_step_6', 'imp-cc88c6bd94df496e', 6, 'finish', 'Tắt bếp, rắc hành lá và dọn nóng', 'Tắt bếp ngay, múc canh cua nấm ra 3 bát, chia đều thịt cua và nấm đùi gà rồi rắc hành lá thái nhỏ lên mặt để giữ màu xanh tươi và thưởng thức nóng.', NULL, NULL),
('imp-df7a6429150724b1_v4_step_1', 'imp-df7a6429150724b1', 1, 'prep', 'Sơ chế tôm tươi, cà chua và hành tỏi', 'Rửa sạch 300 g tôm tươi đã bóc vỏ, rút chỉ đen, thấm thật khô bằng khăn giấy. Cà chua chín bỏ cuống, cắt miếng nhỏ vừa ăn; hành tây bóc vỏ thái lát mỏng; tỏi tươi băm nhuyễn và hành lá thái khoanh mỏng.', NULL, NULL),
('imp-df7a6429150724b1_v4_step_2', 'imp-df7a6429150724b1', 2, 'cook', 'Phi tỏi và áp chảo sơ tôm cho săn ngọt', 'Đun nóng 15 ml dầu ô liu trong chảo sâu lòng trên lửa vừa, cho tỏi băm vào phi khoảng 20 giây đến khi thơm nhẹ rồi trút tôm vào đảo nhanh tay với 1 g muối ăn trong khoảng 2 phút đến khi tôm vừa chuyển màu hồng thì gắp ngay ra đĩa riêng.', 'Xào sơ tôm rồi lấy ra trước khi om cà chua giúp tôm giữ độ giòn ngọt, không bị dai hay teo nhỏ do om lâu.', 2),
('imp-df7a6429150724b1_v4_step_3', 'imp-df7a6429150724b1', 3, 'cook', 'Xào hành tây mềm ngọt', 'Vẫn dùng chảo đó trên lửa vừa, cho toàn bộ hành tây thái lát vào đảo đều khoảng 3 phút đến khi hành tây chuyển trong và tỏa mùi thơm ngọt tự nhiên.', NULL, 3),
('imp-df7a6429150724b1_v4_step_4', 'imp-df7a6429150724b1', 4, 'sauce', 'Om cà chua với xì dầu, tương cà và Sake', 'Cho cà chua cắt miếng vào chảo cùng 18 ml xì dầu Nhật Bản, 15 ml tương cà Ketchup, 22 ml rượu Sake Nhật Bản, 5 g đường cát trắng, 1 g muối ăn còn lại và 100 ml nước lọc. Đảo đều, đun sôi rồi hạ lửa nhỏ, đậy nắp om khoảng 6 phút cho cà chua nhừ ra sốt đỏ sánh.', 'Nếm thử sốt cà chua ở bước này; tùy độ chua ngọt của cà chua mà có thể gia giảm thêm một chút đường cho hài hòa.', 6),
('imp-df7a6429150724b1_v4_step_5', 'imp-df7a6429150724b1', 5, 'cook', 'Thả tôm vào om thấm sốt cà chua', 'Mở nắp, trút toàn bộ tôm đã áp chảo trở lại chảo sốt, đảo nhẹ cho sốt phủ đều và om trên lửa vừa thêm 2–3 phút đến khi tôm cong tròn, thịt chín đục hoàn toàn và nước sốt sánh quyện.', 'Quan sát thân tôm vừa cuộn tròn hình chữ C và chuyển màu đỏ hồng đồng nhất là đạt, không om quá lâu để tránh tôm bị khô xác.', 3),
('imp-df7a6429150724b1_v4_step_6', 'imp-df7a6429150724b1', 6, 'finish', 'Rắc tiêu, hành lá và dọn ăn nóng', 'Tắt bếp, rắc 1 g tiêu đen xay cùng hành lá thái khoanh lên trên, đảo nhẹ một vòng rồi múc ra đĩa sâu lòng dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-9157234945e6ff01_v4_step_1', 'imp-9157234945e6ff01', 1, 'prep', 'Ngâm miến khoai lang và sơ chế gà, rau củ', 'Ngâm 100 g miến khoai lang Hàn Quốc trong nước lạnh ít nhất 35 phút cho mềm. Trộn 800 g đùi gà chặt miếng với 2 g muối ăn và 1 g tiêu đen xay để nghỉ 15 phút. Thái miếng khoai tây dày 1,5 cm, thái vát cà rốt và nấm đùi gà, bổ múi cau hành tây, thái lát dưa leo, cắt khúc ớt tươi và thái sợi hành lá ngâm nước lạnh.', 'Ngâm đủ thời gian giúp sợi miến khoai lang hút nước từ từ, khi cho vào chảo hầm sẽ chín trong và dai ngon mà không hút cạn hết nước sốt.', 35),
('imp-9157234945e6ff01_v4_step_2', 'imp-9157234945e6ff01', 2, 'sauce', 'Pha hỗn hợp sốt tương đen Andong', 'Trong tô vừa, khuấy tan đều 60 ml nước tương Hàn Quốc, 30 ml dầu hào, 50 ml siro ngô, 15 g tương đen Hàn Quốc (Chunjang), tỏi băm nhuyễn và gừng băm nhuyễn đến khi sốt mịn đồng nhất.', 'Một lượng nhỏ tương đen Chunjang tạo màu nâu sẫm bóng đẹp và vị mặn ngọt dịu đặc trưng mà không cần dùng nhiều đường thắng.', NULL),
('imp-9157234945e6ff01_v4_step_3', 'imp-9157234945e6ff01', 3, 'cook', 'Áp chảo săn vàng hai mặt đùi gà', 'Đun nóng chảo sâu lòng trên lửa vừa-cao với 30 ml dầu ăn thực vật, xếp đùi gà vào áp chảo 3 phút mỗi mặt cho lớp da và thịt se săn vàng nhẹ, giúp thịt gà chắc thơm và không bị bở khi hầm.', NULL, 6),
('imp-9157234945e6ff01_v4_step_4', 'imp-9157234945e6ff01', 4, 'cook', 'Hầm gà cùng khoai tây và hành tây', 'Đổ hỗn hợp sốt đã pha cùng 500 ml nước lọc, khoai tây và hành tây vào chảo gà. Đảo đều cho sốt hòa tan, đậy nắp và nấu lửa vừa-cao trong 12 phút đến khi khoai tây gần chín bở và thịt gà chín mềm từ bên trong.', NULL, 12),
('imp-9157234945e6ff01_v4_step_5', 'imp-9157234945e6ff01', 5, 'cook', 'Cho miến, nấm, cà rốt và ớt vào om thấm sốt', 'Vớt miến khoai lang ra để ráo rồi thả vào chảo cùng cà rốt, nấm đùi gà và ớt tươi. Đảo đều bằng đũa gỗ trên lửa vừa trong 5 phút đến khi sợi miến chuyển trong suốt, dẻo dai, rau củ chín tới và nước sốt còn sệt vừa phải.', 'Nếu nước sốt cạn nhanh trước khi miến trong, châm thêm 50–80 ml nước lọc nóng và hạ nhỏ lửa.', 5),
('imp-9157234945e6ff01_v4_step_6', 'imp-9157234945e6ff01', 6, 'finish', 'Trộn dưa leo, rưới dầu mè và bày biện', 'Tắt bếp ngay, thả dưa leo thái lát, 1 g tiêu đen xay còn lại và 10 ml dầu mè rang vào đảo nhanh một lượt cho dưa leo giữ độ giòn mát. Vớt hành lá thái sợi ra để ráo đặt lên giữa mặt chảo, rắc hạt mè trắng rang rồi dọn nóng.', NULL, NULL),
('imp-aedcf1c5c1d05d04_v4_step_1', 'imp-aedcf1c5c1d05d04', 1, 'prep', 'Làm sạch và ướp sơ tôm tươi', 'Tôm tươi bóc vỏ, rút sạch chỉ đen dọc lưng, rửa qua nước muối loãng rồi dùng khăn giấy thấm thật ráo. Ướp tôm với 1 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thịt tôm săn chắc. Thái lát mỏng hành tây, cắt khúc hành lá (tách riêng đầu trắng và lá xanh), băm nhỏ tỏi.', 'Thấm thật ráo nước giúp tôm xào săn giòn và bắt sốt nhanh mà không bị tiết nước đọng đáy chảo.', 10),
('imp-aedcf1c5c1d05d04_v4_step_2', 'imp-aedcf1c5c1d05d04', 2, 'sauce', 'Hòa sẵn hỗn hợp sốt tương Mirin', 'Trong chén nhỏ, khuấy tan 25 ml nước tương, 15 ml rượu ngọt Mirin Nhật và 6 g đường cát trắng để khi xào tôm chỉ việc rưới ngay vào chảo.', NULL, NULL),
('imp-aedcf1c5c1d05d04_v4_step_3', 'imp-aedcf1c5c1d05d04', 3, 'cook', 'Phi thơm tỏi cùng bơ và dầu ăn', 'Làm nóng chảo trên lửa vừa với 15 ml dầu ăn thực vật và 12 g bơ lạt. Khi bơ vừa tan sủi bọt, cho tỏi băm vào phi khoảng 30 giây đến khi dậy mùi thơm dịu mà tỏi chưa bị cháy vàng sậm.', 'Kết hợp dầu ăn cùng bơ giúp nâng điểm bốc khói, giữ bơ thơm béo mà không bị cháy khét.', NULL),
('imp-aedcf1c5c1d05d04_v4_step_4', 'imp-aedcf1c5c1d05d04', 4, 'cook', 'Xào lửa lớn cho tôm cong hồng chín săn', 'Tăng lên lửa lớn, trút toàn bộ tôm đã ướp vào chảo xào nhanh tay khoảng 2–3 phút đến khi thân tôm uốn cong, chuyển màu đỏ hồng đục đều và chín hoàn toàn.', 'Xào tôm nhanh trên lửa lớn giúp thịt tôm săn giòn giữ được vị ngọt, không đảo quá 3 phút kẻo tôm bị khô xác.', 3),
('imp-aedcf1c5c1d05d04_v4_step_5', 'imp-aedcf1c5c1d05d04', 5, 'cook', 'Rưới sốt tương và xào cùng hành tây, đầu hành', 'Rưới hỗn hợp sốt tương Mirin vào chảo, thêm hành tây thái lát và phần đầu trắng hành lá, đảo đều trên lửa lớn thêm 2 phút cho hành vừa chín tới giòn ngọt và nước sốt rút sánh quyện quanh từng con tôm.', NULL, 2),
('imp-aedcf1c5c1d05d04_v4_step_6', 'imp-aedcf1c5c1d05d04', 6, 'finish', 'Thả lá hành, rưới dầu mè và rắc mè rang', 'Cho phần lá xanh hành lá vào đảo nhanh một lượt rồi tắt bếp, rưới 5 ml dầu mè rang lên trên. Trút tôm ra đĩa, xoa nhẹ hạt mè trắng rang rắc đều lên mặt và dùng nóng với cơm trắng.', NULL, NULL),
('imp-e39a1be406f9e1ea_v4_step_1', 'imp-e39a1be406f9e1ea', 1, 'prep', 'Pha gia vị ướp hành lá và đánh tan trứng', 'Thái nhỏ hành lá. Trộn 2/3 lượng hành lá với 10 ml nước mắm ngon, 5 ml nước tương, 3 g đường cát trắng, 4 ml dầu mè rang và 0,5 g tiêu đen xay trong chén nhỏ, để nghỉ 2 phút cho thấm. Đập 5 quả trứng gà vào tô lớn đánh thật tan, rồi đổ 220 ml nước lọc cùng chén hành lá gia vị vào khuấy đều.', 'Tỉ lệ nước gần tương đương thể tích trứng giúp kết cấu trứng hấp mềm ẩm và nở phồng xốp đẹp mắt.', NULL),
('imp-e39a1be406f9e1ea_v4_step_2', 'imp-e39a1be406f9e1ea', 2, 'cook', 'Nấu trứng giai đoạn đầu trong nồi đất đậy nắp', 'Đổ hỗn hợp trứng vào nồi đất Hàn Quốc hoặc nồi inox đáy dày cỡ nhỏ (nên dùng nồi sâu lòng sao cho trứng chiếm khoảng 2/3 chiều cao nồi). Đậy nắp kín, nấu trên lửa vừa khoảng 7 phút.', 'Không đổ trứng quá đầy miệng nồi để chừa không gian cho trứng nở phồng lên khi gặp hơi nóng.', 7),
('imp-e39a1be406f9e1ea_v4_step_3', 'imp-e39a1be406f9e1ea', 3, 'cook', 'Khuấy nhẹ giữa chừng giúp trứng chín xốp đều', 'Mở nắp nồi: lúc này phần rìa và đáy trứng đã bắt đầu đông đặc còn phần giữa vẫn sánh loãng. Dùng thìa khuấy nhẹ nhàng từ đáy lên trên trong vài giây cho hỗn hợp hòa đều và không bị cháy đáy, sau đó đậy nắp lại ngay.', 'Bước khuấy nhẹ giữa chừng giúp nhiệt phân bổ đều khắp khối trứng, tạo độ bông xốp tơi nhẹ chứ không bị chai cứng đáy.', NULL),
('imp-e39a1be406f9e1ea_v4_step_4', 'imp-e39a1be406f9e1ea', 4, 'cook', 'Hạ lửa nhỏ ủ cho trứng phồng xốp hoàn toàn', 'Hạ xuống lửa nhỏ, tiếp tục nấu kín nắp thêm 4 phút đến khi khối trứng nở phồng cao lên sát nắp, mặt trứng se mịn và chín hẳn ở tâm.', NULL, 4),
('imp-e39a1be406f9e1ea_v4_step_5', 'imp-e39a1be406f9e1ea', 5, 'cook', 'Ủ thêm hơi nóng trong 1 phút tạo mùi thơm đáy nồi', 'Giữ nguyên nắp đậy và hạ lửa thật nhỏ thêm 1 phút để phần đáy có lớp xém vàng thơm nhẹ (không để quá lâu kẻo khét đắng) rồi tắt bếp.', NULL, 1),
('imp-e39a1be406f9e1ea_v4_step_6', 'imp-e39a1be406f9e1ea', 6, 'finish', 'Rắc hành lá, tiêu, ớt bột và dầu mè dọn nóng', 'Mở nắp nồi, nhanh tay rắc phần hành lá còn lại, 0,5 g tiêu đen xay, 2 g ớt bột Hàn Quốc, hạt mè trắng rang và rưới nốt 4 ml dầu mè rang lên mặt trứng đang phồng xốp rồi thưởng thức ngay.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_1', 'imp-da5a134e2654eeb5', 1, 'prep', 'Sơ chế và ướp ngấm kim chi với gia vị', 'Cắt 280 g kim chi cải thảo thành miếng vừa ăn, thái mỏng hành tây, cắt khúc hành lá (chừa ít lá xanh để rắc mặt), băm nhuyễn tỏi và gừng. Cho kim chi, hành tây, phần lớn hành lá, tỏi băm, gừng băm, 30 g tương ớt Hàn Quốc, 15 ml nước tương, 12 g đường cát trắng, 10 ml dầu mè rang và 1 g tiêu đen xay vào tô trộn đều, để 10 phút cho thấm vị.', 'Ướp kim chi trước với đường và gia vị giúp giảm vị chua gắt và khiến kim chi thấm đều hương vị khi lên chảo.', 10),
('imp-da5a134e2654eeb5_v4_step_2', 'imp-da5a134e2654eeb5', 2, 'cook', 'Luộc làm mềm đậu phụ trắng', 'Đun sôi 800 ml nước lọc trong nồi trên lửa lớn, hạ về lửa vừa rồi thả nhẹ 4 miếng đậu phụ trắng vào luộc khoảng 5 phút cho đậu nóng đều từ trong ra ngoài và có kết cấu mềm mịn.', 'Luộc đậu ở mức sôi lăn tăn lửa vừa giúp miếng đậu nóng mềm đồng đều mà không bị rỗ mặt hoặc vỡ cạnh.', 5),
('imp-da5a134e2654eeb5_v4_step_3', 'imp-da5a134e2654eeb5', 3, 'prep', 'Vớt đậu phụ để ráo và thái lát', 'Dùng vá lỗ nhẹ nhàng vớt đậu phụ ra rổ cho ráo hơi nước trong 2 phút, sau đó đặt lên thớt thái từng miếng thành lát dày khoảng 1,2 cm thật nhẹ tay để không làm vỡ mép đậu.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_4', 'imp-da5a134e2654eeb5', 4, 'cook', 'Xào săn kim chi cho dậy mùi cay thơm', 'Làm nóng chảo trên lửa vừa-cao với 10 ml dầu ăn thực vật, đổ toàn bộ tô kim chi đã ướp vào xào đều tay trong 5 phút đến khi lá kim chi mềm dịu, hành tây trong lại và phần nước tiết ra bay hơi sệt bóng.', 'Xào đến khi nước kim chi rút sệt lại để khi xếp lên đĩa không bị chảy nước làm nhão phần đậu phụ.', 5),
('imp-da5a134e2654eeb5_v4_step_5', 'imp-da5a134e2654eeb5', 5, 'cook', 'Điều chỉnh gia vị và rưới dầu mè', 'Nếm thử phần kim chi xào (nếu quá chua có thể thêm chút đường, thích đậm hơn thêm chút nước tương), tắt bếp và rưới nốt 5 ml dầu mè rang còn lại vào đảo đều.', NULL, NULL),
('imp-da5a134e2654eeb5_v4_step_6', 'imp-da5a134e2654eeb5', 6, 'finish', 'Bày đĩa đậu phụ kẹp kim chi xào', 'Xếp các lát đậu phụ trắng luộc ấm thành vòng tròn quanh mép đĩa, múc phần kim chi xào nóng vào chính giữa (hoặc rắc đều lên mặt đậu), rắc hành lá xanh thái nhỏ và hạt mè trắng rang lên trên rồi thưởng thức.', NULL, NULL),
('imp-8cd9bb1abdd63a9e_v4_step_1', 'imp-8cd9bb1abdd63a9e', 1, 'cook', 'Hầm nước dùng bò trong và luộc mềm thịt nạm', 'Lau sạch máu trên 225 g thịt nạm bò bằng khăn sạch rồi cho vào nồi cùng 1100 ml nước lọc. Đun lửa lớn cho sôi và hớt thật sạch bọt, sau đó hạ lửa nhỏ hầm trong 35 phút. Thêm hành lá và tỏi đập dập vào hầm tiếp 15 phút cho nước dùng ngọt thơm rồi vớt thịt bò ra để nguội, lọc bỏ xác hành tỏi.', 'Hớt sạch bọt và lọc qua rây mịn giúp nước dùng naengmyeon thật trong, không bị váng đục khi làm lạnh.', 50),
('imp-8cd9bb1abdd63a9e_v4_step_2', 'imp-8cd9bb1abdd63a9e', 2, 'sauce', 'Pha nước dùng chua ngọt và làm lạnh dăm đá', 'Để nước dùng bò nguội hẳn rồi hớt sạch lớp mỡ nổi trên mặt. Hòa tan 15 ml nước tương, 30 ml giấm gạo trắng, 20 g đường cát trắng, 6 g muối ăn và 5 g mù tạt vàng vào nước dùng, nêm lại vị chua ngọt dịu vừa miệng rồi cho vào ngăn đá 2–3 giờ đến khi mặt nước bắt đầu đóng lớp dăm đá mỏng.', 'Vị nước dùng khi nguội lạnh sẽ nhạt hơn lúc còn ấm một chút, vì vậy có thể pha đậm nhẹ trước khi cho vào ngăn đá.', NULL),
('imp-8cd9bb1abdd63a9e_v4_step_3', 'imp-8cd9bb1abdd63a9e', 3, 'prep', 'Muối nhanh củ cải, dưa leo và luộc trứng', 'Thái lát mỏng củ cải trắng, trộn đều với 15 ml giấm gạo, 10 g đường cát trắng, 1,5 g muối ăn và 2 g ớt bột Hàn Quốc, ướp 20 phút. Thái chéo mỏng dưa leo, ướp 1,5 g muối ăn trong 15 phút rồi vắt nhẹ cho ráo giòn. Luộc 2 quả trứng gà với 3 g muối ăn trong 10 phút, ngâm nước lạnh rồi bóc vỏ bổ đôi. Thái lát mỏng thịt bò luộc nguội.', NULL, 20),
('imp-8cd9bb1abdd63a9e_v4_step_4', 'imp-8cd9bb1abdd63a9e', 4, 'cook', 'Luộc chín mì kiều mạch và xả nước đá thật dai', 'Đun sôi nồi nước lớn (khoảng 900 ml trở lên), thả 300 g mì kiều mạch vào đảo nhẹ cho tơi sợi và luộc khoảng 3 phút đến khi lõi mì vừa chín tới nhưng vẫn giữ độ dai. Lập tức vớt mì ra xả mạnh dưới vòi nước lạnh, dùng tay vò nhẹ cho sạch hết nhớt tinh bột rồi ngâm nhanh trong thau nước đá và vắt ráo.', 'Xả thật sạch lớp nhớt ngoài sợi mì rồi chần nước đá là bí quyết giúp sợi naengmyeon dai sần sật và giữ nước dùng trong veo.', 3),
('imp-8cd9bb1abdd63a9e_v4_step_5', 'imp-8cd9bb1abdd63a9e', 5, 'finish', 'Xếp mì, chan nước dùng dăm đá và bày topping', 'Cuộn mì thành từng vắt gọn đặt vào 3 tô sâu lòng. Khuấy đều phần nước dùng dăm đá rồi chan nhẹ men theo thành tô. Xếp thịt bò thái lát, củ cải trộn chua ngọt, dưa leo giòn và nửa quả trứng luộc lên mặt, rắc hạt mè trắng rang và ớt sừng đỏ thái sợi rồi thưởng thức ngay.', NULL, NULL),
('imp-8cd9bb1abdd63a9e_v4_step_6', 'imp-8cd9bb1abdd63a9e', 6, 'finish', 'Thưởng thức và gia giảm thêm tại bàn', 'Dọn mì lạnh kèm giấm gạo trắng và mù tạt vàng ở bên cạnh để từng người tự gia giảm thêm độ chua cay theo khẩu vị, dùng đũa và kéo cắt ngắn sợi mì nếu cần trước khi ăn.', NULL, NULL),
('imp-a631650d667191b4_v4_step_1', 'imp-a631650d667191b4', 1, 'prep', 'Chà muối làm sạch nhớt và khứa caro thân mực', 'Tách bỏ nội tạng, mắt, mỏ cứng và thanh mai trong thân 500 g mực tươi. Dùng 15 g muối hạt chà xát kỹ thân và các giác hút râu mực cho hết nhớt rồi xả sạch nhiều lần dưới vòi nước lạnh và thấm khô. Kê hai chiếc đũa hai bên thân mực để khứa caro nông mặt trong mà không cắt thủng.', 'Chà muối hạt giúp làm sạch cát bám trên râu mực rất hiệu quả và giúp bóc màng da mực dễ dàng hơn.', NULL),
('imp-a631650d667191b4_v4_step_2', 'imp-a631650d667191b4', 2, 'marinate', 'Pha sốt cay Gochujang và ướp mực 20 phút', 'Khuấy đều 45 g tương ớt Hàn Quốc, 8 g ớt bột Hàn Quốc, 30 ml siro ngô, 15 ml nước tương, 8 g đường cát trắng, 15 ml rượu ngọt Mirin Nhật, tỏi băm, gừng băm, 5 g mù tạt vàng, 1 g tiêu đen xay, 5 ml dầu mè rang và 1/2 lượng hành lá thái nhỏ. Trộn mực thấm đều sốt và ướp trong ngăn mát 20 phút.', 'Chỉ nên ướp mực khoảng 20–30 phút để mực thấm vị bên ngoài mà giữ nguyên độ giòn sần sật, tránh ướp qua đêm làm thịt mực bị bở.', 20),
('imp-a631650d667191b4_v4_step_3', 'imp-a631650d667191b4', 3, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang trên lửa lớn', 'Đun thật nóng chảo gang hoặc vỉ nướng than trên lửa lớn, phết đều 5 ml dầu ăn thực vật lên bề mặt để mực không bị dính sát khi gặp sốt đường.', 'Làm nóng chảo thật kỹ trước khi đặt mực lên giúp bề mặt mực săn nhanh ngay lập tức, giữ trọn vị ngọt và không bị ra nước.', NULL),
('imp-a631650d667191b4_v4_step_4', 'imp-a631650d667191b4', 4, 'cook', 'Nướng xém mặt đầu thân và râu mực', 'Đặt thân và râu mực lên mặt chảo hoặc vỉ nóng (để mặt khía caro ngửa lên trên), nướng yên trong 2 phút trên lửa lớn đến khi mặt dưới săn đục và bắt đầu xém vàng nhẹ.', NULL, 2),
('imp-a631650d667191b4_v4_step_5', 'imp-a631650d667191b4', 5, 'cook', 'Lật mặt và phết sốt cay nướng bóng đều', 'Lật mặt mực, dùng cọ phết thêm phần sốt ướp còn lại và nướng tiếp 2 phút; lật lại một lần nữa phết nốt sốt và nướng thêm 1 phút đến khi mực chín săn hoàn toàn, sốt keo đỏ bóng xém cạnh thơm lừng.', 'Tổng thời gian nướng chỉ khoảng 4–5 phút trên lửa lớn để mực chín giòn ngọt; nướng quá lâu mực sẽ dai và mất nước.', 3),
('imp-a631650d667191b4_v4_step_6', 'imp-a631650d667191b4', 6, 'finish', 'Bày đĩa cùng lá tía tô và cắt khoanh nóng hổi', 'Lót lá tía tô thái sợi ra đĩa, đặt mực nướng nóng lên trên. Rắc nốt 1/2 lượng hành lá thái nhỏ và hạt mè trắng rang, rưới 5 ml dầu mè rang còn lại, vắt nước cốt từ 1/2 quả chanh vàng tươi rồi dùng kéo cắt mực thành từng khoanh vừa ăn.', NULL, NULL),
('imp-2a958e709ba9cb7c_v4_step_1', 'imp-2a958e709ba9cb7c', 1, 'prep', 'Thấm khô đậu phụ và pha sốt xào kim chi', 'Thấm thật khô 3 miếng đậu phụ chắc rồi cắt lát dày khoảng 1,5 cm. Cắt khúc 280 g kim chi cải thảo, thái miếng hành tây, cắt khúc hành lá, thái lát xéo ớt sừng đỏ và băm nhỏ tỏi. Trộn đều 25 g tương ớt Hàn Quốc, 6 g ớt bột Hàn Quốc, 15 ml nước tương, 12 g đường cát trắng, 1 g tiêu đen xay và 30 ml nước lọc trong chén.', NULL, NULL),
('imp-2a958e709ba9cb7c_v4_step_2', 'imp-2a958e709ba9cb7c', 2, 'cook', 'Áp chảo vàng giòn hai mặt đậu phụ', 'Làm nóng chảo chống dính trên lửa vừa-cao với 15 ml dầu ăn thực vật, xếp đậu phụ vào áp chảo khoảng 3–4 phút mỗi mặt đến khi hai mặt vàng ruộm giòn cạnh rồi gắp riêng ra đĩa.', 'Chiên vàng đậu phụ trước rồi tận dụng luôn chảo đó để xào kim chi giúp tiết kiệm thời gian mà đậu vẫn giữ được độ giòn mặt ngoài.', 7),
('imp-2a958e709ba9cb7c_v4_step_3', 'imp-2a958e709ba9cb7c', 3, 'cook', 'Phi thơm hành tây và tỏi băm', 'Thêm 5 ml dầu ăn thực vật còn lại vào cùng chảo, cho hành tây và tỏi băm vào đảo đều 1 phút trên lửa vừa đến khi tỏi dậy mùi thơm và hành hơi trong lại.', NULL, 1),
('imp-2a958e709ba9cb7c_v4_step_4', 'imp-2a958e709ba9cb7c', 4, 'cook', 'Xào mềm kim chi cùng hỗn hợp sốt cay', 'Trút kim chi cải thảo vào chảo xào 4 phút trên lửa vừa cho lá kim chi mềm săn lại, sau đó đổ chén sốt tương ớt đã pha vào đảo đều thêm 2 phút cho sốt thấm quyện đỏ bóng.', 'Xào kỹ kim chi trước khi đổ chén sốt giúp dịu độ chua gắt và giải phóng vị ngọt tự nhiên của cải thảo lên men.', 6),
('imp-2a958e709ba9cb7c_v4_step_5', 'imp-2a958e709ba9cb7c', 5, 'cook', 'Thêm ớt sừng, hành lá và rưới dầu mè', 'Thả ớt sừng đỏ thái lát và phần lớn hành lá cắt khúc vào chảo kim chi xào thêm 1 phút cho hành vừa chín tới rồi tắt bếp. Rưới 8 ml dầu mè rang lên trên và đảo nhẹ một lượt.', 'Tắt bếp rồi mới rưới dầu mè rang giúp giữ trọn hương thơm bùi béo mà không bị bay mùi ở nhiệt độ cao.', NULL),
('imp-2a958e709ba9cb7c_v4_step_6', 'imp-2a958e709ba9cb7c', 6, 'finish', 'Bày đậu phụ cạnh kim chi xào nóng', 'Xếp các lát đậu phụ áp chảo vàng giòn ra một bên đĩa, múc phần kim chi xào cay nóng cạnh bên, rắc phần hành lá thái nhỏ còn lại và hạt mè trắng rang lên trên rồi dùng nóng.', NULL, NULL),
('imp-1f3a7df71f4cbc77_v4_step_1', 'imp-1f3a7df71f4cbc77', 1, 'prep', 'Ngâm sạch vụn xương và máu thừa trên sườn bò', 'Cắt bỏ phần mỡ thừa ở viền 1200 g sườn bò cắt ngang kiểu LA, ngâm sườn trong thau nước lạnh khoảng 15 phút cho ra bớt máu thừa, sau đó tráng sạch nhiều lần dưới vòi nước lạnh để loại bỏ hoàn toàn vụn xương nhỏ rồi để thật ráo.', 'Rửa kỹ từng dẻ sườn cắt ngang giúp loại bỏ vụn xương li ti từ máy cưa thịt và giúp món nướng không bị hôi.', 15),
('imp-1f3a7df71f4cbc77_v4_step_2', 'imp-1f3a7df71f4cbc77', 2, 'marinate', 'Xay nhuyễn gia vị thơm và pha sốt ướp Galbi', 'Xay thật nhuyễn mịn hành tây, 6 tép tỏi, gừng tươi cùng 120 ml nước lọc thành hỗn hợp sánh mượt. Đổ ra tô lớn, khuấy tan với 100 ml nước tương Hàn Quốc, 40 g đường cát trắng, 25 ml mật ong, 60 ml rượu ngọt Mirin Nhật, 25 ml dầu mè rang, 2/3 lượng hành lá thái nhỏ và 2 g tiêu đen xay.', 'Xay thật mịn hành tây và gừng tỏi giúp nước ướp bám đều vào từng dẻ sườn và không để lại xác hành bị cháy đen trên vỉ nướng.', NULL),
('imp-1f3a7df71f4cbc77_v4_step_3', 'imp-1f3a7df71f4cbc77', 3, 'marinate', 'Ướp sườn thấm đều trong ngăn mát', 'Xếp sườn bò vào hộp kín hoặc túi lớn, đổ nước sốt ướp vào bóp nhẹ cho từng miếng sườn phủ đều sốt. Bọc kín, cho vào ngăn mát ướp tối thiểu 4 giờ (ướp qua đêm sẽ mềm ngọt và đậm vị nhất), giữa chừng trở mặt sườn một lần.', NULL, 240),
('imp-1f3a7df71f4cbc77_v4_step_4', 'imp-1f3a7df71f4cbc77', 4, 'sauce', 'Pha sốt chấm Ssamjang và rửa sạch rau cuốn', 'Trong chén nhỏ, trộn đều 30 g tương đậu tương Hàn Quốc (Doenjang), 18 g tương ớt Hàn Quốc (Gochujang), 1–2 tép tỏi băm còn lại, 1/3 lượng hành lá thái nhỏ, 5 ml mật ong, 5 ml dầu mè rang và một nửa lượng hạt mè trắng rang. Rửa sạch rau xà lách và lá tía tô rồi vẩy thật ráo.', NULL, NULL),
('imp-1f3a7df71f4cbc77_v4_step_5', 'imp-1f3a7df71f4cbc77', 5, 'cook', 'Nướng sườn xém vàng cạnh trên lửa vừa-cao', 'Làm nóng vỉ nướng than hoa hoặc chảo gang ở lửa vừa-cao, xếp từng dẻ sườn đã ráo nước ướp lên nướng khoảng 2–3 phút mỗi mặt. Vì sườn cắt mỏng nên thịt chín rất nhanh; canh trở đều tay đến khi hai mặt xém vàng nâu óng đẹp và thịt săn chín hoàn toàn thì gắp ra.', 'Sốt ướp chứa nhiều đường và mật ong nên dễ cháy xém; hãy trở mặt đều và giữ lửa vừa-cao thay vì lửa quá lớn.', 6),
('imp-1f3a7df71f4cbc77_v4_step_6', 'imp-1f3a7df71f4cbc77', 6, 'finish', 'Cắt miếng sườn và cuốn rau chấm Ssamjang', 'Dùng kéo bếp cắt thịt sườn tách khỏi phần xương thành miếng vừa ăn, xếp ra đĩa rắc phần hạt mè trắng rang còn lại lên trên; cuốn thịt sườn với lá xà lách, lá tía tô và chấm sốt ssamjang thưởng thức nóng.', NULL, NULL),
('imp-328b6c9769e256eb_v4_step_1', 'imp-328b6c9769e256eb', 1, 'prep', 'Làm sạch chỉ lưng tôm và thấm thật ráo vỏ', 'Dùng kéo cắt gọn râu, chân và phần gai nhọn đầu 500 g tôm tươi nguyên vỏ. Dùng tăm xiên qua đốt lưng thứ 2–3 khều bỏ sạch chỉ đen, rửa nhanh rồi dùng khăn giấy thấm thật khô lớp vỏ ngoài để muối không bám dính gây mặn gắt.', 'Thấm thật khô vỏ tôm là bước rất quan trọng giúp muối hạt chỉ truyền nhiệt khô mà không tan chảy thấm mặn vào thịt tôm.', NULL),
('imp-328b6c9769e256eb_v4_step_2', 'imp-328b6c9769e256eb', 2, 'sauce', 'Pha sốt Gochujang chanh tỏi ớt và chén dầu mè hành', 'Trong chén thứ nhất, khuấy tan 54 g tương ớt Hàn Quốc với nước cốt 1 quả chanh tươi, 10 ml mật ong, tỏi băm nhuyễn, ớt hiểm đỏ băm nhỏ và một nửa hạt mè trắng rang cho đạt vị chua cay ngọt hài hòa. Ở chén nhỏ còn lại, pha 10 ml dầu mè rang với một ít hành lá thái nhỏ để chấm thêm cho béo thơm.', NULL, NULL),
('imp-328b6c9769e256eb_v4_step_3', 'imp-328b6c9769e256eb', 3, 'cook', 'Lót giấy bạc, rải muối hạt to và làm nóng chảo', 'Lót một lớp giấy bạc chịu nhiệt vào lòng chảo đáy dày (chọn chảo cũ hoặc chảo gang), đổ 250 g muối biển hạt to dàn thành lớp phẳng dày đều khắp đáy chảo. Đậy nắp và đun lửa vừa-nhỏ khoảng 5 phút cho lớp muối nóng đều.', 'Bắt buộc dùng muối biển hạt to thay cho muối tinh mịn vì muối mịn sẽ bám chặt vào vỏ khiến thịt tôm bị mặn chát.', 5),
('imp-328b6c9769e256eb_v4_step_4', 'imp-328b6c9769e256eb', 4, 'cook', 'Nướng tôm mặt thứ nhất trên lớp muối nóng', 'Mở nắp, nhanh tay xếp tôm thành một lớp rời nhau lên trên mặt muối đang nóng (không xếp chồng lên nhau). Đậy kín nắp chảo và giữ lửa vừa-nhỏ nướng trong 5 phút cho hơi nóng muối làm chín đều mặt dưới.', NULL, 5),
('imp-328b6c9769e256eb_v4_step_5', 'imp-328b6c9769e256eb', 5, 'cook', 'Trở mặt nướng chín đỏ giòn vỏ tôm', 'Mở nắp, dùng kẹp trở lật toàn bộ tôm sang mặt còn lại, đậy nắp nướng thêm 3 phút đến khi vỏ tôm chuyển đỏ rực, hơi giòn cạnh, thân tôm uốn cong săn chắc và chín hoàn toàn bên trong.', 'Tổng thời gian nướng khoảng 8 phút tùy kích cỡ tôm; thấy thân tôm chuyển đục săn chắc và vỏ đỏ thơm là đạt, không nướng quá lâu làm tôm bị khô bở.', 3),
('imp-328b6c9769e256eb_v4_step_6', 'imp-328b6c9769e256eb', 6, 'finish', 'Gạt sạch muối và thưởng thức nóng cùng hai loại sốt', 'Gắp tôm ra đĩa (gạt nhẹ những hạt muối còn bám trên vỏ), rắc phần hành lá thái nhỏ và hạt mè trắng rang còn lại lên trên rồi dọn ăn nóng ngay cùng bát nước chấm gochujang chanh ớt và chén dầu mè hành.', NULL, NULL),
('imp-5dbb6aa38dae701d_v4_step_1', 'imp-5dbb6aa38dae701d', 1, 'prep', 'Luộc mì ramen vừa chín tới và làm tơi sợi', 'Đun sôi khoảng 1.470 ml nước lọc trong nồi lớn, thả 240 g mì ramen khô vào luộc trong 3 phút đến khi sợi mì vừa tách tơi nhưng vẫn còn độ dai ở lõi (không dùng gói gia vị đi kèm). Vớt mì ra rổ, xả nhanh dưới vòi nước lạnh, xóc thật ráo rồi trộn đều với 5 ml dầu ăn để sợi mì không bết dính.', 'Xả nước lạnh ngay sau khi luộc và áo một lớp dầu mỏng giúp sợi mì săn bóng, khi xào trên lửa lớn không bị nát vụn.', 3),
('imp-5dbb6aa38dae701d_v4_step_2', 'imp-5dbb6aa38dae701d', 2, 'sauce', 'Sơ chế rau củ và pha sẵn hỗn hợp sốt xào', 'Cắt kim chi cải thảo chua thành miếng dài 2–3 cm (giữ lại phần nước kim chi). Băm nhuyễn tỏi khô, thái lát mỏng hành tây và chia hành lá thành 2 phần. Trong chén nhỏ, khuấy tan 15 g tương ớt Hàn Quốc (Gochujang), 25 ml xì dầu, 6 g đường cát trắng cùng 30 ml nước lọc đến khi hỗn hợp sánh mịn.', NULL, NULL),
('imp-5dbb6aa38dae701d_v4_step_3', 'imp-5dbb6aa38dae701d', 3, 'cook', 'Chiên trứng ốp la lòng đào ăn kèm', 'Làm nóng chảo chống dính trên lửa vừa với 5 ml dầu ăn, đập từng quả trong 3 quả trứng gà vào chiên khoảng 2–3 phút đến khi lòng trắng chín đục hoàn toàn và mép dưới hơi giòn, lòng đỏ vẫn dẻo sánh (hoặc chiên chín kỹ tùy khẩu vị). Nhẹ nhàng gắp trứng ra đĩa riêng giữ ấm.', NULL, 3),
('imp-5dbb6aa38dae701d_v4_step_4', 'imp-5dbb6aa38dae701d', 4, 'cook', 'Phi thơm bơ tỏi cùng hành tây và xào kim chi', 'Vẫn dùng chảo lớn trên lửa vừa, cho 10 ml dầu ăn còn lại và 15 g bơ lạt vào đun tan chảy. Cho tỏi băm vào phi thơm 20 giây rồi trút hành tây và 2/3 lượng hành lá vào đảo 2 phút cho hành mềm trong. Tiếp theo, thả kim chi vào xào mạnh tay trên lửa lớn 2 phút đến khi kim chi săn ráo và dậy mùi chua cay thơm nồng.', 'Kết hợp dầu ăn với bơ lạt giúp món ăn có độ béo thơm của bơ mà không bị cháy khét khi xào ở nhiệt độ cao.', 4),
('imp-5dbb6aa38dae701d_v4_step_5', 'imp-5dbb6aa38dae701d', 5, 'cook', 'Xào mì ramen thấm đều sốt cay ngọt', 'Trút toàn bộ mì ramen đã luộc và bát sốt tương ớt Gochujang vào chảo kim chi, tăng lên lửa lớn và đảo đều tay liên tục trong 2 phút để từng sợi mì áo đều màu đỏ cam bóng đẹp và xém cạnh nhẹ.', NULL, 2),
('imp-5dbb6aa38dae701d_v4_step_6', 'imp-5dbb6aa38dae701d', 6, 'finish', 'Rưới dầu mè, bày đĩa cùng trứng và rong biển', 'Tắt bếp ngay rồi rưới 8 ml dầu mè rang và 1/3 lượng hành lá còn lại vào chảo, đảo thêm vài lượt cho dậy mùi thơm. Chia mì ra 3 đĩa, đặt mỗi đĩa một quả trứng ốp la lên trên và rắc rong biển lá khô cắt vụn tùy thích để thưởng thức ngay khi còn nóng.', 'Chỉ rưới dầu mè sau khi đã tắt bếp để giữ trọn hương thơm đặc trưng và tránh làm dầu mè bị đắng do nhiệt cao.', NULL),
('imp-b7f8a716b25a7072_v4_step_1', 'imp-b7f8a716b25a7072', 1, 'marinate', 'Thái lát và ướp thịt bò thấm gia vị', 'Thái thịt bò thăn thành lát mỏng ngang thớ cỡ 3–4 cm để khi nấu không bị dai. Ướp thịt trong tô với 15 ml xì dầu nhạt, 1/2 lượng tỏi băm, 10 ml dầu mè rang và 1 g tiêu đen xay, trộn đều rồi để nghỉ 10 phút trong lúc sơ chế rau.', 'Ướp thịt bò với xì dầu nấu canh và dầu mè trước khi xào là bí quyết tạo nước dùng ngọt đậm nhanh mà không cần ninh xương lâu.', 10),
('imp-b7f8a716b25a7072_v4_step_2', 'imp-b7f8a716b25a7072', 2, 'prep', 'Rửa sạch và cắt khúc cải thảo, hành lá', 'Tách rời từng lá cải thảo, rửa sạch từng bẹ dưới vòi nước rồi để ráo, cắt khúc dài khoảng 4–5 cm (phần cuống trắng dày có thể chẻ dọc làm đôi để chín đều cùng lá). Hành lá rửa sạch, cắt khúc 3–4 cm.', NULL, NULL),
('imp-b7f8a716b25a7072_v4_step_3', 'imp-b7f8a716b25a7072', 3, 'cook', 'Xào săn thịt bò dậy hương dầu mè', 'Đặt nồi đáy dày lên bếp ở lửa lớn, cho toàn bộ thịt bò đã ướp vào xào nhanh tay khoảng 3 phút đến khi các mặt thịt chuyển màu nâu xém nhẹ, săn lại và không còn đỏ hồng.', 'Không cần thêm dầu ăn khi xào vì trong phần ướp thịt đã có đủ dầu mè giúp thịt dậy mùi thơm mà nước canh vẫn thanh nhẹ.', 3),
('imp-b7f8a716b25a7072_v4_step_4', 'imp-b7f8a716b25a7072', 4, 'cook', 'Ninh nước dùng bò và hớt bọt làm trong canh', 'Đổ 1.400 ml nước lọc vào nồi thịt bò, đun sôi mạnh trên lửa lớn rồi dùng muỗng hớt sạch lớp bọt nâu nổi trên mặt. Đậy nắp, hạ xuống lửa vừa và đun liu riu khoảng 10 phút để nước dùng chiết ra vị ngọt thịt.', NULL, 10),
('imp-b7f8a716b25a7072_v4_step_5', 'imp-b7f8a716b25a7072', 5, 'cook', 'Nấu chín mềm cải thảo và nêm nước canh', 'Cho cải thảo cắt khúc vào nồi canh, đun sôi lại rồi hạ lửa vừa, đậy nắp nấu thêm 10 phút cho cọng cải chín mềm trong và tiết vị ngọt tự nhiên. Nêm nốt 15 ml xì dầu nhạt còn lại, 1/2 lượng tỏi băm còn lại, 4 g muối ăn và hành lá vào nồi, khuấy nhẹ và đun thêm 2 phút cho hòa vị.', 'Dùng xì dầu nhạt (xì dầu nấu canh) và muối tinh giúp nước canh giữ được màu vàng trong đẹp mắt thay vì bị sẫm đen.', 10),
('imp-b7f8a716b25a7072_v4_step_6', 'imp-b7f8a716b25a7072', 6, 'finish', 'Hoàn thiện tô canh và dọn nóng', 'Kiểm tra lại độ vừa miệng, rắc 1 g tiêu đen xay còn lại rồi tắt bếp. Múc canh bò cải thảo nóng hổi ra tô, rắc thêm hạt mè trắng rang tùy thích và thưởng thức cùng cơm trắng.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_1', 'imp-7d38862afc164a8d', 1, 'prep', 'Làm sạch mực tươi và cắt khoanh đều tay', 'Rút nhẹ phần đầu mực để loại bỏ túi mực, nội tạng và thanh mai trong suốt ở lưng. Rửa sạch thân và râu mực dưới vòi nước lạnh rồi thấm thật ráo nước. Cắt thân mực thành từng khoanh tròn dày khoảng 1 cm và cắt rời phần râu thành miếng vừa ăn.', 'Thấm thật khô mực sau khi rửa giúp mực không bị tiết quá nhiều nước làm loãng sốt khi xào.', NULL),
('imp-7d38862afc164a8d_v4_step_2', 'imp-7d38862afc164a8d', 2, 'prep', 'Thái rau củ và pha chén sốt xì dầu dầu hào', 'Thái hành tây thành múi cau mỏng, cắt ớt chuông đỏ thành sợi dày 0,8 cm; chia hành lá thành 1/3 phần đầu hành thái nhỏ và 2/3 phần lá cắt khúc 4 cm, tỏi khô băm nhuyễn. Khuấy tan 35 ml xì dầu đặc, 20 ml dầu hào cùng 10 g đường cát trắng trong chén nhỏ.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_3', 'imp-7d38862afc164a8d', 3, 'cook', 'Phi thơm hành tỏi và xào hành tây vừa chín trong', 'Làm nóng chảo rộng với 30 ml dầu ăn trên lửa vừa, cho tỏi băm và phần đầu hành lá thái nhỏ vào phi nhanh khoảng 20 giây cho dậy mùi thơm mà không bị cháy. Thả hành tây vào đảo đều trong 2 phút đến khi mép hành hơi trong lại.', NULL, 2),
('imp-7d38862afc164a8d_v4_step_4', 'imp-7d38862afc164a8d', 4, 'cook', 'Xào nhanh mực và ớt chuông trên lửa lớn', 'Tăng bếp lên lửa lớn, trút mực tươi, ớt chuông đỏ và toàn bộ chén sốt xì dầu dầu hào đã pha vào chảo. Đảo liên tục và nhanh tay trong 3 phút đến khi khoanh mực săn tròn, chuyển màu trắng đục chín đều và nước sốt sánh nhẹ bám quanh thân mực.', 'Xào mực dứt khoát trên lửa lớn trong 2–3 phút là bí quyết giữ mực giòn ngọt; xào lâu hơn mực sẽ dai và ra nước.', 3),
('imp-7d38862afc164a8d_v4_step_5', 'imp-7d38862afc164a8d', 5, 'cook', 'Cô sánh sốt nếu chảo còn nhiều nước', 'Quan sát đáy chảo, nếu mực tiết nhiều nước, giữ lửa lớn đảo thêm 30–60 giây cho nước cạn bớt và phần sốt áo bóng đẹp vào từng miếng mực và ớt chuông.', NULL, NULL),
('imp-7d38862afc164a8d_v4_step_6', 'imp-7d38862afc164a8d', 6, 'finish', 'Thêm hành lá, dầu mè và mè rang hoàn thiện món', 'Tắt bếp rồi thả phần hành lá cắt khúc 4 cm vào đảo nhanh 30 giây cho vừa tái xanh, sau đó rưới 15 ml dầu mè rang, rắc 6 g hạt mè trắng rang và trộn đều một lượt trước khi bày ra đĩa dùng nóng với cơm trắng.', 'Rưới dầu mè rang sau khi tắt bếp giúp giữ trọn hương thơm béo đặc trưng mà không bị đắng khét.', NULL),
('imp-c78c4d4ca35484d3_v4_step_1', 'imp-c78c4d4ca35484d3', 1, 'prep', 'Vo ngâm gạo tẻ và nấu nước dùng nấm tảo bẹ', 'Vo sạch 400 g gạo tẻ hạt ngắn 2–3 lần nước, ngâm trong nước lạnh khoảng 30 phút rồi vớt ra rổ để thật ráo. Cho 820 ml nước lọc vào nồi cùng 8 g tảo bẹ Kombu khô và phần gốc cuống nấm đùi gà đã rửa sạch, đun sôi rồi hạ lửa nhỏ ninh liu riu 15 phút cho ngọt nước. Vớt bỏ xác tảo bẹ và cuống nấm, đong lấy khoảng 650 ml nước dùng nóng.', 'Ngâm gạo trước khi nấu giúp hạt cơm chín đều từ lõi và tạo độ dẻo bóng; không nấu tảo bẹ quá lâu ở lửa lớn để tránh nước dùng bị nhớt.', 15),
('imp-c78c4d4ca35484d3_v4_step_2', 'imp-c78c4d4ca35484d3', 2, 'prep', 'Cắt lát nấm đùi gà, xé nấm bào ngư và tách nấm kim châm', 'Nấm đùi gà thái lát dày 0,8 cm (cắt hơi dày vì nấm sẽ ngót lại khi chín). Nấm bào ngư dùng tay xé dọc thành sợi vừa ăn để không bị nát, còn nấm kim châm tươi cắt bỏ gốc, tách thành từng chùm nhỏ để riêng.', NULL, NULL),
('imp-c78c4d4ca35484d3_v4_step_3', 'imp-c78c4d4ca35484d3', 3, 'cook', 'Rang sơ gạo và nấu cơm cùng nấm đùi gà, bào ngư', 'Làm nóng nồi gang đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, trút gạo đã ráo vào đảo đều tay khoảng 3 phút đến khi hạt gạo hơi trong lại. Hạ lửa vừa, chế từ từ 650 ml nước dùng tảo bẹ vào vừa ngập mặt gạo rồi xếp đều nấm đùi gà và nấm bào ngư lên trên. Đậy kín nắp, nấu lửa vừa 5 phút rồi hạ lửa nhỏ nấu thêm 15 phút.', NULL, 20),
('imp-c78c4d4ca35484d3_v4_step_4', 'imp-c78c4d4ca35484d3', 4, 'sauce', 'Pha chén sốt xì dầu hành lá dầu mè', 'Trong lúc chờ cơm chín, cho hành lá thái nhuyễn vào chén trộn đều với 10 ml dầu mè rang trước để giữ màu xanh tươi. Tiếp tục thêm 30 ml xì dầu, 30 ml nước lọc còn lại và 4 g hạt mè trắng rang, khuấy đều cho gia vị hòa quyện.', 'Áo hành lá với dầu mè trước khi thêm xì dầu giúp hành giữ độ giòn tươi, không bị héo sẫm màu.', NULL),
('imp-c78c4d4ca35484d3_v4_step_5', 'imp-c78c4d4ca35484d3', 5, 'cook', 'Nấu cạn hơi và ủ kín nồi cơm nấm', 'Sau 15 phút nấu lửa nhỏ, hạ về mức lửa nhỏ nhất nấu tiếp 8 phút đến khi không còn hơi nước thoát mạnh ở mép nắp. Tắt bếp và giữ nguyên nắp đậy kín để ủ cơm thêm 5 phút cho hạt cơm chín ráo hoàn toàn.', 'Tuyệt đối không mở nắp trong suốt 5 phút ủ cơm để giữ trọn hơi nóng làm nấm và hạt cơm dẻo thơm đồng đều.', 5),
('imp-c78c4d4ca35484d3_v4_step_6', 'imp-c78c4d4ca35484d3', 6, 'finish', 'Xếp nấm kim châm hấp hơi và dọn cơm nóng', 'Mở nắp nồi, trải đều 100 g nấm kim châm lên bề mặt cơm nóng và đậy nắp lại 1 phút cho nấm chín mềm bằng hơi nóng tự nhiên. Dùng muôi xới nhẹ từ dưới lên cho cơm tơi đều với ba loại nấm, múc ra chén và dọn kèm sốt xì dầu hành lá để chan trực tiếp khi ăn.', NULL, NULL),
('imp-97c4b38c79bf9f39_v4_step_1', 'imp-97c4b38c79bf9f39', 1, 'prep', 'Sơ chế tôm tươi, kim chi và đậu phụ non', 'Tôm tươi bóc sạch vỏ, rút chỉ đen dọc sống lưng rồi rửa nhẹ qua nước lạnh và để ráo. Kim chi cải thảo chua cắt miếng dài 3–4 cm và giữ lại khoảng 60 ml nước kim chi trong hũ. Đậu phụ non nhẹ nhàng cắt lát dày 1,5 cm; hành tây thái múi cau, tỏi khô băm nhuyễn và tách riêng phần đầu trắng, lá xanh của hành lá.', NULL, NULL),
('imp-97c4b38c79bf9f39_v4_step_2', 'imp-97c4b38c79bf9f39', 2, 'cook', 'Xào thơm tỏi và kim chi cho dậy màu đỏ đẹp', 'Đun nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm 30 giây rồi trút kim chi cùng 60 ml nước kim chi vào xào liên tục trong 4 phút đến khi kim chi săn mềm và tiết ra mùi thơm chua cay đặc trưng.', 'Xào kim chi với dầu ăn trước khi chế nước giúp loại bỏ vị chua gắt, đồng thời làm nước canh có độ sánh bóng và đậm đà hơn.', 4),
('imp-97c4b38c79bf9f39_v4_step_3', 'imp-97c4b38c79bf9f39', 3, 'cook', 'Ninh kim chi cùng nước dùng cá cơm tảo bẹ', 'Đổ 1.200 ml nước dùng cá cơm tảo bẹ Hàn vào nồi kim chi, nêm 14 g ớt bột Hàn Quốc (Gochugaru), 18 g tương ớt Hàn Quốc (Gochujang), 15 ml xì dầu và 8 g đường cát trắng. Khuấy tan đều gia vị, đun sôi bùng rồi hạ lửa vừa, đậy nắp ninh liu riu 12 phút để kim chi mềm nhừ và nước canh ngọt sâu.', NULL, 12),
('imp-97c4b38c79bf9f39_v4_step_4', 'imp-97c4b38c79bf9f39', 4, 'cook', 'Nấu hành tây và thả tôm tươi chín tới', 'Cho hành tây và phần đầu trắng hành lá vào nấu tiếp 3 phút trên lửa vừa. Sau đó tăng lên lửa lớn cho nước canh sôi mạnh, thả toàn bộ tôm tươi vào nấu khoảng 2–3 phút đến khi tôm cong tròn, chuyển màu hồng cam tươi và phần thịt đục chín hoàn toàn.', 'Không nấu tôm quá lâu sau khi thịt tôm đã chuyển hồng đục vì tôm sẽ bị co cứng và mất độ ngọt tự nhiên.', 3),
('imp-97c4b38c79bf9f39_v4_step_5', 'imp-97c4b38c79bf9f39', 5, 'cook', 'Xếp đậu phụ non và nêm lại độ mặn thanh', 'Hạ lửa nhỏ, nhẹ nhàng đặt từng miếng đậu phụ non lên bề mặt nồi canh và nấu thêm 4 phút cho đậu nóng đều và thấm vị mà không bị vỡ nát. Nếm thử nước canh và chỉ thêm tối đa 1 g muối ăn nếu cần theo độ mặn chua của mẻ kim chi.', 'Hạn chế dùng vá khuấy mạnh sau khi đã thả đậu phụ non; chỉ nghiêng nhẹ hoặc múc nước chan lên mặt đậu.', 4),
('imp-97c4b38c79bf9f39_v4_step_6', 'imp-97c4b38c79bf9f39', 6, 'finish', 'Rưới dầu mè, rắc hành lá và thưởng thức nóng', 'Rưới 5 ml dầu mè rang cùng phần lá xanh hành lá lên mặt nồi canh rồi tắt bếp. Dọn canh kim chi tôm đậu phụ còn nóng hổi ra bàn để thưởng thức ngay cùng cơm trắng.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_1', 'imp-b855b6ba4a9a3be8', 1, 'prep', 'Lột vỏ tôm giữ đầu và rút sạch chỉ đen', 'Rửa sạch 450 g tôm sú tươi, bóc bỏ vỏ và ngắt phần đầu để riêng vào tô (không bỏ đi vì phần gạch và vỏ giúp nước dùng ngọt đậm). Rút sạch chỉ đen dọc sống lưng thịt tôm, rửa lại nhanh rồi để ráo.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_2', 'imp-b855b6ba4a9a3be8', 2, 'cook', 'Xào gạch đầu tôm và ninh nước dùng ngọt thanh', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa-lớn, cho toàn bộ đầu và vỏ tôm vào đảo đều tay khoảng 3 phút, dùng muôi ấn nhẹ phần đầu cho gạch tôm tiết ra màu đỏ cam thơm nức. Đổ 1050 ml nước lọc vào đun sôi rồi hạ lửa nhỏ liu riu 5 phút, vớt bỏ hết vỏ và đầu tôm để thu nước dùng trong ngọt.', 'Không ninh vỏ tôm quá lâu hơn 5–7 phút vì nước dùng dễ bị đục và mất vị ngọt thanh tự nhiên.', 8),
('imp-b855b6ba4a9a3be8_v4_step_3', 'imp-b855b6ba4a9a3be8', 3, 'prep', 'Sơ chế bộ ba thảo mộc Thái và nấm đùi gà', 'Đập dập sả tươi cắt khúc 5 cm; thái lát mỏng củ riềng tươi; vò nhẹ và xé bỏ gân giữa lá chanh Kaffir; đập dập ớt hiểm; cắt nấm đùi gà thành lát hoặc miếng vừa ăn; thái nhỏ hành lá và ngò gai.', NULL, NULL),
('imp-b855b6ba4a9a3be8_v4_step_4', 'imp-b855b6ba4a9a3be8', 4, 'cook', 'Nấu thơm thảo mộc cùng nấm đùi gà', 'Cho sả, riềng, lá chanh Kaffir, ớt hiểm và nấm đùi gà vào nồi nước dùng tôm, đun sôi rồi hạ lửa vừa nấu liu riu 5 phút cho thảo mộc tiết hết tinh dầu thơm và nấm chín ngọt.', NULL, 5),
('imp-b855b6ba4a9a3be8_v4_step_5', 'imp-b855b6ba4a9a3be8', 5, 'cook', 'Hòa tương ớt xào Thái, nêm nước mắm và nấu tôm', 'Múc một ít nước dùng nóng ra chén hòa tan 50 g tương ớt xào Thái cho mịn rồi trút ngược vào nồi, nêm thêm 40 ml nước mắm. Bật lửa lớn cho canh sôi bùng trở lại, thả thịt tôm vào nấu khoảng 1 phút đến khi tôm vừa chuyển đỏ hồng cong mình chín hoàn toàn thì tắt bếp ngay.', 'Chỉ thả tôm khi nước sôi bùng và tắt bếp ngay sau 1 phút để thịt tôm chín ngọt, giòn săn mà không bị dai bã.', 1),
('imp-b855b6ba4a9a3be8_v4_step_6', 'imp-b855b6ba4a9a3be8', 6, 'finish', 'Vắt nước cốt chanh tươi và dọn canh nóng', 'Khi nồi canh đã tắt bếp và bớt sôi sục, rót nước cốt của 2,5 quả chanh tươi vào cùng 5 g đường cát trắng, khuấy nhẹ và nếm chỉnh vị chua cay mặn ngọt hài hòa. Múc ra tô, rắc hành lá và ngò gai lên trên rồi thưởng thức nóng (nhắc người ăn không nhai sả, riềng, lá chanh).', 'Cho nước cốt chanh sau khi tắt bếp giúp giữ trọn hương thơm tươi mát của tinh dầu chanh và tránh làm nước canh bị đắng.', NULL),
('imp-2b514b564c702ff1_v4_step_1', 'imp-2b514b564c702ff1', 1, 'prep', 'Ngâm xiên tre, làm sạch tôm và ướp muối nhẹ', 'Ngâm 6–8 que xiên tre vào nước lạnh ít nhất 20 phút để không bị cháy khi nướng. Làm sạch 500 g tôm tươi, bóc vỏ thân giữ lại đuôi, rút chỉ đen và thấm thật khô bằng khăn giấy. Rắc đều 2 g muối ăn và 15 ml dầu ăn vào tôm trộn đều.', 'Ngâm xiên tre trước giúp que không bị cháy đen và thấm khô tôm giúp lớp sốt phết bám đều lên thịt tôm.', 20),
('imp-2b514b564c702ff1_v4_step_2', 'imp-2b514b564c702ff1', 2, 'sauce', 'Pha chén sốt chanh tỏi ớt chua cay đậm đà', 'Trong chén nhỏ, hòa tan 15 g đường cát trắng với 35 ml nước mắm và toàn bộ nước cốt của 2 quả chanh tươi đến khi đường tan hết. Thêm tỏi băm nhuyễn và ớt hiểm băm nhỏ vào khuấy đều.', NULL, NULL),
('imp-2b514b564c702ff1_v4_step_3', 'imp-2b514b564c702ff1', 3, 'marinate', 'Phết lớp sốt mỏng lên tôm và xiên que', 'Múc 1/3 lượng sốt chanh ớt vừa pha rưới nhẹ trộn đều với tôm, để thấm khoảng 10 phút (giữ lại 2/3 phần sốt còn lại để phết khi nướng và lúc dọn). Lần lượt xiên 4–5 con tôm vào mỗi que tre theo chiều dọc thân tôm.', 'Không ướp tôm với nước cốt chanh quá 15 phút vì axit trong chanh sẽ làm chín tái bề mặt khiến thịt tôm bị bở khi nướng.', 10),
('imp-2b514b564c702ff1_v4_step_4', 'imp-2b514b564c702ff1', 4, 'cook', 'Làm nóng vỉ nướng và phết lớp dầu chống dính', 'Làm nóng bếp than hoa hoặc chảo gang rãnh nướng ở lửa lớn đến khi vỉ thật nóng, dùng cọ quét 5 ml dầu ăn còn lại lên mặt vỉ để tôm không bị dính sát.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-2b514b564c702ff1_v4_step_5', 'imp-2b514b564c702ff1', 5, 'cook', 'Nướng tôm lửa lớn hai mặt và phết sốt bóng đẹp', 'Đặt các xiên tôm lên vỉ nóng, nướng khoảng 2–3 phút cho mặt dưới chuyển đỏ hồng xém nhẹ thì lật mặt. Phết thêm 1/3 lượng sốt lên mặt tôm đã lật và nướng tiếp 2–3 phút cho đến khi tôm săn cong hoàn toàn và hai mặt hơi cháy cạnh thơm lừng.', 'Nướng nhanh trên lửa lớn trong 4–6 phút giúp tôm vừa chín tới mọng nước, tránh nướng lâu làm thịt tôm khô xác.', 5),
('imp-2b514b564c702ff1_v4_step_6', 'imp-2b514b564c702ff1', 6, 'finish', 'Phết nốt phần sốt tươi, rắc hành lá và thưởng thức', 'Gắp các xiên tôm nướng ra đĩa lớn, dùng cọ phết nốt 1/3 lượng sốt chanh ớt tươi còn lại lên trên khi tôm đang nóng hổi để tạo lớp áo bóng thơm. Rắc hành lá thái nhỏ lên mặt và dọn ăn ngay.', NULL, NULL),
('imp-119da2ec6738c17e_v4_step_1', 'imp-119da2ec6738c17e', 1, 'prep', 'Sơ chế đùi gà và xay nhuyễn hỗn hợp thảo mộc', 'Chà xát 750 g đùi gà với 2 g muối ăn rồi rửa sạch lại nước lạnh, thấm ráo và chặt miếng vừa ăn hoặc khứa sâu 2 đường. Cho sả thái lát, củ riềng tươi, lá chanh Kaffir và 15 g phần rễ ngò rí vào cối xay hoặc giã nhuyễn thành hỗn hợp thảo mộc thơm mịn.', 'Khứa nhẹ vài đường trên mặt thịt đùi gà giúp hỗn hợp thảo mộc thấm sâu và gà chín đều nhanh hơn khi hấp.', NULL),
('imp-119da2ec6738c17e_v4_step_2', 'imp-119da2ec6738c17e', 2, 'marinate', 'Ướp gà đậm đà với thảo mộc và gia vị', 'Cho thịt gà vào tô lớn cùng hỗn hợp thảo mộc vừa xay, 25 ml dầu hào, 20 ml xì dầu và 1 g muối ăn còn lại. Dùng tay bóp trộn kỹ cho gia vị thấm sâu vào từng thớ thịt, đậy kín ướp ít nhất 15–20 phút.', NULL, 20),
('imp-119da2ec6738c17e_v4_step_3', 'imp-119da2ec6738c17e', 3, 'cook', 'Xếp gà vào đĩa sâu lòng và hấp cách thủy', 'Xếp gà đã ướp cùng phần sốt vào đĩa sâu lòng có thành cao để hứng trọn phần nước ngọt tiết ra. Đun sôi nước trong xửng, đặt đĩa gà vào hấp lửa vừa khoảng 15 phút cho thịt bắt đầu săn lại và tỏa hương thơm.', 'Dùng đĩa sâu lòng hứng phần nước ngọt tiết ra khi hấp để hòa vào nước chấm giúp hương vị đậm đà hơn hẳn.', 15),
('imp-119da2ec6738c17e_v4_step_4', 'imp-119da2ec6738c17e', 4, 'cook', 'Thêm lá húng quế Thái và hấp chín mềm hoàn toàn', 'Ở phút thứ 15, mở nắp xửng rải nhanh 20 g lá húng quế Thái lên mặt gà rồi đậy kín hấp tiếp thêm 25 phút trên lửa vừa đến khi xăm đũa vào phần thịt dày nhất thấy nước chảy ra trong suốt không còn đỏ hồng.', NULL, 25),
('imp-119da2ec6738c17e_v4_step_5', 'imp-119da2ec6738c17e', 5, 'sauce', 'Giã tỏi ớt và pha nước chấm chanh Thái', 'Trong lúc chờ gà chín, cho tỏi bóc vỏ và ớt hiểm vào cối giã nhuyễn. Trút ra chén, thêm nước cốt của 3 quả chanh tươi, 30 ml nước mắm, 30 g đường cát trắng và 60 ml nước lọc, khuấy tan hết đường rồi thả 10 g lá ngò rí thái nhỏ vào.', 'Cân chỉnh độ chua cay mặn ngọt của chén nước chấm theo khẩu vị, giữ độ hơi đậm để khi hòa thêm nước hấp gà sẽ vừa miệng.', NULL),
('imp-119da2ec6738c17e_v4_step_6', 'imp-119da2ec6738c17e', 6, 'finish', 'Hòa nước hấp gà vào nước chấm và trình bày', 'Nhấc đĩa gà hấp chín ra khỏi xửng, múc khoảng 3–4 muỗng canh nước ngọt trong đĩa hấp hòa vào chén nước chấm cho dậy vị béo thơm, phần còn lại rưới lên gà, rắc hành lá thái nhỏ rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_1', 'imp-2fb85e79ab43b8bc', 1, 'marinate', 'Pha sốt ướp và ướp miếng thăn bò nguyên khối', 'Khuấy tan 12 ml dầu hào, 8 ml xì dầu, 4 g đường cát trắng, 1,5 g tiêu đen xay và 15 ml dầu ăn. Xoa đều hỗn hợp này lên khắp miếng thịt thăn bò 350 g, bọc kín ướp trong ngăn mát ít nhất 60 phút, sau đó lấy ra để nhiệt độ phòng 20 phút trước khi nướng.', 'Để thịt bò về nhiệt độ phòng trước khi đặt lên vỉ giúp nhiệt độ chín đều từ ngoài vào trong và giữ phần lõi thịt hồng mọng.', 60),
('imp-2fb85e79ab43b8bc_v4_step_2', 'imp-2fb85e79ab43b8bc', 2, 'prep', 'Sơ chế mỏng sả, hành tím và các loại rau thơm', 'Thái thật mỏng phần gốc non của 2 cây sả và 45 g hành tím khô; nhặt lá bạc hà (húng lủi), thái khúc 2 cm ngò rí và hành lá, để tất cả thật ráo nước.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_3', 'imp-2fb85e79ab43b8bc', 3, 'cook', 'Nướng bò chín vừa và giữ lại nước thịt ngọt', 'Làm nóng chảo gang hoặc vỉ nướng ở lửa vừa-lớn. Đặt miếng thăn bò lên nướng tổng 6–8 phút, trở mặt mỗi 2 phút đến khi hai mặt xém nâu đẹp và thịt đạt độ chín vừa (nhiệt độ lõi khoảng 60°C). Gắp ra đĩa sâu lòng để thịt nghỉ 5 phút và giữ lại toàn bộ nước thịt tiết ra.', 'Không cắt thịt ngay khi vừa nhấc khỏi chảo vì nước thịt sẽ chảy ra hết làm miếng bò khô xác; thời gian nghỉ 5 phút giúp thớ thịt giữ trọn độ mọng.', 8),
('imp-2fb85e79ab43b8bc_v4_step_4', 'imp-2fb85e79ab43b8bc', 4, 'prep', 'Thái lát bò ngược thớ và giữ lại nước thịt', 'Sau khi thịt bò đã nghỉ đủ thời gian, dùng dao sắc thái thành từng lát mỏng ngang thớ dày 3–4 mm rồi cho vào tô trộn cùng toàn bộ phần nước thịt ngọt tiết ra trên đĩa.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_5', 'imp-2fb85e79ab43b8bc', 5, 'sauce', 'Pha nước trộn gỏi chua mặn cay cùng nước thịt', 'Thêm vào tô thịt bò 20 ml nước mắm, nước cốt của 1,5 quả chanh tươi, 4 g đường cát trắng còn lại, 3 g ớt bột vảy rang và 35 ml nước dùng gà, trộn đều cho đường tan hoàn toàn và thịt ngấm vị đậm đà.', NULL, NULL),
('imp-2fb85e79ab43b8bc_v4_step_6', 'imp-2fb85e79ab43b8bc', 6, 'finish', 'Trộn thính gạo rang, rau thơm và dọn ăn ngay', 'Rắc 30 g thính gạo rang vào tô thịt bò đảo đều cho thính bám thơm quyện sốt, nếm lại cho vừa vị chua mặn cay hài hòa. Cuối cùng cho sả thái mỏng, hành tím, lá bạc hà, ngò rí và hành lá vào đảo nhẹ tay rồi bày ra đĩa dùng ngay.', 'Chỉ trộn thính gạo và rau thơm ngay sát lúc dọn bàn ăn để thính giữ được hương rang bùi thơm và rau thơm tươi xanh.', NULL),
('imp-3f14cf8e63967712_v4_step_1', 'imp-3f14cf8e63967712', 1, 'prep', 'Làm sạch mực, khía vảy rồng và thấm thật khô', 'Làm sạch 450 g mực ống tươi, bỏ nang cứng, túi mực và mắt. Lật mặt trong thân mực khía các đường chéo đan xen tạo hình vảy rồng, cắt miếng chữ nhật 2x4 cm, râu mực cắt khúc vừa ăn rồi dùng khăn giấy thấm thật khô toàn bộ mực.', 'Thấm thật khô mực trước khi xào là bước quan trọng giúp mực săn giòn ngay khi chạm chảo nóng và không tiết ra nhiều nước.', NULL),
('imp-3f14cf8e63967712_v4_step_2', 'imp-3f14cf8e63967712', 2, 'prep', 'Giã thô tỏi ớt và cắt khúc hành lá', 'Cho tỏi bóc vỏ và ớt hiểm vào cối đá giã dập thô (không cần nhuyễn mịn) để tỏi ớt tiết hết tinh dầu thơm. Hành lá rửa sạch cắt khúc 3 cm.', 'Giã tỏi ớt bằng cối thay vì băm sẽ giúp hương thơm tỏa ra mạnh mẽ hơn hẳn khi phi nhanh trên chảo nóng.', NULL),
('imp-3f14cf8e63967712_v4_step_3', 'imp-3f14cf8e63967712', 3, 'sauce', 'Pha sẵn chén sốt gia vị xào mực', 'Khuấy tan 25 ml dầu hào, 15 ml nước mắm, 5 ml xì dầu đặc, 5 g đường cát trắng và 4 g hạt nêm trong chén nhỏ để sẵn bên cạnh bếp.', NULL, NULL),
('imp-3f14cf8e63967712_v4_step_4', 'imp-3f14cf8e63967712', 4, 'cook', 'Phi thơm tỏi ớt giã trong chảo nóng', 'Đun nóng chảo rộng với 30 ml dầu ăn trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào đảo nhanh khoảng 20–30 giây đến khi dậy mùi cay thơm nồng và tỏi vừa ngả vàng nhạt (tránh để tỏi cháy đắng).', NULL, 1),
('imp-3f14cf8e63967712_v4_step_5', 'imp-3f14cf8e63967712', 5, 'cook', 'Xào mực lửa lớn săn giòn và rưới sốt áo đều', 'Tăng lửa lên mức lớn nhất, trút toàn bộ mực vào đảo nhanh tay khoảng 2 phút đến khi các đường khía bung nở cong đều và thịt mực chuyển màu trắng đục săn chắc. Rưới đều chén sốt đã pha vào đảo mạnh thêm 45 giây cho sốt bám bóng vào từng miếng mực.', 'Món mực xào lửa lớn chỉ mất khoảng 2–3 phút; xào quá lâu sẽ làm mực ra nước và bị dai cứng như cao su.', 2),
('imp-3f14cf8e63967712_v4_step_6', 'imp-3f14cf8e63967712', 6, 'finish', 'Đảo nhanh hành lá và dọn mực xào nóng', 'Thả hành lá cắt khúc vào chảo, đảo đều thêm 15 giây rồi tắt bếp ngay để hành giữ màu xanh tươi giòn ngọt. Trút mực xào tỏi ớt ra đĩa và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-244640181aff1fb6_v4_step_1', 'imp-244640181aff1fb6', 1, 'prep', 'Luộc sơ nấm đùi gà, thái khoanh và khứa mặt', 'Đun sôi 500 ml nước lọc, cho 380 g nấm đùi gà đã rửa sạch vào luộc sơ đúng 2 phút để nấm sạch và hết mùi hăng, vớt ra để nguội bớt rồi thái khoanh dày 1 cm. Dùng dao khứa nhẹ vài đường chéo trên hai mặt mỗi khoanh nấm để gia vị thấm sâu.', 'Luộc sơ 2 phút trước khi ướp giúp nấm mềm dẻo không gãy nát, ra bớt nước khi nướng và thấm gia vị nhanh gấp đôi.', 2),
('imp-244640181aff1fb6_v4_step_2', 'imp-244640181aff1fb6', 2, 'prep', 'Băm nhuyễn sả tỏi và thái lát hành tím', 'Băm thật nhuyễn phần gốc non của 3 cây sả tươi và tỏi khô; thái lát mỏng 45 g hành tím khô; thái nhỏ hành lá tươi để riêng một ít rắc mặt sau khi nướng.', NULL, NULL),
('imp-244640181aff1fb6_v4_step_3', 'imp-244640181aff1fb6', 3, 'marinate', 'Pha sốt dầu hào chay và ướp thấm khoanh nấm', 'Khuấy tan 20 ml xì dầu, 30 ml dầu hào chay, 8 g đường cát trắng, 10 ml tương ớt, 1,5 g tiêu đen xay, 12 ml dầu mè, 20 ml dầu ăn và 15 ml nước lọc còn lại. Trộn nhẹ khoanh nấm với phần sốt này cùng sả băm, tỏi băm, hành tím thái lát và phần lớn hành lá; ướp 15 phút.', 'Giữa thời gian ướp nên đảo trở mặt các khoanh nấm một lần để hai mặt ngấm đều sả và gia vị.', 15),
('imp-244640181aff1fb6_v4_step_4', 'imp-244640181aff1fb6', 4, 'cook', 'Xếp nấm thành một lớp đều lên khay nướng', 'Làm nóng trước nồi chiên không dầu hoặc lò nướng ở 200°C trong 3 phút. Lót giấy bạc vào khay, xếp từng khoanh nấm đã ướp thành một lớp thưa đều nhau rồi rưới hết phần sốt ướp còn lại lên mặt nấm.', 'Không xếp chồng nấm lên nhau để luồng khí nóng lưu thông đều, giúp các khoanh nấm xém cạnh đẹp mắt thay vì bị hấp ướt.', NULL),
('imp-244640181aff1fb6_v4_step_5', 'imp-244640181aff1fb6', 5, 'cook', 'Nướng nấm ở 200°C đến khi xém vàng thơm lừng', 'Đưa khay nấm vào nướng ở nhiệt độ 200°C trong 8–10 phút đến khi mặt nấm se ráo, cạnh xém vàng nhẹ và dậy mùi thơm nồng của sả nướng cùng dầu mè.', NULL, 9),
('imp-244640181aff1fb6_v4_step_6', 'imp-244640181aff1fb6', 6, 'finish', 'Rắc mè rang, hành lá và thưởng thức nóng', 'Gắp nấm nướng sả ra đĩa, chan nhẹ phần sốt còn đọng trong khay lên mặt nấm. Rắc hạt mè trắng rang vàng cùng chút hành lá tươi còn lại lên trên rồi dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-f494a9f384ce66a4_v4_step_1', 'imp-f494a9f384ce66a4', 1, 'prep', 'Kiểm tra thịt cua và sơ chế rau củ gia vị', 'Dàn nhẹ 400 g thịt cua biển ra đĩa, rà kỹ bằng tay để nhặt bỏ hết mảnh vỏ hoặc sụn cua còn lẫn và để ráo. Rửa sạch ớt chuông xanh, bỏ hạt thái miếng vuông 2,5 cm; tỏi bóc vỏ băm nhỏ; ớt hiểm băm nhỏ (chừa 1 quả thái lát); hành lá cắt khúc 3 cm.', 'Kiểm tra kỹ thịt cua bóc sẵn giúp loại bỏ hoàn toàn mảnh sụn nhỏ mà vẫn giữ được các thớ thịt cua nguyên tảng đẹp mắt.', NULL),
('imp-f494a9f384ce66a4_v4_step_2', 'imp-f494a9f384ce66a4', 2, 'sauce', 'Pha sẵn chén sốt dầu hào và nước dùng gà', 'Trộn đều trong chén 45 ml dầu hào, 10 ml xì dầu nhạt, 5 g đường cát trắng, 1,5 g tiêu đen xay và 100 ml nước dùng gà, khuấy tan đường để phần sốt có vị mặn ngọt hài hòa.', 'Pha sẵn toàn bộ chén sốt trước khi bật bếp giúp món xào hải sản diễn ra nhanh gọn và thịt cua không bị chín quá lửa.', NULL),
('imp-f494a9f384ce66a4_v4_step_3', 'imp-f494a9f384ce66a4', 3, 'cook', 'Phi thơm tỏi ớt trên lửa vừa không để cháy', 'Đun nóng chảo rộng với 45 ml dầu ăn trên lửa vừa, cho tỏi băm và ớt hiểm băm vào phi khoảng 40 giây đến khi tỏi dậy mùi thơm cay nồng và vừa ngả vàng nhẹ.', NULL, 1),
('imp-f494a9f384ce66a4_v4_step_4', 'imp-f494a9f384ce66a4', 4, 'cook', 'Xào nhanh ớt chuông xanh giữ độ giòn tươi', 'Vặn lửa lớn, cho toàn bộ ớt chuông xanh thái miếng vuông vào chảo đảo nhanh tay khoảng 1 phút cho ớt vừa chín tới, dậy mùi thơm mà vẫn giữ được độ giòn ngọt và màu xanh mướt.', NULL, 1),
('imp-f494a9f384ce66a4_v4_step_5', 'imp-f494a9f384ce66a4', 5, 'cook', 'Đun sôi nhẹ sốt và đảo đều thịt cua', 'Rưới toàn bộ chén sốt dầu hào đã pha vào chảo đun sôi nhẹ 1 phút cho nước sốt hơi sánh lại. Nhẹ nhàng trút 400 g thịt cua vào chảo, dùng muôi gỗ đảo nhẹ tay từ dưới lên trong 2 phút cho thịt cua nóng đều tận trong và áo bóng sốt mà không bị nát vụn.', 'Thịt cua đã hấp chín sẵn nên chỉ cần đảo nhẹ 1–2 phút trong nước sốt sôi lăn tăn cho ngấm vị, tránh đảo mạnh tay làm cua bị vụn.', 3),
('imp-f494a9f384ce66a4_v4_step_6', 'imp-f494a9f384ce66a4', 6, 'finish', 'Thêm hành lá và thưởng thức nóng với cơm trắng', 'Thả hành lá cắt khúc vào chảo đảo nhẹ 15 giây rồi tắt bếp ngay. Múc cua xào cay ra đĩa, rắc thêm vài lát ớt hiểm lên trên và dọn nóng cùng cơm trắng.', NULL, NULL),
('imp-0ec0d1db60dbdc1e_v4_step_1', 'imp-0ec0d1db60dbdc1e', 1, 'prep', 'Làm sạch gà, lạng mỡ gà và nấu nước dùng nền', 'Rửa sạch con gà ta 1300 g, lạng riêng phần mỡ quanh cổ và phao câu để thắng lấy mỡ; chặt đầu, cổ, cánh cho vào nồi lớn cùng củ cải trắng cắt khúc, hành tây bổ đôi, 4 tép tỏi đập dập, 3 lát gừng tươi, 10 g rễ ngò rí và 2 g tiêu trắng xay. Đổ 1800 ml nước lọc vào đun sôi rồi hạ lửa nhỏ ninh 15 phút.', NULL, 15),
('imp-0ec0d1db60dbdc1e_v4_step_2', 'imp-0ec0d1db60dbdc1e', 2, 'cook', 'Luộc gà lửa liu riu cho thịt chín mọng không nát', 'Vớt sạch bọt trong nồi nước dùng, nêm 12 g muối ăn rồi nhẹ nhàng thả nguyên con gà vào sao cho nước ngập thân gà. Hạ lửa nhỏ giữ nước chỉ sôi lăn tăn nhẹ (không sôi bùng) và luộc khoảng 35 phút đến khi xăm phần đùi dày nhất thấy nước chảy ra trong suốt không còn đỏ hồng; vớt gà ra để nguội bớt mới chặt.', 'Luộc gà ở nhiệt độ sôi lăn tăn nhẹ và để gà nguội hoàn toàn mới chặt sẽ giúp da gà căng bóng không rách và thớ thịt giữ trọn nước ngọt.', 35),
('imp-0ec0d1db60dbdc1e_v4_step_3', 'imp-0ec0d1db60dbdc1e', 3, 'cook', 'Thắng mỡ gà, phi thơm tỏi và xào gạo nấu cơm', 'Trong chảo nóng trên lửa vừa, cho 15 ml dầu ăn thực vật cùng phần mỡ da gà đã lạng vào rán chảy lấy nước mỡ gà thơm trong rồi vớt bỏ phần tóp mỡ. Cho 4 tép tỏi băm vào phi thơm 30 giây rồi trút 360 g gạo tẻ thơm vo sạch vào đảo đều 3 phút cho hạt gạo săn bóng mỡ thơm; chuyển vào nồi cơm điện, múc 650 ml nước luộc gà nóng chan vào và bật nấu chín.', 'Rang gạo cùng mỡ gà và tỏi phi trước khi nấu giúp hạt cơm bóng đẹp, tơi ráo và dậy hương béo thơm đặc trưng.', 20),
('imp-0ec0d1db60dbdc1e_v4_step_4', 'imp-0ec0d1db60dbdc1e', 4, 'sauce', 'Pha chén sốt tương đậu nành Taojiew gừng tỏi ớt', 'Giã nhuyễn 20 g gừng tươi còn lại cùng 4 tép tỏi và ớt hiểm. Cho hỗn hợp này vào chén cùng 35 g tương đậu nành lên men, 15 ml xì dầu đặc, 20 ml xì dầu thường, 5 ml giấm gạo, 20 g đường cát trắng và nước cốt của 1 quả chanh tươi, khuấy tan hết đường.', 'Tương đậu nành lên men Taojiew có độ mặn dịu đặc trưng; hãy nếm thử chén sốt và cân chỉnh thêm chút nước luộc gà nếu thích vị thanh nhẹ hơn.', NULL),
('imp-0ec0d1db60dbdc1e_v4_step_5', 'imp-0ec0d1db60dbdc1e', 5, 'prep', 'Chặt thịt gà đã nguội và thái dưa leo ăn kèm', 'Khi gà đã nguội hẳn, dùng dao sắc lọc và chặt thịt gà thành từng miếng vừa ăn giữ nguyên da bóng đẹp; rửa sạch dưa leo tươi và thái lát xéo dày 0,5 cm để xếp kèm đĩa cơm.', NULL, NULL),
('imp-0ec0d1db60dbdc1e_v4_step_6', 'imp-0ec0d1db60dbdc1e', 6, 'finish', 'Xới cơm tơi và hoàn thiện đĩa cơm gà nóng hổi', 'Khi cơm chín bật nút, xới tơi hạt cơm bóng thơm ra đĩa, xếp thịt gà chặt miếng cùng dưa leo thái lát bên cạnh. Múc bát nước luộc gà nóng rắc 15 g lá ngò rí thái nhỏ ăn kèm và chấm thịt gà đẫm sốt tương đậu gừng tỏi ớt.', NULL, NULL),
('imp-4316659025be0f91_v4_step_1', 'imp-4316659025be0f91', 1, 'marinate', 'Ướp thịt thăn bò mềm mọng và ngâm sợi hủ tiếu', 'Ngâm 240 g hủ tiếu khô bản rộng trong nước lạnh 30 phút cho sợi mềm dẻo rồi vớt ra rổ để thật ráo. Thịt thăn bò thái lát mỏng ngang thớ, ướp cùng 10 ml xì dầu, 2 g đường cát trắng và 20 ml nước lọc trong 15 phút để thịt ngấm vị và giữ ẩm.', 'Không ngâm hủ tiếu khô bằng nước sôi vì sợi sẽ nhanh nhũn và dễ đứt gãy khi đảo mạnh trên chảo.', 30),
('imp-4316659025be0f91_v4_step_2', 'imp-4316659025be0f91', 2, 'prep', 'Giã tỏi ớt, pha sốt xào và cắt thái rau củ', 'Giã dập thô tỏi khô và ớt hiểm trong cối. Trong chén nhỏ, khuấy đều 25 ml dầu hào, 15 ml xì dầu còn lại, 5 ml xì dầu đặc và 5 ml nước mắm. Thái sợi cà rốt, thái xéo ớt chuông đỏ, tách riêng cọng và lá cải rổ, nhặt lá húng quế Thái để ráo.', NULL, NULL),
('imp-4316659025be0f91_v4_step_3', 'imp-4316659025be0f91', 3, 'cook', 'Áp chảo thịt bò chín tới trên lửa lớn', 'Đun nóng chảo rộng với 15 ml dầu ăn trên lửa lớn, dàn đều thịt bò đã ướp thành một lớp và áp chảo nhanh 2 phút đến khi hai mặt xém nâu nhẹ, thịt chín tái vừa tới thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-4316659025be0f91_v4_step_4', 'imp-4316659025be0f91', 4, 'cook', 'Phi tỏi ớt giã và xào nhanh rau củ cứng', 'Hạ lửa vừa, thêm 25 ml dầu ăn còn lại vào chảo phi thơm hỗn hợp tỏi ớt giã khoảng 30 giây (tránh cháy). Bật lửa lớn, cho cà rốt, ớt chuông đỏ và phần cọng cải rổ vào xào nhanh 45 giây cho vừa chín giòn.', NULL, NULL),
('imp-4316659025be0f91_v4_step_5', 'imp-4316659025be0f91', 5, 'cook', 'Đảo mì thấm sốt và áp chảo xém cạnh tạo mùi khói', 'Cho hủ tiếu đã ráo vào chảo, rưới đều chén sốt đã pha và rắc 16 g đường cát trắng còn lại lên mặt mì. Đảo nhanh 2 phút cho sợi mì thấm bóng sốt, sau đó dàn phẳng mặt chảo giữ yên 20 giây cho sợi mì hơi xém cạnh thơm mùi khói chảo rồi lật đảo lại.', 'Để yên sợi mì tiếp xúc đáy chảo nóng 15–20 giây không đảo sẽ tạo lớp xém nhẹ caramel đặc trưng của Pad Kee Mao.', 3),
('imp-4316659025be0f91_v4_step_6', 'imp-4316659025be0f91', 6, 'finish', 'Trộn thịt bò, lá húng quế Thái và dọn nóng', 'Trút thịt bò đã áp chảo (gạn bỏ nước thịt đọng để mì không nhão) trở lại chảo cùng phần lá cải rổ, đảo đều 30 giây cho thịt bò chín hoàn toàn. Tắt bếp, thả ngay 50 g lá húng quế Thái và hành lá vào đảo vài lượt cho lá vừa héo dậy mùi thơm nồng rồi bày ra đĩa dùng nóng.', 'Chỉ cho lá húng quế Thái vào sau khi tắt bếp để hơi nóng còn lại làm héo nhẹ mà lá không bị thâm đen hay mất hương thơm.', NULL),
('imp-0e30c82a4c77802e_v4_step_1', 'imp-0e30c82a4c77802e', 1, 'prep', 'Ướp lạnh đậu phụ non và rang thơm hạt mè', 'Đặt hộp 450 g đậu phụ non vào ngăn mát tủ lạnh ít nhất 2 giờ để đậu mát sâu và săn mịn. Rang khô 10 g hạt mè trên chảo nhỏ lửa nhỏ khoảng 2 phút đến khi mè dậy mùi thơm bùi thì trút ra chén để nguội.', 'Đậu phụ non càng mát lạnh khi ăn cùng nước trộn chua cay mặn ngọt sẽ càng thanh mát và giữ khối đẹp hơn.', 5),
('imp-0e30c82a4c77802e_v4_step_2', 'imp-0e30c82a4c77802e', 2, 'prep', 'Băm nhuyễn sả non và thái hạt lựu rau củ', 'Băm thật nhuyễn lõi non của 1,5 cây sả tươi và 4 quả ớt hiểm. Thái hạt lựu nhỏ 20 g hành tím, dưa leo bỏ ruột và ớt chuông đỏ; thái nhỏ hành lá, ngò rí và lá bạc hà (húng lủi).', 'Phần sả dùng ăn sống nên chỉ lấy lõi non trắng mềm nhất và băm thật mịn để không bị xơ cứng khi nhai.', NULL),
('imp-0e30c82a4c77802e_v4_step_3', 'imp-0e30c82a4c77802e', 3, 'sauce', 'Pha nước trộn đường thốt nốt hòa tan kỹ', 'Cho 20 g đường thốt nốt bào vụn vào tô cùng 35 ml xì dầu nhạt, nước cốt của 1,5 quả chanh tươi và ớt hiểm băm, khuấy kỹ khoảng 2 phút đến khi đường tan hoàn toàn thành hỗn hợp sánh thơm.', NULL, NULL),
('imp-0e30c82a4c77802e_v4_step_4', 'imp-0e30c82a4c77802e', 4, 'sauce', 'Trộn thấm các loại rau củ và rau thơm', 'Cho hành tím, sả băm, dưa leo, ớt chuông đỏ, hành lá, ngò rí và lá bạc hà vào tô nước trộn vừa pha, đảo nhẹ đều tay và để nghỉ 5 phút cho rau củ ngấm đều vị chua cay mặn ngọt.', NULL, 5),
('imp-0e30c82a4c77802e_v4_step_5', 'imp-0e30c82a4c77802e', 5, 'prep', 'Cắt khối đậu phụ non xếp ngay ngắn ra đĩa sâu lòng', 'Nhẹ nhàng lấy đậu phụ non ra khỏi hộp, chắt bỏ hết nước, dùng dao mỏng sắc cắt thành khối vuông lớn cạnh 4 cm rồi xếp ngay ngắn vào đĩa sâu lòng để hứng nước trộn.', NULL, NULL),
('imp-0e30c82a4c77802e_v4_step_6', 'imp-0e30c82a4c77802e', 6, 'finish', 'Phủ rau trộn, rưới sốt đáy đĩa và rắc mè rang', 'Múc phần rau củ trộn đặt gọn lên mặt từng miếng đậu phụ non, rưới nước trộn còn lại xung quanh đáy đĩa và rắc hạt mè rang thơm lên trên để thưởng thức ngay khi đậu còn mát lạnh.', 'Đặt rau trộn lên mặt và rưới nước sốt xung quanh đáy đĩa thay vì trộn đảo chung để các khối đậu phụ non không bị vỡ nát.', NULL),
('imp-d005aca18d138bfe_v4_step_1', 'imp-d005aca18d138bfe', 1, 'prep', 'Làm sạch tôm, giã tỏi ớt và nhặt lá húng quế', 'Rửa sạch 350 g tôm tươi, bóc vỏ, bỏ đầu và rút sạch chỉ đen sống lưng, để thật ráo. Giã thô tỏi bóc vỏ cùng ớt hiểm trong cối cho dậy mùi tinh dầu. Nhặt lá húng quế Thái rửa ráo; thái múi cau hành tây và cắt khúc hành lá.', 'Giã thô tỏi và ớt bằng cối đá giúp giải phóng nhiều tinh dầu thơm nồng hơn so với băm nhỏ bằng dao.', NULL),
('imp-d005aca18d138bfe_v4_step_2', 'imp-d005aca18d138bfe', 2, 'sauce', 'Pha sẵn chén sốt Pad Krapao đậm vị', 'Khuấy tan hoàn toàn 30 ml dầu hào, 15 ml xì dầu nhạt, 15 ml nước mắm, 8 g đường cát trắng và 15 ml nước lọc trong chén nhỏ để sẵn bên bếp.', NULL, NULL),
('imp-d005aca18d138bfe_v4_step_3', 'imp-d005aca18d138bfe', 3, 'cook', 'Phi thơm tỏi ớt giã trên chảo dầu nóng', 'Đun nóng chảo rộng với 35 ml dầu ăn trên lửa vừa-lớn, cho hỗn hợp tỏi ớt giã vào phi thơm khoảng 30 giây đến khi tỏi vừa ngả vàng thơm nồng và dậy mùi cay.', 'Canh chảo thật nóng và đảo liên tục khi phi tỏi ớt để tỏi thơm vàng mà không bị cháy khét gây đắng.', NULL),
('imp-d005aca18d138bfe_v4_step_4', 'imp-d005aca18d138bfe', 4, 'cook', 'Xào săn tôm nhanh trên lửa lớn', 'Tăng lửa lên mức lớn nhất, trút toàn bộ tôm tươi đã ráo nước vào chảo đảo nhanh tay khoảng 2 phút đến khi tôm chuyển màu đỏ hồng cong đều và săn bề mặt.', NULL, 2),
('imp-d005aca18d138bfe_v4_step_5', 'imp-d005aca18d138bfe', 5, 'cook', 'Om nhanh tôm trong sốt và xào hành tây chín giòn', 'Rưới đều chén sốt đã pha vào chảo tôm, đảo đều khoảng 1 phút cho sốt sôi sánh bám quanh thân tôm. Nếu dùng hành tây, thả hành tây thái lát vào đảo tiếp 1 phút cho hành vừa chín trong và tôm chín hoàn toàn.', NULL, 2),
('imp-d005aca18d138bfe_v4_step_6', 'imp-d005aca18d138bfe', 6, 'finish', 'Đảo lá húng quế Thái khi tắt bếp và dọn nóng', 'Tắt bếp ngay, thả toàn bộ 30 g lá húng quế Thái và hành lá cắt khúc vào chảo đảo nhanh 3–4 lượt để hơi nóng làm lá vừa héo dậy hương thơm nồng đặc trưng mà vẫn giữ màu xanh mướt. Trút ra đĩa dùng nóng với cơm trắng.', 'Chỉ cho lá húng quế vào sau khi đã tắt bếp để tránh lá bị thâm đen và bay mất tinh dầu thơm.', NULL),
('imp-a9710414682c8521_v4_step_1', 'imp-a9710414682c8521', 1, 'marinate', 'Ướp thịt bò mềm đậm và pha sẵn sốt xì dầu', 'Thái 300 g thịt thăn bò thành lát mỏng ngang thớ, ướp cùng 10 ml xì dầu, 2 g đường cát trắng và 5 ml dầu ăn trong 20 phút cho thịt thấm vị và tơi mềm. Trong chén nhỏ, khuấy tan 15 ml xì dầu còn lại, 20 ml dầu hào, 10 ml xì dầu đặc và 13 g đường cát trắng.', NULL, 20),
('imp-a9710414682c8521_v4_step_2', 'imp-a9710414682c8521', 2, 'prep', 'Luộc mì trứng vừa chín tới và sơ chế rau củ', 'Đun sôi 1500 ml nước lọc, cho 270 g mì trứng khô vào luộc khoảng 3–4 phút cho sợi vừa mềm tới (vẫn còn độ dai lõi), vớt ra xả ngay nước lạnh, để ráo và trộn 5 ml dầu ăn cho sợi tơi không dính. Thái sợi bắp cải, băm nhỏ tỏi, cắt khúc hành lá và đánh tan 2 quả trứng gà.', 'Không luộc mì quá mềm vì sợi mì còn tiếp tục chín và thấm sốt trong chảo nóng ở bước xào.', 4),
('imp-a9710414682c8521_v4_step_3', 'imp-a9710414682c8521', 3, 'cook', 'Xào nhanh thịt bò trên lửa lớn rồi trút riêng', 'Làm nóng chảo rộng với 15 ml dầu ăn trên lửa lớn nhất, cho thịt bò đã ướp vào đảo nhanh tay 2 phút đến khi thịt vừa chín tái tới thì trút ngay ra đĩa riêng (không xào lâu kẻo thịt dai).', NULL, 2),
('imp-a9710414682c8521_v4_step_4', 'imp-a9710414682c8521', 4, 'cook', 'Phi thơm tỏi, đánh tơi trứng và xào bắp cải giòn ngọt', 'Thêm 10 ml dầu ăn còn lại vào chảo trên lửa vừa, phi thơm tỏi băm 30 giây. Đổ trứng gà đánh tan vào để yên 15 giây cho se mặt rồi đảo tơi thành miếng vừa. Cho bắp cải vào xào lửa lớn 2 phút (thêm 30 ml nước lọc nếu chảo hơi khô) đến khi bắp cải vừa chín giòn.', NULL, NULL),
('imp-a9710414682c8521_v4_step_5', 'imp-a9710414682c8521', 5, 'cook', 'Xào mì thấm sốt xì dầu và áp chảo xém cạnh', 'Cho mì trứng đã luộc vào chảo, rưới toàn bộ chén sốt xì dầu dầu hào vào đảo đều 2 phút cho sợi mì thấm màu nâu bóng đẹp. Dàn phẳng mì ra mặt chảo giữ yên 20 giây cho một mặt hơi xém thơm mùi khói rồi lật đảo thêm một lượt.', 'Áp chảo để sợi mì hơi xém nâu nhẹ giúp món Pad See Ew dậy hương vị thơm bùi đặc trưng khó cưỡng.', NULL),
('imp-a9710414682c8521_v4_step_6', 'imp-a9710414682c8521', 6, 'finish', 'Trộn lại thịt bò, rắc tiêu hành và dọn nóng', 'Cho thịt bò đã xào (gạn bỏ phần nước thịt đọng) trở lại chảo cùng hành lá cắt khúc, đảo nhanh 30 giây cho thịt bò chín hoàn toàn và quyện đều với mì. Tắt bếp, rắc 1,5 g tiêu đen xay lên trên rồi gắp ra đĩa dùng nóng.', 'Gạn bỏ phần nước thịt bò đọng lại trên đĩa trước khi trút vào chảo để sợi mì luôn ráo bóng và không bị nhão.', NULL),
('imp-c64c83ef34771b5a_v4_step_1', 'imp-c64c83ef34771b5a', 1, 'prep', 'Sơ chế thảo mộc tạo hương Thái', 'Bóc bỏ lớp bẹ già bên ngoài của 2 cây sả tươi, dùng sống dao đập dập phần gốc rồi cắt khúc dài khoảng 8 cm. Củ riềng tươi cạo vỏ, thái 4 lát mỏng. Lá chanh Thái rửa sạch rồi dùng tay xé đôi bỏ gân cứng; ớt hiểm đỏ đập dập nhẹ. Vắt 1,5 quả chanh tươi lấy khoảng 30 ml nước cốt để riêng.', 'Đập dập sả và xé rách lá chanh Thái ngay trước khi nấu giúp tinh dầu thơm thoát ra mạnh mẽ nhất mà không làm đắng nước dùng.', NULL),
('imp-c64c83ef34771b5a_v4_step_2', 'imp-c64c83ef34771b5a', 2, 'prep', 'Chuẩn bị nấm đùi gà, đậu phụ và rau thơm', 'Dùng khăn ẩm lau sạch 350 g nấm đùi gà rồi cắt bỏ chân nấm, thái lát vát dày 0,5 cm cho vừa miệng. Cà chua rửa sạch, bổ 8 múi cau. Đậu phụ non cắt khối vuông cạnh 2 cm đặt riêng ra đĩa. Hành lá và ngò rí rửa sạch, để ráo rồi thái nhỏ.', 'Tránh ngâm nấm đùi gà quá lâu trong nước vì nấm hút nước sẽ nhão và giảm vị ngọt tự nhiên khi nấu.', NULL),
('imp-c64c83ef34771b5a_v4_step_3', 'imp-c64c83ef34771b5a', 3, 'cook', 'Xào sơ cà chua và nấm dậy vị ngọt', 'Đặt nồi lên bếp ở lửa vừa, làm nóng 10 ml dầu ăn thực vật rồi cho một nửa phần cà chua bổ múi cùng nấm đùi gà vào đảo nhanh trong 2 phút đến khi nấm hơi săn mặt và dậy mùi thơm nhẹ.', NULL, 2),
('imp-c64c83ef34771b5a_v4_step_4', 'imp-c64c83ef34771b5a', 4, 'cook', 'Ninh nước dùng sả riềng lá chanh', 'Đổ 950 ml nước lọc vào nồi nấm, thả sả tươi đập dập, riềng tươi thái lát và lá chanh Thái vào đun lửa lớn đến khi sôi bùng. Hạ lửa vừa và nấu sôi lăn riu trong 5 phút cho tinh dầu thảo mộc hòa quyện vào nước dùng, hớt bỏ bọt nếu có.', 'Thời gian ninh 5 phút giúp nước dùng chuyển hơi ánh xanh dịu và thơm nồng mùi sả riềng mà lá chanh không bị nồng hắc.', 5),
('imp-c64c83ef34771b5a_v4_step_5', 'imp-c64c83ef34771b5a', 5, 'cook', 'Nấu chín nấm, đậu phụ non và cà chua', 'Thả nhẹ phần cà chua còn lại, ớt hiểm đỏ và đậu phụ non vào nồi. Nêm 8 g hạt nêm chay nấm hương và 8 g đường cát trắng, khuấy thật nhẹ tay theo thành nồi trong 3 phút ở lửa vừa để đậu phụ nóng đều mà không bị vỡ nát, nấm chín mềm ngọt.', NULL, 3),
('imp-c64c83ef34771b5a_v4_step_6', 'imp-c64c83ef34771b5a', 6, 'finish', 'Tắt bếp nêm chanh, nước mắm chay và hoàn thiện', 'Tắt bếp rồi mới rót 30 ml nước mắm chay và 30 ml nước cốt chanh tươi vào khuấy nhẹ cho hòa vị chua thanh dịu. Vớt bỏ bớt xác sả, riềng và lá chanh Thái, múc canh ra tô, rắc hành lá và ngò rí lên trên rồi dùng nóng.', 'Luôn tắt bếp trước khi cho nước cốt chanh tươi để giữ trọn vị chua thanh mát và tránh làm tinh dầu vỏ chanh gây vị đắng.', NULL),
('imp-a71f6ef791b463ea_v4_step_1', 'imp-a71f6ef791b463ea', 1, 'prep', 'Làm sạch tôm và sơ chế rau gia vị', 'Tôm sú rửa sạch, bóc bỏ đầu và vỏ thân nhưng giữ lại chóp đuôi cho đẹp, dùng dao khía nhẹ sống lưng rút sạch chỉ đen. Bóc vỏ già của 3 cây sả tươi: lấy 1 cây đập dập để nấu nước chần, 2 cây còn lại thái lát vát thật mỏng phần thân trắng non. Bóc vỏ hành tím thái lát mỏng, băm nhuyễn tỏi khô và 2 quả ớt hiểm đỏ; thái sợi 1 quả ớt còn lại. Rửa sạch ngò gai, lá bạc hà và hành lá rồi để thật ráo.', 'Thái sả tươi càng mỏng theo lát chéo thì khi trộn gỏi sẽ thơm dịu, giòn mềm và không bị xơ cứng khi nhai.', NULL),
('imp-a71f6ef791b463ea_v4_step_2', 'imp-a71f6ef791b463ea', 2, 'cook', 'Chần chín tôm với nước sả thơm', 'Đun sôi 400 ml nước lọc cùng cây sả đập dập trên lửa lớn. Khi nước sôi bùng, thả toàn bộ 500 g tôm sú vào chần trong 2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong tròn và thịt trắng đục chín hoàn toàn.', 'Không luộc tôm quá lâu làm thịt tôm mất nước và bị bở; vừa thấy thân tôm cong săn và chuyển màu đỏ hồng hoàn toàn là vớt ngay.', 2),
('imp-a71f6ef791b463ea_v4_step_3', 'imp-a71f6ef791b463ea', 3, 'prep', 'Ngâm tôm lạnh giữ độ giòn sần sật', 'Vớt tôm vừa chần chín thả ngay vào tô 200 ml nước lọc lạnh có đá trong 3 phút để hãm nhiệt giúp thịt tôm giòn chắc, đồng thời ngâm chung hành tím thái lát cho bớt vị hăng. Sau đó vớt tôm và hành tím ra rổ, dùng khăn giấy thấm thật ráo nước.', NULL, 3),
('imp-a71f6ef791b463ea_v4_step_4', 'imp-a71f6ef791b463ea', 4, 'sauce', 'Pha nước sốt trộn gỏi chua cay Thái', 'Trong chén nhỏ, hòa tan 30 ml nước mắm ngon, 20 g đường cát trắng, 20 ml tương ớt Thái và 45 ml nước cốt chanh tươi đến khi đường tan hết. Cho toàn bộ tỏi băm và 2 quả ớt hiểm băm vào khuấy đều để tạo hỗn hợp sốt sánh thơm đủ vị chua, cay, mặn, ngọt.', 'Nếm thử nước sốt sao cho vị hơi đậm đà một chút vì khi trộn với tôm và rau thơm sẽ dịu lại vừa miệng.', NULL),
('imp-a71f6ef791b463ea_v4_step_5', 'imp-a71f6ef791b463ea', 5, 'finish', 'Trộn gỏi tôm sả chanh nhẹ tay', 'Cho tôm đã ráo nước vào âu trộn lớn cùng sả non thái mỏng, hành tím, ngò gai và hành lá. Rưới từ từ nước sốt đã pha lên, đảo nhẹ tay trong 1 phút cho từng con tôm và lát sả áo đều lớp sốt bóng đẹp.', NULL, NULL),
('imp-a71f6ef791b463ea_v4_step_6', 'imp-a71f6ef791b463ea', 6, 'finish', 'Hoàn thiện với lá bạc hà và thưởng thức ngay', 'Cho gỏi tôm ra đĩa sâu lòng, rắc lá bạc hà tươi và ớt sợi lên trên cùng để giữ màu xanh tươi mát không bị thâm. Dọn dùng ngay khi gỏi còn mát lạnh và giòn ngọt.', NULL, NULL),
('imp-9236740e2b55e8a1_v4_step_1', 'imp-9236740e2b55e8a1', 1, 'prep', 'Sơ chế thịt gà, cơm nguội và pha mắm ớt Thái', 'Thịt đùi gà lọc xương thái hạt lựu 1,5 cm, ướp nhanh trong 5 phút với 5 ml xì dầu nhạt và 1 g tiêu trắng xay. Đánh tơi 450 g cơm nguội bằng tay cho các hạt tách rời. Thái hạt lựu cà rốt; băm nhỏ tỏi và hành tím; thái khoanh hành lá, ngò rí; thái lát dưa leo và cắt múi cau chanh. Pha chén nước mắm ớt Prik Nam Pla với 20 ml nước mắm ngon, 3 quả ớt hiểm thái lát, 1/3 lượng tỏi băm và vắt vài giọt nước cốt chanh.', 'Dùng cơm nguội để tủ mát qua đêm giúp hạt cơm khô bề mặt, khi rang không bị bết dính và bắt gia vị rất đều.', 5),
('imp-9236740e2b55e8a1_v4_step_2', 'imp-9236740e2b55e8a1', 2, 'cook', 'Phi thơm tỏi hành và xào chín thịt đùi gà', 'Đun nóng chảo sâu lòng trên lửa vừa-lớn với 15 ml dầu ăn thực vật. Cho 2/3 phần tỏi băm và hành tím băm vào phi khoảng 45 giây đến khi dậy mùi thơm, tiếp tục cho thịt đùi gà và cà rốt vào đảo đều 3–4 phút cho đến khi thịt gà chuyển trắng đục, săn cạnh và chín hoàn toàn bên trong.', NULL, 4),
('imp-9236740e2b55e8a1_v4_step_3', 'imp-9236740e2b55e8a1', 3, 'cook', 'Chiên tơi trứng gà ngay trong chảo', 'Gạt thịt gà và cà rốt sang một bên chảo, thêm 10 ml dầu ăn thực vật vào khoảng trống còn lại, đập 2 quả trứng gà vào. Chờ khoảng 20 giây cho lòng trắng hơi se mặt rồi dùng muôi đánh tơi thành từng mảng trứng mềm xốp trước khi trộn chung với thịt gà.', NULL, NULL),
('imp-9236740e2b55e8a1_v4_step_4', 'imp-9236740e2b55e8a1', 4, 'cook', 'Rang cơm nguội trên lửa lớn cho tơi hạt', 'Trút toàn bộ 450 g cơm nguội vào chảo, tăng lên lửa lớn và đảo tơi liên tục khoảng 3 phút cho hạt cơm nóng đều, săn lại và quyện cùng trứng, thịt gà. Thỉnh thoảng để cơm yên 10 giây rồi mới đảo để tạo mùi thơm xém chảo nhẹ.', 'Giữ lửa lớn và không đè nát hạt cơm giúp đĩa Khao Pad tơi bóng và có hương thơm đặc trưng như ngoài hàng.', 3),
('imp-9236740e2b55e8a1_v4_step_5', 'imp-9236740e2b55e8a1', 5, 'cook', 'Nêm xì dầu, nước mắm và đường cho cơm thấm vị', 'Rưới 15 ml xì dầu nhạt và 15 ml nước mắm ngon quanh thành chảo nóng để gia vị bốc mùi thơm, rắc 8 g đường cát trắng và 1 g tiêu trắng xay còn lại. Đảo nhanh tay thêm 2 phút cho hạt cơm lên màu vàng nhạt óng ả và thấm đều gia vị.', 'Rưới xì dầu nhạt và nước mắm men theo thành chảo nóng thay vì đổ trực tiếp vào giữa cơm giúp gia vị bốc hương thơm chảo wok và bám đều từng hạt.', 2),
('imp-9236740e2b55e8a1_v4_step_6', 'imp-9236740e2b55e8a1', 6, 'finish', 'Tắt bếp trộn hành lá và bày đĩa ăn kèm', 'Tắt bếp ngay rồi cho hành lá và ngò rí vào đảo nhanh 10 giây cho vừa dậy mùi thơm mà vẫn giữ màu xanh tươi. Xới cơm chiên gà ra đĩa, xếp dưa leo thái lát, múi chanh tươi bên cạnh và dọn nóng cùng chén nước mắm ớt Prik Nam Pla.', NULL, NULL),
('imp-a1904f60d9f4f10e_v4_step_1', 'imp-a1904f60d9f4f10e', 1, 'prep', 'Chuẩn bị tỏi thái lát, ngò tây và phô mai', 'Bóc vỏ 1 củ tỏi khô rồi thái thành các lát mỏng đều nhau. Rửa sạch 12 g ngò tây tươi, thấm khô và thái nhỏ phần lá. Bào mịn sẵn 35 g phô mai Parmesan và chuẩn bị sẵn 70 g bơ lạt chia làm hai phần bằng nhau.', 'Thái tỏi thành lát mỏng đều giúp tỏi tiết hương thơm ngọt từ từ trong bơ mà không dễ bị cháy xém như tỏi băm nhuyễn.', NULL),
('imp-a1904f60d9f4f10e_v4_step_2', 'imp-a1904f60d9f4f10e', 2, 'cook', 'Đun nước muối sôi và luộc mì Spaghetti', 'Đun sôi mạnh 2500 ml nước lọc trong nồi lớn, hòa tan 15 g muối ăn rồi thả 300 g mì Ý Spaghetti khô vào luộc khoảng 8 phút (ít hơn 1 phút so với hướng dẫn bao bì để mì còn độ dai al dente). Trước khi vớt mì, múc giữ lại khoảng 120 ml nước luộc mì.', 'Không nên dùng quá nhiều nước khi luộc mì để giữ nồng độ tinh bột cao trong nước luộc, giúp sốt bơ nhanh chóng sánh bóng khi nhũ hóa.', 8),
('imp-a1904f60d9f4f10e_v4_step_3', 'imp-a1904f60d9f4f10e', 3, 'sauce', 'Phi thơm tỏi lát và ớt vảy trong bơ lạt', 'Trong lúc luộc mì, đặt chảo lớn lên bếp ở lửa nhỏ, cho 35 g bơ lạt vào đun tan chảy nhẹ. Thả tỏi thái lát cùng 1 g ớt vảy khô vào đảo đều khoảng 1 phút đến khi tỏi sủi bọt nhẹ, dậy mùi thơm và vừa ngả vàng nhạt.', 'Tuyệt đối giữ lửa nhỏ để tỏi chỉ ngả vàng nhạt; nếu để tỏi chuyển nâu sậm, vị đắng sẽ làm hỏng cả chảo sốt bơ.', 1),
('imp-a1904f60d9f4f10e_v4_step_4', 'imp-a1904f60d9f4f10e', 4, 'cook', 'Nhũ hóa mì cùng bơ và nước luộc mì', 'Dùng kẹp gắp trực tiếp mì Spaghetti vừa luộc sang chảo bơ tỏi, rót vào khoảng 60 ml nước luộc mì giữ lại. Bật lửa vừa, đảo và xóc chảo liên tục trong 1–2 phút cho tinh bột trong nước luộc quyện cùng bơ thành lớp sốt sánh bóng bám đều sợi mì; thêm chút nước luộc nếu thấy khô.', NULL, 2),
('imp-a1904f60d9f4f10e_v4_step_5', 'imp-a1904f60d9f4f10e', 5, 'finish', 'Đánh bóng bơ lạnh và trộn phô mai Parmesan', 'Cho nốt 35 g bơ lạt còn lại vào chảo đảo tan đều, sau đó tắt hẳn bếp và nhấc chảo khỏi nguồn nhiệt. Thêm 25 g phô mai Parmesan bào mịn, 3 g muối ăn (nêm từ từ theo khẩu vị), 1 g tiêu đen xay và 2/3 lượng ngò tây tươi thái nhỏ, đảo nhanh tay cho phô mai tan quyện mượt mà.', 'Luôn tắt bếp trước khi cho phô mai Parmesan để nhiệt độ dịu xuống, giúp phô mai tan quyện thành kem mịn mà không bị vón cục tách dầu.', NULL),
('imp-a1904f60d9f4f10e_v4_step_6', 'imp-a1904f60d9f4f10e', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Gắp mì xoắn gọn ra 3 đĩa sâu lòng khi còn nóng hổi, rưới hết phần sốt bơ tỏi trong chảo lên trên rồi rắc nốt 10 g phô mai Parmesan bào cùng phần ngò tây tươi còn lại.', NULL, NULL),
('imp-cc5f58548e934d9e_v4_step_1', 'imp-cc5f58548e934d9e', 1, 'prep', 'Sơ chế tôm tươi và các loại gia vị thơm', 'Bóc vỏ 400 g tôm tươi, bỏ đầu và rút sạch chỉ đen dọc sống lưng, rửa nhanh rồi thấm thật khô bằng khăn giấy. Ướp nhẹ tôm với 1 g muối ăn và 0,5 g tiêu đen xay. Thái lát mỏng 3–4 tép tỏi khô, bỏ hạt thái lát 1 quả ớt hiểm tươi, băm nhỏ 15 g ngò tây tươi và bào lấy phần vỏ vàng của 1/2 quả chanh vàng.', 'Thấm thật khô thịt tôm giúp tôm khi áp chảo nhanh săn chín, lên mùi thơm mà không bị tiết nước làm loãng dầu ô liu.', NULL),
('imp-cc5f58548e934d9e_v4_step_2', 'imp-cc5f58548e934d9e', 2, 'cook', 'Luộc mì Ý trong nước muối sôi già', 'Đun sôi mạnh 2500 ml nước lọc cùng 15 g muối ăn, cho 250 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để mì vừa đạt độ al dente. Trước khi vớt, múc giữ lại 120 ml nước luộc mì giàu tinh bột.', NULL, 8),
('imp-cc5f58548e934d9e_v4_step_3', 'imp-cc5f58548e934d9e', 3, 'sauce', 'Phi tỏi ớt và xào chín nhanh thịt tôm', 'Làm nóng chảo rộng trên lửa vừa với 45 ml dầu ô liu và 15 g bơ lạt. Cho tỏi thái lát và ớt hiểm vào phi thơm khoảng 1–2 phút đến khi tỏi vừa ngả vàng nhạt. Tăng lên lửa lớn, thả tôm đã ướp vào đảo đều khoảng 2–3 phút đến khi tôm cong chữ C và chuyển màu hồng đỏ chín hoàn toàn thì trút tôm ra đĩa riêng.', 'Vớt tôm ra ngay khi vừa chuyển hồng chín tới giúp thịt tôm giữ được độ giòn ngọt, không bị khô dai khi đảo chung với mì.', 3),
('imp-cc5f58548e934d9e_v4_step_4', 'imp-cc5f58548e934d9e', 4, 'cook', 'Đảo mì cùng nước luộc tạo sốt sánh nhẹ', 'Hạ chảo về lửa vừa, gắp mì Ý đã luộc cùng thịt tôm trở lại chảo dầu tỏi ớt. Rót thêm khoảng 60 ml nước luộc mì vào, xóc đều tay trong 1–2 phút để nước luộc tinh bột và dầu ô liu nhũ hóa thành lớp sốt sánh nhẹ bám đều từng sợi mì.', NULL, 2),
('imp-cc5f58548e934d9e_v4_step_5', 'imp-cc5f58548e934d9e', 5, 'finish', 'Hoàn thiện hương chanh vàng và phô mai', 'Tắt bếp và nhấc chảo ra ngoài. Thêm 20 g bơ lạt còn lại, 15 g phô mai Parmesan bào mịn, phần vỏ bào cùng vài giọt nước cốt chanh vàng, 15 g ngò tây băm và 0,5 g tiêu đen xay còn lại vào đảo nhanh tay đến khi bơ tan bóng mượt.', 'Bào vỏ chanh vàng chỉ lấy lớp tinh dầu bên ngoài, tránh cùi trắng vì sẽ gây vị đắng; cho vào sau khi tắt bếp giúp giữ trọn hương thơm tươi mát.', NULL),
('imp-cc5f58548e934d9e_v4_step_6', 'imp-cc5f58548e934d9e', 6, 'finish', 'Trình bày ra đĩa và dùng nóng ngay', 'Chia mì và tôm ra 3 đĩa sâu lòng khi còn nóng hổi, rưới hết phần sốt dầu tỏi thơm dưới chảo lên trên và thưởng thức ngay.', NULL, NULL),
('imp-8fdcddab058d5f65_v4_step_1', 'imp-8fdcddab058d5f65', 1, 'prep', 'Sơ chế cà chua tươi, tỏi và húng quế Tây', 'Rửa sạch 3,5 quả cà chua chín mọng, bỏ cuống rồi cắt miếng nhỏ cỡ 1,5 cm (nếu dùng cà chua bi chỉ cần bổ đôi). Bóc vỏ và đập dập 2–3 tép tỏi khô; rửa nhẹ 8 g lá húng quế Tây để thật ráo nước.', NULL, NULL),
('imp-8fdcddab058d5f65_v4_step_2', 'imp-8fdcddab058d5f65', 2, 'cook', 'Luộc mì Ý đạt độ dai al dente', 'Đun sôi mạnh 2500 ml nước lọc cùng 14 g muối ăn, thả 260 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để sợi mì giữ lõi hơi dai. Trước khi vớt mì, múc giữ lại 100 ml nước luộc mì.', 'Luộc mì ít hơn hướng dẫn bao bì 1 phút vì sợi mì còn tiếp tục chín trong chảo sốt nóng, giữ được độ dai chuẩn al dente.', 8),
('imp-8fdcddab058d5f65_v4_step_3', 'imp-8fdcddab058d5f65', 3, 'sauce', 'Phi thơm tỏi và xào cà chua tươi', 'Đun nóng 35 ml dầu ô liu trong chảo lớn ở lửa vừa-nhỏ, cho tỏi đập dập vào phi thơm khoảng 1–2 phút mà không để tỏi chuyển nâu. Tăng lên lửa lớn, trút toàn bộ cà chua cắt nhỏ cùng 4 g muối ăn vào đảo đều 4 phút cho cà chua mềm xẹp và tiết nước ngọt.', 'Xào nhanh cà chua tươi trên lửa lớn giúp giữ trọn hương vị tươi mát và độ ngọt thanh tự nhiên, không bị nhừ nát quá mức.', 4),
('imp-8fdcddab058d5f65_v4_step_4', 'imp-8fdcddab058d5f65', 4, 'sauce', 'Nấu sánh sốt cùng cà chua cô đặc và húng quế', 'Thêm 10 g cà chua cô đặc vào chảo đảo tan đều, hạ lửa vừa và đun liu riu thêm 5 phút đến khi nước sốt hơi sánh quyện. Tắt bếp, xé nhỏ 5 g lá húng quế Tây cho vào cùng 1 g tiêu đen xay rồi đảo đều (có thể gắp bỏ xác tỏi nếu thích vị nhẹ).', 'Thêm lá húng quế Tây vào giai đoạn cuối giúp giữ nguyên mùi thơm dịu đặc trưng không bị bay hơi.', 5),
('imp-8fdcddab058d5f65_v4_step_5', 'imp-8fdcddab058d5f65', 5, 'cook', 'Xóc mì trực tiếp trong chảo sốt', 'Bật bếp lại ở lửa vừa, gắp mì Spaghetti vừa luộc vào thẳng chảo sốt cà chua. Đảo và xóc đều tay khoảng 1 phút, thêm từng chút nước luộc mì giữ lại nếu thấy khô để sốt bám bóng mượt vào từng sợi mì.', NULL, 1),
('imp-8fdcddab058d5f65_v4_step_6', 'imp-8fdcddab058d5f65', 6, 'finish', 'Trình bày và dọn nóng', 'Gắp mì ra 3 đĩa sâu lòng khi còn nóng hổi, rắc nốt 3 g lá húng quế Tây xé nhỏ và 25 g phô mai Parmesan bào mịn lên trên trước khi thưởng thức.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_1', 'imp-d4d1de72f13e8f30', 1, 'prep', 'Băm nhuyễn rau củ nền và thịt xông khói', 'Gọt vỏ cà rốt, rửa sạch cần tây, bóc vỏ hành tây rồi băm thật nhuyễn cả ba loại để tạo nền hương vị ngọt thanh. Thái nhỏ 150 g thịt ba chỉ xông khói và đun ấm sẵn 260 ml nước dùng rau củ trên bếp nhỏ.', 'Rau củ băm càng nhỏ mịn thì khi ninh lâu sẽ tan quyện vào sốt Ragù tạo độ sánh ngọt tự nhiên.', NULL),
('imp-d4d1de72f13e8f30_v4_step_2', 'imp-d4d1de72f13e8f30', 2, 'cook', 'Xào rau củ và áp chảo vàng thịt bò xay', 'Đun nóng 40 ml dầu ô liu trong nồi đế dày trên lửa vừa, cho thịt ba chỉ xông khói vào đảo 3–4 phút cho tươm mỡ vàng nhẹ. Thêm cà rốt, cần tây và hành tây băm vào xào 6 phút cho mềm trong. Tiếp theo cho 500 g thịt bò xay vào, tăng lửa lớn, dằm tơi và đảo khoảng 8–10 phút đến khi thịt săn vàng xém cạnh.', 'Phải áp chảo trên lửa lớn cho thịt bò xay săn vàng xém mặt thay vì xám nước để sốt Ragù có vị đậm đà thơm nức.', 18),
('imp-d4d1de72f13e8f30_v4_step_3', 'imp-d4d1de72f13e8f30', 3, 'sauce', 'Khử rượu vang và ninh chậm sốt bò bằm Ragù', 'Rót 80 ml rượu vang đỏ vào nồi thịt bò, cạo sạch lớp cháy thơm dưới đáy nồi và đun sôi khoảng 3 phút cho bay hết mùi cồn. Khuấy vào 300 g cà chua nghiền đóng hộp Ý, 25 g cà chua cô đặc, 5 g muối ăn, 2 g tiêu đen xay và 1 vá nước dùng rau củ nóng. Đậy nắp hé, hạ lửa thật nhỏ và ninh liu riu ít nhất 60–90 phút, thỉnh thoảng đảo và châm thêm nước dùng nóng khi cạn.', NULL, 75),
('imp-d4d1de72f13e8f30_v4_step_4', 'imp-d4d1de72f13e8f30', 4, 'sauce', 'Nấu sốt sữa trắng Béchamel sánh mịn', 'Đun nóng già 600 ml sữa tươi không đường (không để sôi trào). Trong nồi khác trên lửa vừa, làm tan chảy 38 g bơ lạt, đổ 38 g bột mì đa dụng vào khuấy liên tục 2 phút thành hỗn hợp roux vàng nhạt. Rót sữa nóng vào làm 3 đợt, mỗi lần vừa rót vừa khuấy mạnh bằng phới lồng cho tan mịn rồi đun 5 phút đến khi sốt sánh phủ lưng muỗng; nêm 3 g muối ăn và 1 g nhục đậu khấu xay.', 'Đổ sữa nóng từng phần nhỏ vào hỗn hợp bơ bột và khuấy liên tục giúp sốt Béchamel mịn mượt tuyệt đối, không bị vón cục.', 8),
('imp-d4d1de72f13e8f30_v4_step_5', 'imp-d4d1de72f13e8f30', 5, 'prep', 'Làm nóng lò và chuẩn bị lá mì Lasagna', 'Bật lò nướng làm nóng trước ở 175°C chế độ hai lửa trên-dưới. Nếu dùng lá mì Lasagna loại cần luộc trước, đun sôi 1500 ml nước lọc với 2 g muối ăn, chần từng lá mì khoảng 30–40 giây rồi trải phẳng lên khăn sạch (không xếp chồng); nếu dùng loại nướng trực tiếp thì bỏ qua bước chần.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_6', 'imp-d4d1de72f13e8f30', 6, 'cook', 'Xếp xen kẽ 5 tầng sốt và lá mì vào khuôn', 'Phết đều 4 g bơ lạt xuống đáy và thành khuôn nướng chữ nhật khoảng 30×20 cm. Trải một lớp mỏng sốt Béchamel và sốt Ragù xuống đáy khuôn, đặt một lớp lá mì Lasagna phủ kín, rồi lần lượt phết sốt Ragù, sốt Béchamel và rắc một phần phô mai Parmesan bào mịn. Lặp lại quy trình đến tầng thứ 5, trên cùng phủ sốt Ragù, sốt Béchamel, rắc dày phần phô mai Parmesan còn lại và rải vụn 3 g bơ lạt.', NULL, NULL),
('imp-d4d1de72f13e8f30_v4_step_7', 'imp-d4d1de72f13e8f30', 7, 'finish', 'Nướng vàng phồng và để nghỉ trước khi cắt', 'Đặt khuôn Lasagna vào ngăn giữa lò nướng ở 175°C trong khoảng 35–40 phút đến khi mặt phô mai vàng ruộm và phần sốt ở mép khuôn sôi sủi bọt (có thể che nhẹ giấy bạc trong 15 phút đầu nếu mặt vàng quá nhanh). Lấy khay ra để nghỉ 10 phút cho các lớp định hình chắc chắn rồi cắt miếng vuông dùng nóng.', NULL, 40),
('imp-3fd9eb5a7c40c3c0_v4_step_1', 'imp-3fd9eb5a7c40c3c0', 1, 'prep', 'Sơ chế gà, hành tây và hâm nóng nước dùng gà', 'Thấm thật khô 300 g ức gà phi lê rồi cắt thành khối hạt lựu 2 cm. Băm nhỏ 1 củ hành tây, băm nhuyễn 2 tép tỏi khô và băm nhỏ 10 g ngò tây tươi. Đổ 1200 ml nước dùng gà vào nồi riêng, đun sôi nhẹ rồi giữ nóng liu riu trên bếp phụ suốt quá trình nấu.', 'Nước dùng gà phải luôn giữ nóng; nếu châm nước nguội vào chảo gạo đang sôi sẽ làm hạt gạo sốc nhiệt và chín sượng không đều.', NULL),
('imp-3fd9eb5a7c40c3c0_v4_step_2', 'imp-3fd9eb5a7c40c3c0', 2, 'cook', 'Áp chảo chín vàng hạt lựu ức gà', 'Đun nóng 25 g bơ lạt cùng 15 ml dầu ô liu trong chảo sâu lòng trên lửa vừa-lớn. Thả ức gà vào áp chảo khoảng 5 phút, nêm 2 g muối ăn và 1 g tiêu đen xay, đảo đều đến khi các mặt thịt gà vàng thơm và chín hoàn toàn bên trong rồi gắp ra đĩa riêng.', NULL, 5),
('imp-3fd9eb5a7c40c3c0_v4_step_3', 'imp-3fd9eb5a7c40c3c0', 3, 'cook', 'Xào hành tây và rang hạt gạo Arborio', 'Cùng chiếc chảo đó, thêm 10 ml dầu ô liu ở lửa vừa, cho hành tây và tỏi băm vào xào 4 phút đến khi hành mềm trong. Trút toàn bộ 320 g gạo Ý Arborio (không vo rửa) vào đảo đều liên tục khoảng 2 phút đến khi viền hạt gạo hơi trong lại và tỏa mùi thơm bùi.', 'Không vo gạo Arborio và rang khô nhẹ 2 phút giúp hạt gạo săn lớp vỏ ngoài, giữ độ dẻo dai mà không bị nát bấy khi khuấy.', 6),
('imp-3fd9eb5a7c40c3c0_v4_step_4', 'imp-3fd9eb5a7c40c3c0', 4, 'cook', 'Châm rượu vang và nấu chậm cùng nước dùng gà', 'Rót 100 ml rượu vang trắng khô vào chảo gạo, khuấy đều 1–2 phút đến khi bay hết mùi cồn. Tiếp tục múc từng muôi nước dùng gà nóng châm vào xấp mặt gạo, khuấy nhẹ đều tay đến khi gạo hút gần cạn nước mới châm muôi tiếp theo. Lặp lại quá trình này trong khoảng 18 phút đến khi hạt gạo mềm dẻo bên ngoài và còn lõi hơi sần nhẹ.', NULL, 18),
('imp-3fd9eb5a7c40c3c0_v4_step_5', 'imp-3fd9eb5a7c40c3c0', 5, 'cook', 'Trộn thịt gà và nêm gia vị', 'Khi gạo gần chín tới (khoảng 3–4 phút cuối), trút toàn bộ ức gà đã áp chảo vào chảo cơm, châm thêm chút nước dùng gà nóng nếu thấy đặc và đảo nhẹ 3 phút cho thịt gà hòa vị cùng cơm. Nếm thử rồi nêm thêm khoảng 3 g muối ăn và 1 g tiêu đen xay cho vừa miệng.', NULL, NULL),
('imp-3fd9eb5a7c40c3c0_v4_step_6', 'imp-3fd9eb5a7c40c3c0', 6, 'finish', 'Đánh bóng bơ phô mai (Mantecatura) và dọn nóng', 'Tắt hẳn bếp, cho 25 g bơ lạt còn lại và 40 g phô mai Parmesan bào mịn vào chảo cơm, khuấy nhanh tay đến khi bơ và phô mai tan quyện thành lớp sốt kem bóng mượt bao đều từng hạt gạo. Múc ra 4 đĩa sâu lòng, rắc 10 g phô mai Parmesan còn lại cùng ngò tây băm lên trên và dùng nóng ngay.', 'Đánh bóng bơ và phô mai sau khi tắt bếp là kỹ thuật chuẩn Ý giúp Risotto sánh kem mịn màng thay vì bị tách dầu.', NULL),
('imp-4c5955ef4919d61a_v4_step_1', 'imp-4c5955ef4919d61a', 1, 'prep', 'Kiểm tra thịt cua và sơ chế gia vị thơm', 'Dùng tay kiểm tra nhẹ nhàng 250 g thịt cua biển gỡ sẵn để loại bỏ sạch các mảnh vỏ hay sụn cứng còn sót. Bóc vỏ đập dập 2–3 tép tỏi khô, bỏ hạt thái lát 2 quả ớt tươi, băm thật nhuyễn 12 g ngò tây tươi và bào lấy phần vỏ vàng thơm của 1 quả chanh vàng (tránh phần cùi trắng) rồi vắt sẵn 15 ml nước cốt.', NULL, NULL),
('imp-4c5955ef4919d61a_v4_step_2', 'imp-4c5955ef4919d61a', 2, 'cook', 'Luộc mì Spaghetti và giữ lại nước luộc', 'Đun sôi mạnh 3000 ml nước lọc cùng 15 g muối ăn, cho 360 g mì Ý Spaghetti vào luộc khoảng 8 phút (ít hơn hướng dẫn bao bì 1 phút) để sợi mì đạt độ dai al dente. Trước khi vớt mì, múc giữ lại 150 ml nước luộc mì.', 'Múc nước luộc mì ngay trước khi vớt để giữ phần tinh bột tự nhiên, giúp sốt dầu ô liu nhanh chóng nhũ hóa sánh mượt.', 8),
('imp-4c5955ef4919d61a_v4_step_3', 'imp-4c5955ef4919d61a', 3, 'sauce', 'Phi thơm nhẹ tỏi ớt và làm nóng thịt cua', 'Đặt chảo rộng lên bếp, cho 35 ml dầu ô liu, tỏi đập dập và ớt thái lát vào chảo ngay từ khi dầu còn nguội rồi bật lửa nhỏ. Phi từ từ 2–3 phút cho dầu dậy mùi thơm mà tỏi không bị vàng cháy, sau đó gắp bỏ xác tỏi. Cho 250 g thịt cua biển vào chảo đảo thật nhẹ tay khoảng 1–2 phút cho cua nóng đều và thấm dầu thơm.', 'Phi tỏi từ dầu nguội trên lửa nhỏ và gắp bỏ tỏi trước khi chuyển vàng giúp dầu thơm dịu mà không bị đắng; đồng thời không đảo mạnh làm nát thớ thịt cua.', 3),
('imp-4c5955ef4919d61a_v4_step_4', 'imp-4c5955ef4919d61a', 4, 'sauce', 'Nhũ hóa sốt trắng từ nước luộc mì', 'Múc khoảng 80 ml nước luộc mì đang nóng rót vào chảo thịt cua, nêm 3 g muối ăn rồi lắc nhẹ chảo trên lửa vừa khoảng 1 phút cho dầu ô liu và tinh bột trong nước luộc nhũ hóa thành lớp sốt hơi sánh bao quanh thịt cua.', NULL, NULL),
('imp-4c5955ef4919d61a_v4_step_5', 'imp-4c5955ef4919d61a', 5, 'cook', 'Xóc mì Spaghetti trong chảo sốt cua', 'Vớt mì Ý Spaghetti đang al dente cho thẳng vào chảo sốt cua, đảo và xóc chảo trên lửa vừa khoảng 1 phút để từng sợi mì hút trọn vị ngọt của cua và nước sốt. Nếu thấy khô, châm thêm từng chút nước luộc mì còn lại đến khi sốt bóng đều.', NULL, 1),
('imp-4c5955ef4919d61a_v4_step_6', 'imp-4c5955ef4919d61a', 6, 'finish', 'Trộn vỏ chanh vàng, ngò tây và dọn nóng', 'Tắt bếp, rắc phần vỏ chanh vàng bào mịn, vài giọt nước cốt chanh vàng và 12 g ngò tây băm nhỏ vào chảo, rưới thêm 10 ml dầu ô liu còn lại rồi trộn đều một lượt. Chia mì ra 4 đĩa sâu lòng và dùng nóng ngay.', 'Cho vỏ chanh và ngò tây sau khi tắt bếp để nhiệt dư làm dậy hương tươi mát mà không làm mất mùi tinh dầu tự nhiên.', NULL),
('imp-c398c169dc196c4e_v4_step_1', 'imp-c398c169dc196c4e', 1, 'prep', 'Rạch lưng rút chỉ tôm và sơ chế gia vị', 'Rửa sạch 600 g tôm sú hoặc tôm thẻ lớn dưới vòi nước lạnh, giữ nguyên vỏ để chống khô thịt khi nướng. Dùng kéo hoặc mũi dao nhọn xẻ một đường dọc sống lưng vỏ tôm, rút bỏ chỉ đen rồi thấm khô. Băm thật nhuyễn 2–3 tép tỏi khô, băm nhỏ 12 g ngò tây tươi và 1 quả ớt tươi bỏ hạt; bào lấy phần vỏ vàng thơm của 1 quả chanh vàng rồi vắt lấy nước cốt, 1/2 quả còn lại cắt múi.', 'Giữ nguyên lớp vỏ ngoài của tôm khi nướng trên lửa lớn giúp giữ trọn độ ẩm ngọt bên trong và tránh thịt tôm bị cháy sém.', NULL),
('imp-c398c169dc196c4e_v4_step_2', 'imp-c398c169dc196c4e', 2, 'marinate', 'Pha sốt dầu chanh tỏi và chia hai phần', 'Trong tô nhỏ, đánh đều 50 ml dầu ô liu, nước cốt và vỏ bào của 1 quả chanh vàng, tỏi băm, 8 g ngò tây băm, ớt tươi băm, 5 g muối ăn và 1,5 g tiêu đen xay. Trích riêng khoảng 2 muỗng canh hỗn hợp sạch này sang chén nhỏ để làm sốt rưới hoàn thiện.', NULL, NULL),
('imp-c398c169dc196c4e_v4_step_3', 'imp-c398c169dc196c4e', 3, 'marinate', 'Ướp thấm gia vị trong thời gian ngắn', 'Cho tôm đã thấm khô vào tô phần sốt ướp còn lại, xóc đều cho gia vị bám vào khe lưng và lớp vỏ tôm. Đậy kín và ướp trong ngăn mát tủ lạnh khoảng 20 phút.', 'Không ướp tôm cùng nước cốt chanh quá 30 phút vì axit chanh sẽ làm biến tính thịt tôm sống khiến tôm mất độ giòn sần.', 20),
('imp-c398c169dc196c4e_v4_step_4', 'imp-c398c169dc196c4e', 4, 'prep', 'Làm nóng vỉ nướng hoặc chảo gang rãnh', 'Làm nóng vỉ nướng hoặc chảo gang rãnh trên lửa lớn đến khi thật nóng rồi dùng cọ phết 10 ml dầu ô liu còn lại lên bề mặt vỉ để chống dính.', NULL, NULL),
('imp-c398c169dc196c4e_v4_step_5', 'imp-c398c169dc196c4e', 5, 'cook', 'Nướng tôm nhanh trên lửa lớn hai mặt', 'Xếp đều tôm lên vỉ hoặc chảo nóng, nướng mỗi mặt khoảng 3–4 phút trên lửa lớn đến khi vỏ tôm chuyển màu cam hồng rực, hơi xém cạnh thơm lừng, phần thịt bên trong chuyển trắng đục hoàn toàn và thân tôm uốn cong hình chữ C.', 'Tránh nướng quá lâu đến khi thân tôm cuộn tròn thành hình chữ O vì lúc đó thịt tôm đã quá chín và bị dai xác.', 7),
('imp-c398c169dc196c4e_v4_step_6', 'imp-c398c169dc196c4e', 6, 'finish', 'Rưới sốt chanh tỏi sạch và dọn nóng', 'Gắp tôm ra đĩa rộng khi còn nóng hổi, rưới đều chén sốt dầu ô liu chanh tỏi sạch đã trích riêng lên trên, rắc nốt 4 g ngò tây băm cùng vài múi chanh vàng tươi bên cạnh và dùng ngay.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-8fcc592ab7250a38_v4_step_1', 'imp-8fcc592ab7250a38', 1, 'prep', 'Thái sợi bắp cải và chuẩn bị hành tỏi', 'Tách bỏ lớp lá già bên ngoài của 1 bắp cải tươi, bổ tư theo chiều dọc rồi cắt bỏ phần lõi cứng, sau đó thái ngang thành sợi dày khoảng 1 cm, rửa sạch và vẩy ráo. Thái hạt lựu nhỏ 3/4 củ hành tây, bóc vỏ và đập dập nhẹ 2 tép tỏi khô.', NULL, NULL),
('imp-8fcc592ab7250a38_v4_step_2', 'imp-8fcc592ab7250a38', 2, 'cook', 'Phi thơm hành tây và tỏi với dầu ô liu', 'Làm nóng 45 ml dầu ô liu trong chảo sâu lòng hoặc nồi đế dày trên lửa vừa. Cho hành tây thái nhỏ vào xào 4 phút đến khi mềm trong, tiếp tục thả tỏi đập dập vào đảo thêm 1 phút cho dậy mùi thơm dịu rồi gắp bỏ xác tỏi ra ngoài.', 'Vớt bỏ tép tỏi ngay khi vừa thơm giúp món om có hương tỏi thoang thoảng dễ chịu mà không bị đắng nếu tỏi quá lửa.', 5),
('imp-8fcc592ab7250a38_v4_step_3', 'imp-8fcc592ab7250a38', 3, 'cook', 'Xào xẹp bắp cải với muối và tiêu', 'Cho toàn bộ bắp cải thái sợi vào nồi, nêm 6 g muối ăn và 1,5 g tiêu đen xay. Xào mở nắp trên lửa vừa khoảng 4–5 phút, đảo đều tay để từng sợi cải thấm lớp dầu thơm và bắt đầu xẹp bớt thể tích.', NULL, 5),
('imp-8fcc592ab7250a38_v4_step_4', 'imp-8fcc592ab7250a38', 4, 'sauce', 'Đảo quyện cùng cà chua nghiền đóng hộp', 'Đổ 300 g cà chua nghiền đóng hộp Ý vào nồi bắp cải, đảo đều tay và đun mở nắp trong 3 phút để nước sốt cà chua hơi cô lại và bám đều lên từng sợi cải.', 'Đun mở nắp cùng cà chua nghiền trong vài phút đầu giúp sốt cô lại và bám đều lên từng sợi bắp cải trước khi om.', 3),
('imp-8fcc592ab7250a38_v4_step_5', 'imp-8fcc592ab7250a38', 5, 'cook', 'Om nhỏ lửa đến khi bắp cải chín mềm ngọt', 'Rót 200 ml nước dùng rau củ vào xấp mặt cải, đậy kín nắp, hạ lửa nhỏ và om liu riu trong khoảng 20–22 phút đến khi bắp cải chín mềm ngọt hoàn toàn.', 'Nếu thích sợi bắp cải còn giữ chút độ giòn nhẹ có thể rút ngắn thời gian om xuống khoảng 15 phút.', 20),
('imp-8fcc592ab7250a38_v4_step_6', 'imp-8fcc592ab7250a38', 6, 'finish', 'Cô sánh sốt và dọn nóng', 'Mở nắp kiểm tra độ mềm của bắp cải; nếu nước còn loãng, bật lửa lớn đun thêm 2–3 phút cho nước sốt sánh bóng quyện vào cải. Nêm nếm lại vừa miệng rồi trút ra đĩa dùng nóng.', NULL, NULL),
('imp-da0c2dea539000e5_v4_step_1', 'imp-da0c2dea539000e5', 1, 'prep', 'Lau sạch nấm đùi gà và sơ chế ngò tây, tỏi', 'Dùng khăn ẩm lau sạch 300 g nấm đùi gà tươi (không ngâm ngập nước để nấm không hút ẩm), cắt bỏ phần gốc già và thái lát dày 0,5 cm. Rửa sạch 15 g ngò tây tươi, thấm khô và băm nhỏ; bóc vỏ băm nhuyễn 2 tép tỏi khô.', NULL, NULL),
('imp-da0c2dea539000e5_v4_step_2', 'imp-da0c2dea539000e5', 2, 'cook', 'Xào chín vàng nấm đùi gà và để nguội bớt', 'Đun nóng 15 ml dầu ô liu trong chảo chống dính đường kính khoảng 24 cm trên lửa vừa, cho tỏi băm và 0,5 g ớt vảy khô vào đảo nhanh 30 giây cho thơm. Tăng lên lửa lớn, thả nấm đùi gà vào xào mở nắp khoảng 6 phút cùng 1 g muối ăn đến khi nấm ra hết nước và xém vàng cạnh; trút nấm ra đĩa để nguội bớt 3 phút.', 'Xào nấm mở nắp ở lửa lớn và để nấm nguội bớt trước khi trộn vào trứng giúp nấm không tiết nước làm loãng trứng và không làm trứng bị chín vón cục.', 7),
('imp-da0c2dea539000e5_v4_step_3', 'imp-da0c2dea539000e5', 3, 'prep', 'Đánh tan trứng gà với phô mai Parmesan', 'Đập 6 quả trứng gà tươi vào tô lớn, thêm 40 g phô mai Parmesan bào mịn, 2 g muối ăn và 1 g tiêu đen xay. Dùng phới lồng đánh đều cho lòng đỏ, lòng trắng và phô mai hòa quyện hoàn toàn, sau đó trút phần nấm đùi gà xào đã nguội bớt vào trộn đều.', 'Phô mai Parmesan vốn có vị mặn đậm nên chỉ cần nêm lượng muối vừa phải để tránh món trứng bị gắt mặn.', NULL),
('imp-da0c2dea539000e5_v4_step_4', 'imp-da0c2dea539000e5', 4, 'cook', 'Đổ hỗn hợp trứng và gom mép chín đều', 'Lau sạch chảo, thêm 15 ml dầu ô liu còn lại đun nóng nhẹ trên lửa nhỏ. Rót hỗn hợp trứng nấm vào chảo, rắc 2/3 phần ngò tây băm lên mặt. Để yên 1 phút cho đáy se lại rồi dùng phới silicon kéo nhẹ trứng từ mép vào giữa để phần trứng lỏng chảy xuống đáy, lặp lại thao tác này trong khoảng 4 phút đến khi phần đáy và viền thành hình.', 'Thao tác gom mép trứng từ ngoài vào giữa trong vài phút đầu giúp khối trứng chín đều từ đáy lên mà không bị khô cứng.', 5),
('imp-da0c2dea539000e5_v4_step_5', 'imp-da0c2dea539000e5', 5, 'cook', 'Đậy nắp om nhỏ lửa cho trứng chín mặt trên', 'Đậy nắp vung kín chảo, hạ lửa thật nhỏ và nấu thêm khoảng 8 phút đến khi toàn bộ khối trứng phồng nhẹ, bề mặt trên se chín đặc lại chỉ còn hơi ẩm nhẹ ở tâm.', NULL, 8),
('imp-da0c2dea539000e5_v4_step_6', 'imp-da0c2dea539000e5', 6, 'finish', 'Lật áp chảo mặt trên và cắt múi tam giác', 'Úp một chiếc đĩa phẳng rộng lên miệng chảo, lật dứt khoát ổ Frittata ra đĩa rồi trượt nhẹ trở lại chảo áp mặt còn lại thêm 2 phút trên lửa nhỏ cho vàng đều cả hai mặt. Trút ra thớt hoặc đĩa lớn, rắc nốt phần ngò tây tươi còn lại, nghỉ 2 phút rồi cắt thành 6 miếng tam giác dùng nóng hoặc ấm.', NULL, NULL);
